let isLicenseValid = true;
let licenseTimer: NodeJS.Timeout | null = null;
let isExpired = false;

function getHwid() {
    try {
        const interfaces = os.networkInterfaces() || {};
        let mac = '';
        for (const name of Object.keys(interfaces)) {
            const iface = interfaces[name];
            if (!iface) continue;
            for (const i of iface) {
                if (!i.internal && i.mac && i.mac !== '00:00:00:00:00:00') {
                    mac = i.mac;
                    break;
                }
            }
            if (mac) break;
        }
        
        const cpus = os.cpus() || [];
        const cpuInfo = cpus.length > 0 ? cpus[0].model : 'unknown-cpu';
        const platform = os.platform() || 'unknown-platform';
        const raw = `${mac}-${cpuInfo}-${platform}`;
        return crypto.createHash('sha256').update(raw).digest('hex').substring(0, 16).toUpperCase();
    } catch (err) {
        // Fallback for cPanel/CageFS where os.cpus() or os.networkInterfaces() might fail
        const raw = `cpanel-fallback-${os.hostname ? os.hostname() : 'unknown'}`;
        return crypto.createHash('sha256').update(raw).digest('hex').substring(0, 16).toUpperCase();
    }
}

function updateEnv(key: string, value: string) {
    const envPath = path.join(process.cwd(), '.env');
    let envContent = '';
    if (fs.existsSync(envPath)) {
        envContent = fs.readFileSync(envPath, 'utf8');
    }
    const regex = new RegExp(`^${key}=.*`, 'm');
    if (regex.test(envContent)) {
        envContent = envContent.replace(regex, `${key}=${value}`);
    } else {
        envContent += `\n${key}=${value}`;
    }
    fs.writeFileSync(envPath, envContent.trim() + '\n');
    process.env[key] = value;
}

async function verifyLicenseOnBoot() {
    let licenseKey = process.env.LICENSE_KEY || "";
    let hwid = getHwid();
    const hubServerUrl = 'https://hub.dapoy.net';

    if (licenseKey) {
        try {
            const res = await fetch(`${hubServerUrl}/api/verify-license`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    license_key: licenseKey,
                    hardware_id: hwid,
                    app_name: 'Dapoy Schools'
                })
            });
            if (!res.ok && res.status >= 500) {
                throw new Error(`Hub Server HTTP error ${res.status}`);
            }
            const data: any = await res.json();
            if (data.valid) {
                isLicenseValid = true;
                isExpired = false;
                console.log(`[LICENSE] Valid. Activated for: ${data.client_name || 'Client'}`);
                if (licenseTimer) clearInterval(licenseTimer);
                licenseTimer = setInterval(verifyLicenseOnBoot, 60 * 60 * 1000); // 1 jam
            } else {
                console.log(`[LICENSE] Invalid: ${data.error}`);
                isLicenseValid = false;
                checkFreeTrial();
            }
        } catch (err: any) {
            console.log(`[LICENSE] Hub Server offline/unreachable (${err.message}). Retaining valid status since license_key is configured.`);
            isLicenseValid = true;
            isExpired = false;
            if (licenseTimer) clearInterval(licenseTimer);
            licenseTimer = setInterval(verifyLicenseOnBoot, 60 * 60 * 1000);
        }
    } else {
        isLicenseValid = false;
        checkFreeTrial();
    }
}

async function checkFreeTrial() {
    let envContent = '';
    const envPath = path.join(process.cwd(), '.env');
    if (fs.existsSync(envPath)) {
        envContent = fs.readFileSync(envPath, 'utf8');
    }
    if (!envContent.includes('FREE_TRIAL_START=')) {
        const startTime = Date.now();
        updateEnv('FREE_TRIAL_START', startTime.toString());
    }
    
    const trialStartStr = process.env.FREE_TRIAL_START;
    if (trialStartStr) {
        const trialStart = parseInt(trialStartStr);
        const now = Date.now();
        const twoHours = 5 * 24 * 60 * 60 * 1000;
        if (now - trialStart > twoHours) {
            isExpired = true;
            console.log(`[LICENSE] Waktu Versi Free (5 Hari) telah habis. Harap aktivasi lisensi.`);
        } else {
            isExpired = false;
            const remaining = Math.round((twoHours - (now - trialStart)) / 60000);
            console.log(`[LICENSE] Versi Free berjalan. Sisa waktu: ${remaining} menit.`);
            setTimeout(verifyLicenseOnBoot, (twoHours - (now - trialStart)) + 1000);
        }
    }
}

