async function uploadArsipFileHelper(file: any, category: string = 'Arsip Dokumen Sekolah', subfolderName: string = 'Surat Resmi Bertanda Tangan', defaultName?: string) {
    let fileUrl = `/uploads/arsip_surat/${file.filename}`;
    try {
        const fileBuffer = fs.readFileSync(file.path);
        const [schRows]: any = await getPool().query("SELECT school_name FROM pengaturan_sekolah WHERE id = 1");
        const schoolName = schRows?.[0]?.school_name || "SDN Tanah Tinggi 1";
        
        const gdRes = await uploadFileToDrive({
            buffer: fileBuffer,
            originalFilename: defaultName || file.originalname,
            mimeType: file.mimetype,
            schoolName: schoolName,
            category: category,
            subfolderName: subfolderName
        });
        if (gdRes && (gdRes.viewLink || gdRes.directLink)) {
            fileUrl = gdRes.viewLink || gdRes.directLink;
        }
    } catch (gdErr: any) {
        console.warn("[Upload Arsip] Google Drive sync error, using local storage fallback:", gdErr.message);
    }
    return fileUrl;
}

