// Proxy for Google Drive images to bypass CORS/403
app.get("/api/drive-proxy", async (req: any, res: any) => {
    let url = req.query.url as string;
    if (!url) return res.status(400).send("No URL provided");
    
    try {
        let fetchUrl = url;
        let fileId = '';

        const matchFile = url.match(/\/file\/d\/([a-zA-Z0-9_-]+)/);
        if (matchFile && matchFile[1]) {
            fileId = matchFile[1];
        } else {
            const matchId = url.match(/[?&]id=([a-zA-Z0-9_-]+)/);
            if (matchId && matchId[1]) {
                fileId = matchId[1];
            } else {
                const matchLh3 = url.match(/\/d\/([a-zA-Z0-9_-]+)/);
                if (matchLh3 && matchLh3[1]) {
                    fileId = matchLh3[1];
                }
            }
        }

        if (fileId) {
            fetchUrl = `https://lh3.googleusercontent.com/d/${fileId}=s1000`;
        }

        let response = await fetch(fetchUrl);
        if (!response.ok && fileId) {
            // Fallback to Google Drive thumbnail endpoint
            response = await fetch(`https://drive.google.com/thumbnail?id=${fileId}&sz=w1000`);
        }

        if (!response.ok) return res.status(response.status).send(response.statusText);
        
        const contentType = response.headers.get('content-type') || 'image/jpeg';
        res.set('Content-Type', contentType);
        res.set('Cache-Control', 'public, max-age=31536000');
        
        const arrayBuffer = await response.arrayBuffer();
        res.send(Buffer.from(arrayBuffer));
    } catch (e) {
        console.error("Proxy error:", e);
        res.status(500).send("Proxy error");
    }
});

