// API Pencarian Sekolah Se-Indonesia (Lookup NPSN & Nama Sekolah)
const schoolLookupCache = new Map<string, { timestamp: number, data: any }>();
app.get("/api/public/school-lookup", async (req: any, res: any) => {
    const rawQuery = (req.query.query || req.query.npsn || req.query.nama || req.query.q || '').toString().trim();
    if (!rawQuery || rawQuery.length < 2) {
        return res.status(400).json({ success: false, message: "Parameter query/NPSN minimal 2 karakter" });
    }

    const cacheKey = rawQuery.toLowerCase();
    const cached = schoolLookupCache.get(cacheKey);
    if (cached && (Date.now() - cached.timestamp < 3600000)) { // Cache 1 jam
        return res.json({ success: true, source: "cache", data: cached.data });
    }

    let formatted: any[] = [];
    const isNumeric = /^\d+$/.test(rawQuery);

    // 1. Coba sumber data utama (sekolah.devapi.id)
    try {
        let apiUrl = isNumeric
            ? `https://sekolah.devapi.id/sekolah?npsn=${encodeURIComponent(rawQuery)}`
            : `https://sekolah.devapi.id/sekolah?nama=${encodeURIComponent(rawQuery)}`;

        const response = await fetch(apiUrl, {
            headers: { 'User-Agent': 'DapoySchools/2.0 (SchoolManagementSystem)' },
            signal: AbortSignal.timeout(6000)
        });

        if (response.ok) {
            const json: any = await response.json();
            const rawList = Array.isArray(json.data) ? json.data : [];

            formatted = rawList.map((item: any) => {
                const alamatObj = item.alamat || {};
                let statusVal = item.statusSatuanPendidikan || item.status || '';
                if (statusVal === 'S') statusVal = 'SWASTA';
                if (statusVal === 'N') statusVal = 'NEGERI';

                return {
                    npsn: item.npsn || '',
                    nama: item.nama || item.sekolah || '',
                    bentuk: item.bentukPendidikan || item.bentuk || '',
                    status: statusVal,
                    akreditasi: item.akreditasi || '',
                    jalan: alamatObj.jalan || item.alamat_jalan || '',
                    desa: alamatObj.nama_desa || '',
                    kecamatan: alamatObj.nama_kecamatan || item.kecamatan || '',
                    kabupaten: alamatObj.nama_kabupaten || item.kabupaten_kota || '',
                    provinsi: alamatObj.nama_provinsi || item.propinsi || '',
                    telepon: item.kontak?.nomor_telepon || '',
                    email: item.kontak?.email || ''
                };
            });
        }
    } catch (e1: any) {
        console.warn("[school-lookup] Primary API devapi failed, trying secondary fallback:", e1.message);
    }

    // 2. Fallback sumber data cadangan (api-sekolah-indonesia.vercel.app) jika data kosong
    if (formatted.length === 0) {
        try {
            let apiUrl2 = isNumeric
                ? `https://api-sekolah-indonesia.vercel.app/sekolah?npsn=${encodeURIComponent(rawQuery)}`
                : `https://api-sekolah-indonesia.vercel.app/sekolah?sekolah=${encodeURIComponent(rawQuery)}`;

            const response2 = await fetch(apiUrl2, {
                headers: { 'User-Agent': 'DapoySchools/2.0 (SchoolManagementSystem)' },
                signal: AbortSignal.timeout(6000)
            });

            if (response2.ok) {
                const json2: any = await response2.json();
                const rawList2 = Array.isArray(json2.dataSekolah) ? json2.dataSekolah : [];

                formatted = rawList2.map((item: any) => {
                    let statusVal = item.status || '';
                    if (statusVal === 'S') statusVal = 'SWASTA';
                    if (statusVal === 'N') statusVal = 'NEGERI';

                    return {
                        npsn: item.npsn || '',
                        nama: item.sekolah || item.nama || '',
                        bentuk: item.bentuk || '',
                        status: statusVal,
                        akreditasi: item.akreditasi || '',
                        jalan: item.alamat_jalan || '',
                        desa: '',
                        kecamatan: item.kecamatan?.replace(/^Kec\.\s*/i, '') || '',
                        kabupaten: item.kabupaten_kota?.replace(/^Kab\.\s*/i, '') || '',
                        provinsi: item.propinsi?.replace(/^Prov\.\s*/i, '') || '',
                        telepon: '',
                        email: ''
                    };
                });
            }
        } catch (e2: any) {
            console.warn("[school-lookup] Secondary API fallback failed:", e2.message);
        }
    }

    if (formatted.length > 0) {
        schoolLookupCache.set(cacheKey, { timestamp: Date.now(), data: formatted });
    }

    return res.json({ success: true, count: formatted.length, data: formatted });
});

