/**
 * REKONSILIASI CERDAS SISWA PINDAHAN / MANUAL KE DATA DAPODIK RESMI
 * Menyelaraskan siswa yang sempat diinput manual berdasarkan kecocokan NIK atau NISN.
 * Jika cocok, seluruh nilai (ASTS, Kokurikuler P5, Formatif, Tryout, dll), rombel, dan absensi
 * otomatis dialihkan ke ID Dapodik yang baru, lalu ID manual diupgrade ke ID Dapodik resmi.
 */
async function reconcileManualStudents(pool: any, incomingStudents: any[]): Promise<number> {
    if (!Array.isArray(incomingStudents) || incomingStudents.length === 0) return 0;

    let reconciledCount = 0;

    for (const item of incomingStudents) {
        const dapodikId = item.peserta_didik_id || item.id;
        if (!dapodikId) continue;

        const nik = item.nik ? String(item.nik).trim() : '';
        const nisn = item.nisn ? String(item.nisn).trim() : '';

        // Safeguard: Validasi NIK minimal 12 digit (standar 16 digit) dan bukan angka dummy
        const isValidNik = nik.length >= 12 && !/^0+$/.test(nik) && !/^1+$/.test(nik);
        // Validasi NISN minimal 8 digit dan bukan angka dummy
        const isValidNisn = nisn.length >= 8 && nisn.length <= 12 && !/^0+$/.test(nisn);

        if (!isValidNik && !isValidNisn) continue;

        // 1. Cek apakah ID Dapodik ini sudah ada di database peserta_didik
        const [existingDapodik]: any = await pool.query(
            "SELECT peserta_didik_id FROM peserta_didik WHERE peserta_didik_id = ? LIMIT 1",
            [dapodikId]
        ).catch(() => [[]]);

        if (existingDapodik && existingDapodik.length > 0) {
            // ID Dapodik sudah ada di database, tidak perlu rekonsiliasi ID
            continue;
        }

        // 2. Cari apakah ada siswa yang diinput manual sebelumnya dengan NIK atau NISN yang sama
        const conditions: string[] = [];
        const params: any[] = [];

        if (isValidNik) {
            conditions.push("nik = ?");
            params.push(nik);
        }
        if (isValidNisn) {
            conditions.push("nisn = ?");
            params.push(nisn);
        }

        const [matches]: any = await pool.query(
            `SELECT peserta_didik_id, nama, nik, nisn 
             FROM peserta_didik 
             WHERE (${conditions.join(" OR ")}) 
               AND peserta_didik_id != ? 
               AND (soft_delete = 0 OR soft_delete IS NULL OR soft_delete = '0')
             LIMIT 1`,
            [...params, dapodikId]
        ).catch(() => [[]]);

        if (!matches || matches.length === 0) continue;

        const manualStudent = matches[0];
        const oldId = manualStudent.peserta_didik_id;
        if (!oldId || oldId === dapodikId) continue;

        console.log(`[SMART RECONCILIATION] Menemukan siswa manual cocok: "${manualStudent.nama}" (NIK: ${manualStudent.nik}, NISN: ${manualStudent.nisn}) [${oldId}] -> ID Resmi Dapodik [${dapodikId}]`);

        // 3. Migrasikan seluruh tabel anak ke ID Dapodik yang baru
        const pdTables = [
            'anggota_rombel',
            'kokurikuler_nilai',
            'nilai_asts',
            'nilai_asts_sikap',
            'nilai_penilaian_harian',
            'pelanggaran_siswa',
            'peserta_didik_longitudinal',
            'registrasi_peserta_didik',
            'surat_panggilan',
            'surat_pernyataan_siswa',
            'tryout_nilai',
            'ujian_peserta'
        ];

        for (const tbl of pdTables) {
            try {
                await pool.query(
                    `UPDATE \`${tbl}\` SET peserta_didik_id = ? WHERE peserta_didik_id = ?`,
                    [dapodikId, oldId]
                );
            } catch (err: any) {
                console.warn(`[RECONCILE WARNING] Gagal update peserta_didik_id pada ${tbl}:`, err.message);
            }
        }

        const siswaIdTables = [
            'absensi_bidang_study',
            'absensi_ekskul',
            'absensi_siswa',
            'arsip_siswa',
            'data_afirmasi',
            'data_bank',
            'data_periodik',
            'laporan_bantuan',
            'literasi_jurnal',
            'penerima_bantuan',
            'pengajuan_rekening_bantuan',
            'siswa_gamifikasi'
        ];

        for (const tbl of siswaIdTables) {
            try {
                await pool.query(
                    `UPDATE \`${tbl}\` SET siswa_id = ? WHERE siswa_id = ?`,
                    [dapodikId, oldId]
                );
            } catch (err: any) {
                console.warn(`[RECONCILE WARNING] Gagal update siswa_id pada ${tbl}:`, err.message);
            }
        }

        const studentIdTables = [
            'absensi_bidang_study',
            'absensi_siswa',
            'pengajuan_ubah_data',
            'permohonan_pindah',
            'riwayat_masuk'
        ];

        for (const tbl of studentIdTables) {
            try {
                await pool.query(
                    `UPDATE \`${tbl}\` SET student_id = ? WHERE student_id = ?`,
                    [dapodikId, oldId]
                );
            } catch (err: any) {
                console.warn(`[RECONCILE WARNING] Gagal update student_id pada ${tbl}:`, err.message);
            }
        }

        // 4. Update peserta_didik utama ke ID Dapodik yang baru
        try {
            await pool.query(
                "UPDATE `peserta_didik` SET peserta_didik_id = ? WHERE peserta_didik_id = ?",
                [dapodikId, oldId]
            );
            reconciledCount++;
        } catch (err: any) {
            console.error(`[RECONCILE ERROR] Gagal update peserta_didik_id utama:`, err.message);
        }
    }

    if (reconciledCount > 0) {
        console.log(`[SMART RECONCILIATION] Sukses merekonsiliasi ${reconciledCount} siswa manual ke ID Dapodik resmi beserta seluruh nilai & rombelnya.`);
    }

    return reconciledCount;
}

// Endpoint untuk sinkronisasi Dapodik API
app.post(['/api/sync/siswa', '/api/sync/pegawai', '/api/sync/referensi', '/api/sync/semua', '/api/sync/:type?'], async (req: any, res: any) => {
    try {
        const token = req.headers['authorization']?.replace('Bearer ', '') || req.headers['x-api-key'] || req.body?.token;
        const pool = getPool();

        if (!token) {
            return res.status(401).json({ success: false, message: 'Unauthorized: No token provided' });
        }

        // Validate token against database
        const [settingsRows]: any = await pool.query('SELECT sync_token FROM pengaturan_sekolah LIMIT 1');
        if (!settingsRows || settingsRows.length === 0 || settingsRows[0].sync_token !== token || !token.startsWith('dapoy-')) {
            return res.status(403).json({ success: false, message: 'Invalid API token' });
        }

        const data = req.body?.data;
        if (!data || typeof data !== 'object') {
            return res.status(400).json({ success: false, message: 'Data payload is missing or invalid' });
        }

        // Nonaktifkan strict mode untuk sesi koneksi sinkronisasi agar toleran terhadap data kosong Dapodik
        try {
            await pool.query("SET SESSION sql_mode = ''");
        } catch (e) {}

        const BATCH_SIZE = 200;
        let totalProcessed = 0;

        // Urutkan pemrosesan tabel agar 'peserta_didik' diproses terlebih dahulu sebelum anggota_rombel & registrasi
        const sortedEntries = Object.entries(data).sort(([a], [b]) => {
            if (a === 'peserta_didik') return -1;
            if (b === 'peserta_didik') return 1;
            return 0;
        });

        for (let [table, items] of sortedEntries) {
            if (!Array.isArray(items) || items.length === 0) continue;

            // DapoySync is sending ptk data under the 'pegawai' key. Map it to 'ptk' table natively.
            if (table === 'pegawai') {
                table = 'ptk';
            }

            // Jalankan rekonsiliasi cerdas untuk peserta didik sebelum upsert
            if (table === 'peserta_didik') {
                try {
                    await reconcileManualStudents(pool, items);
                } catch (reconcileErr: any) {
                    console.error('[SYNC RECONCILIATION ERROR]:', reconcileErr);
                }
            }

            const sample = items[0];
            if (!sample || typeof sample !== 'object') continue;
            const keys = Object.keys(sample).filter(k => k !== 'undefined');

            // Cek atau buat tabel di MySQL bila belum ada (atau tambahkan kolom bila ada yang baru)
            const [cols]: any = await pool.query(`SHOW COLUMNS FROM \`${table}\``).catch(() => [[]]);
            let pk = keys[0];
            if (table === 'peserta_didik') pk = 'peserta_didik_id';
            else if (table === 'registrasi_peserta_didik') pk = 'registrasi_id';
            else if (table === 'peserta_didik_longitudinal') pk = 'peserta_didik_id';
            else if (table === 'anggota_rombel') pk = 'anggota_rombel_id';
            else if (table === 'rombongan_belajar') pk = 'rombongan_belajar_id';

            if (cols.length === 0) {
                const colDefs = keys.map(k => k === pk ? `\`${k}\` VARCHAR(64) NOT NULL PRIMARY KEY` : `\`${k}\` TEXT`).join(', ');
                await pool.query(`CREATE TABLE IF NOT EXISTS \`${table}\` (${colDefs})`);
            } else {
                const existingColNames = cols.map((c: any) => c.Field);
                for (const k of keys) {
                    if (!existingColNames.includes(k)) {
                        await pool.query(`ALTER TABLE \`${table}\` ADD COLUMN \`${k}\` TEXT`).catch(() => {});
                    }
                }

                // Special safeguard: Perbaiki kolom yang NOT NULL tanpa default yang tidak dikirim di keys Dapodik (contoh: field 'nama')
                for (const c of cols) {
                    if (c.Null === 'NO' && c.Default === null && !c.Extra?.includes('auto_increment') && !c.Key?.includes('PRI') && !keys.includes(c.Field)) {
                        try {
                            await pool.query(`ALTER TABLE \`${table}\` MODIFY COLUMN \`${c.Field}\` ${c.Type} DEFAULT NULL`);
                        } catch (alterErr) {
                            try {
                                await pool.query(`ALTER TABLE \`${table}\` MODIFY COLUMN \`${c.Field}\` ${c.Type} DEFAULT ''`);
                            } catch (e2) {}
                        }
                    }
                }

                // Special safeguard for legacy rombongan_belajar schema (drop obsolete unique key `name` & make nullable)
                if (table === 'rombongan_belajar') {
                    try {
                        const [nameIdx]: any = await pool.query("SHOW INDEX FROM `rombongan_belajar` WHERE Key_name = 'name'").catch(() => [[]]);
                        if (nameIdx && nameIdx.length > 0) {
                            await pool.query("ALTER TABLE `rombongan_belajar` DROP INDEX `name`").catch(() => {});
                        }
                        if (existingColNames.includes('name')) {
                            await pool.query("ALTER TABLE `rombongan_belajar` MODIFY COLUMN `name` VARCHAR(100) DEFAULT NULL").catch(() => {});
                        }
                    } catch (e) {}
                }

                // Ensure the Dapodik primary key column has a UNIQUE index if table was created with an id column
                if (pk && existingColNames.includes(pk)) {
                    try {
                        const [idxs]: any = await pool.query(`SHOW INDEX FROM \`${table}\``).catch(() => [[]]);
                        const indexedCols = (idxs || []).map((ix: any) => ix.Column_name);
                        if (!indexedCols.includes(pk)) {
                            await pool.query(`ALTER TABLE \`${table}\` ADD UNIQUE INDEX \`idx_uniq_${pk}\` (\`${pk}\`(36))`).catch(() => {});
                        }
                    } catch (e) {}
                }
            }

            // Dapatkan informasi tipe kolom terkini untuk sanitasi nilai (Anti Incorrect decimal value: '')
            const [currentCols]: any = await pool.query(`SHOW COLUMNS FROM \`${table}\``).catch(() => [cols]);
            const colTypeMap = new Map<string, { isNumeric: boolean, isDate: boolean, isNullable: boolean }>();
            for (const c of (currentCols || cols)) {
                const tLower = (c.Type || '').toLowerCase();
                const isNum = tLower.includes('int') || tLower.includes('decimal') || tLower.includes('float') || tLower.includes('double') || tLower.includes('numeric');
                const isD = tLower.includes('date') || tLower.includes('time') || tLower.includes('year');
                colTypeMap.set(c.Field, { isNumeric: isNum, isDate: isD, isNullable: c.Null === 'YES' });
            }

            // Normalisasi nilai agar aman dari type error di MySQL/MariaDB
            const cleanSyncValue = (colName: string, rawVal: any) => {
                if (rawVal === undefined || rawVal === null) return null;
                const str = String(rawVal).trim();
                const meta = colTypeMap.get(colName);
                if (meta?.isNumeric) {
                    if (str === '' || str.toLowerCase() === 'null') return meta.isNullable ? null : 0;
                    const parsed = Number(str.replace(',', '.'));
                    return isNaN(parsed) ? (meta.isNullable ? null : 0) : parsed;
                }
                if (meta?.isDate) {
                    if (str === '' || str.toLowerCase() === 'null' || str.startsWith('0000-00-00')) return null;
                    return str;
                }
                if (str === '' && meta?.isNullable) return null;
                return str;
            };

            // Upsert / Insert batching
            const placeholders = keys.map(() => '?').join(',');
            const updateStr = keys.map(k => `\`${k}\`=VALUES(\`${k}\`)`).join(', ');
            const colNamesStr = keys.map(k => `\`${k}\``).join(', ');
            
            for (let i = 0; i < items.length; i += BATCH_SIZE) {
                const batch = items.slice(i, i + BATCH_SIZE);
                if (batch.length === 0) continue;
                const values = batch.map((obj: any) => keys.map(k => cleanSyncValue(k, obj[k])));
                const sql = `INSERT INTO \`${table}\` (${colNamesStr}) VALUES ${batch.map(() => `(${placeholders})`).join(',')} ON DUPLICATE KEY UPDATE ${updateStr}`;
                await pool.query(sql, values.flat());
            }

            totalProcessed += items.length;
            console.log(`Synced ${items.length} records into ${table}`);
        }

        res.json({ success: true, message: 'Sinkronisasi berhasil (100% struktur Dapodik)', count: totalProcessed });
    } catch (e: any) {
        console.error('Error syncing data:', e);
        res.status(500).json({ success: false, message: e.message || String(e) });
    }
});

