const authenticate = (req: any, res: any, next: any) => {
    let token = '';
    const authHeader = req.headers.authorization;
    if (authHeader && authHeader.startsWith('Bearer ')) {
        token = authHeader.split(" ")[1];
    } else if (authHeader) {
        token = authHeader;
    } else if (req.query && req.query.token) {
        token = String(req.query.token);
    }

    if (!token) return res.status(401).json({ error: "No token provided" });

    jwt.verify(token, JWT_SECRET, async (err: any, user: any) => {
        if (err) return res.status(401).json({ error: "Sesi login telah berakhir atau token tidak valid", session_expired: true });
        req.user = { ...user, permissions: Array.isArray(user?.permissions) ? user.permissions : ['all'] };
        
        if ((req.user.type === 'staff' || req.user.type === 'guru' || req.user.type === 'guru_kelas' || req.user.type === 'guru_bidang') && !req.user.staff_id && req.user.id) {
            try {
                const [uRows]: any = await getPool().execute("SELECT staff_id FROM pengguna_web WHERE id = ?", [req.user.id]);
                if (uRows.length > 0) req.user.staff_id = uRows[0].staff_id;
            } catch (e) {
                console.error("Error attaching staff_id:", e);
            }
        }
        
        next();
    });
};

