const getAppRootDir = () => {
    // 1. Cek apakah process.cwd() adalah root aplikasi
    const cwd = process.cwd();
    if (fs.existsSync(path.join(cwd, 'package.json')) || fs.existsSync(path.join(cwd, 'server.js')) || fs.existsSync(path.join(cwd, 'dist', 'server.cjs'))) {
        return cwd;
    }
    // 2. Cek path berbasis __dirname (ketika dikompilasi ke dist/server.cjs)
    if (typeof __dirname !== 'undefined') {
        const parentDir = path.resolve(__dirname, '..');
        if (fs.existsSync(path.join(parentDir, 'package.json')) || fs.existsSync(path.join(parentDir, 'server.js')) || fs.existsSync(path.join(parentDir, 'dist'))) {
            return parentDir;
        }
        if (fs.existsSync(path.join(__dirname, 'package.json')) || fs.existsSync(path.join(__dirname, 'server.js'))) {
            return __dirname;
        }
    }
    return cwd;
};

const APP_BUILD_VERSION = '2.14.12';

const getCurrentAppVersion = () => {
    const rootPath = getAppRootDir();

    // 1. Coba baca update_version.txt
    try {
        const txtCandidates = [
            path.join(rootPath, 'update_version.txt'),
            path.join(process.cwd(), 'update_version.txt'),
            typeof __dirname !== 'undefined' ? path.join(__dirname, 'update_version.txt') : null,
            typeof __dirname !== 'undefined' ? path.join(__dirname, '..', 'update_version.txt') : null,
        ].filter(Boolean) as string[];

        for (const p of txtCandidates) {
            if (fs.existsSync(p)) {
                const txt = fs.readFileSync(p, 'utf-8');
                const match = txt.match(/(?:Versi|Version|v)?\s*(\d+(?:\.\d+)+)/i);
                if (match && match[1]) return match[1].trim();
            }
        }
    } catch (e) {}

    // 2. Coba baca package.json
    try {
        const pkgCandidates = [
            path.join(rootPath, 'package.json'),
            path.join(process.cwd(), 'package.json'),
            typeof __dirname !== 'undefined' ? path.join(__dirname, 'package.json') : null,
            typeof __dirname !== 'undefined' ? path.join(__dirname, '..', 'package.json') : null,
        ].filter(Boolean) as string[];

        for (const p of pkgCandidates) {
            if (fs.existsSync(p)) {
                const pkg = JSON.parse(fs.readFileSync(p, 'utf-8'));
                if (pkg.version) return String(pkg.version).trim();
            }
        }
    } catch (e) {}

    return APP_BUILD_VERSION;
};

const checkUpdateHandler = async (req: any, res: any) => {
    try {
        let text = '';
        try {
            const apiRes = await fetch(`https://api.github.com/repos/syahmuhamadrizky/SekolahV2_Releases/contents/update_version.txt?ref=main&t=${Date.now()}`, {
                headers: {
                    'Accept': 'application/vnd.github.v3.raw',
                    'User-Agent': 'DapoySchools-OTA',
                    'Cache-Control': 'no-cache, no-store, must-revalidate',
                    'Pragma': 'no-cache'
                }
            });
            if (apiRes.ok) {
                const rawOrJson = await apiRes.text();
                if (rawOrJson.trim().startsWith('{') && rawOrJson.includes('"content"')) {
                    try {
                        const parsed = JSON.parse(rawOrJson);
                        if (parsed.content && parsed.encoding === 'base64') {
                            text = Buffer.from(parsed.content, 'base64').toString('utf-8');
                        }
                    } catch (_) {
                        text = rawOrJson;
                    }
                } else {
                    text = rawOrJson;
                }
            }
        } catch (apiErr) {
            console.warn('[OTA] GitHub API check failed, falling back to raw:', apiErr);
        }

        if (!text) {
            const response = await fetch(`https://raw.githubusercontent.com/syahmuhamadrizky/SekolahV2_Releases/main/update_version.txt?t=${Date.now()}`, {
                headers: { 'Cache-Control': 'no-cache, no-store, must-revalidate', 'Pragma': 'no-cache' }
            });
            text = await response.text();
        }

        const match = text.match(/(?:Versi|Version|v)?\s*(\d+(?:\.\d+)+)/i);
        let latest_version = match ? match[1] : text.trim().replace(/^v/i, '');
        if (!latest_version || !/\d+\.\d+/.test(latest_version)) {
            latest_version = APP_BUILD_VERSION;
        }
        
        const current_version = getCurrentAppVersion();
        
        // Membandingkan versi dengan format SemVer (x.y.z)
        const currentParts = current_version.split('.').map(Number);
        const latestParts = latest_version.split('.').map(Number);
        let has_update = false;
        
        for (let i = 0; i < 3; i++) {
            const cur = currentParts[i] || 0;
            const lat = latestParts[i] || 0;
            if (lat > cur) { has_update = true; break; }
            if (lat < cur) { break; }
        }
        
        res.json({
            available: has_update,
            has_update,
            currentVersion: current_version,
            current_version: current_version,
            version: current_version,
            latestVersion: latest_version,
            latest_version: latest_version,
            changelog: text
        });
    } catch (error) {
        const curVer = getCurrentAppVersion();
        res.json({
            available: false,
            has_update: false,
            currentVersion: curVer,
            current_version: curVer,
            version: curVer,
            latestVersion: curVer,
            latest_version: curVer,
            error: "Gagal mengecek update ke GitHub server"
        });
    }
};

