async function seedHariLiburNasional(p: mysql.Pool | mysql.PoolConnection) {
    try {
        for (const h of HARI_LIBUR_NASIONAL_DEFAULT_2026_2027) {
            const [existing]: any = await p.query(
                "SELECT id FROM kalender_akademik WHERE event_date = ? AND title = ? LIMIT 1",
                [h.event_date, h.title]
            );
            if (!existing || existing.length === 0) {
                await p.query(
                    "INSERT INTO kalender_akademik (title, event_date, end_date, description, category, is_libur) VALUES (?, ?, ?, ?, ?, 1)",
                    [h.title, h.event_date, h.event_date, h.description, h.category]
                );
            } else {
                await p.query(
                    "UPDATE kalender_akademik SET is_libur = 1, category = 'Libur Nasional' WHERE id = ?",
                    [existing[0].id]
                );
            }
        }
        console.log("[DB] Hari Libur Nasional 2026 & 2027 verified and synchronized.");
    } catch (e: any) {
        console.warn("[DB] Warning seeding hari libur nasional:", e.message);
    }
}

