async function seedMataPelajaranDefault(p: mysql.Pool | mysql.PoolConnection, force: boolean = false) {
    try {
        await p.query(`
          CREATE TABLE IF NOT EXISTS ref_mata_pelajaran (
            id INT AUTO_INCREMENT PRIMARY KEY,
            kode_mapel VARCHAR(50) DEFAULT NULL,
            nama_mapel VARCHAR(150) NOT NULL,
            kelompok VARCHAR(50) DEFAULT 'Wajib',
            bentuk_pendidikan VARCHAR(50) DEFAULT 'Semua',
            kurikulum VARCHAR(50) DEFAULT 'Semua',
            tingkat VARCHAR(50) DEFAULT 'Semua',
            rombel_id VARCHAR(36) DEFAULT NULL,
            kkm DECIMAL(5,2) DEFAULT 75.00,
            urutan INT DEFAULT 0,
            status_aktif TINYINT(1) DEFAULT 1,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
          )
        `);

        const [existing]: any = await p.query("SELECT COUNT(*) as cnt FROM ref_mata_pelajaran");
        const count = existing?.[0]?.cnt || 0;
        
        if (count === 0 || force) {
            console.log("[DB] Seeding default mata pelajaran ASTS presets...");
            for (const m of DEFAULT_MATA_PELAJARAN_PRESETS) {
                const [dup]: any = await p.query(
                    "SELECT id FROM ref_mata_pelajaran WHERE nama_mapel = ? AND bentuk_pendidikan = ? AND kurikulum = ? AND tingkat = ? AND (rombel_id IS NULL) LIMIT 1",
                    [m.nama_mapel, m.bentuk_pendidikan, m.kurikulum, m.tingkat]
                );
                if (!dup || dup.length === 0) {
                    await p.query(
                        "INSERT INTO ref_mata_pelajaran (kode_mapel, nama_mapel, kelompok, bentuk_pendidikan, kurikulum, tingkat, kkm, urutan, status_aktif) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 1)",
                        [m.kode_mapel, m.nama_mapel, m.kelompok, m.bentuk_pendidikan, m.kurikulum, m.tingkat, m.kkm, m.urutan]
                    );
                }
            }
            console.log("[DB] Default mata pelajaran ASTS successfully seeded.");
        }
    } catch (e: any) {
        console.warn("[DB] Warning seeding default mata pelajaran ASTS:", e.message);
    }
}

