app.get('/api/bantuan/pengajuan/:siswa_id/:istilah', authenticate, async (req: any, res: any) => {
    try {
        const { siswa_id, istilah } = req.params;
        
        // Fetch siswa first to get nik and Dapodik student data
        const [siswaData] = await getPool().query(`
            SELECT s.nik, s.nama as nama_lengkap, s.tempat_lahir, s.tanggal_lahir, 
            COALESCE(s.nomor_kk, s.no_kk, '') as nomor_kk, 
            s.provinsi, COALESCE(s.kabupaten_kota, s.kota, '') as kota, s.kecamatan, 
            COALESCE(s.desa_kelurahan, s.kelurahan, '') as kelurahan, 
            s.rt, s.rw, s.alamat_jalan, s.nomor_telepon_seluler,
            s.nama_ayah, s.nik_ayah, s.nama_ibu_kandung, s.nik_ibu, s.nama_wali, s.nik_wali,
            kec.nama as kecamatan_nama, kota.nama as kota_nama, prov.nama as provinsi_nama
            FROM peserta_didik s 
            LEFT JOIN ref_mst_wilayah kec ON s.kecamatan = kec.kode_wilayah
            LEFT JOIN ref_mst_wilayah kota ON kec.mst_kode_wilayah = kota.kode_wilayah
            LEFT JOIN ref_mst_wilayah prov ON kota.mst_kode_wilayah = prov.kode_wilayah
            WHERE s.peserta_didik_id = ? OR s.id = ?
        `, [siswa_id, siswa_id]);
        let nikSiswa = (siswaData as any[]).length > 0 ? (siswaData as any[])[0].nik || '' : '';

        const [existing] = await getPool().query(`
            SELECT p.*,
            kec.nama as kecamatan_nama, kota.nama as kota_nama, prov.nama as provinsi_nama
            FROM pengajuan_rekening_bantuan p
            LEFT JOIN ref_mst_wilayah kec ON p.kecamatan = kec.kode_wilayah
            LEFT JOIN ref_mst_wilayah kota ON kec.mst_kode_wilayah = kota.kode_wilayah
            LEFT JOIN ref_mst_wilayah prov ON kota.mst_kode_wilayah = prov.kode_wilayah
            WHERE p.siswa_id = ? AND p.istilah = ?
        `, [siswa_id, istilah]);
        if ((existing as any[]).length > 0) {
            let existingData = (existing as any[])[0];
            existingData.nik = existingData.nik || nikSiswa;
            return res.json(existingData);
        }
        
        let prefill = {
            nik: nikSiswa, nama_lengkap: '', tempat_lahir: '', tanggal_lahir: '', nomor_hp: '', nomor_kk: '',
            provinsi: '', kota: '', kecamatan: '', kelurahan: '', rt: '', rw: '', alamat_jalan: '',
            kecamatan_nama: '', kota_nama: '', provinsi_nama: '',
            nama_ayah: '', nik_ayah: '', nama_ibu: '', nik_ibu: '', wali: '', nik_wali: '', hubungan_wali: ''
        };
        
        if ((siswaData as any[]).length > 0) {
            const s = (siswaData as any[])[0];
            prefill.nama_lengkap = s.nama_lengkap || '';
            prefill.tempat_lahir = s.tempat_lahir || '';
            prefill.tanggal_lahir = s.tanggal_lahir ? new Date(s.tanggal_lahir).toISOString().split('T')[0] : '';
            prefill.nomor_hp = s.nomor_telepon_seluler || '';
            prefill.nomor_kk = s.nomor_kk || '';
            prefill.provinsi = s.provinsi || '';
            prefill.kota = s.kota || '';
            prefill.kecamatan = s.kecamatan || '';
            prefill.kelurahan = s.kelurahan || '';
            prefill.kecamatan_nama = s.kecamatan_nama || '';
            prefill.kota_nama = s.kota_nama || '';
            prefill.provinsi_nama = s.provinsi_nama || '';
            prefill.rt = s.rt || '';
            prefill.rw = s.rw || '';
            prefill.alamat_jalan = s.alamat_jalan || '';
            
            // Ortu data from peserta_didik
            prefill.nama_ayah = s.nama_ayah || '';
            prefill.nik_ayah = s.nik_ayah || '';
            prefill.nama_ibu = s.nama_ibu_kandung || '';
            prefill.nik_ibu = s.nik_ibu || '';
            prefill.wali = s.nama_wali || '';
            prefill.nik_wali = s.nik_wali || '';
        }

        res.json(prefill);
    } catch (err: any) {
        res.status(500).json({ error: err.message });
    }
});

app.post('/api/bantuan/pengajuan/:siswa_id/:istilah', authenticate, uploadBantuan.fields([
    { name: 'foto_ktp', maxCount: 1 },
    { name: 'foto_kk', maxCount: 1 },
    { name: 'foto_akte', maxCount: 1 },
    { name: 'foto_surat_wali', maxCount: 1 }
]), async (req: any, res: any) => {
    try {
        const { siswa_id, istilah } = req.params;
        const body = req.body;
        const files = req.files as { [fieldname: string]: Express.Multer.File[] };
        const renameFile = async (fileObj: Express.Multer.File, jenisFile: string) => {
            if (!fileObj) return undefined;
            const ext = path.extname(fileObj.originalname);
            const sanitizedNama = (body.nama_lengkap || '').replace(/[^a-z0-9]/gi, '_').toLowerCase();
            const newName = `${jenisFile}_${body.nik || 'nonik'}_${sanitizedNama}${ext}`;
            const oldPath = fileObj.path;
            const newPath = path.join(fileObj.destination, newName);
            if (fs.existsSync(oldPath)) {
                fs.renameSync(oldPath, newPath);
            }
            
            const gdLink = await uploadToGoogleDriveFallback(newPath, newName, fileObj.mimetype, 'bantuan', 'Pengajuan Bantuan - ' + jenisFile);
            if (gdLink) {
                return gdLink;
            }
            return '/uploads/bantuan/' + newName;
        };
        
        let foto_ktp = await renameFile(files['foto_ktp']?.[0], 'KTP');
        let foto_kk = await renameFile(files['foto_kk']?.[0], 'KK');
        let foto_akte = await renameFile(files['foto_akte']?.[0], 'AKTE');
        let foto_surat_wali = await renameFile(files['foto_surat_wali']?.[0], 'SURAT_WALI');
        
        const [existing] = await getPool().query('SELECT id FROM pengajuan_rekening_bantuan WHERE siswa_id = ? AND istilah = ?', [siswa_id, istilah]);
        
        if ((existing as any[]).length > 0) {
            let updateQuery = `UPDATE pengajuan_rekening_bantuan SET 
                nik=COALESCE(NULLIF(?, ''), nik), nama_lengkap=?, tempat_lahir=?, tanggal_lahir=?, 
                nama_ayah=?, nik_ayah=?, nama_ibu=?, nik_ibu=?, status_orang_tua=?,
                wali=?, nik_wali=?, hubungan_wali=?, nomor_hp=?, nomor_kk=?, 
                provinsi=?, kota=?, kecamatan=?, kelurahan=?, rt=?, rw=?, alamat_jalan=?,
                penanggung_jawab_rekening=?`;
            const params = [
                body.nik || null, body.nama_lengkap, body.tempat_lahir, body.tanggal_lahir || null,
                body.nama_ayah, body.nik_ayah, body.nama_ibu, body.nik_ibu, body.status_orang_tua || 'Lengkap',
                body.wali || body.nama_wali || null, body.nik_wali, body.hubungan_wali, body.nomor_hp, body.nomor_kk,
                body.provinsi, body.kota, body.kecamatan, body.kelurahan, body.rt, body.rw, body.alamat_jalan,
                body.penanggung_jawab_rekening
            ];
            
            if (foto_ktp) { updateQuery += ', foto_ktp=?'; params.push(foto_ktp); }
            if (foto_kk) { updateQuery += ', foto_kk=?'; params.push(foto_kk); }
            if (foto_akte) { updateQuery += ', foto_akte=?'; params.push(foto_akte); }
            if (foto_surat_wali) { updateQuery += ', foto_surat_wali=?'; params.push(foto_surat_wali); }
            if (body.status_pengajuan !== undefined) { updateQuery += ', status_pengajuan=?'; params.push(body.status_pengajuan); }

            updateQuery += ' WHERE siswa_id = ? AND istilah = ?';
            params.push(siswa_id, istilah);
            
            const safeParams = params.map(p => p === undefined ? null : p);
            await getPool().query(updateQuery, safeParams);
        } else {
                const insertParams = [
                    siswa_id, istilah, body.nama_lengkap, body.tempat_lahir, body.tanggal_lahir || null,
                    body.nama_ayah, body.nik_ayah, body.nama_ibu, body.nik_ibu, body.status_orang_tua || 'Lengkap',
                    body.wali || body.nama_wali || null, body.nik_wali, body.hubungan_wali, body.nomor_hp, body.nomor_kk,
                    body.provinsi, body.kota, body.kecamatan, body.kelurahan, body.rt, body.rw, body.alamat_jalan,
                    body.penanggung_jawab_rekening, foto_ktp || null, foto_kk || null, foto_akte || null, foto_surat_wali || null
                ].map(p => p === undefined ? null : p);
                
                await getPool().query(`INSERT INTO pengajuan_rekening_bantuan 
                (siswa_id, istilah, nama_lengkap, tempat_lahir, tanggal_lahir, 
                nama_ayah, nik_ayah, nama_ibu, nik_ibu, status_orang_tua,
                wali, nik_wali, hubungan_wali, nomor_hp, nomor_kk,
                provinsi, kota, kecamatan, kelurahan, rt, rw, alamat_jalan, 
                penanggung_jawab_rekening, foto_ktp, foto_kk, foto_akte, foto_surat_wali) 
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
                insertParams
            );
        }
        res.json({ success: true });
    } catch (err: any) {
        res.status(500).json({ error: err.message });
    }
});

