app.get('/api/bantuan/laporan_all', authenticate, async (req: any, res: any) => {
    try {
        await ensureLaporanBantuanSchema();
        const query = `
            SELECT 
                l.id,
                l.siswa_id,
                l.bantuan_id,
                COALESCE(l.tahun, p.tahun) as tahun,
                COALESCE(l.semester, p.semester) as semester,
                l.tanggal_pencairan,
                l.tanggal_penarikan,
                l.nominal,
                l.upload_foto_selfie,
                l.upload_foto_transaksi,
                l.tanda_tangan,
                l.is_editable,
                l.items_diterima,
                COALESCE(j.kategori, 'uang') as kategori_bantuan,
                p.items_barang,
                l.created_at,
                s.peserta_didik_id,
                COALESCE(s.nama, l.siswa_id) as nama_lengkap, 
                COALESCE(s.nisn, '-') as nisn, 
                rombel_data.rombel, 
                COALESCE(p.istilah, l.istilah) as jenis_bantuan, 
                COALESCE(j.nama_bantuan, p.istilah, l.istilah) as nama_bantuan,
                COALESCE(
                    NULLIF(l.upload_foto_buku_rekening, ''),
                    NULLIF(db.upload_foto_buku_rekening, '')
                ) as upload_foto_buku_rekening,
                db.nomor_rekening as nomor_rekening,
                db.bank as bank
            FROM laporan_bantuan l
            LEFT JOIN peserta_didik s ON s.peserta_didik_id = l.siswa_id
            LEFT JOIN (
                SELECT ar.peserta_didik_id, MAX(rb.nama) as rombel
                FROM anggota_rombel ar
                JOIN rombongan_belajar rb ON rb.rombongan_belajar_id = ar.rombongan_belajar_id
                WHERE (ar.soft_delete = 0 OR ar.soft_delete IS NULL OR ar.soft_delete = '0')
                GROUP BY ar.peserta_didik_id
            ) rombel_data ON rombel_data.peserta_didik_id = l.siswa_id
            LEFT JOIN penerima_bantuan p ON l.bantuan_id = p.id
            LEFT JOIN jenis_bantuan j ON j.istilah = COALESCE(NULLIF(p.istilah, ''), l.istilah)
            LEFT JOIN (
                SELECT db1.*
                FROM data_bank db1
                INNER JOIN (
                    SELECT MAX(id) as max_id FROM data_bank GROUP BY siswa_id, istilah
                ) db2 ON db1.id = db2.max_id
            ) db ON db.siswa_id = l.siswa_id AND db.istilah = COALESCE(NULLIF(p.istilah, ''), l.istilah)
            ORDER BY l.created_at DESC
        `;
        const [rows]: any = await getPool().query(query);
        
        // Post process to ensure upload_foto_buku_rekening is not duplicate selfie
        const cleanedRows = (rows || []).map((r: any) => {
            if (r.upload_foto_buku_rekening && r.upload_foto_selfie && r.upload_foto_buku_rekening === r.upload_foto_selfie) {
                return { ...r, upload_foto_buku_rekening: '' };
            }
            return r;
        });
        
        res.json(cleanedRows);
    } catch (err: any) {
        res.status(500).json({ error: err.message });
    }
});

