app.get('/api/public/bantuan/init', asyncHandler(async (req: any, res: any) => {
    const [jenis]: any = await getPool().query('SELECT istilah, nama_bantuan FROM jenis_bantuan ORDER BY nama_bantuan ASC');
    
    const [tahunRows]: any = await getPool().query('SELECT DISTINCT tahun FROM penerima_bantuan WHERE tahun IS NOT NULL AND tahun != "" ORDER BY tahun DESC');
    let tahunList = (tahunRows || []).map((r: any) => String(r.tahun).trim()).filter(Boolean);
    const currYear = String(new Date().getFullYear());
    const prevYear = String(new Date().getFullYear() - 1);
    if (!tahunList.includes(currYear)) tahunList.unshift(currYear);
    if (!tahunList.includes(prevYear)) tahunList.push(prevYear);

    let school = { school_name: 'Sekolah', logo_url: '' };
    try {
        const [rows]: any = await getPool().query('SELECT school_name, npsn, akreditasi, status_sekolah, logo_url, kop_surat_url, contact_address as address, contact_address, contact_phone, contact_email, kota, kecamatan, kelurahan, provinsi, headmaster_name, headmaster_nip FROM pengaturan_sekolah WHERE id = 1 LIMIT 1');
        if (rows && rows.length > 0) school = rows[0];
    } catch (e) {}

    res.json({
        jenis_bantuan: jenis || [],
        tahun_list: tahunList,
        school
    });
}));

app.post('/api/public/bantuan/check-student', asyncHandler(async (req: any, res: any) => {
    const { identitas, tanggal_lahir } = req.body;

    if (!identitas || !tanggal_lahir) {
        return res.status(400).json({ error: "Mohon lengkapi NISN atau NIK dan Tanggal Lahir Siswa." });
    }

    const cleanIdentitas = String(identitas).replace(/[\s-]/g, '').trim();
    const cleanTglLahir = String(tanggal_lahir).trim();

    // 1. Cari data siswa berdasarkan NISN, NIK, atau ID
    const [students]: any = await getPool().query(
        `SELECT pd.peserta_didik_id as id, pd.nama as nama_lengkap, pd.nisn, pd.nik,
                pd.tempat_lahir, DATE_FORMAT(pd.tanggal_lahir, '%Y-%m-%d') as tanggal_lahir,
                pd.nama_ibu_kandung as nama_ibu, pd.nama_ayah, pd.nomor_telepon_seluler as nomor_hp,
                DATE_FORMAT(prb.tanggal_lahir, '%Y-%m-%d') as prb_tanggal_lahir,
                rombel_data.rombel
         FROM peserta_didik pd
         LEFT JOIN (
             SELECT ar.peserta_didik_id, MAX(rb.nama) as rombel
             FROM anggota_rombel ar
             JOIN rombongan_belajar rb ON rb.rombongan_belajar_id = ar.rombongan_belajar_id
             WHERE (ar.soft_delete = 0 OR ar.soft_delete IS NULL OR ar.soft_delete = '0')
             GROUP BY ar.peserta_didik_id
         ) rombel_data ON rombel_data.peserta_didik_id = pd.peserta_didik_id
         LEFT JOIN (
             SELECT siswa_id, MAX(tanggal_lahir) as tanggal_lahir
             FROM pengajuan_rekening_bantuan
             GROUP BY siswa_id
         ) prb ON (prb.siswa_id = pd.peserta_didik_id OR prb.siswa_id = pd.id)
         WHERE (
             REPLACE(REPLACE(pd.nisn, ' ', ''), '-', '') = ? 
             OR REPLACE(REPLACE(pd.nik, ' ', ''), '-', '') = ?
             OR pd.peserta_didik_id = ?
         )
         LIMIT 1`,
        [cleanIdentitas, cleanIdentitas, cleanIdentitas]
    );

    if (!students || students.length === 0) {
        return res.status(404).json({
            error: "Data siswa dengan NISN atau NIK tersebut tidak ditemukan di sekolah. Mohon periksa kembali nomor yang Anda masukkan."
        });
    }

    const student = students[0];

    // 2. Verifikasi Tanggal Lahir Siswa (Toleran terhadap UTC vs WIB timezone shift & data pengajuan)
    let dateMatches = false;
    const inputDateStr = cleanTglLahir;
    const pdDateStr = student.tanggal_lahir;
    const prbDateStr = student.prb_tanggal_lahir;

    if (inputDateStr === pdDateStr || (prbDateStr && inputDateStr === prbDateStr)) {
        dateMatches = true;
    } else {
        const inputD = new Date(inputDateStr);
        if (!isNaN(inputD.getTime())) {
            if (pdDateStr) {
                const pdD = new Date(pdDateStr);
                if (!isNaN(pdD.getTime())) {
                    const diffDays = Math.abs((pdD.getTime() - inputD.getTime()) / (1000 * 60 * 60 * 24));
                    if (diffDays <= 2) dateMatches = true;
                }
            }
            if (!dateMatches && prbDateStr) {
                const prbD = new Date(prbDateStr);
                if (!isNaN(prbD.getTime())) {
                    const diffDays = Math.abs((prbD.getTime() - inputD.getTime()) / (1000 * 60 * 60 * 24));
                    if (diffDays <= 2) dateMatches = true;
                }
            }
        }
    }

    if (!dateMatches) {
        return res.status(400).json({
            error: "Tanggal lahir yang dimasukkan tidak sesuai dengan data siswa di sekolah. Mohon periksa kembali tanggal lahir anak Anda."
        });
    }

    // 3. Ambil seluruh data bantuan yang ada nama siswa tersebut
    const [penerimaRows]: any = await getPool().query(
        `SELECT pb.id as penerima_bantuan_id, pb.istilah, pb.tahun, pb.semester,
                pb.nominal as pb_nominal, pb.bank_rekomendasi, pb.items_barang,
                jb.nama_bantuan, jb.kategori, jb.metode_penyaluran, jb.default_nominal, jb.default_bank, jb.default_items,
                lb.id as laporan_id,
                DATE_FORMAT(lb.tanggal_pencairan, '%Y-%m-%d') as tanggal_pencairan,
                DATE_FORMAT(lb.created_at, '%d/%m/%Y %H:%i') as laporan_created_at,
                lb.nominal as laporan_nominal,
                lb.items_diterima,
                lb.is_editable,
                lb.tanda_tangan
         FROM penerima_bantuan pb
         JOIN jenis_bantuan jb ON pb.istilah = jb.istilah
         LEFT JOIN (
             SELECT id, bantuan_id, siswa_id, istilah, tahun, semester, tanggal_pencairan, created_at, nominal, items_diterima, is_editable, tanda_tangan
             FROM laporan_bantuan
             WHERE id IN (
                 SELECT MAX(id) FROM laporan_bantuan 
                 GROUP BY CASE WHEN bantuan_id IS NOT NULL AND bantuan_id > 0 THEN bantuan_id ELSE id END
             )
         ) lb ON (
             (lb.bantuan_id IS NOT NULL AND lb.bantuan_id > 0 AND lb.bantuan_id = pb.id)
             OR ((lb.siswa_id = pb.siswa_id OR lb.siswa_id = ? OR lb.siswa_id = ? OR lb.siswa_id = ?) 
                 AND (lb.istilah IS NULL OR NULLIF(TRIM(lb.istilah), '') IS NULL OR LOWER(TRIM(lb.istilah)) = LOWER(TRIM(pb.istilah))) 
                 AND (lb.tahun IS NULL OR NULLIF(TRIM(lb.tahun), '') IS NULL OR lb.tahun = pb.tahun))
         )
         WHERE (pb.siswa_id = ? OR pb.siswa_id = ? OR pb.siswa_id = ?)
         ORDER BY pb.tahun DESC, pb.semester DESC, pb.id DESC`,
        [student.id, student.nisn, student.nik, student.id, student.nisn, student.nik]
    );

    const bantuanList = (penerimaRows || []).map((pb: any) => {
        const isBarang = pb.kategori === 'barang';
        const nominalVal = pb.pb_nominal ? parseFloat(pb.pb_nominal) : (pb.default_nominal ? parseFloat(pb.default_nominal) : (pb.laporan_nominal ? parseFloat(pb.laporan_nominal) : null));
        let items = null;
        try {
            const rawIt = pb.items_barang || pb.default_items;
            if (rawIt) items = typeof rawIt === 'string' ? JSON.parse(rawIt) : rawIt;
        } catch (e) {}

        return {
            penerima_bantuan_id: pb.penerima_bantuan_id,
            istilah: pb.istilah,
            nama_bantuan: pb.nama_bantuan,
            kategori: pb.kategori || 'uang',
            metode_penyaluran: pb.metode_penyaluran || 'transfer',
            tahun: String(pb.tahun || '').trim(),
            semester: pb.semester ? String(pb.semester).trim() : null,
            nominal: nominalVal,
            bank_rekomendasi: pb.bank_rekomendasi || pb.default_bank || 'BRI',
            items_barang: items,
            sudah_lapor: !!pb.laporan_id,
            laporan_id: pb.laporan_id || null,
            tanggal_pencairan: pb.tanggal_pencairan || null,
            laporan_created_at: pb.laporan_created_at || null,
            is_editable: pb.is_editable !== undefined ? pb.is_editable : 1,
            status_text: pb.laporan_id ? 'Sudah Dilaporkan' : 'Belum Dilaporkan'
        };
    });

    res.json({
        success: true,
        siswa: student,
        bantuan_list: bantuanList
    });
}));

app.post('/api/public/bantuan/select-bantuan', asyncHandler(async (req: any, res: any) => {
    const { siswa_id, penerima_bantuan_id } = req.body;

    if (!siswa_id || !penerima_bantuan_id) {
        return res.status(400).json({ error: "Data siswa dan bantuan tidak valid." });
    }

    // 1. Ambil data siswa lengkap dengan data orang tua, nomor KK, dan kontak
    const [students]: any = await getPool().query(
        `SELECT pd.peserta_didik_id as id, pd.nama as nama_lengkap, pd.nisn, pd.nik, COALESCE(NULLIF(prb.nomor_kk, ''), pd.nomor_kk, '') as nomor_kk,
                pd.tempat_lahir, DATE_FORMAT(pd.tanggal_lahir, '%Y-%m-%d') as tanggal_lahir,
                COALESCE(NULLIF(prb.nama_ibu, ''), pd.nama_ibu_kandung, '') as nama_ibu,
                COALESCE(NULLIF(prb.nik_ibu, ''), '') as nik_ibu,
                COALESCE(NULLIF(prb.nama_ayah, ''), pd.nama_ayah, '') as nama_ayah,
                COALESCE(NULLIF(prb.nik_ayah, ''), '') as nik_ayah,
                COALESCE(NULLIF(prb.wali, ''), pd.nama_wali, '') as wali,
                COALESCE(NULLIF(prb.nik_wali, ''), '') as nik_wali,
                COALESCE(NULLIF(prb.hubungan_wali, ''), '') as hubungan_wali,
                COALESCE(NULLIF(prb.status_orang_tua, ''), 'Lengkap') as status_orang_tua,
                COALESCE(NULLIF(prb.penanggung_jawab_rekening, ''), 'Ibu') as penanggung_jawab_rekening,
                COALESCE(NULLIF(prb.nomor_hp, ''), pd.nomor_telepon_seluler, '') as nomor_hp,
                rombel_data.rombel
         FROM peserta_didik pd
         LEFT JOIN (
             SELECT ar.peserta_didik_id, MAX(rb.nama) as rombel
             FROM anggota_rombel ar
             JOIN rombongan_belajar rb ON rb.rombongan_belajar_id = ar.rombongan_belajar_id
             WHERE (ar.soft_delete = 0 OR ar.soft_delete IS NULL OR ar.soft_delete = '0')
             GROUP BY ar.peserta_didik_id
         ) rombel_data ON rombel_data.peserta_didik_id = pd.peserta_didik_id
         LEFT JOIN (
             SELECT siswa_id, istilah, nama_ibu, nik_ibu, nama_ayah, nik_ayah, wali, nik_wali, hubungan_wali, status_orang_tua, penanggung_jawab_rekening, nomor_hp, nomor_kk
             FROM pengajuan_rekening_bantuan
             ORDER BY id DESC
         ) prb ON (prb.siswa_id = pd.peserta_didik_id OR prb.siswa_id = pd.id OR prb.siswa_id = pd.nisn OR prb.siswa_id = pd.nik)
         WHERE (pd.peserta_didik_id = ? OR pd.nisn = ? OR pd.nik = ?)
           AND (pd.soft_delete = 0 OR pd.soft_delete IS NULL OR pd.soft_delete = '0')
         LIMIT 1`,
        [siswa_id, siswa_id, siswa_id]
    );

    if (!students || students.length === 0) {
        return res.status(404).json({ error: "Siswa tidak ditemukan." });
    }
    const student = students[0];

    // 2. Ambil data penerima_bantuan spesifik dengan metadata jenis_bantuan
    const [penerimaRows]: any = await getPool().query(
        `SELECT pb.id as penerima_bantuan_id, pb.istilah, pb.tahun, pb.semester,
                pb.nominal as pb_nominal, pb.bank_rekomendasi, pb.items_barang,
                jb.nama_bantuan, jb.kategori, jb.metode_penyaluran, jb.default_nominal, jb.default_bank, jb.default_items
         FROM penerima_bantuan pb
         JOIN jenis_bantuan jb ON pb.istilah = jb.istilah
         WHERE pb.id = ? AND (pb.siswa_id = ? OR pb.siswa_id = ? OR pb.siswa_id = ?)
         LIMIT 1`,
        [penerima_bantuan_id, student.id, student.nisn, student.nik]
    );

    if (!penerimaRows || penerimaRows.length === 0) {
        return res.status(404).json({ error: "Data bantuan tidak ditemukan untuk siswa ini." });
    }
    const penerimaRaw = penerimaRows[0];
    const finalNominal = penerimaRaw.pb_nominal ? parseFloat(penerimaRaw.pb_nominal) : (penerimaRaw.default_nominal ? parseFloat(penerimaRaw.default_nominal) : null);
    const finalBank = penerimaRaw.bank_rekomendasi || penerimaRaw.default_bank || 'BRI';
    let finalItems = null;
    try {
        const rawIt = penerimaRaw.items_barang || penerimaRaw.default_items;
        if (rawIt) finalItems = typeof rawIt === 'string' ? JSON.parse(rawIt) : rawIt;
    } catch (e) {}

    const penerima = {
        ...penerimaRaw,
        kategori: penerimaRaw.kategori || 'uang',
        metode_penyaluran: penerimaRaw.metode_penyaluran || 'transfer',
        nominal: finalNominal,
        bank_rekomendasi: finalBank,
        items_barang: finalItems
    };

    // 3. Ambil data rekening yang tersimpan sebelumnya di data_bank khusus istilah bantuan ini
    const [bankRows]: any = await getPool().query(
        `SELECT nomor_rekening, bank, an_rekening, upload_foto_buku_rekening 
         FROM data_bank 
         WHERE (siswa_id = ? OR siswa_id = ? OR siswa_id = ?) AND LOWER(TRIM(istilah)) = LOWER(TRIM(?)) 
         ORDER BY id DESC LIMIT 1`,
        [student.id, student.nisn, student.nik, penerima.istilah]
    );
    let existingBank = (bankRows && bankRows.length > 0) ? { ...bankRows[0] } : null;

    // 4. Ambil data laporan bantuan sebelumnya (jika ada) khusus istilah bantuan ini
    const [laporanRows]: any = await getPool().query(
        `SELECT id, bantuan_id, DATE_FORMAT(tanggal_pencairan, '%Y-%m-%d') as tanggal_pencairan,
                DATE_FORMAT(tanggal_penarikan, '%Y-%m-%d') as tanggal_penarikan,
                nominal, items_diterima, upload_foto_selfie, upload_foto_transaksi, upload_foto_buku_rekening, tanda_tangan, created_at, is_editable
         FROM laporan_bantuan 
         WHERE (siswa_id = ? OR siswa_id = ? OR siswa_id = ?) 
           AND LOWER(TRIM(istilah)) = LOWER(TRIM(?))
           AND (bantuan_id = ? OR tahun = ?)
         ORDER BY id DESC LIMIT 1`,
        [student.id, student.nisn, student.nik, penerima.istilah, penerima.penerima_bantuan_id, penerima.tahun]
    );
    const existingLaporan = (laporanRows && laporanRows.length > 0) ? laporanRows[0] : null;

    // Sinkronkan foto buku rekening dari laporan_bantuan spesifik bantuan ini jika di data_bank belum ada
    if (existingLaporan?.upload_foto_buku_rekening) {
        if (!existingBank) {
            existingBank = {
                nomor_rekening: '',
                bank: '',
                an_rekening: '',
                upload_foto_buku_rekening: existingLaporan.upload_foto_buku_rekening
            };
        } else if (!existingBank.upload_foto_buku_rekening) {
            existingBank.upload_foto_buku_rekening = existingLaporan.upload_foto_buku_rekening;
        }
    }

    // 5. Generate secure temporary token (berlaku 1 jam)
    const sessionToken = jwt.sign(
        {
            type: 'public_bantuan_session',
            siswa_id: student.id,
            nisn: student.nisn,
            penerima_bantuan_id: penerima.penerima_bantuan_id,
            istilah: penerima.istilah,
            tahun: penerima.tahun,
            semester: penerima.semester || ''
        },
        JWT_SECRET,
        { expiresIn: '1h' }
    );

    res.json({
        success: true,
        token: sessionToken,
        siswa: student,
        bantuan: penerima,
        existing_bank: existingBank,
        existing_laporan: existingLaporan
    });
}));

