app.post('/api/system/restart-pm2', authenticate, async (req: any, res: any) => {
    try {
        res.json({ success: true, message: 'Server sedang direstart. Mohon tunggu 5-10 detik.' });
        
        setTimeout(() => {
            try {
                const fsExt = require('fs');
                const path = require('path');
                // Trigger cPanel/Passenger restart (touch tmp/restart.txt)
                const tmpDir = path.join(process.cwd(), 'tmp');
                if (!fsExt.existsSync(tmpDir)) fsExt.mkdirSync(tmpDir);
                fsExt.writeFileSync(path.join(tmpDir, 'restart.txt'), String(Date.now()));
                
                console.log('[SYSTEM] Memicu restart server (PM2/cPanel)...');
                if (process.env.pm_id) {
                    require('child_process').exec(`pm2 restart ${process.env.pm_id}`, (err: any) => {
                        if (err) process.exit(1);
                    });
                } else {
                    process.exit(1);
                }
            } catch (err) {
                console.error('[SYSTEM] Restart error:', err);
            }
        }, 1000);
    } catch (error) {
        res.status(500).json({ success: false, message: error.message });
    }
});

