const handleSelfPasswordChange = async (req: any, res: any) => {
    const oldPassword = (req.body.oldPassword || req.body.old_password || req.body.password_lama || '').toString().trim();
    const newPassword = (req.body.newPassword || req.body.new_password || req.body.password_baru || '').toString().trim();

    if (!newPassword || newPassword.length < 6) {
        return res.status(400).json({ error: "Password baru minimal 6 karakter." });
    }

    if (!oldPassword) {
        return res.status(400).json({ error: "Password lama wajib diisi." });
    }

    // 1. Khusus Role Pelatih
    if (req.user.type === 'pelatih') {
        const identifier = req.user.username || String(req.user.id);
        const [authRows]: any = await getPool().execute(
            "SELECT password FROM pelatih_auth WHERE nik = ? OR nik = ? LIMIT 1",
            [identifier, String(req.user.id)]
        );
        let isMatch = false;
        if (authRows.length > 0) {
            isMatch = await bcrypt.compare(oldPassword, authRows[0].password) || (oldPassword === authRows[0].password);
        } else {
            isMatch = (oldPassword === identifier || oldPassword === String(req.user.id));
        }

        if (!isMatch) {
            return res.status(400).json({ error: "Password lama salah." });
        }

        const hashed = await bcrypt.hash(newPassword, 10);
        if (authRows.length > 0) {
            await getPool().execute(
                "UPDATE pelatih_auth SET password = ? WHERE nik = ? OR nik = ?",
                [hashed, identifier, String(req.user.id)]
            );
        } else {
            await getPool().execute(
                "INSERT INTO pelatih_auth (nik, password) VALUES (?, ?) ON DUPLICATE KEY UPDATE password = VALUES(password)",
                [identifier, hashed]
            );
        }

        try {
            await getPool().execute(
                "UPDATE pengguna_web SET password = ? WHERE username = ? OR staff_id = ?",
                [hashed, identifier, req.user.id]
            );
        } catch (e) {}

        return res.json({ success: true, message: "Password login berhasil diperbarui." });
    }

    // 2. Untuk Guru Kelas, Guru Bidang, Staff / Pegawai, Admin
    let [rows]: any = await getPool().execute(`
        SELECT wu.*, r.name as role_name 
        FROM pengguna_web wu
        LEFT JOIN peran r ON wu.role_id = r.id
        LEFT JOIN ptk p ON (wu.staff_id = p.ptk_id OR wu.staff_id = p.nik OR wu.username = p.nik OR wu.username = p.nip OR wu.username = p.nuptk)
        LEFT JOIN pegawai pg ON (wu.staff_id = pg.pegawai_id OR wu.staff_id = pg.nik OR wu.username = pg.nik OR wu.username = pg.nip OR wu.username = pg.nuptk)
        WHERE wu.id = ? 
           OR wu.username = ? 
           OR wu.staff_id = ?
           OR p.nik = ? OR p.nip = ? OR p.nuptk = ? OR p.ptk_id = ?
           OR pg.nik = ? OR pg.nip = ? OR pg.nuptk = ? OR pg.pegawai_id = ?
        ORDER BY wu.status_aktif DESC, wu.id ASC
        LIMIT 1
    `, [
        req.user.id,
        req.user.username || '',
        req.user.staff_id || req.user.id || '',
        req.user.username || '', req.user.username || '', req.user.username || '', req.user.username || '',
        req.user.username || '', req.user.username || '', req.user.username || '', req.user.username || ''
    ]);

    let matchedUser = rows.length > 0 ? rows[0] : null;

    const getValidDefaults = async (userId: any, staffId: any, uname: any) => {
        const defaults: string[] = [
            '123456',
            'password123',
            'admin123',
            'admin',
            process.env.ADMIN_PASSWORD || 'admin123'
        ];
        if (uname) defaults.push(String(uname).trim());
        if (staffId) defaults.push(String(staffId).trim());
        if (userId) defaults.push(String(userId).trim());

        const ids = [userId, staffId, uname, req.user.nik, req.user.nip, req.user.nuptk].filter(Boolean);
        if (ids.length > 0) {
            try {
                const placeholders = ids.map(() => '?').join(',');
                const [ptkRows]: any = await getPool().query(
                    `SELECT nik, nip, nuptk, tanggal_lahir FROM ptk WHERE ptk_id IN (${placeholders}) OR nik IN (${placeholders}) OR nip IN (${placeholders}) OR nuptk IN (${placeholders}) LIMIT 1`,
                    [...ids, ...ids, ...ids, ...ids]
                );
                if (ptkRows && ptkRows.length > 0) {
                    const p = ptkRows[0];
                    if (p.nik) defaults.push(String(p.nik).trim());
                    if (p.nip) defaults.push(String(p.nip).trim());
                    if (p.nuptk) defaults.push(String(p.nuptk).trim());
                    if (p.tanggal_lahir) {
                        const d = new Date(p.tanggal_lahir);
                        if (!isNaN(d.getTime())) {
                            const yyyy = d.getFullYear().toString();
                            const mm = String(d.getMonth() + 1).padStart(2, '0');
                            const dd = String(d.getDate()).padStart(2, '0');
                            defaults.push(`${yyyy}-${mm}-${dd}`);
                            defaults.push(`${dd}-${mm}-${yyyy}`);
                            defaults.push(`${dd}${mm}${yyyy}`);
                            defaults.push(`${yyyy}${mm}${dd}`);
                        }
                    }
                }
            } catch (e) {}

            try {
                const placeholders = ids.map(() => '?').join(',');
                const [pgRows]: any = await getPool().query(
                    `SELECT nik, nip, nuptk, tanggal_lahir FROM pegawai WHERE pegawai_id IN (${placeholders}) OR nik IN (${placeholders}) OR nip IN (${placeholders}) OR nuptk IN (${placeholders}) LIMIT 1`,
                    [...ids, ...ids, ...ids, ...ids]
                );
                if (pgRows && pgRows.length > 0) {
                    const p = pgRows[0];
                    if (p.nik) defaults.push(String(p.nik).trim());
                    if (p.nip) defaults.push(String(p.nip).trim());
                    if (p.nuptk) defaults.push(String(p.nuptk).trim());
                    if (p.tanggal_lahir) {
                        const d = new Date(p.tanggal_lahir);
                        if (!isNaN(d.getTime())) {
                            const yyyy = d.getFullYear().toString();
                            const mm = String(d.getMonth() + 1).padStart(2, '0');
                            const dd = String(d.getDate()).padStart(2, '0');
                            defaults.push(`${yyyy}-${mm}-${dd}`);
                            defaults.push(`${dd}-${mm}-${yyyy}`);
                            defaults.push(`${dd}${mm}${yyyy}`);
                            defaults.push(`${yyyy}${mm}${dd}`);
                        }
                    }
                }
            } catch (e) {}
        }
        return defaults.filter(Boolean);
    };

    if (matchedUser) {
        let isMatch = await bcrypt.compare(oldPassword, matchedUser.password);
        if (!isMatch && oldPassword === matchedUser.password) {
            isMatch = true;
        }

        if (!isMatch) {
            const defaults = await getValidDefaults(matchedUser.id, matchedUser.staff_id, matchedUser.username);
            if (defaults.includes(oldPassword)) {
                isMatch = true;
            }
        }

        if (!isMatch) {
            return res.status(400).json({ error: "Password lama salah." });
        }

        const hashed = await bcrypt.hash(newPassword, 10);
        await getPool().execute("UPDATE pengguna_web SET password = ? WHERE id = ?", [hashed, matchedUser.id]);
        return res.json({ success: true, message: "Password login akun berhasil diperbarui!" });
    }

    // Jika user belum ada di tabel pengguna_web (misal Guru yang login via fallback Dapodik PTK)
    const defaults = await getValidDefaults(req.user.id, req.user.staff_id, req.user.username);
    if (!defaults.includes(oldPassword)) {
        return res.status(400).json({ error: "Password lama salah." });
    }

    let roleId = 2;
    try {
        const [roleRows]: any = await getPool().query("SELECT id FROM peran WHERE name LIKE '%Guru%' OR name LIKE '%Pegawai%' LIMIT 1");
        if (roleRows && roleRows.length > 0) roleId = roleRows[0].id;
    } catch (e) {}

    const hashed = await bcrypt.hash(newPassword, 10);
    const newUsername = req.user.username || req.user.nik || req.user.nip || `guru_${Date.now()}`;
    const targetStaffId = req.user.staff_id || req.user.id || null;

    await getPool().execute(
        "INSERT INTO pengguna_web (staff_id, role_id, username, password, status_aktif) VALUES (?, ?, ?, ?, 1)",
        [targetStaffId, roleId, newUsername, hashed]
    );

    return res.json({ success: true, message: "Password login akun berhasil diperbarui!" });
};

