const formatWaliKelasWithGelar = (nama?: string, gDepan?: string, gBelakang?: string) => {
    let cleanNama = (nama || '').trim();
    if (!cleanNama) return '';
    const cleanGDepan = (gDepan || '').trim().replace(/^[-–—]+$/, '');
    const cleanGBelakang = (gBelakang || '').trim().replace(/^[-–—]+$/, '');

    let res = cleanNama;
    if (cleanGDepan && !res.toLowerCase().startsWith(cleanGDepan.toLowerCase())) {
        res = `${cleanGDepan} ${res}`;
    }
    if (cleanGBelakang && !res.toLowerCase().includes(cleanGBelakang.toLowerCase())) {
        res = `${res}, ${cleanGBelakang}`;
    }
    return res.trim();
};

const getStaffGelarMap = async (pool: any) => {
    const [ptkRows]: any = await pool.query('SELECT ptk_id, nama, nip, gelar_depan, gelar_belakang FROM ptk').catch(() => [[]]);
    const [pegRows]: any = await pool.query('SELECT pegawai_id, nama_lengkap, nip, gelar_depan, gelar_belakang FROM pegawai').catch(() => [[]]);
    const [rpfRows]: any = await pool.query(`
        SELECT rpf.ptk_id, rpf.jenjang_pendidikan_id, rpf.gelar_akademik_id, 
               ga.kode as gelar_kode, ga.posisi_gelar
        FROM rwy_pend_formal rpf
        LEFT JOIN gelar_akademik ga ON rpf.gelar_akademik_id = ga.gelar_akademik_id
        WHERE (rpf.soft_delete = 0 OR rpf.soft_delete IS NULL OR rpf.soft_delete = '0')
        ORDER BY CAST(rpf.jenjang_pendidikan_id AS UNSIGNED) DESC, rpf.tahun_lulus DESC
    `).catch(() => [[]]);

    const rpfGelarMap = new Map<string, { gDepan: string, gBelakang: string }>();
    for (const r of (rpfRows || [])) {
        const id = String(r.ptk_id || '').toLowerCase();
        if (!id) continue;
        if (!rpfGelarMap.has(id)) {
            rpfGelarMap.set(id, { gDepan: '', gBelakang: '' });
        }
        const entry = rpfGelarMap.get(id)!;
        const code = (r.gelar_kode || '').trim().replace(/^[-–—]+$/, '');
        if (code) {
            const isDepan = String(r.posisi_gelar) === '1' || code.startsWith('Dr') || code.startsWith('Prof') || code.startsWith('Drs') || code.startsWith('Dra');
            if (isDepan && !entry.gDepan) {
                entry.gDepan = code;
            } else if (!isDepan && !entry.gBelakang) {
                entry.gBelakang = code;
            }
        }
    }

    const staffMap = new Map<string, { name: string, raw_name: string, nip: string, gelar_depan: string, gelar_belakang: string }>();

    for (const p of (ptkRows || [])) {
        const id = String(p.ptk_id || '').toLowerCase();
        if (!id) continue;
        const rpf = rpfGelarMap.get(id) || { gDepan: '', gBelakang: '' };
        const gd = (p.gelar_depan && p.gelar_depan !== '-') ? p.gelar_depan : rpf.gDepan;
        const gb = (p.gelar_belakang && p.gelar_belakang !== '-') ? p.gelar_belakang : rpf.gBelakang;
        const formatted = formatWaliKelasWithGelar(p.nama, gd, gb);
        staffMap.set(id, { name: formatted, raw_name: p.nama, nip: p.nip || '', gelar_depan: gd, gelar_belakang: gb });
    }

    for (const s of (pegRows || [])) {
        const id = String(s.pegawai_id || '').toLowerCase();
        if (!id) continue;
        const rpf = rpfGelarMap.get(id) || { gDepan: '', gBelakang: '' };
        const gd = (s.gelar_depan && s.gelar_depan !== '-') ? s.gelar_depan : rpf.gDepan;
        const gb = (s.gelar_belakang && s.gelar_belakang !== '-') ? s.gelar_belakang : rpf.gBelakang;
        const formatted = formatWaliKelasWithGelar(s.nama_lengkap, gd, gb);
        staffMap.set(id, { name: formatted, raw_name: s.nama_lengkap, nip: s.nip || '', gelar_depan: gd, gelar_belakang: gb });
    }

    return staffMap;
};

const getTingkatNumber = (r: any) => {
    // 1. Try tingkat_pendidikan_id / tingkat
    const tStr = String(r.tingkat_pendidikan_id || r.tingkat || '').trim();
    const tNum = parseInt(tStr.replace(/\D/g, ''), 10);
    if (!isNaN(tNum) && tNum > 0) return tNum;

    // 2. Extract roman numeral or number from class name (e.g. "Kelas 1A" -> 1, "VI-A" -> 6)
    const nameStr = String(r.nama || r.name || '').trim();
    const matchRoman = nameStr.match(/^(?:kelas\s+)?(XII|XI|X|IX|VIII|VII|VI|V|IV|III|II|I)\b/i);
    if (matchRoman) {
        const romanMap: Record<string, number> = { 'I': 1, 'II': 2, 'III': 3, 'IV': 4, 'V': 5, 'VI': 6, 'VII': 7, 'VIII': 8, 'IX': 9, 'X': 10, 'XI': 11, 'XII': 12 };
        return romanMap[matchRoman[1].toUpperCase()] || 0;
    }
    const matchNum = nameStr.match(/^(?:kelas\s+)?(\d+)/i);
    if (matchNum) {
        return parseInt(matchNum[1], 10) || 0;
    }
    return 0;
};

const normalizeRombelKey = (name: string): string => {
    return String(name || '').toLowerCase().replace(/[\s\-_]+/g, '').replace(/^kelas/i, '');
};

const getRombonganBelajarData = async (pool: any, whereClause: string = "", params: any[] = []) => {
    const staffMap = await getStaffGelarMap(pool);
    try {
        // 1. Dapatkan target semester aktif dari pengaturan_sekolah atau semester_id terbaru di rombongan_belajar
        let activeSemesterId = '';
        try {
            const [settingsRows]: any = await pool.query("SELECT tahun_ajaran, semester_aktif FROM pengaturan_sekolah LIMIT 1");
            if (settingsRows && settingsRows[0]) {
                const thn = String(settingsRows[0].tahun_ajaran || '').trim();
                const sem = String(settingsRows[0].semester_aktif || '').trim();
                const startYear = thn.split('/')[0]?.trim();
                if (startYear) {
                    activeSemesterId = `${startYear}${sem.includes('2') || sem.toLowerCase().includes('genap') ? '2' : '1'}`;
                }
            }
        } catch (e) {}

        let maxSemesterId = '';
        try {
            const [maxSem]: any = await pool.query(
                "SELECT MAX(semester_id) as max_sem FROM rombongan_belajar WHERE (soft_delete = 0 OR soft_delete IS NULL OR soft_delete = '0' OR soft_delete = '') AND semester_id IS NOT NULL AND semester_id != ''"
            );
            if (maxSem && maxSem[0]?.max_sem) {
                maxSemesterId = String(maxSem[0].max_sem).trim();
            }
        } catch (e) {}

        const targetSemester = activeSemesterId || maxSemesterId;

        // 2. Query seluruh kandidat rombel aktif beserta rincian wali kelas & jumlah siswa
        const [rawRows]: any = await pool.query(`
            SELECT r.*, 
                   COALESCE(r.nama, '') as name, 
                   r.rombongan_belajar_id as id, 
                   COALESCE(p.nama, s.nama_lengkap) as raw_wali_kelas, 
                   COALESCE(p.nip, s.nip, '') as wali_kelas_nip,
                   (SELECT COUNT(DISTINCT pd.peserta_didik_id) 
                    FROM anggota_rombel ar 
                    JOIN peserta_didik pd ON (ar.peserta_didik_id = pd.peserta_didik_id OR ar.peserta_didik_id = pd.id) 
                    WHERE ar.rombongan_belajar_id = r.rombongan_belajar_id 
                      AND (ar.soft_delete = 0 OR ar.soft_delete IS NULL OR ar.soft_delete = '0') 
                      AND (pd.soft_delete = 0 OR pd.soft_delete IS NULL OR pd.soft_delete = '0') 
                      AND UPPER(pd.jenis_kelamin) = 'L') as count_l,
                   (SELECT COUNT(DISTINCT pd.peserta_didik_id) 
                    FROM anggota_rombel ar 
                    JOIN peserta_didik pd ON (ar.peserta_didik_id = pd.peserta_didik_id OR ar.peserta_didik_id = pd.id) 
                    WHERE ar.rombongan_belajar_id = r.rombongan_belajar_id 
                      AND (ar.soft_delete = 0 OR ar.soft_delete IS NULL OR ar.soft_delete = '0') 
                      AND (pd.soft_delete = 0 OR pd.soft_delete IS NULL OR pd.soft_delete = '0') 
                      AND UPPER(pd.jenis_kelamin) = 'P') as count_p,
                   (SELECT COUNT(DISTINCT pd.peserta_didik_id) 
                    FROM anggota_rombel ar 
                    JOIN peserta_didik pd ON (ar.peserta_didik_id = pd.peserta_didik_id OR ar.peserta_didik_id = pd.id) 
                    WHERE ar.rombongan_belajar_id = r.rombongan_belajar_id 
                      AND (ar.soft_delete = 0 OR ar.soft_delete IS NULL OR ar.soft_delete = '0') 
                      AND (pd.soft_delete = 0 OR pd.soft_delete IS NULL OR pd.soft_delete = '0')) as student_count
            FROM rombongan_belajar r
            LEFT JOIN ptk p ON (r.ptk_id = p.ptk_id OR r.wali_kelas_id = p.ptk_id)
            LEFT JOIN pegawai s ON (r.wali_kelas_id = s.pegawai_id OR r.ptk_id = s.pegawai_id)
            WHERE (r.soft_delete = 0 OR r.soft_delete IS NULL OR r.soft_delete = '0' OR r.soft_delete = '')
        `);

        // 3. Normalisasi & Pengelompokan Cerdas (Deduplikasi Mutlak & Isolasi Semester Aktif)
        const groups = new Map<string, any[]>();
        for (const r of (rawRows || [])) {
            const rawName = String(r.nama || r.name || '').trim();
            if (!rawName) continue;
            const key = normalizeRombelKey(rawName);
            if (!groups.has(key)) groups.set(key, []);
            groups.get(key)!.push(r);
        }

        const finalResult: any[] = [];
        for (const [key, candidates] of groups) {
            let poolForGroup = candidates;
            if (targetSemester) {
                const inTarget = candidates.filter((c: any) => String(c.semester_id || '').trim() === targetSemester);
                if (inTarget.length > 0) {
                    poolForGroup = inTarget;
                } else {
                    // Jika rombel ini tidak ada di semester aktif, periksa apakah rombel manual (tanpa semester_id)
                    const unassigned = candidates.filter((c: any) => !c.semester_id || String(c.semester_id).trim() === '');
                    if (unassigned.length > 0) {
                        poolForGroup = unassigned;
                    } else {
                        // Hanya ada di semester sebelumnya! Skip rombel ini agar rombel lampau tidak bocor ke tahun ajaran aktif berjalan
                        continue;
                    }
                }
            }

            // Urutkan kandidat dalam grup untuk memilih record yang paling representatif & lengkap
            poolForGroup.sort((a: any, b: any) => {
                // 1. Jumlah siswa tertinggi
                const countDiff = (Number(b.student_count) || 0) - (Number(a.student_count) || 0);
                if (countDiff !== 0) return countDiff;

                // 2. Wali kelas terisi
                const aHasWali = (a.ptk_id || a.wali_kelas_id || a.raw_wali_kelas) ? 1 : 0;
                const bHasWali = (b.ptk_id || b.wali_kelas_id || b.raw_wali_kelas) ? 1 : 0;
                if (bHasWali !== aHasWali) return bHasWali - aHasWali;

                // 3. Semester terbaru
                const semDiff = (parseInt(String(b.semester_id || '0')) || 0) - (parseInt(String(a.semester_id || '0')) || 0);
                if (semDiff !== 0) return semDiff;

                // 4. Update / last_sync / create_date terbaru
                return String(b.last_sync || b.create_date || '').localeCompare(String(a.last_sync || a.create_date || ''));
            });

            const chosen = { ...poolForGroup[0] };
            const teacher = staffMap.get(String(chosen.ptk_id || chosen.wali_kelas_id || '').toLowerCase());
            chosen.wali_kelas_name = teacher ? teacher.name : (chosen.raw_wali_kelas || null);
            chosen.wali_kelas_nip = teacher ? teacher.nip : (chosen.wali_kelas_nip || '');
            chosen.gelar_depan = teacher ? teacher.gelar_depan : '';
            chosen.gelar_belakang = teacher ? teacher.gelar_belakang : '';
            chosen.tingkat = chosen.tingkat_pendidikan_id || chosen.tingkat || String(getTingkatNumber(chosen));
            finalResult.push(chosen);
        }

        // 4. Filter jika ada pembatasan hak akses guru/wali kelas tertentu
        let filtered = finalResult;
        if (whereClause && params.length > 0) {
            const staffIdLower = String(params[0] || '').toLowerCase();
            filtered = finalResult.filter((r: any) => 
                String(r.ptk_id || '').toLowerCase() === staffIdLower ||
                String(r.wali_kelas_id || '').toLowerCase() === staffIdLower
            );
        }

        // 5. Urutkan berdasarkan tingkat, lalu nama rombel secara natural
        filtered.sort((a: any, b: any) => {
            const tDiff = getTingkatNumber(a) - getTingkatNumber(b);
            if (tDiff !== 0) return tDiff;
            return String(a.nama || a.name || '').localeCompare(String(b.nama || b.name || ''), 'id', { numeric: true, sensitivity: 'base' });
        });

        return filtered;
    } catch (err: any) {
        console.warn("[getRombonganBelajarData] Error in query, using safe fallback:", err.message);
        try {
            const [basicRows]: any = await pool.query("SELECT *, nama as name, rombongan_belajar_id as id FROM rombongan_belajar WHERE (soft_delete = 0 OR soft_delete IS NULL OR soft_delete = '0')");
            const res = basicRows || [];
            res.sort((a: any, b: any) => {
                const tDiff = getTingkatNumber(a) - getTingkatNumber(b);
                if (tDiff !== 0) return tDiff;
                return String(a.nama || a.name || '').localeCompare(String(b.nama || b.name || ''), 'id', { numeric: true, sensitivity: 'base' });
            });
            return res;
        } catch (e2) {
            return [];
        }
    }
};

