app.get('/api/wilayah/resolve/:kode', authenticate, asyncHandler(async (req: any, res: any) => {
    try {
        let currentKode = req.params.kode;
        let result = [];
        for (let i = 0; i < 3; i++) {
            if (!currentKode || currentKode.length < 4) break;
            const [rows]: any = await getPool().execute("SELECT nama, mst_kode_wilayah FROM ref_mst_wilayah WHERE kode_wilayah = ?", [currentKode]);
            if (rows.length > 0) {
                result.unshift(rows[0].nama);
                currentKode = (rows[0].mst_kode_wilayah || "").trim();
            } else {
                break;
            }
        }
        res.json({ nama: result.join(', ') });
    } catch (err) {
        res.json({ nama: req.params.kode });
    }
}));

