app.put("/api/pegawai/:id", authenticate, asyncHandler(async (req: any, res: any) => {
    const { 
        nama_lengkap, nuptk, jenis_kelamin, nip, nik, tempat_lahir, tanggal_lahir, 
        status_kepegawaian, jenis_ptk, gelar_depan, gelar_belakang, jenjang_pendidikan, 
        jurusan_prodi, sertifikasi, tmt_kerja, jabatan_ptk, tugas_tambahan, 
        mengajar, jam_tugas_tambahan, jjm, total_jjm, siswa, kompetensi 
    } = req.body;
    const { id } = req.params;

    if (!nama_lengkap) return res.status(400).json({ error: "Nama lengkap harus diisi" });

    const cleanPegawai = (v: any) => {
        if (typeof v === 'string') {
            const t = v.trim();
            return (t === '' || t === '-') ? null : t;
        }
        return (v === undefined || v === null) ? null : v;
    };

    const gDepanVal = (gelar_depan !== undefined)
        ? ((gelar_depan && String(gelar_depan).trim() !== '' && String(gelar_depan).trim() !== '-') ? String(gelar_depan).trim() : '-')
        : '-';
    const gBelakangVal = (gelar_belakang !== undefined)
        ? ((gelar_belakang && String(gelar_belakang).trim() !== '' && String(gelar_belakang).trim() !== '-') ? String(gelar_belakang).trim() : '-')
        : '-';

    const cleanNum = (v: any) => {
        if (v === undefined || v === null || v === '') return 0;
        const n = parseInt(v, 10);
        return isNaN(n) ? 0 : n;
    };

    try {
        const pool = getPool();
        const connection = await pool.getConnection();
        await connection.beginTransaction();

        try {
            await connection.execute(
                `UPDATE ptk SET 
                    nama = ?, nuptk = ?, jenis_kelamin = ?, nip = ?, nik = ?, tempat_lahir = ?, 
                    tanggal_lahir = ?, status_kepegawaian = ?, jenis_ptk = ?, jabatan_ptk = ?, 
                    gelar_depan = ?, gelar_belakang = ?, jenjang_pendidikan = ?, jurusan_prodi = ?, 
                    sertifikasi = ?, tmt_kerja = ?, tugas_tambahan = ?, mengajar = ?, 
                    jam_tugas_tambahan = ?, jjm = ?, total_jjm = ?, siswa = ?, kompetensi = ?
                WHERE ptk_id = ? OR nip = ? OR nik = ?`,
                [
                    nama_lengkap, 
                    cleanPegawai(nuptk), 
                    cleanPegawai(jenis_kelamin), 
                    cleanPegawai(nip), 
                    cleanPegawai(nik), 
                    cleanPegawai(tempat_lahir), 
                    cleanPegawai(tanggal_lahir), 
                    status_kepegawaian || 'Honorer', 
                    cleanPegawai(jenis_ptk), 
                    cleanPegawai(jabatan_ptk) || cleanPegawai(jenis_ptk), 
                    gDepanVal, 
                    gBelakangVal,
                    cleanPegawai(jenjang_pendidikan),
                    cleanPegawai(jurusan_prodi),
                    cleanPegawai(sertifikasi),
                    cleanPegawai(tmt_kerja),
                    cleanPegawai(tugas_tambahan),
                    cleanPegawai(mengajar),
                    cleanNum(jam_tugas_tambahan),
                    cleanNum(jjm),
                    cleanNum(total_jjm),
                    cleanNum(siswa),
                    cleanPegawai(kompetensi),
                    id, id, id
                ]
            );

            // Sinkronkan ke tabel legacy pegawai jika ada
            await connection.execute(
                `UPDATE pegawai SET 
                    nama_lengkap = ?, nuptk = ?, jenis_kelamin = ?, nip = ?, nik = ?, tempat_lahir = ?, 
                    tanggal_lahir = ?, status_kepegawaian = ?, jenis_ptk = ?, jabatan_ptk = ?, 
                    gelar_depan = ?, gelar_belakang = ?, jenjang_pendidikan = ?, jurusan_prodi = ?, 
                    sertifikasi = ?, tmt_kerja = ?, tugas_tambahan = ?, mengajar = ?, 
                    jam_tugas_tambahan = ?, jjm = ?, total_jjm = ?, siswa = ?, kompetensi = ?
                WHERE pegawai_id = ? OR ptk_id = ? OR id = ? OR nip = ? OR nik = ?`,
                [
                    nama_lengkap, 
                    cleanPegawai(nuptk), 
                    cleanPegawai(jenis_kelamin), 
                    cleanPegawai(nip), 
                    cleanPegawai(nik), 
                    cleanPegawai(tempat_lahir), 
                    cleanPegawai(tanggal_lahir), 
                    status_kepegawaian || 'Honorer', 
                    cleanPegawai(jenis_ptk), 
                    cleanPegawai(jabatan_ptk) || cleanPegawai(jenis_ptk), 
                    gDepanVal, 
                    gBelakangVal,
                    cleanPegawai(jenjang_pendidikan),
                    cleanPegawai(jurusan_prodi),
                    cleanPegawai(sertifikasi),
                    cleanPegawai(tmt_kerja),
                    cleanPegawai(tugas_tambahan),
                    cleanPegawai(mengajar),
                    cleanNum(jam_tugas_tambahan),
                    cleanNum(jjm),
                    cleanNum(total_jjm),
                    cleanNum(siswa),
                    cleanPegawai(kompetensi),
                    id, id, id, id, id
                ]
            ).catch(() => {});

            // Update / clear riwayat gelar
            if (gBelakangVal === '-') {
                try {
                    await connection.execute(`UPDATE rwy_pend_formal SET gelar_akademik_id = NULL WHERE ptk_id = ?`, [id]);
                } catch (e) {}
            } else {
                try {
                    const [gaRows]: any = await connection.execute("SELECT gelar_akademik_id FROM gelar_akademik WHERE LOWER(kode) = ? OR LOWER(nama) = ? LIMIT 1", [gBelakangVal.toLowerCase(), gBelakangVal.toLowerCase()]);
                    if (gaRows && gaRows.length > 0) {
                        await connection.execute("UPDATE rwy_pend_formal SET gelar_akademik_id = ? WHERE ptk_id = ? ORDER BY tahun_lulus DESC LIMIT 1", [gaRows[0].gelar_akademik_id, id]);
                    }
                } catch (e) {}
            }

            // Update riwayat pendidikan (only mapping jenjang_pendidikan to rwy_jenjang_id since it's most common)
            if (jenjang_pendidikan) {
                const revMap:any = {'Tidak sekolah':'1', 'PAUD':'2', 'TK / sederajat':'3', 'SD / sederajat':'4', 'SMP / sederajat':'5', 'SMA / sederajat':'6', 'Paket A':'7', 'Paket B':'8', 'Paket C':'9', 'D1':'20', 'D2':'21', 'D3':'22', 'D4':'23', 'S1':'30', 'S2':'35', 'S3':'40'};
                const jenjangId = revMap[jenjang_pendidikan];
                if (jenjangId) {
                    await connection.execute(`
                        UPDATE rwy_pend_formal SET jenjang_pendidikan_id = ? 
                        WHERE ptk_id = ? ORDER BY tahun_lulus DESC LIMIT 1
                    `, [jenjangId, id]);
                }
            }

            // Update riwayat sertifikasi
            if (sertifikasi) {
                const revCert:any = {'Sertifikasi Pendidik':'1', 'Keahlian Tingkat 1':'2'};
                const certId = revCert[sertifikasi];
                if (certId) {
                    await connection.execute(`
                        UPDATE rwy_sertifikasi SET id_jenis_sertifikasi = ? 
                        WHERE ptk_id = ? LIMIT 1
                    `, [certId, id]);
                }
            }
            await connection.commit();
        } catch (e) {
            await connection.rollback();
            throw e;
        } finally {
            connection.release();
        }
        res.json({ success: true });
    } catch (err: any) {
        if (err.code === 'ER_DUP_ENTRY') return res.status(400).json({ error: 'NIK atau NIP sudah terdaftar' });
        throw err;
    }
}));

