app.get("/api/pegawai/search", authenticate, asyncHandler(async (req: any, res: any) => {
    const q = (req.query.q || '').toString().toLowerCase();
    const ptkMap = await loadResolvedPtkMap();
    const uniqueList = Array.from(new Set(Object.values(ptkMap)));
    const matched = uniqueList.filter((p: any) => {
        const name = (p.fullName || p.nama || '').toLowerCase();
        const nip = (p.nip || '').toLowerCase();
        const nik = (p.nik || '').toLowerCase();
        return name.includes(q) || nip.includes(q) || nik.includes(q);
    }).slice(0, 10).map((p: any) => ({
        id: p.ptk_id || p.pegawai_id,
        ptk_id: p.ptk_id,
        name: p.fullName || p.nama,
        nama_lengkap: p.fullName || p.nama,
        nama: p.nama,
        nip: p.nip || '',
        nik: p.nik || '',
        gelar_depan: p.gelar_depan || '',
        gelar_belakang: p.gelar_belakang || '',
        jabatan_ptk: p.jenis_ptk || ''
    }));
    res.json(matched);
}));

app.get("/api/pengguna_web", authenticate, asyncHandler(async (req: any, res: any) => {
    let rows: any[] = [];
    try {
        const [queryRows]: any = await getPool().execute(`
            SELECT wu.*, r.name as role_name 
            FROM pengguna_web wu
            LEFT JOIN peran r ON wu.role_id = r.id
            ORDER BY wu.id DESC
        `);
        rows = queryRows || [];
    } catch (e) {
        return res.json([]);
    }

    const ptkMap = await loadResolvedPtkMap();
    const result = [];
    for (const u of rows) {
        const trimmedUsername = String(u.username || '').trim();
        const p = (u.staff_id ? ptkMap[String(u.staff_id).trim()] : null) || (trimmedUsername ? ptkMap[trimmedUsername] : null);
        
        let finalName = '';
        if (p) {
            finalName = p.fullName || p.nama || '';
            // Auto-heal link staff_id if it was NULL or empty
            if (!u.staff_id && p.ptk_id) {
                try {
                    await getPool().execute("UPDATE pengguna_web SET staff_id = ?, nama_lengkap = ? WHERE id = ?", [p.ptk_id, finalName, u.id]);
                    u.staff_id = p.ptk_id;
                } catch (eHeal) {}
            }
        }
        
        if (!finalName) {
            finalName = (u.nama_lengkap && String(u.nama_lengkap).trim() !== '' && u.nama_lengkap !== u.username) 
                ? u.nama_lengkap 
                : (u.username === 'admin' ? 'Administrator' : (u.nama_lengkap || u.username || 'User'));
        }

        result.push({
            ...u,
            nama_lengkap: finalName,
            resolved_nama_pegawai: p?.fullName || p?.nama || '',
            nip_pegawai: p?.nip || '',
            nik_pegawai: p?.nik || '',
            jabatan_pegawai: p?.jenis_ptk || '',
            is_matched_ptk: Boolean(p)
        });
    }
    res.json(result);
}));

app.post("/api/pengguna_web", authenticate, asyncHandler(async (req: any, res: any) => {
    const { staff_id, role_id, username, password, is_elearning_admin, nama_lengkap } = req.body;
    const hashedPassword = await bcrypt.hash(password, 10);
    const isAdmin = is_elearning_admin ? 1 : 0;
    
    let resolvedStaffId = clean(staff_id);
    let resolvedName = clean(nama_lengkap);

    // Auto lookup PTK if staff_id is empty but username matches NIK
    if (username) {
        try {
            const ptkMap = await loadResolvedPtkMap();
            const matched = ptkMap[String(username).trim()];
            if (matched) {
                if (!resolvedStaffId) resolvedStaffId = matched.ptk_id || null;
                if (!resolvedName) resolvedName = matched.fullName || matched.nama;
            }
        } catch (eLookup) {}
    }

    await getPool().execute(
        "INSERT INTO pengguna_web (staff_id, role_id, username, password, is_elearning_admin, nama_lengkap) VALUES (?, ?, ?, ?, ?, ?)", 
        [resolvedStaffId, clean(role_id), clean(username), hashedPassword, isAdmin, resolvedName]
    );
    res.json({ success: true });
}));

