app.put("/api/pengguna_web/:id", authenticate, asyncHandler(async (req: any, res: any) => {
    const isCallerSuperadmin = (req.user?.role?.toLowerCase() === 'superadmin' || req.user?.role_name?.toLowerCase() === 'superadmin' || (req.user?.permissions && req.user.permissions.includes('all')));
    
    const [user]: any = await getPool().execute(
        "SELECT r.name, pw.username FROM pengguna_web pw LEFT JOIN peran r ON pw.role_id = r.id WHERE pw.id = ?",
        [req.params.id]
    );
    if (user.length === 0) return res.status(404).json({ error: "User tidak ditemukan" });

    const targetIsSuperadmin = user[0].name && user[0].name.toLowerCase() === 'superadmin';
    if (targetIsSuperadmin && !isCallerSuperadmin) {
        return res.status(403).json({ error: "Hanya Superadmin yang berhak mengedit akun Superadmin" });
    }

    const { username, role_id, password, is_elearning_admin, status_aktif, nama_lengkap, staff_id } = req.body;
    
    if (username) {
        const [existing]: any = await getPool().execute(
            "SELECT id FROM pengguna_web WHERE username = ? AND id != ?",
            [username, req.params.id]
        );
        if (existing.length > 0) {
            return res.status(400).json({ error: "Username sudah digunakan oleh akun lain" });
        }
    }

    const updates: string[] = [];
    const values: any[] = [];

    if (username !== undefined && username !== null) {
        updates.push("username = ?");
        values.push(clean(username));
    }
    if (nama_lengkap !== undefined && nama_lengkap !== null) {
        updates.push("nama_lengkap = ?");
        values.push(clean(nama_lengkap));
    }
    if (staff_id !== undefined) {
        updates.push("staff_id = ?");
        values.push(clean(staff_id));
    }
    if (role_id !== undefined && role_id !== null && role_id !== '') {
        updates.push("role_id = ?");
        values.push(clean(role_id));
    }
    if (is_elearning_admin !== undefined) {
        updates.push("is_elearning_admin = ?");
        values.push(is_elearning_admin ? 1 : 0);
    }
    if (status_aktif !== undefined) {
        updates.push("status_aktif = ?");
        values.push(status_aktif ? 1 : 0);
    }
    if (password && String(password).trim() !== '') {
        const hashedPassword = await bcrypt.hash(String(password).trim(), 10);
        updates.push("password = ?");
        values.push(hashedPassword);
    }

    if (updates.length > 0) {
        values.push(req.params.id);
        await getPool().execute(`UPDATE pengguna_web SET ${updates.join(", ")} WHERE id = ?`, values);
    }

    res.json({ success: true, message: "Data user berhasil diperbarui" });
}));

