app.post("/api/pengguna_web/:id/reset-password", authenticate, asyncHandler(async (req: any, res: any) => {
    const isCallerSuperadmin = (req.user?.role?.toLowerCase() === 'superadmin' || req.user?.role_name?.toLowerCase() === 'superadmin' || (req.user?.permissions && req.user.permissions.includes('all')));
    const { password, useNik } = req.body;
    let newPassword = password;
    
    const [user]: any = await getPool().execute(
        "SELECT pw.username, pw.staff_id, r.name FROM pengguna_web pw LEFT JOIN peran r ON pw.role_id = r.id WHERE pw.id = ?",
        [req.params.id]
    );
    
    if (user.length === 0) return res.status(404).json({ error: "User tidak ditemukan" });

    const targetIsSuperadmin = user[0].name && user[0].name.toLowerCase() === 'superadmin';
    if (targetIsSuperadmin && !isCallerSuperadmin) {
        return res.status(403).json({ error: "Hanya Superadmin yang berhak mereset password Superadmin" });
    }

    if (useNik) {
        const ptkMap = await loadResolvedPtkMap();
        const p = user[0].staff_id ? ptkMap[String(user[0].staff_id)] : null;
        const nik = p?.nik;
        if (!nik) return res.status(400).json({ error: "Pegawai ini tidak memiliki NIK yang valid pada database" });
        newPassword = nik;
    }

    if (!newPassword) return res.status(400).json({ error: "Password diperlukan" });
    
    const hashedPassword = await bcrypt.hash(newPassword, 10);
    await getPool().execute("UPDATE pengguna_web SET password = ? WHERE id = ?", [hashedPassword, req.params.id]);
    res.json({ success: true, message: "Password berhasil direset" });
}));


