app.post("/api/pengajuan_ubah_data/:id/approve", authenticate, asyncHandler(async (req: any, res: any) => {
    const { id } = req.params;
    const [requestRows]: any = await getPool().execute("SELECT * FROM pengajuan_ubah_data WHERE id = ?", [id]);
    if (requestRows.length === 0) return res.status(404).json({ error: "Request not found" });
    
    const request = requestRows[0];
    const proposedData = JSON.parse(request.proposed_data);
    
    // Build update query dynamically for student table
    const fields = Object.keys(proposedData);
    const values = Object.values(proposedData);
    const setClause = fields.map(f => `${f} = ?`).join(", ");
    
    await getPool().execute(
        `UPDATE peserta_didik SET ${setClause} WHERE id = ?`,
        [...values, request.student_id]
    );
    
    await getPool().execute(
        "UPDATE pengajuan_ubah_data SET status = 'approved' WHERE id = ?",
        [id]
    );
    
    res.json({ success: true });
}));

