app.post("/api/login", asyncHandler(async (req: any, res: any) => {
    const { username, password, type } = req.body;
    const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress || 'unknown';
    const ua = req.headers['user-agent'] || 'unknown';

    const safeLogLogin = async (logData: { type?: string; username?: string; status?: string; user_id?: any; student_id?: any }) => {
        try {
            if (logData.user_id) {
                await getPool().execute(
                    "INSERT INTO riwayat_masuk (user_id, type, username, ip_address, user_agent, status) VALUES (?, ?, ?, ?, ?, ?)",
                    [logData.user_id, logData.type || 'staff', logData.username || username, ip, ua, logData.status || 'success']
                );
            } else if (logData.student_id) {
                await getPool().execute(
                    "INSERT INTO riwayat_masuk (student_id, type, username, ip_address, user_agent, status) VALUES (?, ?, ?, ?, ?, ?)",
                    [logData.student_id, logData.type || 'student', logData.username || username, ip, ua, logData.status || 'success']
                );
            } else {
                await getPool().execute(
                    "INSERT INTO riwayat_masuk (type, username, ip_address, user_agent, status) VALUES (?, ?, ?, ?, ?)",
                    [logData.type || type || 'unknown', logData.username || username || 'unknown', ip, ua, logData.status || 'failed']
                );
            }
        } catch (e: any) {
            // Logging failure should never crash the login endpoint
            console.error("[Login] Audit log error (ignored):", e.message);
        }
    };

    const resolveTeacherPersona = async (teacherId: string, teacherName: string, candidateInputs: string[] = []) => {
        try {
            const allInputs = [teacherId, ...candidateInputs].filter(Boolean);
            
            // 1. Find PTK record
            let ptkRecord: any = null;
            for (const inp of allInputs) {
                const [rows]: any = await getPool().query(
                    `SELECT ptk_id, nama, nik, nip, nuptk, jenis_ptk, jabatan_ptk, mengajar FROM ptk 
                     WHERE ptk_id = ? OR nik = ? OR nip = ? OR nuptk = ? LIMIT 1`,
                    [inp, inp, inp, inp]
                ).catch(() => [[]]);
                if (rows && rows.length > 0) {
                    ptkRecord = rows[0];
                    break;
                }
            }
            if (!ptkRecord && teacherName) {
                const [rows]: any = await getPool().query(
                    `SELECT ptk_id, nama, nik, nip, nuptk, jenis_ptk, jabatan_ptk, mengajar FROM ptk 
                     WHERE nama = ? OR nama LIKE ? LIMIT 1`,
                    [teacherName, `%${teacherName}%`]
                ).catch(() => [[]]);
                if (rows && rows.length > 0) ptkRecord = rows[0];
            }

            // 2. Find Pegawai record
            let pgRecord: any = null;
            for (const inp of allInputs) {
                const [rows]: any = await getPool().query(
                    `SELECT pegawai_id, nama_lengkap, nik, nip, nuptk, jenis_ptk, jabatan_ptk, mengajar FROM pegawai 
                     WHERE pegawai_id = ? OR nik = ? OR nip = ? OR nuptk = ? LIMIT 1`,
                    [inp, inp, inp, inp]
                ).catch(() => [[]]);
                if (rows && rows.length > 0) {
                    pgRecord = rows[0];
                    break;
                }
            }
            if (!pgRecord && teacherName) {
                const [rows]: any = await getPool().query(
                    `SELECT pegawai_id, nama_lengkap, nik, nip, nuptk, jenis_ptk, jabatan_ptk, mengajar FROM pegawai 
                     WHERE nama_lengkap = ? OR nama_lengkap LIKE ? LIMIT 1`,
                    [teacherName, `%${teacherName}%`]
                ).catch(() => [[]]);
                if (rows && rows.length > 0) pgRecord = rows[0];
            }

            const allIds = new Set([teacherId]);
            if (ptkRecord) {
                if (ptkRecord.ptk_id) allIds.add(ptkRecord.ptk_id);
                if (ptkRecord.nik) allIds.add(ptkRecord.nik);
                if (ptkRecord.nip) allIds.add(ptkRecord.nip);
                if (ptkRecord.nuptk) allIds.add(ptkRecord.nuptk);
            }
            if (pgRecord) {
                if (pgRecord.pegawai_id) allIds.add(pgRecord.pegawai_id);
                if (pgRecord.nik) allIds.add(pgRecord.nik);
                if (pgRecord.nip) allIds.add(pgRecord.nip);
                if (pgRecord.nuptk) allIds.add(pgRecord.nuptk);
            }
            const idList = Array.from(allIds).filter(Boolean);

            let isWali = false;
            let waliClass = '';
            if (idList.length > 0) {
                const placeholders = idList.map(() => '?').join(',');
                const [rbRows]: any = await getPool().query(
                    `SELECT nama FROM rombongan_belajar 
                     WHERE (ptk_id IN (${placeholders}) OR wali_kelas_id IN (${placeholders}))
                       AND (soft_delete = 0 OR soft_delete IS NULL OR soft_delete = '0')
                     LIMIT 1`,
                    [...idList, ...idList]
                ).catch(() => [[]]);
                if (rbRows && rbRows.length > 0) {
                    isWali = true;
                    waliClass = rbRows[0].nama;
                }
            }

            let isBidang = false;
            let bidangName = '';
            if (idList.length > 0) {
                const placeholders = idList.map(() => '?').join(',');
                const [beRows]: any = await getPool().query(
                    `SELECT mata_pelajaran, nama_bidang, kategori FROM bidang_ekskul 
                     WHERE pegawai_id IN (${placeholders})
                       AND (kategori LIKE '%bidang%' OR (mata_pelajaran IS NOT NULL AND mata_pelajaran != ''))
                     LIMIT 1`,
                    idList
                ).catch(() => [[]]);
                if (beRows && beRows.length > 0) {
                    isBidang = true;
                    bidangName = beRows[0].mata_pelajaran || beRows[0].nama_bidang || beRows[0].kategori;
                }
            }

            // Fallback check on jenis_ptk / jabatan_ptk / mengajar
            if (!isBidang) {
                const jenis = (ptkRecord?.jenis_ptk || pgRecord?.jenis_ptk || ptkRecord?.jabatan_ptk || pgRecord?.jabatan_ptk || ptkRecord?.mengajar || pgRecord?.mengajar || '').toLowerCase();
                if (jenis.includes('agama') || jenis.includes('penjas') || jenis.includes('pjok') || jenis.includes('mapel') || jenis.includes('bidang') || jenis.includes('olahraga')) {
                    isBidang = true;
                    bidangName = ptkRecord?.jenis_ptk || pgRecord?.jenis_ptk || 'Guru Bidang Studi';
                }
            }

            return { isWali, waliClass, isBidang, bidangName };
        } catch (err: any) {
            console.error("[Login] Error resolving teacher persona:", err.message);
            return { isWali: false, waliClass: '', isBidang: false, bidangName: '' };
        }
    };
    
    if (type === 'staff' || type === 'guru_kelas' || type === 'guru_bidang') {
        const defaultAdminUsername = process.env.ADMIN_USERNAME || 'admin';
        const defaultAdminPassword = process.env.ADMIN_PASSWORD || 'admin123';

        // Check bootstrap credentials first (Admin / Pegawai only)
        if (type === 'staff' && username === defaultAdminUsername && password === defaultAdminPassword) {
            const token = jwt.sign({ username, role: 'Superadmin', type: 'staff', permissions: ['all'] }, JWT_SECRET, { expiresIn: "7d" });
            await safeLogLogin({ type: 'staff', username, status: 'success' });
            return res.json({ success: true, token, role: 'Superadmin', type: 'staff' });
        }

        const queryInput = (username || '').trim();

        // Search pengguna_web flexibly by username, staff_id, or linked ptk/pegawai NIK/NIP/NUPTK
        const [rows]: any = await getPool().execute(`
            SELECT wu.*, r.name as role_name, r.permissions
            FROM pengguna_web wu
            LEFT JOIN peran r ON wu.role_id = r.id
            LEFT JOIN ptk p ON (wu.staff_id = p.ptk_id OR wu.staff_id = p.nik OR wu.username = p.nik OR wu.username = p.nip OR wu.username = p.nuptk)
            LEFT JOIN pegawai pg ON (wu.staff_id = pg.pegawai_id OR wu.staff_id = pg.nik OR wu.username = pg.nik OR wu.username = pg.nip OR wu.username = pg.nuptk)
            WHERE wu.username = ?
               OR wu.staff_id = ?
               OR p.nik = ? OR p.nip = ? OR p.nuptk = ? OR p.ptk_id = ?
               OR pg.nik = ? OR pg.nip = ? OR pg.nuptk = ? OR pg.pegawai_id = ?
            ORDER BY wu.status_aktif DESC, wu.id ASC
            LIMIT 1
        `, [queryInput, queryInput, queryInput, queryInput, queryInput, queryInput, queryInput, queryInput, queryInput, queryInput]);

        if (rows.length > 0) {
            const user = rows[0];
            let isMatch = await bcrypt.compare(password, user.password);
            if (!isMatch && password === user.password) {
                isMatch = true;
            }

            // Jika belum match, cek password default guru (NIK, NIP, NUPTK, Tanggal Lahir, admin123, password123, 123456)
            if (!isMatch && (type === 'guru_kelas' || type === 'guru_bidang' || type === 'staff' || (user.role_name && user.role_name.toLowerCase().includes('guru')))) {
                const validDefaults: (string | null)[] = [
                    user.username ? String(user.username).trim() : null,
                    queryInput,
                    '123456',
                    'password123',
                    'admin123',
                    'admin',
                    defaultAdminPassword
                ];

                const searchStaffIds = [user.staff_id, user.username, queryInput].filter(Boolean);
                if (searchStaffIds.length > 0) {
                    try {
                        const [ptkRows]: any = await getPool().query(
                            `SELECT nik, nip, nuptk, tanggal_lahir FROM ptk WHERE ptk_id IN (?) OR nik IN (?) OR nip IN (?) OR nuptk IN (?) LIMIT 1`,
                            [searchStaffIds, searchStaffIds, searchStaffIds, searchStaffIds]
                        );
                        if (ptkRows && ptkRows.length > 0) {
                            const p = ptkRows[0];
                            if (p.nik) validDefaults.push(String(p.nik).trim());
                            if (p.nip) validDefaults.push(String(p.nip).trim());
                            if (p.nuptk) validDefaults.push(String(p.nuptk).trim());
                            if (p.tanggal_lahir) {
                                const d = new Date(p.tanggal_lahir);
                                if (!isNaN(d.getTime())) {
                                    const yyyy = d.getFullYear().toString();
                                    const mm = String(d.getMonth() + 1).padStart(2, '0');
                                    const dd = String(d.getDate()).padStart(2, '0');
                                    validDefaults.push(`${yyyy}-${mm}-${dd}`);
                                    validDefaults.push(`${dd}-${mm}-${yyyy}`);
                                    validDefaults.push(`${dd}${mm}${yyyy}`);
                                    validDefaults.push(`${yyyy}${mm}${dd}`);
                                }
                            }
                        }
                    } catch (e) {}
                }

                const cleanDefaults = validDefaults.filter(Boolean) as string[];
                const inputPass = password.trim();
                if (cleanDefaults.includes(inputPass)) {
                    isMatch = true;
                    // Update password di database agar tersinkronisasi
                    try {
                        const hashed = await bcrypt.hash(password, 10);
                        await getPool().execute("UPDATE pengguna_web SET password = ? WHERE id = ?", [hashed, user.id]);
                    } catch (e) {}
                }
            }

            if (!isMatch) {
                await safeLogLogin({ type, username: queryInput, status: 'failed' });
                return res.status(401).json({ error: "Password yang Anda masukkan salah." });
            }

            if (!user.status_aktif) {
                await safeLogLogin({ user_id: user.id, type, username: queryInput, status: 'failed' });
                return res.status(403).json({ error: "Akun Anda telah dinonaktifkan. Silakan hubungi operator / administrator." });
            }

            const perms = (() => { try { return JSON.parse(user.permissions); } catch { return ['all']; } })();
            let finalNama = user.nama_lengkap || '';
            if (user.staff_id) {
                try {
                    const [staffRows]: any = await getPool().execute(
                        "SELECT nama_lengkap FROM pegawai WHERE pegawai_id = ? OR nik = ?",
                        [user.staff_id, user.staff_id]
                    );
                    if (staffRows.length > 0 && staffRows[0].nama_lengkap) finalNama = staffRows[0].nama_lengkap;
                } catch (e) {}
                if (!finalNama) {
                    try {
                        const [ptkRows]: any = await getPool().execute(
                            "SELECT nama as nama_lengkap FROM ptk WHERE ptk_id = ? OR nik = ?",
                            [user.staff_id, user.staff_id]
                        );
                        if (ptkRows.length > 0 && ptkRows[0].nama_lengkap) finalNama = ptkRows[0].nama_lengkap;
                    } catch (e) {}
                }
            }
            if (!finalNama) {
                try {
                    const [staffRows2]: any = await getPool().execute(
                        "SELECT nama_lengkap FROM pegawai WHERE nik = ? OR nip = ? OR nuptk = ?",
                        [user.username, user.username, user.username]
                    );
                    if (staffRows2.length > 0 && staffRows2[0].nama_lengkap) finalNama = staffRows2[0].nama_lengkap;
                } catch (e) {}
            }
            if (!finalNama) {
                try {
                    const [ptkRows2]: any = await getPool().execute(
                        "SELECT nama as nama_lengkap FROM ptk WHERE nik = ? OR nip = ? OR nuptk = ?",
                        [user.username, user.username, user.username]
                    );
                    if (ptkRows2.length > 0 && ptkRows2[0].nama_lengkap) finalNama = ptkRows2[0].nama_lengkap;
                } catch (e) {}
            }
            if (!finalNama) {
                finalNama = (user.role_name === 'Superadmin' || user.role_name === 'Admin') ? 'Super Administrator' : user.username;
            }

            // Role-First Evaluation for Teacher / Wali Kelas / Guru Bidang
            let isTeacher = (user.role_name && user.role_name.toLowerCase().includes('guru'));
            if (!isTeacher) {
                try {
                    const candidateIds = [user.staff_id, user.id, user.username, queryInput].filter(Boolean);
                    if (candidateIds.length > 0) {
                        const placeholders = candidateIds.map(() => '?').join(',');
                        // 1. Check wali kelas in rombongan_belajar
                        const [rbRows]: any = await getPool().query(
                            `SELECT rombongan_belajar_id FROM rombongan_belajar 
                             WHERE (ptk_id IN (${placeholders}) OR wali_kelas_id IN (${placeholders})) 
                               AND (soft_delete = 0 OR soft_delete IS NULL OR soft_delete = '0') 
                             LIMIT 1`, 
                            [...candidateIds, ...candidateIds]
                        ).catch(() => [[]]);
                        if (rbRows && rbRows.length > 0) isTeacher = true;

                        // 2. Check if assigned in bidang_ekskul
                        if (!isTeacher) {
                            const [beRows]: any = await getPool().query(
                                `SELECT id FROM bidang_ekskul WHERE pegawai_id IN (${placeholders}) LIMIT 1`, 
                                candidateIds
                            ).catch(() => [[]]);
                            if (beRows && beRows.length > 0) isTeacher = true;
                        }

                        // 3. Check if assigned in jadwal_pelajaran
                        if (!isTeacher) {
                            const [schRows]: any = await getPool().query(
                                `SELECT id FROM jadwal_pelajaran WHERE guru_id IN (${placeholders}) OR ptk_id IN (${placeholders}) OR nama_guru = ? LIMIT 1`,
                                [...candidateIds, ...candidateIds, finalNama]
                            ).catch(() => [[]]);
                            if (schRows && schRows.length > 0) isTeacher = true;
                        }
                    }
                } catch (e) {}
            }

            // Validate teacher persona if logging in as guru_kelas or guru_bidang
            if ((type === 'guru_kelas' || type === 'guru_bidang') && user.role_name !== 'Superadmin' && user.role_name !== 'Admin') {
                const targetStaffId = user.staff_id || user.id;
                const persona = await resolveTeacherPersona(targetStaffId, finalNama, [user.username, user.nik, queryInput]);

                if (type === 'guru_kelas' && !persona.isWali && persona.isBidang) {
                    await safeLogLogin({ user_id: user.id, type, username: queryInput, status: 'failed' });
                    return res.status(403).json({ 
                        error: `Akun Anda (${finalNama}) terdaftar sebagai Guru Bidang Studi (${persona.bidangName}). Silakan pilih persona 'Guru Bidang Studi' pada menu login.` 
                    });
                }

                if (type === 'guru_bidang' && persona.isWali && !persona.isBidang) {
                    await safeLogLogin({ user_id: user.id, type, username: queryInput, status: 'failed' });
                    return res.status(403).json({ 
                        error: `Akun Anda (${finalNama}) terdaftar sebagai Guru Kelas / Wali Kelas (${persona.waliClass}). Silakan pilih persona 'Guru Kelas / Wali Kelas' pada menu login.` 
                    });
                }
            }

            const teacherMode = (type === 'guru_kelas' || type === 'guru_bidang') 
                ? (type === 'guru_kelas' ? 'kelas' : 'bidang') 
                : undefined;

            let finalRoleName = user.role_name;
            let finalPerms = perms;

            if (type === 'guru_kelas' || type === 'guru_bidang') {
                finalRoleName = type === 'guru_kelas' ? 'Guru Kelas' : 'Guru Bidang Studi';
                try {
                    const [roleRows]: any = await getPool().execute("SELECT permissions FROM peran WHERE name = 'Guru' LIMIT 1");
                    if (roleRows && roleRows.length > 0 && roleRows[0].permissions) {
                        finalPerms = JSON.parse(roleRows[0].permissions);
                    }
                } catch (e) {}
            }

            const finalUserType = (type === 'guru_kelas' || type === 'guru_bidang') ? 'guru' : 'staff';

            const token = jwt.sign({ 
                id: user.id, 
                username: user.username, 
                role: finalRoleName, 
                type: finalUserType, 
                teacher_mode: teacherMode,
                permissions: finalPerms, 
                staff_id: user.staff_id, 
                nama: finalNama, 
                is_teacher: isTeacher 
            }, JWT_SECRET, { expiresIn: "7d" });

            await safeLogLogin({ user_id: user.id, type, username: queryInput, status: 'success' });
            return res.json({ 
                success: true, 
                token, 
                role: finalRoleName, 
                type: finalUserType, 
                teacher_mode: teacherMode,
                id: user.id, 
                nama: finalNama, 
                is_teacher: isTeacher 
            });
        } else {
            // Fallback check for direct teacher login via ptk/pegawai if account not yet in pengguna_web
            if (type === 'guru_kelas' || type === 'guru_bidang') {
                try {
                    const [ptkRows]: any = await getPool().execute(
                        `SELECT ptk_id as id, nama as nama_lengkap, nik, nip, nuptk, tanggal_lahir, gelar_depan, gelar_belakang, jenis_ptk 
                         FROM ptk 
                         WHERE (nik = ? OR nip = ? OR nuptk = ? OR ptk_id = ? OR nama = ? OR nama LIKE ?) 
                           AND (soft_delete = 0 OR soft_delete IS NULL OR soft_delete = '0') 
                         LIMIT 1`,
                        [queryInput, queryInput, queryInput, queryInput, queryInput, `%${queryInput}%`]
                    );
                    let foundTeacher = ptkRows && ptkRows.length > 0 ? ptkRows[0] : null;
                    if (!foundTeacher) {
                        const [pgRows]: any = await getPool().execute(
                            `SELECT pegawai_id as id, nama_lengkap, nik, nip, nuptk, tanggal_lahir, gelar_depan, gelar_belakang, jenis_ptk 
                             FROM pegawai 
                             WHERE (nik = ? OR nip = ? OR nuptk = ? OR pegawai_id = ? OR nama_lengkap = ? OR nama_lengkap LIKE ?) 
                             LIMIT 1`,
                            [queryInput, queryInput, queryInput, queryInput, queryInput, `%${queryInput}%`]
                        );
                        if (pgRows && pgRows.length > 0) foundTeacher = pgRows[0];
                    }

                    if (foundTeacher) {
                        const validDefaults: (string | null)[] = [
                            foundTeacher.nik ? String(foundTeacher.nik).trim() : null,
                            foundTeacher.nip ? String(foundTeacher.nip).trim() : null,
                            foundTeacher.nuptk ? String(foundTeacher.nuptk).trim() : null,
                            queryInput,
                            String(foundTeacher.id).trim(),
                            '123456',
                            'password123',
                            'admin123',
                            'admin',
                            defaultAdminPassword
                        ];

                        if (foundTeacher.tanggal_lahir) {
                            try {
                                const d = new Date(foundTeacher.tanggal_lahir);
                                if (!isNaN(d.getTime())) {
                                    const yyyy = d.getFullYear().toString();
                                    const mm = String(d.getMonth() + 1).padStart(2, '0');
                                    const dd = String(d.getDate()).padStart(2, '0');
                                    validDefaults.push(`${yyyy}-${mm}-${dd}`);
                                    validDefaults.push(`${dd}-${mm}-${yyyy}`);
                                    validDefaults.push(`${dd}${mm}${yyyy}`);
                                    validDefaults.push(`${yyyy}${mm}${dd}`);
                                }
                            } catch (e) {}
                        }

                        const cleanValidDefaults = validDefaults.filter(Boolean) as string[];
                        const inputPass = password.trim();

                        if (cleanValidDefaults.includes(inputPass) || inputPass === defaultAdminPassword) {
                            // Validate persona role (Guru Kelas vs Guru Bidang Studi)
                            const persona = await resolveTeacherPersona(foundTeacher.id, foundTeacher.nama_lengkap, [foundTeacher.nik, foundTeacher.nip, foundTeacher.nuptk, queryInput]);

                            if (type === 'guru_kelas' && !persona.isWali && persona.isBidang) {
                                await safeLogLogin({ type, username: queryInput, status: 'failed' });
                                return res.status(403).json({ 
                                    error: `Akun Anda (${foundTeacher.nama_lengkap}) terdaftar sebagai Guru Bidang Studi (${persona.bidangName}). Silakan pilih persona 'Guru Bidang Studi' pada menu login.` 
                                });
                            }

                            if (type === 'guru_bidang' && persona.isWali && !persona.isBidang) {
                                await safeLogLogin({ type, username: queryInput, status: 'failed' });
                                return res.status(403).json({ 
                                    error: `Akun Anda (${foundTeacher.nama_lengkap}) terdaftar sebagai Guru Kelas / Wali Kelas (${persona.waliClass}). Silakan pilih persona 'Guru Kelas / Wali Kelas' pada menu login.` 
                                });
                            }

                            const teacherMode = type === 'guru_kelas' ? 'kelas' : 'bidang';
                            const targetRole = type === 'guru_bidang' ? 'Guru Bidang Studi' : 'Guru Kelas';
                            let guruPerms: string[] = ['guru'];
                            try {
                                const [roleRows]: any = await getPool().execute("SELECT permissions FROM peran WHERE name = 'Guru' LIMIT 1");
                                if (roleRows && roleRows.length > 0 && roleRows[0].permissions) {
                                    guruPerms = JSON.parse(roleRows[0].permissions);
                                }
                            } catch (e) {}

                            let displayNama = foundTeacher.nama_lengkap;
                            const gDepan = foundTeacher.gelar_depan && foundTeacher.gelar_depan !== '-' ? foundTeacher.gelar_depan.trim() : '';
                            const gBelakang = foundTeacher.gelar_belakang && foundTeacher.gelar_belakang !== '-' ? foundTeacher.gelar_belakang.trim() : '';
                            if (gDepan && !displayNama.startsWith(gDepan)) displayNama = `${gDepan} ${displayNama}`;
                            if (gBelakang && !displayNama.includes(gBelakang)) displayNama = `${displayNama}, ${gBelakang}`;

                            const token = jwt.sign({ 
                                id: foundTeacher.id, 
                                username: queryInput, 
                                role: targetRole, 
                                type: 'guru', 
                                teacher_mode: teacherMode,
                                permissions: guruPerms, 
                                staff_id: foundTeacher.id, 
                                nama: displayNama, 
                                nama_lengkap: displayNama,
                                nik: foundTeacher.nik,
                                nip: foundTeacher.nip,
                                nuptk: foundTeacher.nuptk,
                                is_teacher: true 
                            }, JWT_SECRET, { expiresIn: "7d" });

                            await safeLogLogin({ type, username: queryInput, status: 'success' });
                            return res.json({ 
                                success: true, 
                                token, 
                                role: targetRole, 
                                type: 'guru', 
                                teacher_mode: teacherMode,
                                id: foundTeacher.id, 
                                nama: displayNama, 
                                nama_lengkap: displayNama,
                                is_teacher: true 
                            });
                        }
                    }
                } catch (e) {}
            }

            await safeLogLogin({ type, username: queryInput, status: 'failed' });
            return res.status(401).json({ error: "Akun Pegawai / Guru tidak ditemukan atau password salah. Pastikan Anda memasukkan NIK, NIP, atau Nama Guru dengan benar." });
        }
    } else if (type === 'pelatih') {
        const queryInput = (username || '').trim();
        let pelatih: any = null;
        
        // 1. Cek di tabel standar Dapodik: ptk (berdasarkan NIK, NIP, NUPTK, atau ptk_id)
        try {
            const [ptkRows]: any = await getPool().execute(
                "SELECT ptk_id as id, nama as nama, nik, nip, nuptk, nomor_kta FROM ptk WHERE (nik = ? OR nip = ? OR nuptk = ? OR ptk_id = ?) AND (soft_delete = 0 OR soft_delete IS NULL OR soft_delete = '0') LIMIT 1",
                [queryInput, queryInput, queryInput, queryInput]
            );
            if (ptkRows && ptkRows.length > 0) {
                pelatih = ptkRows[0];
            }
        } catch (e) {}

        // 2. Fallback: Cek di tabel pegawai jika ptk belum ketemu
        if (!pelatih) {
            try {
                const [pegawaiRows]: any = await getPool().execute(
                    "SELECT p.pegawai_id as id, p.nama_lengkap as nama, p.nik, p.nip, p.nomor_kta FROM pegawai p WHERE p.nik = ? OR p.nip = ? OR p.pegawai_id = ? LIMIT 1",
                    [queryInput, queryInput, queryInput]
                );
                if (pegawaiRows && pegawaiRows.length > 0) {
                    pelatih = pegawaiRows[0];
                }
            } catch (e) {}
        }

        // 3. Fallback: Cek pengguna_web
        if (!pelatih) {
            try {
                const [userRows]: any = await getPool().execute(
                    "SELECT pw.id as user_id, pw.username, pw.password, pw.staff_id, pw.nomor_kta, p.nama as ptk_nama, p.nik as ptk_nik, p.nip as ptk_nip, p.nomor_kta as ptk_nomor_kta FROM pengguna_web pw LEFT JOIN ptk p ON pw.staff_id = p.ptk_id WHERE pw.username = ? LIMIT 1",
                    [queryInput]
                );
                if (userRows && userRows.length > 0) {
                    const u = userRows[0];
                    pelatih = {
                        id: u.staff_id || u.user_id,
                        nama: u.ptk_nama || u.username,
                        nik: u.ptk_nik || u.username,
                        nip: u.ptk_nip || '',
                        nomor_kta: u.nomor_kta || u.ptk_nomor_kta || null,
                        pwPassword: u.password
                    };
                }
            } catch (e) {}
        }

        if (!pelatih) {
            await safeLogLogin({ type: 'pelatih', username, status: 'failed' });
            return res.status(401).json({ error: "NIK / NIP atau Akun Pelatih tidak ditemukan" });
        }

        // STRICT VALIDATION: Pelatih WAJIB terdaftar di tabel bidang_ekskul dengan kategori Pelatih
        const candidateIds = [pelatih.id, pelatih.nik, pelatih.nip, pelatih.nuptk, queryInput].filter(Boolean);
        const placeholders = candidateIds.map(() => '?').join(',');
        const [coachRows]: any = await getPool().query(
            `SELECT id, nama_bidang, kategori FROM bidang_ekskul 
             WHERE (pegawai_id IN (${placeholders})
                OR pegawai_id IN (SELECT pegawai_id FROM pegawai WHERE nik IN (${placeholders}) OR nip IN (${placeholders}) OR nuptk IN (${placeholders}) OR pegawai_id IN (${placeholders}))
                OR pegawai_id IN (SELECT ptk_id FROM ptk WHERE nik IN (${placeholders}) OR nip IN (${placeholders}) OR nuptk IN (${placeholders}) OR ptk_id IN (${placeholders})))
               AND (kategori = 'Pelatih' OR kategori LIKE '%Pelatih%')
             LIMIT 1`,
            [...candidateIds, ...candidateIds, ...candidateIds, ...candidateIds, ...candidateIds, ...candidateIds, ...candidateIds, ...candidateIds, ...candidateIds]
        ).catch(() => [[]]);

        if (!coachRows || coachRows.length === 0) {
            await safeLogLogin({ type: 'pelatih', username, status: 'failed' });
            return res.status(403).json({ 
                error: "Akun Anda tidak terdaftar sebagai Pelatih Ekstrakurikuler. Silakan gunakan opsi login 'Administrator / Guru' untuk masuk." 
            });
        }

        // 4. Cek password di tabel pelatih_auth
        const authKeys = [pelatih.nik, pelatih.nip, String(pelatih.id), queryInput].filter(Boolean);
        let isMatch = false;

        try {
            const authPlaceholders = authKeys.map(() => '?').join(',');
            const [authRows]: any = await getPool().execute(
                `SELECT password FROM pelatih_auth WHERE nik IN (${authPlaceholders}) LIMIT 1`,
                authKeys
            );

            if (authRows && authRows.length > 0) {
                isMatch = await bcrypt.compare(password, authRows[0].password);
                if (!isMatch && password === authRows[0].password) {
                    isMatch = true;
                }
            }
        } catch (e) {}

        // Default password check jika belum ada password di pelatih_auth
        if (!isMatch) {
            const validDefaults = [
                pelatih.nik ? String(pelatih.nik).trim() : null,
                pelatih.nip ? String(pelatih.nip).trim() : null,
                pelatih.nuptk ? String(pelatih.nuptk).trim() : null,
                queryInput,
                String(pelatih.id).trim()
            ].filter(Boolean);

            if (validDefaults.includes(password.trim())) {
                isMatch = true;
            } else if (pelatih.pwPassword) {
                isMatch = await bcrypt.compare(password, pelatih.pwPassword) || (password === pelatih.pwPassword);
            }
        }

        if (!isMatch) {
            await safeLogLogin({ type: 'pelatih', username, status: 'failed' });
            return res.status(401).json({ error: "NIK / Password salah" });
        }

        // 5. Login berhasil
        const userIdentifier = pelatih.nik || pelatih.nip || pelatih.username || String(pelatih.id);
        const token = jwt.sign({ id: pelatih.id, username: userIdentifier, role: 'Pelatih', type: 'pelatih', permissions: ['pelatih'], nomor_kta: pelatih.nomor_kta || null }, JWT_SECRET, { expiresIn: "7d" });
        await safeLogLogin({ type: 'pelatih', username, status: 'success' });
        return res.json({ success: true, token, role: 'Pelatih', type: 'pelatih', id: pelatih.id, nama: pelatih.nama, nomor_kta: pelatih.nomor_kta || null });
    } else if (type === 'student') {
        const queryUsername = username || null;
        const queryPassword = password || null;
        const [rows]: any = await getPool().execute(`
            SELECT 
                s.*, 
                s.peserta_didik_id as id, 
                s.nama as nama_lengkap, 
                rpd.nipd as nipd_rpd, 
                rb.nama as rombel, 
                rb.nama as kelas, 
                rb.tingkat_pendidikan_id as tingkat_kelas 
            FROM peserta_didik s 
            LEFT JOIN registrasi_peserta_didik rpd ON rpd.peserta_didik_id = s.peserta_didik_id 
            LEFT JOIN anggota_rombel ar ON ar.peserta_didik_id = s.peserta_didik_id 
            LEFT JOIN rombongan_belajar rb ON rb.rombongan_belajar_id = ar.rombongan_belajar_id 
            WHERE (s.nisn = ? OR s.nik = ?) AND s.tanggal_lahir = ?
            ORDER BY COALESCE(rb.semester_id, '0') DESC
            LIMIT 1
        `, [queryUsername, queryUsername, queryPassword]);
        if (rows.length > 0) {
            const student = rows[0];
            student.nipd = student.nipd_rpd || student.nipd || '';
            if (!student.status_aktif) {
                await safeLogLogin({ student_id: student.id, type: 'student', username, status: 'failed' });
                return res.status(403).json({ error: "Login siswa ditangguhkan. Silakan hubungi wali kelas." });
            }
            const token = jwt.sign({ id: student.id, nisn: student.nisn, type: 'student', permissions: [] }, JWT_SECRET, { expiresIn: "7d" });
            await safeLogLogin({ student_id: student.id, type: 'student', username, status: 'success' });
            return res.json({ 
                success: true, 
                token, 
                type: 'student', 
                id: student.id,
                rombel: student.rombel || '',
                tingkat_kelas: student.tingkat_kelas || '',
                nama: student.nama_lengkap || ''
            });
        }
    }

    await safeLogLogin({ type: type || 'unknown', username: username || 'unknown', status: 'failed' });
    return res.status(401).json({ error: "Akun tidak ditemukan. Pastikan Anda memilih akses login yang tepat." });
}));

app.post("/api/pelatih/change-password", authenticate, asyncHandler(async (req: any, res: any) => {
    if (req.user.type !== 'pelatih') {
        return res.status(403).json({ error: "Hanya pelatih yang dapat mengubah password" });
    }
    const { oldPassword, newPassword } = req.body;
    const identifier = req.user.username || String(req.user.id);

    // Check old password
    const [authRows]: any = await getPool().execute("SELECT password FROM pelatih_auth WHERE nik = ? OR nik = ?", [identifier, String(req.user.id)]);
    let isMatch = false;

    if (authRows.length > 0) {
        isMatch = await bcrypt.compare(oldPassword, authRows[0].password) || (oldPassword === authRows[0].password);
    } else {
        isMatch = (oldPassword === identifier || oldPassword === String(req.user.id));
    }

    if (!isMatch) {
        return res.status(400).json({ error: "Password lama salah" });
    }

    // Hash new password
    const hashed = await bcrypt.hash(newPassword, 10);
    
    // Insert or Update
    if (authRows.length > 0) {
        await getPool().execute("UPDATE pelatih_auth SET password = ? WHERE nik = ? OR nik = ?", [hashed, identifier, String(req.user.id)]);
    } else {
        await getPool().execute("INSERT INTO pelatih_auth (nik, password) VALUES (?, ?) ON DUPLICATE KEY UPDATE password = VALUES(password)", [identifier, hashed]);
    }

    res.json({ success: true, message: "Password berhasil diubah" });
}));

app.post("/api/pelatih/update-kta", authenticate, asyncHandler(async (req: any, res: any) => {
    const { nomor_kta } = req.body;
    const userId = req.user?.id || req.user?.pegawai_id || req.user?.ptk_id || req.user?.staff_id;
    const identifier = req.user?.username || String(req.user?.id || '');

    if (!userId && !identifier) {
        return res.status(400).json({ error: "Identitas pelatih tidak valid" });
    }

    const cleanKta = (nomor_kta || '').trim();

    // 1. Update ke ptk (Dapodik murni)
    try {
        await getPool().execute(
            "UPDATE ptk SET nomor_kta = ? WHERE ptk_id = ? OR nik = ? OR nip = ? OR nuptk = ?",
            [cleanKta || null, String(userId), identifier, identifier, identifier]
        );
    } catch (err: any) {
        console.warn("Update ptk nomor_kta error:", err.message);
    }

    // 2. Update ke pegawai
    try {
        await getPool().execute(
            "UPDATE pegawai SET nomor_kta = ? WHERE pegawai_id = ? OR id = ? OR ptk_id = ? OR nik = ? OR nip = ?",
            [cleanKta || null, String(userId), String(userId), String(userId), identifier, identifier]
        );
    } catch (err: any) {
        console.warn("Update pegawai nomor_kta error:", err.message);
    }

    // 3. Update ke pengguna_web
    try {
        await getPool().execute(
            "UPDATE pengguna_web SET nomor_kta = ? WHERE id = ? OR staff_id = ? OR username = ?",
            [cleanKta || null, String(userId), String(userId), identifier]
        );
    } catch (err: any) {
        console.warn("Update pengguna_web nomor_kta error:", err.message);
    }

    // 4. Update ke akademik_ekskul, absensi_ekskul, program_latihan_ekskul
    try {
        await getPool().execute(
            "UPDATE akademik_ekskul SET nomor_kta = ? WHERE pelatih_id = ? OR pelatih_id = ?",
            [cleanKta || null, String(userId), identifier]
        );
        await getPool().execute(
            "UPDATE absensi_ekskul SET nomor_kta_pelatih = ? WHERE pelatih_id = ? OR pelatih_id = ?",
            [cleanKta || null, String(userId), identifier]
        );
        await getPool().execute(
            "UPDATE program_latihan_ekskul SET nomor_kta_pelatih = ? WHERE pelatih_id = ? OR pelatih_id = ?",
            [cleanKta || null, String(userId), identifier]
        );
    } catch (_) {}

    return res.json({ success: true, nomor_kta: cleanKta });
}));

