// Admin list of all pelatih berkas (merged with all registered coaches in bidang_ekskul)
app.get("/api/admin/pelatih-berkas", authenticate, asyncHandler(async (req: any, res: any) => {
    const ptkMap = await loadResolvedPtkMap();

    const [pbRows]: any = await getPool().query(`
        SELECT pb.*, 
               COALESCE(p.nama, pg.nama_lengkap, pb.nama_lengkap) as nama_pelatih,
               COALESCE(p.nik, pg.nik, pb.nik) as nik_pelatih
        FROM pelatih_berkas pb
        LEFT JOIN ptk p ON pb.pelatih_id = p.ptk_id OR pb.nik = p.nik
        LEFT JOIN pegawai pg ON pb.pelatih_id = pg.pegawai_id OR pb.nik = pg.nik
        ORDER BY pb.updated_at DESC
    `).catch(() => [[]]);

    const [bidangRows]: any = await getPool().query(`
        SELECT * FROM bidang_ekskul 
        WHERE LOWER(kategori) LIKE '%pelatih%' OR LOWER(kategori) LIKE '%pembina%' OR LOWER(kategori) LIKE '%ekskul%'
        ORDER BY created_at DESC
    `).catch(() => [[]]);

    // Group bidang_ekskul by pegawai_id
    const coachBidangMap = new Map<string, { ekskulList: string[]; kelasList: string[]; pegawai_id: string }>();
    for (const b of (bidangRows || [])) {
        const pid = String(b.pegawai_id || '').trim();
        if (!pid) continue;
        if (!coachBidangMap.has(pid)) {
            coachBidangMap.set(pid, { ekskulList: [], kelasList: [], pegawai_id: pid });
        }
        const entry = coachBidangMap.get(pid)!;
        const mapel = String(b.mata_pelajaran || b.nama_bidang || '').trim();
        if (mapel && !entry.ekskulList.includes(mapel)) entry.ekskulList.push(mapel);

        let kArr: string[] = [];
        if (b.kelas) {
            if (Array.isArray(b.kelas)) kArr = b.kelas.map(String);
            else if (typeof b.kelas === 'string') {
                try {
                    const parsed = JSON.parse(b.kelas);
                    if (Array.isArray(parsed)) kArr = parsed.map(String);
                    else if (parsed) kArr = [String(parsed)];
                } catch (_) {
                    if (b.kelas.trim()) kArr = [b.kelas.trim()];
                }
            }
        }
        for (const k of kArr) {
            if (k && !entry.kelasList.includes(k)) entry.kelasList.push(k);
        }
    }

    const resultList: any[] = [];
    const matchedPegawaiIds = new Set<string>();

    for (const pb of (pbRows || [])) {
        const pid = String(pb.pelatih_id || '').trim();
        const ptk = ptkMap[pid] || Object.values(ptkMap).find((x: any) => (pb.nik && x.nik === pb.nik) || (pb.nik_pelatih && x.nik === pb.nik_pelatih));
        const resolvedPid = ptk ? String(ptk.ptk_id || ptk.pegawai_id || pid) : pid;
        if (pid) matchedPegawaiIds.add(pid);
        if (resolvedPid) matchedPegawaiIds.add(resolvedPid);

        const bidangInfo = coachBidangMap.get(pid) || coachBidangMap.get(resolvedPid);
        resultList.push({
            ...pb,
            pelatih_id: pid || resolvedPid,
            nama_lengkap: pb.nama_lengkap || pb.nama_pelatih || ptk?.fullName || ptk?.nama || 'Pelatih',
            nik: pb.nik || pb.nik_pelatih || ptk?.nik || '',
            bidang_ekskul: bidangInfo ? bidangInfo.ekskulList.join(', ') : '-',
            kelas_binaan: bidangInfo ? bidangInfo.kelasList : [],
            has_submitted: true
        });
    }

    // Add coaches from bidang_ekskul who haven't submitted pelatih_berkas yet
    for (const [pid, bidangInfo] of coachBidangMap.entries()) {
        if (matchedPegawaiIds.has(pid)) continue;
        const ptk = ptkMap[pid];
        // Also check by NIK in resultList
        if (ptk?.nik && resultList.some(r => r.nik && String(r.nik) === String(ptk.nik))) continue;

        resultList.push({
            id: null,
            pelatih_id: pid,
            nama_lengkap: ptk?.fullName || ptk?.nama || 'Pelatih',
            nama_pelatih: ptk?.fullName || ptk?.nama || 'Pelatih',
            nik: ptk?.nik || '',
            nik_pelatih: ptk?.nik || '',
            nomor_kta: '',
            tingkat_lisensi: '',
            lembaga_penerbit: '',
            tahun_lisensi: '',
            pendidikan_terakhir: '',
            jurusan: '',
            nama_bank: '',
            nomor_rekening: '',
            atas_nama_rekening: ptk?.fullName || ptk?.nama || '',
            cabang_bank: '',
            nomor_hp: ptk?.no_hp || ptk?.nomor_hp || '',
            email: ptk?.email || '',
            alamat_domisili: '',
            pengalaman_pelatih: '',
            berkas_ktp: null,
            berkas_sertifikat: null,
            berkas_kta: null,
            berkas_ijazah: null,
            berkas_buku_rekening: null,
            berkas_pendukung_lain: null,
            status_verifikasi: 'Belum Mengisi',
            catatan_admin: null,
            bidang_ekskul: bidangInfo.ekskulList.join(', ') || '-',
            kelas_binaan: bidangInfo.kelasList,
            has_submitted: false,
            updated_at: null
        });
    }

    res.json(resultList);
}));

