// --- SSO ENDPOINT FOR E-LEARNING ---
app.post("/api/sso/verify", asyncHandler(async (req: any, res: any) => {
    const { sso_token, secret_key } = req.body;
    
    const [settingsRows]: any = await getPool().execute("SELECT elearning_token FROM pengaturan_sekolah WHERE id = 1");
    let validSecret = process.env.SSO_SECRET || "rahasia-dapoy-elearning";
    if (settingsRows.length > 0 && settingsRows[0].elearning_token) {
        validSecret = settingsRows[0].elearning_token;
    }

    if (secret_key !== validSecret) {
        return res.status(403).json({ error: "Invalid SSO Secret" });
    }
    try {
        const decoded: any = jwt.verify(sso_token, JWT_SECRET);
        if (decoded.type === 'student') {
            const [rows]: any = await getPool().execute("SELECT * FROM peserta_didik WHERE peserta_didik_id = ?", [decoded.id]);
            if (rows.length === 0) return res.status(404).json({ error: "Siswa not found" });
            const s = rows[0];
            return res.json({ success: true, type: 'SISWA', data: { username: s.nisn, nama: s.nama, nisn: s.nisn, kelas: null } });
        } else if (decoded.type === 'staff') {
            const [rows]: any = await getPool().execute("SELECT p.*, r.name as role_name FROM pengguna_web p JOIN peran r ON p.role_id = r.id WHERE p.id = ?", [decoded.id]);
            if (rows.length === 0) return res.status(404).json({ error: "Staff not found" });
            const s = rows[0];
            
            // Coba ambil nama dari tabel pegawai jika ada
            let nama = s.username;
            if (s.staff_id) {
                const [pegRows]: any = await getPool().execute("SELECT nama_lengkap FROM pegawai WHERE pegawai_id = ?", [s.staff_id]);
                if (pegRows.length > 0) nama = pegRows[0].nama_lengkap;
            }
            
            if (s.is_elearning_admin) {
                return res.json({ success: true, type: 'ADMIN', data: { username: s.username, nama: nama, role: 'Administrator' } });
            }
            return res.json({ success: true, type: 'GURU', data: { username: s.username, nama: nama, role: s.role_name } });
        }
    } catch (e: any) {
        import('fs').then(fs => fs.writeFileSync('debug_sso.txt', e.toString() + '\\n' + (e.stack || '')));
        console.error("SSO Verify Error:", e);
        return res.status(401).json({ error: "Invalid SSO Token" });
    }
}));

app.post("/api/sso/sync-data", asyncHandler(async (req: any, res: any) => {
    const { secret_key } = req.body;
    
    const [settingsRows]: any = await getPool().execute("SELECT elearning_token FROM pengaturan_sekolah WHERE id = 1");
    let validSecret = process.env.SSO_SECRET || "rahasia-dapoy-elearning";
    if (settingsRows.length > 0 && settingsRows[0].elearning_token) {
        validSecret = settingsRows[0].elearning_token;
    }

    if (secret_key !== validSecret) {
        return res.status(403).json({ error: "Invalid SSO Secret" });
    }
    
    // Fetch all active students
    const [siswaRows]: any = await getPool().execute(
        "SELECT s.nisn, s.nama as nama, rb.nama as kelas FROM peserta_didik s LEFT JOIN anggota_rombel ar ON s.peserta_didik_id = ar.peserta_didik_id LEFT JOIN rombongan_belajar rb ON ar.rombongan_belajar_id = rb.rombongan_belajar_id WHERE s.nisn IS NOT NULL AND s.nisn != ''"
    );
    
    // Fetch all active staff (Guru/Admin) from pengguna_web
    const [guruRows]: any = await getPool().execute(
        "SELECT p.username, p.staff_id, p.is_elearning_admin FROM pengguna_web p WHERE p.status_aktif = 1"
    );

    const guruData = await Promise.all(guruRows.map(async (g: any) => {
        let nama = g.username;
        let mapel = null;
        if (g.staff_id) {
            const [pegRows]: any = await getPool().execute("SELECT nama_lengkap, mengajar FROM pegawai WHERE pegawai_id = ?", [g.staff_id]);
            if (pegRows.length > 0) {
                nama = pegRows[0].nama_lengkap;
                mapel = pegRows[0].mengajar;
            }
        } else {
            // fallback checking NIK = username
            const [pegRows2]: any = await getPool().execute("SELECT nama_lengkap, mengajar FROM pegawai WHERE nik = ?", [g.username]);
            if (pegRows2.length > 0) {
                nama = pegRows2[0].nama_lengkap;
                mapel = pegRows2[0].mengajar;
            }
        }
        return { username: g.username, nama, mapel, is_admin: !!g.is_elearning_admin };
    }));

    return res.json({ success: true, data: { siswa: siswaRows, guru: guruData } });
}));

