function cleanBlogHtml(html: string | null | undefined): string {
    if (!html) return '';
    const tokens = html.split(/(<[^>]+>)/g);
    let inCodeBlock = false;

    for (let i = 0; i < tokens.length; i++) {
        const token = tokens[i];
        if (!token) continue;

        if (token.startsWith('<') && token.endsWith('>')) {
            const lower = token.toLowerCase();
            if (lower.startsWith('<pre') || lower.startsWith('<code')) {
                inCodeBlock = true;
            } else if (lower.startsWith('</pre>') || lower.startsWith('</code>')) {
                inCodeBlock = false;
            }
            continue;
        }

        if (inCodeBlock) continue;

        let text = token;
        text = text.replace(/&shy;/gi, '')
                   .replace(/\u00AD/g, '')
                   .replace(/&#173;/g, '')
                   .replace(/\u200B/g, '');
        text = text.replace(/([a-zA-Z0-9]+)-\s*[\r\n]+\s*([a-zA-Z0-9]+)/gi, '$1-$2');
        text = text.replace(/[\r\n]+/g, ' ');

        tokens[i] = text;
    }

    return tokens.join('');
}

