app.get("/api/mata_pelajaran", authenticate, asyncHandler(async (req: any, res: any) => {
    let { kurikulum_id, tingkat_pendidikan_id } = req.query; // kurikulum_id is actually nama_kurikulum
    
    // If not provided in query, fetch from school settings
    if (!kurikulum_id || !tingkat_pendidikan_id) {
        try {
            const [settings]: any = await getPool().query("SELECT kurikulum, bentuk_pendidikan FROM pengaturan_sekolah WHERE id = 1");
            if (settings && settings.length > 0) {
                if (!kurikulum_id) kurikulum_id = settings[0].kurikulum || 'Kurikulum Merdeka';
                if (!tingkat_pendidikan_id) {
                    const tList = getStandardTingkatPendidikan(settings[0].bentuk_pendidikan);
                    tingkat_pendidikan_id = tList[0]?.id || '1';
                }
            }
        } catch (e) {}
    }

    kurikulum_id = kurikulum_id || 'Kurikulum Merdeka';
    tingkat_pendidikan_id = tingkat_pendidikan_id || '1';

    const candidateTableSets = [
        { mpk: 'ref.mata_pelajaran_kurikulum', mp: 'ref.mata_pelajaran', kr: 'ref.kurikulum' },
        { mpk: 'mata_pelajaran_kurikulum', mp: 'mata_pelajaran', kr: 'kurikulum' },
        { mpk: 'ref_mata_pelajaran_kurikulum', mp: 'ref_mata_pelajaran', kr: 'ref_kurikulum' }
    ];

    for (const set of candidateTableSets) {
        try {
            const [rows]: any = await getPool().query(`
                SELECT mp.mata_pelajaran_id, mp.nama
                FROM \`${set.mpk}\` mpk
                JOIN \`${set.mp}\` mp ON mpk.mata_pelajaran_id = mp.mata_pelajaran_id
                JOIN \`${set.kr}\` kr ON mpk.kurikulum_id = kr.kurikulum_id
                WHERE (kr.nama_kurikulum = ? OR kr.nama_kurikulum LIKE ?) AND mpk.tingkat_pendidikan_id = ?
                ORDER BY mp.nama ASC
            `, [kurikulum_id, `%${kurikulum_id}%`, tingkat_pendidikan_id]);
            if (rows && rows.length > 0) return res.json(rows);
        } catch (e) {}
    }

    // Return standard curated list based on kurikulum & tingkat
    const standardMapel = getStandardMataPelajaran(String(kurikulum_id), String(tingkat_pendidikan_id));
    res.json(standardMapel);
}));

app.get("/api/tingkat_pendidikan", authenticate, asyncHandler(async (req: any, res: any) => {
    let { jenjang_pendidikan_id } = req.query;
    
    // If not provided, fetch from pengaturan_sekolah
    if (!jenjang_pendidikan_id) {
        try {
            const [settings]: any = await getPool().query("SELECT bentuk_pendidikan FROM pengaturan_sekolah WHERE id = 1");
            if (settings && settings.length > 0 && settings[0].bentuk_pendidikan) {
                jenjang_pendidikan_id = settings[0].bentuk_pendidikan;
            }
        } catch (e) {}
    }

    const standardTingkat = getStandardTingkatPendidikan(String(jenjang_pendidikan_id || '4'));

    const candidateTables = ['ref.tingkat_pendidikan', 'tingkat_pendidikan', 'ref_tingkat_pendidikan'];
    for (const tbl of candidateTables) {
        try {
            let sql = `SELECT tingkat_pendidikan_id as id, nama as label, kode as value FROM \`${tbl}\``;
            const params: any[] = [];
            if (jenjang_pendidikan_id) {
                sql += ` WHERE jenjang_pendidikan_id = ?`;
                params.push(jenjang_pendidikan_id);
            }
            sql += ` ORDER BY CAST(tingkat_pendidikan_id AS UNSIGNED) ASC`;
            const [rows]: any = await getPool().query(sql, params);
            if (rows && rows.length > 0) return res.json(rows);
        } catch (e) {}
    }

    res.json(standardTingkat);
}));

app.get("/api/kurikulum", authenticate, asyncHandler(async (req: any, res: any) => {
    const jenjang = req.query.jenjang ? String(req.query.jenjang).toLowerCase() : '';
    
    // Map jenjang string / id to possible jenjang_pendidikan_id in Dapodik
    let jenjangIds: any[] = [];
    if (jenjang) {
        if (jenjang.includes('sd') || jenjang === '4' || jenjang === '7' || jenjang.includes('paket a') || jenjang.includes('dasar')) {
            jenjangIds = [1, 2, 4, 7, '1', '2', '4', '7'];
        } else if (jenjang.includes('smp') || jenjang === '5' || jenjang === '8' || jenjang.includes('paket b')) {
            jenjangIds = [2, 3, 5, 8, '2', '3', '5', '8'];
        } else if (jenjang.includes('sma') || jenjang.includes('smk') || jenjang === '6' || jenjang === '9' || jenjang.includes('paket c') || jenjang.includes('menengah')) {
            jenjangIds = [3, 4, 5, 6, 9, '3', '4', '5', '6', '9'];
        } else {
            jenjangIds = [jenjang];
        }
    }

    let rows: any[] = [];
    const pool = getPool();

    // Try finding in `ref.kurikulum`, `kurikulum`, or `ref_kurikulum`
    const candidateTables = ['ref.kurikulum', 'kurikulum', 'ref_kurikulum'];
    for (const tbl of candidateTables) {
        try {
            if (jenjangIds.length > 0) {
                const placeholders = jenjangIds.map(() => '?').join(',');
                const [r]: any = await pool.query(
                    `SELECT kurikulum_id, nama_kurikulum FROM \`${tbl}\` WHERE jenjang_pendidikan_id IN (${placeholders}) OR jenjang_pendidikan_id IS NULL ORDER BY nama_kurikulum ASC`,
                    jenjangIds
                );
                if (r && r.length > 0) {
                    rows = r;
                    break;
                }
            }
            const [allR]: any = await pool.query(`SELECT kurikulum_id, nama_kurikulum FROM \`${tbl}\` ORDER BY nama_kurikulum ASC`);
            if (allR && allR.length > 0) {
                rows = allR;
                break;
            }
        } catch (e) {}
    }

    // Default fallback list of active national curriculums
    if (rows.length === 0) {
        rows = [
            { kurikulum_id: 1, nama_kurikulum: 'Kurikulum Merdeka' },
            { kurikulum_id: 2, nama_kurikulum: 'Kurikulum 2013' },
            { kurikulum_id: 3, nama_kurikulum: 'Kurikulum 2013 Revisi' },
            { kurikulum_id: 4, nama_kurikulum: 'Kurikulum Tingkat Satuan Pendidikan (KTSP)' }
        ];
    }

    res.json(rows);
}));

app.post("/api/absensi", authenticate, asyncHandler(async (req: any, res: any) => {
    const { tanggal, rombel, records } = req.body;
    if (!tanggal || !rombel || !Array.isArray(records)) {
        return res.status(400).json({ error: "Data tidak lengkap" });
    }

    // Double check if weekend or holiday
    const reqDate = new Date(tanggal);
    if (reqDate.getDay() === 0 || reqDate.getDay() === 6) {
        return res.status(400).json({ error: "Libur Akhir Pekan" });
    }
    const [holidays]: any = await getPool().execute(
        "SELECT title FROM kalender_akademik WHERE category = 'Holiday' AND event_date = ?",
        [tanggal]
    );
    if (holidays.length > 0) {
        return res.status(400).json({ error: `Hari Libur: ${holidays[0].title}` });
    }

    const conn = await getPool().getConnection();
    try {
        await conn.beginTransaction();

        for (const rec of records) {
            if (rec.status === 'Hadir' && !rec.keterangan) {
                await conn.execute(
                    "DELETE FROM absensi_siswa WHERE student_id = ? AND tanggal = ?",
                    [rec.student_id, tanggal]
                );
            } else {
                await conn.execute(
                    `INSERT INTO absensi_siswa (student_id, tanggal, status, keterangan, recorded_by)
                     VALUES (?, ?, ?, ?, ?)
                     ON DUPLICATE KEY UPDATE status = VALUES(status), keterangan = VALUES(keterangan), recorded_by = VALUES(recorded_by)`,
                    [rec.student_id, tanggal, rec.status, rec.keterangan || null, req.user.staff_id || null]
                );
            }
        }

        await conn.commit();
        res.json({ success: true });
    } catch (err) {
        await conn.rollback();
        throw err;
    } finally {
        conn.release();
    }
}));

app.get("/api/absensi/report", authenticate, asyncHandler(async (req: any, res: any) => {
    const { start_date, end_date, rombel } = req.query;
    if (!start_date || !end_date || !rombel) return res.status(400).json({ error: "Parameter tidak lengkap" });

    // Calculate Working Days
    const [holidays]: any = await getPool().execute(
        "SELECT event_date FROM kalender_akademik WHERE category = 'Holiday' AND event_date >= ? AND event_date <= ?",
        [start_date, end_date]
    );
    const holidayStrs = holidays.map((h: any) => {
        const d = new Date(h.event_date);
        d.setMinutes(d.getMinutes() - d.getTimezoneOffset());
        return d.toISOString().split('T')[0];
    });

    let workingDays = 0;
    const sDate = new Date(start_date);
    const eDate = new Date(end_date);
    for (let d = new Date(sDate); d <= eDate; d.setDate(d.getDate() + 1)) {
        const day = d.getDay();
        if (day !== 0 && day !== 6) { // Not Sunday or Saturday
            const dLocal = new Date(d);
            dLocal.setMinutes(dLocal.getMinutes() - dLocal.getTimezoneOffset());
            const dStr = dLocal.toISOString().split('T')[0];
            if (!holidayStrs.includes(dStr)) {
                workingDays++;
            }
        }
    }

    const [students]: any = await getPool().execute(
        "SELECT s.peserta_didik_id as id, s.nisn, rpd.nipd, s.nama as nama_lengkap FROM peserta_didik s LEFT JOIN registrasi_peserta_didik rpd ON s.peserta_didik_id = rpd.peserta_didik_id JOIN anggota_rombel ar ON s.peserta_didik_id = ar.peserta_didik_id JOIN rombongan_belajar rb ON ar.rombongan_belajar_id = rb.rombongan_belajar_id WHERE rb.nama = ? ORDER BY s.nama ASC",
        [rombel]
    );

    const [attendance]: any = await getPool().execute(
        `SELECT a.student_id, a.status, COUNT(*) as count
         FROM absensi_siswa a
         JOIN peserta_didik s ON a.student_id = s.peserta_didik_id
         JOIN anggota_rombel ar ON s.peserta_didik_id = ar.peserta_didik_id
         JOIN rombongan_belajar rb ON ar.rombongan_belajar_id = rb.rombongan_belajar_id
         WHERE rb.nama = ? AND a.tanggal >= ? AND a.tanggal <= ?
         GROUP BY a.student_id, a.status`,
        [rombel, start_date, end_date]
    );

    const reportMap = new Map();
    students.forEach((s: any) => {
        reportMap.set(s.id, {
            ...s,
            hadir: 0,
            sakit: 0,
            izin: 0,
            alpa: 0
        });
    });

    attendance.forEach((a: any) => {
        const rec = reportMap.get(a.student_id);
        if (rec) {
            if (a.status === 'Sakit') rec.sakit = a.count;
            else if (a.status === 'Izin') rec.izin = a.count;
            else if (a.status === 'Tanpa Keterangan') rec.alpa = a.count;
        }
    });

    const reportArray = Array.from(reportMap.values()).map((rec: any) => {
        rec.hadir = Math.max(0, workingDays - rec.sakit - rec.izin - rec.alpa);
        return rec;
    });

    res.json({ workingDays, report: reportArray });
}));

