const ENCRYPTION_SECRET = crypto.createHash('sha256').update(String(process.env.JWT_SECRET || 'dapoy-secret-key-2026')).digest();

function encryptPassword(plain: string): string {
    if (!plain) return '';
    try {
        const iv = crypto.randomBytes(16);
        const cipher = crypto.createCipheriv('aes-256-cbc', ENCRYPTION_SECRET, iv);
        let encrypted = cipher.update(plain, 'utf8', 'hex');
        encrypted += cipher.final('hex');
        return iv.toString('hex') + ':' + encrypted;
    } catch (e) {
        return '';
    }
}

function decryptPassword(ciphertext: string): string {
    if (!ciphertext || !ciphertext.includes(':')) return '';
    try {
        const [ivHex, encHex] = ciphertext.split(':');
        const iv = Buffer.from(ivHex, 'hex');
        const decipher = crypto.createDecipheriv('aes-256-cbc', ENCRYPTION_SECRET, iv);
        let decrypted = decipher.update(encHex, 'hex', 'utf8');
        decrypted += decipher.final('utf8');
        return decrypted;
    } catch (e) {
        return '';
    }
}

async function ensurePtkEmailTable(pool: any) {
    try {
        await pool.query(`
            CREATE TABLE IF NOT EXISTS ptk_email_sekolah (
                id INT AUTO_INCREMENT PRIMARY KEY,
                ptk_id VARCHAR(100) NOT NULL UNIQUE,
                email VARCHAR(255) NOT NULL UNIQUE,
                quota_mb INT DEFAULT 500,
                nama_label VARCHAR(255) DEFAULT NULL,
                is_official TINYINT(1) DEFAULT 0,
                encrypted_pass TEXT DEFAULT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
            )
        `);
        await ensureColumn(pool, 'ptk_email_sekolah', 'nama_label', 'VARCHAR(255) DEFAULT NULL');
        await ensureColumn(pool, 'ptk_email_sekolah', 'is_official', 'TINYINT(1) DEFAULT 0');
        await ensureColumn(pool, 'ptk_email_sekolah', 'encrypted_pass', 'TEXT DEFAULT NULL');
    } catch (e: any) {
        console.warn("[DB] Warning ensuring ptk_email_sekolah table:", e.message);
    }
}

app.get(["/api/cpanel/accounts", "/api/cpanel/email-accounts"], authenticate, asyncHandler(async (req: any, res: any) => {
    const p = getPool();
    await ensurePtkEmailTable(p);
    const config = await getCpanelConfig(p);

    // 1. Ambil semua email yang tercatat di database lokal ptk_email_sekolah
    let localRecords: any[] = [];
    try {
        const [rows]: any = await p.query(`
            SELECT pe.ptk_id, pe.email, pe.quota_mb, pe.nama_label, pe.is_official, pe.created_at, pe.updated_at,
                   p.nama as staff_nama, p.nip as staff_nip, p.jenis_ptk
            FROM ptk_email_sekolah pe
            LEFT JOIN ptk p ON pe.ptk_id = p.ptk_id OR pe.ptk_id = CAST(p.id AS CHAR)
            ORDER BY pe.created_at DESC
        `);
        localRecords = rows || [];
    } catch (e: any) {
        console.warn("[cPanel] Warning querying ptk_email_sekolah:", e.message);
    }

    // 2. Ambil juga pegawai dari ptk yang mungkin memiliki email_sekolah
    try {
        const [ptkWithEmail]: any = await p.query(`
            SELECT ptk_id, email_sekolah, nama as staff_nama, nip as staff_nip, jenis_ptk
            FROM ptk 
            WHERE email_sekolah IS NOT NULL AND email_sekolah != ''
        `);
        for (const ptk of ptkWithEmail || []) {
            if (!localRecords.some(r => r.email?.toLowerCase() === ptk.email_sekolah?.toLowerCase())) {
                localRecords.push({
                    ptk_id: ptk.ptk_id,
                    email: ptk.email_sekolah,
                    quota_mb: 500,
                    staff_nama: ptk.staff_nama,
                    staff_nip: ptk.staff_nip,
                    jenis_ptk: ptk.jenis_ptk,
                    nama_label: null,
                    is_official: 0,
                    created_at: new Date()
                });
            }
        }
    } catch (e: any) {}

    // 3. Ambil seluruh staff PTK untuk mencocokkan akun cPanel jika ada yang belum tertaut
    let allStaff: any[] = [];
    try {
        const [sRows]: any = await p.query("SELECT ptk_id, nama, nip, jenis_ptk FROM ptk WHERE (soft_delete = 0 OR soft_delete IS NULL)");
        allStaff = sRows || [];
    } catch (e: any) {}

    let pops: any[] = [];
    if (config && config.host && config.apiToken) {
        try {
            pops = await listCpanelEmailAccounts(config);
        } catch (e: any) {
            console.warn("[cPanel] Warning fetching pops from cPanel:", e.message);
        }
    }

    // Tentukan domain aktif dengan cerdas: Query param -> Request Host (jika bukan localhost/IP) -> Konfigurasi cPanel
    const queryDomain = (req.query.domain ? String(req.query.domain) : '').trim().toLowerCase();
    const reqHost = (req.get('host') || '').split(':')[0].replace(/^www\./, '').trim().toLowerCase();
    
    let activeDomain = queryDomain;
    if (!activeDomain && reqHost && !['localhost', '127.0.0.1', '::1'].includes(reqHost) && reqHost.includes('.')) {
        activeDomain = reqHost;
    }
    if (!activeDomain) {
        activeDomain = (config?.domain || reqHost || '').trim().toLowerCase();
    }

    function cleanFullEmail(rawEmail: string, fallbackDomain: string = ''): { user: string, domain: string, full: string } {
        if (!rawEmail) return { user: '', domain: fallbackDomain, full: '' };
        const clean = rawEmail.trim().toLowerCase();
        if (clean.includes('@')) {
            const parts = clean.split('@');
            const user = parts[0].trim();
            const domain = (parts[1] || fallbackDomain).trim().toLowerCase();
            return { user, domain, full: domain ? `${user}@${domain}` : user };
        }
        const dom = (fallbackDomain || '').trim().toLowerCase();
        return { user: clean, domain: dom, full: dom ? `${clean}@${dom}` : clean };
    }

    const emailMap = new Map<string, any>();

    // Masukkan record dari database lokal dulu (menjamin akun yang baru dibuat PASTI muncul)
    for (const rec of localRecords) {
        if (!rec.email) continue;
        const cleaned = cleanFullEmail(rec.email, activeDomain);
        if (!cleaned.user) continue;

        // Filter: Hanya izinkan email yang cocok dengan activeDomain jika terdefinisi
        if (activeDomain && cleaned.domain && cleaned.domain.toLowerCase() !== activeDomain) {
            continue;
        }

        const isOfficial = rec.is_official === 1 || String(rec.ptk_id || '').startsWith('official_') || !rec.staff_nama;
        const staffNama = rec.staff_nama || rec.nama_label || (isOfficial ? 'Akun Official Sekolah' : null);
        const jenisPtk = rec.jenis_ptk || (isOfficial ? 'Official / Khusus' : 'Guru / GTK');

        emailMap.set(cleaned.full, {
            email: cleaned.user,
            domain: cleaned.domain,
            full_email: cleaned.full,
            quota: rec.quota_mb || 500,
            diskused: 0,
            humandiskquota: `${rec.quota_mb || 500} MB`,
            humandiskused: '0 MB',
            staff_nama: staffNama,
            nama_label: rec.nama_label || null,
            is_official: isOfficial ? 1 : 0,
            staff_nip: rec.staff_nip || null,
            staff_ptk_id: rec.ptk_id || null,
            jenis_ptk: jenisPtk,
            created_at: rec.created_at
        });
    }

    // Perkaya atau tambahkan akun dari cPanel
    for (const pop of pops || []) {
        const emailField = (pop.email || pop.login || '').trim().toLowerCase();
        const userField = (pop.user || '').trim().toLowerCase();
        const domainField = (pop.domain || '').trim().toLowerCase();

        let rawUser = '';
        let rawDomain = domainField || activeDomain;

        if (emailField && emailField.includes('@')) {
            const splitted = emailField.split('@');
            rawUser = splitted[0].trim();
            rawDomain = (splitted[1] || rawDomain).trim();
        } else if (userField) {
            if (userField.includes('@')) {
                const splitted = userField.split('@');
                rawUser = splitted[0].trim();
                rawDomain = (splitted[1] || rawDomain).trim();
            } else {
                rawUser = userField;
            }
        } else if (emailField) {
            rawUser = emailField;
        }

        if (!rawUser) continue;
        rawUser = rawUser.trim().toLowerCase();
        rawDomain = rawDomain.trim().toLowerCase();

        const fullEmail = rawDomain ? `${rawUser}@${rawDomain}` : rawUser;

        // Filter: Hanya izinkan email yang cocok dengan activeDomain jika activeDomain ada
        if (activeDomain && rawDomain && rawDomain !== activeDomain) {
            continue;
        }

        const existing = emailMap.get(fullEmail);

        let matchedStaff: any = null;
        if (!existing) {
            matchedStaff = allStaff.find(s => {
                const cleanStaffName = (s.nama || '').toLowerCase().replace(/[^a-z0-9]/g, '');
                return cleanStaffName.includes(rawUser) || (s.nip && s.nip.includes(rawUser));
            });
        }

        if (existing) {
            existing.diskused = pop.diskused ?? pop.diskusedpercent ?? existing.diskused;
            existing.diskquota = pop.diskquota ?? pop.quota ?? existing.quota;
            existing.humandiskquota = pop.humandiskquota || existing.humandiskquota;
            existing.humandiskused = pop.humandiskused || existing.humandiskused;
            existing.suspended_outgoing = pop.suspended_outgoing ?? pop.suspended_out ?? 0;
            existing.suspended_incoming = pop.suspended_incoming ?? pop.suspended_in ?? 0;
            existing.suspended_login = pop.suspended_login ?? pop.suspended_log ?? 0;
        } else {
            const isOfficial = !matchedStaff;
            emailMap.set(fullEmail, {
                ...pop,
                email: rawUser,
                domain: rawDomain,
                full_email: fullEmail,
                staff_nama: matchedStaff?.nama || (isOfficial ? 'Akun Official Sekolah' : null),
                staff_nip: matchedStaff?.nip || null,
                staff_ptk_id: matchedStaff?.ptk_id || `official_${rawUser}`,
                is_official: isOfficial ? 1 : 0,
                nama_label: isOfficial ? 'Akun Official Sekolah' : null,
                jenis_ptk: matchedStaff?.jenis_ptk || (isOfficial ? 'Official / Khusus' : 'Guru / GTK')
            });
        }
    }

    const allAccounts = Array.from(emailMap.values());
    res.json({ success: true, accounts: allAccounts, active_domain: activeDomain });
}));

app.post("/api/cpanel/create-email", authenticate, asyncHandler(async (req: any, res: any) => {
    let ptk_id = req.body.ptk_id || req.body.id;
    const email_username = req.body.email_username || req.body.email_user || req.body.username;
    const password = req.body.password;
    const domain = req.body.domain;
    const quota_mb = req.body.quota_mb !== undefined ? req.body.quota_mb : req.body.quotaMb;
    const account_type = req.body.account_type || (ptk_id && ptk_id !== 'official' && ptk_id !== 'custom' ? 'staff' : 'official');
    const nama_label = req.body.nama_label || req.body.label_nama || '';

    if (!email_username || !password) {
        return res.status(400).json({ error: "Username email dan password wajib diisi." });
    }

    const isOfficial = account_type === 'official' || !ptk_id || ptk_id === 'official' || ptk_id === 'custom';
    if (isOfficial) {
        ptk_id = `official_${email_username.toLowerCase().replace(/[^a-z0-9]/g, '')}_${Date.now()}`;
    }

    const config = await getCpanelConfig(getPool());
    if (!config || !config.host || !config.apiToken) {
        return res.status(400).json({ error: "cPanel belum dikonfigurasi. Silakan isi Host, User, dan API Token di Pengaturan." });
    }

    const targetDomain = (domain || config.domain || '').trim();

    const p = getPool();
    await ensurePtkEmailTable(p);

    // Call cPanel UAPI to create the mailbox
    let result: any;
    try {
        result = await createCpanelEmailAccount(
            config, 
            email_username, 
            password, 
            quota_mb !== undefined ? Number(quota_mb) : (config.defaultQuotaMb || 500),
            targetDomain
        );
    } catch (err: any) {
        console.error("[cPanel] create-email failed:", err);
        return res.status(400).json({ error: err.message || "Gagal membuat email di server cPanel." });
    }

    // Save or update to ptk_email_sekolah table
    const encPass = encryptPassword(password);
    try {
        await p.query(`
            INSERT INTO ptk_email_sekolah (ptk_id, email, quota_mb, nama_label, is_official, encrypted_pass)
            VALUES (?, ?, ?, ?, ?, ?)
            ON DUPLICATE KEY UPDATE
                email = VALUES(email),
                quota_mb = VALUES(quota_mb),
                nama_label = VALUES(nama_label),
                is_official = VALUES(is_official),
                encrypted_pass = VALUES(encrypted_pass),
                updated_at = CURRENT_TIMESTAMP
        `, [ptk_id, result.email, quota_mb || config.defaultQuotaMb || 500, nama_label || (isOfficial ? 'Akun Official Sekolah' : null), isOfficial ? 1 : 0, encPass]);
    } catch (e: any) {
        console.error("[cPanel] Error inserting ptk_email_sekolah:", e);
    }

    if (!isOfficial) {
        // Also update email_sekolah column on ptk table if exists
        try {
            await p.query(`UPDATE ptk SET email_sekolah = ? WHERE ptk_id = ? OR CAST(id AS CHAR) = ?`, [result.email, ptk_id, ptk_id]);
        } catch (e: any) {}
    }

    // Also generate mobile setup details
    const mobileGuide = generateMobileGuide(result.email, targetDomain || config.domain, config.webmailUrl);

    res.json({
        success: true,
        email: result.email,
        message: `Akun email ${result.email} berhasil dibuat!`,
        mobileGuide,
        guide: mobileGuide
    });
}));

app.post("/api/cpanel/reset-password", authenticate, asyncHandler(async (req: any, res: any) => {
    const ptk_id = req.body.ptk_id || req.body.id;
    const email = req.body.email;
    const new_password = req.body.new_password || req.body.password;
    if ((!ptk_id && !email) || !new_password) {
        return res.status(400).json({ error: "Email/PTK ID dan password baru wajib diisi." });
    }

    const config = await getCpanelConfig(getPool());
    if (!config) {
        return res.status(400).json({ error: "cPanel belum dikonfigurasi." });
    }

    let fullEmail = email;
    if (!fullEmail && ptk_id) {
        const [rows]: any = await getPool().query("SELECT email FROM ptk_email_sekolah WHERE ptk_id = ? OR email = ?", [ptk_id, ptk_id]);
        if (rows && rows.length > 0) {
            fullEmail = rows[0].email;
        } else if (String(ptk_id).includes('@')) {
            fullEmail = ptk_id;
        }
    }

    if (!fullEmail) {
        return res.status(404).json({ error: "Akun email tidak ditemukan." });
    }

    const [userPart, domainPart] = fullEmail.split('@');
    try {
        await changeCpanelEmailPassword(config, userPart, new_password, domainPart || config.domain);
    } catch (err: any) {
        return res.status(400).json({ error: err.message || "Gagal mengubah password di cPanel." });
    }

    const encPass = encryptPassword(new_password);
    try {
        const [exist]: any = await getPool().query("SELECT id FROM ptk_email_sekolah WHERE email = ? OR ptk_id = ?", [fullEmail, ptk_id || '']);
        if (exist && exist.length > 0) {
            await getPool().query(
                "UPDATE ptk_email_sekolah SET encrypted_pass = ?, updated_at = CURRENT_TIMESTAMP WHERE email = ? OR ptk_id = ?",
                [encPass, fullEmail, ptk_id || '']
            );
        } else {
            await getPool().query(
                "INSERT INTO ptk_email_sekolah (ptk_id, email, encrypted_pass, is_official) VALUES (?, ?, ?, 1) ON DUPLICATE KEY UPDATE encrypted_pass = VALUES(encrypted_pass)",
                [ptk_id || `official-${Date.now()}`, fullEmail, encPass]
            );
        }
    } catch (e: any) {
        console.error("[cPanel] Error updating encrypted_pass on reset:", e);
    }

    res.json({ success: true, message: `Password email ${fullEmail} berhasil diperbarui di server cPanel!` });
}));

