app.get("/api/cpanel/webmail-sso/:ptk_id", authenticate, asyncHandler(async (req: any, res: any) => {
    const { ptk_id } = req.params;
    const config = await getCpanelConfig(getPool());
    if (!config) {
        return res.status(400).json({ error: "cPanel belum dikonfigurasi. Silakan simpan pengaturan cPanel." });
    }

    let [rows]: any = await getPool().query("SELECT email FROM ptk_email_sekolah WHERE ptk_id = ? OR email = ?", [ptk_id, ptk_id]);
    if (!rows || rows.length === 0) {
        [rows] = await getPool().query(`
            SELECT pe.email 
            FROM ptk_email_sekolah pe 
            JOIN ptk p ON pe.ptk_id = p.ptk_id 
            WHERE p.id = ?
        `, [ptk_id]);
    }
    
    let fullEmail = (rows && rows.length > 0) ? rows[0].email : (ptk_id.includes('@') ? ptk_id : null);
    if (!fullEmail) {
        return res.status(404).json({ error: "Pegawai ini belum memiliki akun email sekolah." });
    }

    const getReqClientIp = (request: any) => {
        const xff = request.headers['x-forwarded-for'];
        if (xff) {
            const list = typeof xff === 'string' ? xff.split(',') : xff;
            if (list.length > 0) return String(list[0]).trim();
        }
        const realIp = request.headers['x-real-ip'];
        if (realIp) return String(realIp).trim();
        const sockIp = request.socket?.remoteAddress || request.connection?.remoteAddress || request.ip || '';
        return String(sockIp).replace(/^::ffff:/, '').trim();
    };

    try {
        const clientIp = getReqClientIp(req);
        const ssoUrl = await createCpanelWebmailSession(config, fullEmail, clientIp);
        const isSSO = ssoUrl.includes('/cpsess') && (ssoUrl.includes('session=') || ssoUrl.includes('/3rdparty/roundcube/'));
        res.json({ success: true, url: ssoUrl, isSSO, email: fullEmail });
    } catch (err: any) {
        console.error("[cPanel SSO Error]:", err.message);
        const domainPart = fullEmail.split('@')[1] || config.domain;
        res.json({ 
            success: false, 
            error: err.message, 
            url: `https://${domainPart}/webmail`, 
            isSSO: false, 
            email: fullEmail 
        });
    }
}));

