let ImapFlowClass: any = null;
let nodemailerLib: any = null;
let simpleParserFunc: any = null;

async function getMailModules() {
    if (!ImapFlowClass) {
        try {
            const mod = await import("imapflow");
            ImapFlowClass = mod.ImapFlow || mod.default?.ImapFlow || mod.default || mod;
        } catch (e: any) {
            console.warn("[Webmail] ImapFlow module not found:", e.message);
        }
    }
    if (!nodemailerLib) {
        try {
            const mod = await import("nodemailer");
            nodemailerLib = mod.default || mod;
        } catch (e: any) {
            console.warn("[Webmail] nodemailer module not found:", e.message);
        }
    }
    if (!simpleParserFunc) {
        try {
            const mod = await import("mailparser");
            simpleParserFunc = mod.simpleParser || mod.default?.simpleParser || mod.default || mod;
        } catch (e: any) {
            console.warn("[Webmail] mailparser module not found:", e.message);
        }
    }
    return {
        ImapFlow: ImapFlowClass,
        nodemailer: nodemailerLib,
        simpleParser: simpleParserFunc
    };
}

async function getUserEmailCredentials(pool: any, user: any, requestedEmail?: string, allowNoPassword = false) {
    const config = await getCpanelConfig(pool);
    let email = (requestedEmail || user?.email_sekolah || user?.email || '').trim();

    let [rows]: any = [];
    if (email) {
        [rows] = await pool.query(
            "SELECT id, ptk_id, email, encrypted_pass, nama_label, is_official FROM ptk_email_sekolah WHERE email = ?", 
            [email]
        );
    }
    if ((!rows || rows.length === 0) && user?.staff_id) {
        [rows] = await pool.query(
            "SELECT id, ptk_id, email, encrypted_pass, nama_label, is_official FROM ptk_email_sekolah WHERE ptk_id = ? OR ptk_id = (SELECT ptk_id FROM pegawai WHERE pegawai_id = ? OR nik = ? LIMIT 1)",
            [user.staff_id, user.staff_id, user.staff_id]
        );
    }
    if ((!rows || rows.length === 0) && user?.username) {
        [rows] = await pool.query(
            "SELECT id, ptk_id, email, encrypted_pass, nama_label, is_official FROM ptk_email_sekolah WHERE ptk_id = (SELECT staff_id FROM pengguna_web WHERE username = ? LIMIT 1) OR ptk_id = (SELECT ptk_id FROM pegawai WHERE nik = ? OR nip = ? LIMIT 1) OR ptk_id = (SELECT ptk_id FROM ptk WHERE nik = ? OR nip = ? LIMIT 1)",
            [user.username, user.username, user.username, user.username, user.username]
        );
    }
    if ((!rows || rows.length === 0) && user?.id) {
        [rows] = await pool.query(
            "SELECT id, ptk_id, email, encrypted_pass, nama_label, is_official FROM ptk_email_sekolah WHERE ptk_id = (SELECT staff_id FROM pengguna_web WHERE id = ? LIMIT 1)",
            [user.id]
        );
    }

    const rec = (rows && rows.length > 0) ? rows[0] : null;
    const finalEmail = rec ? rec.email : email;
    if (!finalEmail) {
        throw new Error("Akun email resmi belum terdaftar di sistem.");
    }

    const plainPass = rec?.encrypted_pass ? decryptPassword(rec.encrypted_pass) : '';
    if (!plainPass && !allowNoPassword) {
        throw new Error("Password email belum tersimpan di portal. Silakan hubungkan password akun email Anda.");
    }

    const domainPart = finalEmail.split('@')[1] || config?.domain || '';
    const rawHost = config?.host ? config.host.replace(/^https?:\/\//, '').split(':')[0] : `mail.${domainPart}`;
    const mailHost = rawHost.includes('.') ? rawHost : `mail.${domainPart}`;

    // Ambil nama sekolah
    let schoolName = "Sekolah";
    try {
        const [schRows]: any = await pool.query("SELECT school_name FROM pengaturan_sekolah WHERE id = 1");
        if (schRows && schRows.length > 0 && schRows[0].school_name) {
            schoolName = schRows[0].school_name;
        }
    } catch (e) {}

    // Deteksi apakah email official sekolah
    const userPrefix = finalEmail.split('@')[0].toLowerCase();
    const isOfficial = !!(rec?.is_official || ['info', 'admin', 'humas', 'kontak', 'official', 'sekolah', 'mail', 'dinas', 'tatausaha', 'tu'].includes(userPrefix));

    let senderName = '';
    if (isOfficial) {
        senderName = schoolName;
    } else {
        // 1. Coba dari nama_label di ptk_email_sekolah
        if (rec?.nama_label && rec.nama_label.trim()) {
            senderName = rec.nama_label.trim();
        }
        // 2. Coba cari nama PTK dari tabel ptk
        if (!senderName && rec?.ptk_id) {
            try {
                const [pRows]: any = await pool.query("SELECT nama FROM ptk WHERE ptk_id = ? LIMIT 1", [rec.ptk_id]);
                if (pRows && pRows.length > 0 && pRows[0].nama) {
                    senderName = pRows[0].nama;
                }
            } catch (e) {}
        }
        // 3. Coba cari nama pegawai dari tabel pegawai
        if (!senderName && rec?.ptk_id) {
            try {
                const [pegRows]: any = await pool.query("SELECT nama FROM pegawai WHERE ptk_id = ? OR pegawai_id = ? LIMIT 1", [rec.ptk_id, rec.ptk_id]);
                if (pegRows && pegRows.length > 0 && pegRows[0].nama) {
                    senderName = pegRows[0].nama;
                }
            } catch (e) {}
        }
        // 4. Fallback: Format huruf awal kapital dari user email (misal: "ana" -> "Ana")
        if (!senderName) {
            senderName = userPrefix.charAt(0).toUpperCase() + userPrefix.slice(1);
        }
    }

    return {
        email: finalEmail,
        password: plainPass,
        hasPassword: !!plainPass,
        imapHost: mailHost,
        smtpHost: mailHost,
        domainPart,
        isOfficial,
        senderName,
        schoolName
    };
}

async function createImapClient(credentials: { email: string; password: string; imapHost: string; domainPart?: string }) {
    const { ImapFlow } = await getMailModules();
    if (!ImapFlow) {
        throw new Error("Modul email IMAP sedang dimuat atau belum tersedia di server. Pastikan dependencies terpasang.");
    }

    const hostCandidates: { host: string; port: number; secure: boolean }[] = [
        { host: '127.0.0.1', port: 993, secure: true },
        { host: 'localhost', port: 993, secure: true },
        { host: credentials.imapHost, port: 993, secure: true },
        { host: credentials.domainPart ? `mail.${credentials.domainPart}` : '', port: 993, secure: true },
        { host: credentials.domainPart || '', port: 993, secure: true },
        { host: '127.0.0.1', port: 143, secure: false },
        { host: credentials.imapHost, port: 143, secure: false }
    ].filter(c => !!c.host);

    const uniqueCandidates = hostCandidates.filter((item, index, self) =>
        index === self.findIndex((t) => t.host === item.host && t.port === item.port)
    );

    let lastError: any = null;
    for (const candidate of uniqueCandidates) {
        try {
            const client = new ImapFlow({
                host: candidate.host,
                port: candidate.port,
                secure: candidate.secure,
                auth: {
                    user: credentials.email,
                    pass: credentials.password
                },
                tls: {
                    rejectUnauthorized: false,
                    servername: credentials.domainPart || undefined
                },
                logger: false,
                emitLogs: false
            });
            await client.connect();
            return client;
        } catch (err: any) {
            lastError = err;
            console.warn(`[Webmail IMAP] Failed to connect via ${candidate.host}:${candidate.port}:`, err.message);
        }
    }
    throw new Error(`Gagal terhubung ke Mail Server: ${lastError?.message || 'Koneksi ditolak'}`);
}

