async function resolveMailboxName(client: any, requestedFolder: string): Promise<string> {
    const cleanReq = (requestedFolder || 'INBOX').trim();
    if (cleanReq.toUpperCase() === 'INBOX') return 'INBOX';

    try {
        const mailboxes = await client.list();
        if (cleanReq.toLowerCase() === 'sent') {
            const match = mailboxes.find((m: any) => 
                m.specialUse === '\\Sent' || 
                m.path.toLowerCase() === 'inbox.sent' || 
                m.path.toLowerCase() === 'sent' || 
                m.path.toLowerCase() === 'sent messages' ||
                m.path.toLowerCase() === 'sent items' ||
                m.name.toLowerCase() === 'sent'
            );
            if (match) return match.path;
        }

        if (cleanReq.toLowerCase() === 'trash') {
            const match = mailboxes.find((m: any) => 
                m.specialUse === '\\Trash' || 
                m.path.toLowerCase() === 'inbox.trash' || 
                m.path.toLowerCase() === 'trash' || 
                m.path.toLowerCase() === 'deleted messages' ||
                m.path.toLowerCase() === 'deleted items' ||
                m.name.toLowerCase() === 'trash'
            );
            if (match) return match.path;
        }

        if (cleanReq.toLowerCase() === 'drafts') {
            const match = mailboxes.find((m: any) => 
                m.specialUse === '\\Drafts' || 
                m.path.toLowerCase() === 'inbox.drafts' || 
                m.path.toLowerCase() === 'drafts' ||
                m.name.toLowerCase() === 'drafts'
            );
            if (match) return match.path;
        }

        const directMatch = mailboxes.find((m: any) => m.path.toLowerCase() === cleanReq.toLowerCase() || m.name.toLowerCase() === cleanReq.toLowerCase());
        if (directMatch) return directMatch.path;
    } catch (e) {
        console.warn("[Mailbox Resolve Error]:", e);
    }

    return cleanReq;
}

