app.post("/api/webmail/send", authenticate, mailAttachmentUpload.array('attachments', 10), asyncHandler(async (req: any, res: any) => {
    try {
        const creds = await getUserEmailCredentials(getPool(), req.user, req.body.email);
        const { to, cc, bcc, subject, text, html, inReplyTo, references, draftId } = req.body;

        if (!to) {
            return res.status(400).json({ error: "Alamat penerima (To) wajib diisi." });
        }

        const { nodemailer } = await getMailModules();
        if (!nodemailer) {
            return res.status(500).json({ error: "Modul pengiriman email belum tersedia di server." });
        }

        const mailAttachments = ((req.files as Express.Multer.File[]) || []).map((file: any) => ({
            filename: file.originalname,
            path: file.path,
            contentType: file.mimetype
        }));

        const senderName = creds.senderName || (creds.isOfficial ? creds.schoolName : creds.email.split('@')[0]);
        const mailOptions: any = {
            from: `"${senderName}" <${creds.email}>`,
            to,
            cc: cc || undefined,
            bcc: bcc || undefined,
            subject: subject || '(Tanpa Subjek)',
            text: text || (html ? html.replace(/<[^>]*>?/gm, '') : ''),
            html: html || undefined,
            inReplyTo: inReplyTo || undefined,
            references: references || undefined,
            attachments: mailAttachments
        };

        // 1. Buat stream raw RFC822 message SEBELUM file attachment dihapus dari disk
        let rawBuffer: Buffer | null = null;
        try {
            const streamTransporter = nodemailer.createTransport({
                streamTransport: true,
                newline: 'windows',
                buffer: true
            });
            const rawResult: any = await streamTransporter.sendMail(mailOptions);
            if (rawResult && rawResult.message) {
                if (Buffer.isBuffer(rawResult.message)) {
                    rawBuffer = rawResult.message;
                } else {
                    const chunks: any[] = [];
                    for await (const chunk of rawResult.message) {
                        chunks.push(chunk);
                    }
                    rawBuffer = Buffer.concat(chunks);
                }
            }
        } catch (buildErr: any) {
            console.warn("[Webmail] Note: raw RFC822 compile warning:", buildErr.message);
        }

        // 2. Kirim email melalui kandidat SMTP
        const smtpCandidates = [
            { host: '127.0.0.1', port: 465, secure: true },
            { host: 'localhost', port: 465, secure: true },
            { host: creds.smtpHost, port: 465, secure: true },
            { host: creds.domainPart ? `mail.${creds.domainPart}` : '', port: 465, secure: true },
            { host: '127.0.0.1', port: 587, secure: false },
            { host: creds.smtpHost, port: 587, secure: false }
        ].filter(c => !!c.host);

        const uniqueSmtp = smtpCandidates.filter((item, index, self) =>
            index === self.findIndex((t) => t.host === item.host && t.port === item.port)
        );

        let info: any = null;
        let lastSmtpError: any = null;

        for (const cand of uniqueSmtp) {
            try {
                const transporter = nodemailer.createTransport({
                    host: cand.host,
                    port: cand.port,
                    secure: cand.secure,
                    auth: {
                        user: creds.email,
                        pass: creds.password
                    },
                    tls: {
                        rejectUnauthorized: false,
                        servername: creds.domainPart || undefined
                    }
                });
                info = await transporter.sendMail(mailOptions);
                break;
            } catch (err: any) {
                lastSmtpError = err;
                console.warn(`[Webmail SMTP] Failed to send via ${cand.host}:${cand.port}:`, err.message);
            }
        }

        // 3. Bersihkan file upload temporary dari disk
        if (req.files && Array.isArray(req.files)) {
            for (const file of req.files) {
                try { fs.unlinkSync(file.path); } catch (e) {}
            }
        }

        if (!info) {
            throw new Error(`Gagal mengirim email: ${lastSmtpError?.message || 'Koneksi SMTP ditolak'}`);
        }

        // 4. Simpan salinan email ke folder 'Sent' di IMAP Mail Server
        if (rawBuffer && rawBuffer.length > 0) {
            try {
                const client = await createImapClient(creds);
                try {
                    const targetSentBox = await resolveMailboxName(client, 'Sent');
                    await client.append(targetSentBox, rawBuffer, ['\\Seen']);
                    console.log(`[Webmail] Berhasil menyimpan salinan pesan ke folder '${targetSentBox}' untuk ${creds.email}`);
                } finally {
                    await client.logout();
                }
            } catch (appendErr: any) {
                console.warn("[Webmail] Warning appending to Sent mailbox:", appendErr.message);
            }
        }

        // 5. Jika pengiriman ini berasal dari draf, hapus draf dari database
        if (draftId) {
            try {
                await getPool().query("DELETE FROM webmail_drafts WHERE id = ? AND user_email = ?", [draftId, creds.email]);
            } catch (dErr: any) {
                console.warn("[Webmail] Warning cleaning up draft after send:", dErr.message);
            }
        }

        res.json({
            success: true,
            messageId: info.messageId,
            message: "Email berhasil dikirim!"
        });
    } catch (err: any) {
        console.error("[Webmail Send Error]:", err.message);
        // Pastikan file tmp dibersihkan jika error
        if (req.files && Array.isArray(req.files)) {
            for (const file of req.files) {
                try { fs.unlinkSync(file.path); } catch (e) {}
            }
        }
        res.status(400).json({ success: false, error: err.message || "Gagal mengirim email." });
    }
}));

