app.post("/api/webmail/delete", authenticate, asyncHandler(async (req: any, res: any) => {
    try {
        const { uid, uids: rawUids, folder: rawFolder = 'INBOX' } = req.body;
        const uidsList = Array.isArray(rawUids) 
            ? rawUids.map(Number).filter(n => !isNaN(n) && n > 0)
            : (uid ? [Number(uid)].filter(n => !isNaN(n) && n > 0) : []);

        if (uidsList.length === 0) {
            return res.status(400).json({ error: "UID pesan wajib diisi." });
        }

        const creds = await getUserEmailCredentials(getPool(), req.user, req.body.email);

        // Penanganan Hapus untuk Folder Drafts
        if (rawFolder.toLowerCase() === 'drafts' || rawFolder.toLowerCase() === 'draf') {
            await getPool().query(
                "DELETE FROM webmail_drafts WHERE id IN (?) AND user_email = ?",
                [uidsList, creds.email]
            );
            return res.json({ success: true, message: `${uidsList.length} draf berhasil dihapus.` });
        }

        const client = await createImapClient(creds);

        try {
            const folder = await resolveMailboxName(client, rawFolder);
            const lock = await client.getMailboxLock(folder);
            try {
                const seqSet = uidsList.join(',');
                if (folder.toLowerCase().includes('trash')) {
                    await client.messageDelete(seqSet, { uid: true });
                } else {
                    const trashFolder = await resolveMailboxName(client, 'Trash');
                    try {
                        await client.messageMove(seqSet, trashFolder, { uid: true });
                    } catch (moveErr) {
                        await client.messageFlagsAdd(seqSet, ['\\Deleted'], { uid: true });
                    }
                }
                res.json({ success: true, message: `${uidsList.length} pesan berhasil dihapus.` });
            } finally {
                lock.release();
            }
        } finally {
            await client.logout();
        }
    } catch (err: any) {
        console.error("[Webmail Delete Error]:", err.message);
        res.status(400).json({ success: false, error: err.message || "Gagal menghapus pesan." });
    }
}));


// 7. Tandai Pesan (Dibaca / Belum Dibaca / Bintang)
app.post("/api/webmail/toggle-flag", authenticate, asyncHandler(async (req: any, res: any) => {
    try {
        const { uid, folder = 'INBOX', flag, value } = req.body;
        if (!uid || !flag) {
            return res.status(400).json({ error: "UID dan flag wajib diisi." });
        }

        const creds = await getUserEmailCredentials(getPool(), req.user, req.body.email);
        const client = await createImapClient(creds);

        try {
            const lock = await client.getMailboxLock(folder);
            try {
                const imapFlag = flag === 'seen' || flag === 'read' ? '\\Seen' : '\\Flagged';
                if (value) {
                    await client.messageFlagsAdd(String(uid), [imapFlag], { uid: true });
                } else {
                    await client.messageFlagsRemove(String(uid), [imapFlag], { uid: true });
                }
                res.json({ success: true });
            } finally {
                lock.release();
            }
        } finally {
            await client.logout();
        }
    } catch (err: any) {
        console.error("[Webmail Toggle Flag Error]:", err.message);
        res.status(400).json({ success: false, error: err.message || "Gagal mengubah status pesan." });
    }
}));

