const SERVER_STANDARD_TITLES_MAP: Record<string, string> = {
    'S.PD': 'S.Pd',
    'S.PD.SD': 'S.Pd.SD',
    'S.PD.I': 'S.Pd.I',
    'M.PD': 'M.Pd',
    'M.PD.I': 'M.Pd.I',
    'S.KOM': 'S.Kom',
    'M.KOM': 'M.Kom',
    'S.AG': 'S.Ag',
    'M.AG': 'M.Ag',
    'S.E': 'S.E',
    'M.M': 'M.M',
    'M.BA': 'M.BA',
    'S.T': 'S.T',
    'M.T': 'M.T',
    'S.SI': 'S.Si',
    'M.SI': 'M.Si',
    'S.SOS': 'S.Sos',
    'M.SOS': 'M.Sos',
    'S.IP': 'S.IP',
    'M.IP': 'M.IP',
    'S.SN': 'S.Sn',
    'M.SN': 'M.Sn',
    'S.PSI': 'S.Psi',
    'M.PSI': 'M.Psi',
    'S.H': 'S.H',
    'M.H': 'M.H',
    'S.AP': 'S.AP',
    'M.AP': 'M.AP',
    'DRS.': 'Drs.',
    'DRA.': 'Dra.',
    'PROF.': 'Prof.',
    'DR.': 'Dr.',
    'IR.': 'Ir.',
    'HJ.': 'Hj.',
    'H.': 'H.',
    'K.H.': 'K.H.',
    'KH.': 'K.H.',
    'DRG.': 'drg.',
    'APT.': 'apt.',
};

function normalizeServerTitleCasing(title: string): string {
    if (!title) return '';
    const clean = title.trim();
    const upper = clean.toUpperCase().replace(/\s+/g, '');
    for (const [k, v] of Object.entries(SERVER_STANDARD_TITLES_MAP)) {
        if (k.replace(/\s+/g, '') === upper) {
            return v;
        }
    }
    return clean;
}

function formatNamaGelarServer(gelarDepan?: string | null, nama?: string | null, gelarBelakang?: string | null): string {
    let nameStr = (nama || '').trim();
    if (!nameStr) return '';

    let parts = nameStr.split(',');
    let rawMainName = parts[0].trim();
    let existingPostTitles = parts.slice(1).map(p => p.trim()).filter(Boolean);

    const gDepan = (gelarDepan || '').trim();
    const gBelakang = (gelarBelakang || '').trim();

    // 1. Ekstraksi Gelar Depan (agar casing aslinya tetap terjaga, TIDAK di-UPPER)
    const extractedFrontTitles: string[] = [];
    let coreName = rawMainName;

    if (gDepan && gDepan !== '-' && gDepan !== '--') {
        const escaped = gDepan.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        const gDepanRegex = new RegExp(`^${escaped}\\s*`, 'i');
        if (gDepanRegex.test(coreName)) {
            coreName = coreName.replace(gDepanRegex, '').trim();
            extractedFrontTitles.push(normalizeServerTitleCasing(gDepan));
        }
    }

    const standardFrontRegex = /^((?:Prof\.\s*Dr\.|Prof\.|Dr\.|Drs\.|Dra\.|Ir\.|H\.|Hj\.|K\.H\.|KH\.|dr\.|drg\.|Ns\.|apt\.)(?:\s+|$))/i;
    while (true) {
        const match = coreName.match(standardFrontRegex);
        if (match) {
            extractedFrontTitles.push(normalizeServerTitleCasing(match[1].trim()));
            coreName = coreName.slice(match[0].length).trim();
        } else {
            break;
        }
    }

    if (gDepan && gDepan !== '-' && gDepan !== '--') {
        const cleanGD = normalizeServerTitleCasing(gDepan.replace(/^[\s\-_–—]+/, '').trim());
        if (!extractedFrontTitles.some(t => t.toUpperCase() === cleanGD.toUpperCase())) {
            extractedFrontTitles.unshift(cleanGD);
        }
    }

    // HANYA nama inti yang di-UPPERCASE
    const upperCore = coreName.toUpperCase();
    let result = extractedFrontTitles.length > 0 ? `${extractedFrontTitles.join(' ')} ${upperCore}` : upperCore;

    // 2. Kumpulkan Gelar Belakang (casing rapi / standar, TIDAK di-UPPER)
    const allPostTitles: string[] = existingPostTitles.map(t => normalizeServerTitleCasing(t));
    if (gBelakang && gBelakang !== '-' && gBelakang !== '--') {
        const cleanGB = normalizeServerTitleCasing(gBelakang.replace(/^,\s*/, '').trim());
        const normGB = cleanGB.replace(/[.,\s]/g, '').trim().toUpperCase();
        const normResult = result.replace(/[.,\s]/g, '').trim().toUpperCase();
        if (
            cleanGB &&
            !allPostTitles.some(t => t.replace(/[.,\s]/g, '').trim().toUpperCase() === normGB) &&
            !normResult.includes(normGB)
        ) {
            allPostTitles.push(cleanGB);
        }
    }

    // Deduplikasi gelar belakang
    const uniquePostTitles: string[] = [];
    const seenPostNorms = new Set<string>();
    for (const post of allPostTitles) {
        const norm = post.replace(/[.,\s]/g, '').trim().toUpperCase();
        if (norm && !seenPostNorms.has(norm)) {
            seenPostNorms.add(norm);
            uniquePostTitles.push(post);
        }
    }

    // 3. Gabungkan Gelar Belakang dengan koma
    if (uniquePostTitles.length > 0) {
        result = `${result}, ${uniquePostTitles.join(', ')}`;
    }

    return result.trim();
}

// Helper universal untuk mencari nama lengkap + seluruh gelar PTK / Pegawai
async function fetchStaffCompleteNameServer(pool: any, ident: string) {
    if (!ident) return null;
    const clean = ident.trim();
    if (!clean || clean === '-') return null;

    try {
        let [pRows]: any = [];
        // 1. Cari by NIP
        if (clean.length > 5 && !clean.includes(' ')) {
            [pRows] = await pool.query(`
                SELECT ptk_id, nama as nama_lengkap, nama, nip, gelar_depan, gelar_belakang, jabatan_ptk, jenis_ptk
                FROM ptk WHERE nip = ? AND (soft_delete = 0 OR soft_delete IS NULL OR soft_delete = '0') LIMIT 1
            `, [clean]).catch(() => [[]]);
        }
        // 2. Cari by UUID ptk_id
        if (!pRows.length && clean.length === 36) {
            [pRows] = await pool.query(`
                SELECT ptk_id, nama as nama_lengkap, nama, nip, gelar_depan, gelar_belakang, jabatan_ptk, jenis_ptk
                FROM ptk WHERE ptk_id = ? AND (soft_delete = 0 OR soft_delete IS NULL OR soft_delete = '0') LIMIT 1
            `, [clean]).catch(() => [[]]);
        }
        // 3. Cari by Nama PTK
        if (!pRows.length) {
            const cleanNamePart = clean.split(',')[0].replace(/^(dr\.|drs\.|dra\.|prof\.|hj\.|h\.)\s+/i, '').trim();
            [pRows] = await pool.query(`
                SELECT ptk_id, nama as nama_lengkap, nama, nip, gelar_depan, gelar_belakang, jabatan_ptk, jenis_ptk
                FROM ptk 
                WHERE (LOWER(nama) = LOWER(?) OR LOWER(nama) = LOWER(?) OR LOWER(?) LIKE CONCAT('%', LOWER(nama), '%') OR LOWER(nama) LIKE CONCAT('%', LOWER(?), '%'))
                  AND (soft_delete = 0 OR soft_delete IS NULL OR soft_delete = '0')
                ORDER BY LENGTH(nama) DESC LIMIT 1
            `, [clean, cleanNamePart, clean, cleanNamePart]).catch(() => [[]]);
        }
        // 4. Cari dari tabel pegawai (Manajemen Pegawai)
        let pegRow: any = null;
        try {
            const cleanNamePart = clean.split(',')[0].replace(/^(dr\.|drs\.|dra\.|prof\.|hj\.|h\.)\s+/i, '').trim();
            const [pegRows]: any = await pool.query(`
                SELECT pegawai_id as ptk_id, nama_lengkap as nama, nama_lengkap, nip, gelar_depan, gelar_belakang, jabatan
                FROM pegawai
                WHERE (nip = ? OR LOWER(nama_lengkap) = LOWER(?) OR LOWER(nama_lengkap) = LOWER(?) OR LOWER(?) LIKE CONCAT('%', LOWER(nama_lengkap), '%') OR LOWER(nama_lengkap) LIKE CONCAT('%', LOWER(?), '%'))
                LIMIT 1
            `, [clean, clean, cleanNamePart, clean, cleanNamePart]);
            if (pegRows && pegRows.length > 0) {
                pegRow = pegRows[0];
                if (!pRows.length) {
                    pRows = pegRows;
                }
            }
        } catch (ePeg2) {}

        if (!pRows.length) {
            return {
                pureName: clean.split(',')[0].trim().toUpperCase(),
                fullName: clean.trim().toUpperCase(),
                nip: '-'
            };
        }

        const p = pRows[0];
        let pureName = (p.nama || p.nama_lengkap || '').split(',')[0].trim().toUpperCase();
        let gDepan = (p.gelar_depan || pegRow?.gelar_depan || '').trim();
        if (gDepan === '-') gDepan = '';
        let gBelakang = (p.gelar_belakang || pegRow?.gelar_belakang || '').trim();
        if (gBelakang === '-') gBelakang = '';

        // Ambil dari rwy_pend_formal jika gelar masih kosong
        if (p.ptk_id && (!gDepan || !gBelakang)) {
            try {
                const [rpfRows]: any = await pool.query(`
                    SELECT rpf.gelar_akademik_id, ga.kode as gelar_kode, ga.nama as gelar_nama, ga.posisi_gelar
                    FROM rwy_pend_formal rpf
                    LEFT JOIN gelar_akademik ga ON rpf.gelar_akademik_id = ga.gelar_akademik_id
                    WHERE rpf.ptk_id = ? AND (rpf.soft_delete = 0 OR rpf.soft_delete IS NULL OR rpf.soft_delete = '0')
                    ORDER BY CAST(rpf.jenjang_pendidikan_id AS UNSIGNED) DESC, rpf.tahun_lulus DESC
                `, [p.ptk_id]);

                const mapGelarBelakang: Record<string, string> = {
                    '1': 'S.Pd', '2': 'S.Pd.I', '3': 'S.Ag', '4': 'S.Kom', '5': 'S.Si', '6': 'S.Sos', '7': 'S.E', '8': 'S.T',
                    '9': 'S.Stat', '10': 'S.Psi', '11': 'S.H', '12': 'S.S', '13': 'S.Sn', '14': 'M.Pd', '15': 'M.Pd.I',
                    '16': 'M.Ag', '17': 'M.Kom', '18': 'M.Si', '19': 'M.M', '20': 'M.T', '21': 'M.E', '22': 'M.H',
                    '23': 'A.Ma', '24': 'A.Md', '25': 'A.Md.Pd', '26': 'A.Md.Kom', '27': 'Gr.'
                };

                for (const r of rpfRows || []) {
                    const gKode = r.gelar_kode || r.gelar_nama || mapGelarBelakang[String(r.gelar_akademik_id)] || '';
                    const gPosisi = r.posisi_gelar;
                    if (gKode) {
                        if ((String(gPosisi) === '1' || gKode.startsWith('Dr') || gKode.startsWith('Prof') || gKode.startsWith('Drs') || gKode.startsWith('Dra')) && !gDepan) {
                            gDepan = gKode;
                        } else if (!gBelakang && String(gPosisi) !== '1') {
                            gBelakang = gKode;
                        }
                    }
                }
            } catch (eRpf) {}
        }

        // Ambil dari pegawai jika masih kosong
        if (!gDepan || !gBelakang) {
            try {
                const [pegMatch]: any = await pool.query(`
                    SELECT gelar_depan, gelar_belakang FROM pegawai
                    WHERE (nip = ? OR LOWER(nama_lengkap) = LOWER(?) OR LOWER(?) LIKE CONCAT('%', LOWER(nama_lengkap), '%'))
                    LIMIT 1
                `, [p.nip, p.nama, p.nama]);
                if (pegMatch && pegMatch.length > 0) {
                    if (!gDepan && pegMatch[0].gelar_depan && pegMatch[0].gelar_depan !== '-') gDepan = pegMatch[0].gelar_depan.trim();
                    if (!gBelakang && pegMatch[0].gelar_belakang && pegMatch[0].gelar_belakang !== '-') gBelakang = pegMatch[0].gelar_belakang.trim();
                }
            } catch (ePeg) {}
        }

        const fullName = formatNamaGelarServer(gDepan, pureName || p.nama || clean, gBelakang);
        return {
            pureName,
            fullName,
            nip: (p.nip && p.nip !== '-' && p.nip !== '0') ? p.nip : (pegRow?.nip && pegRow?.nip !== '-' ? pegRow?.nip : ''),
            jabatan: p.jabatan_ptk || p.jenis_ptk || pegRow?.jabatan || 'Guru'
        };
    } catch (e) {
        return {
            pureName: clean.split(',')[0].trim().toUpperCase(),
            fullName: clean.trim().toUpperCase(),
            nip: '-'
        };
    }
}

// Helper untuk mengambil data Kepala Sekolah yang aktif di Tahun Ajaran terbaru secara standar Dapodik
async function getActiveKepalaSekolah(p: any, sekolahData?: any) {
    try {
        // 1. Cek dari ptk_terdaftar (Tahun Ajaran terbaru yang aktif, soft_delete = 0)
        const [ptRows]: any = await p.query(`
            SELECT 
                p.ptk_id,
                p.nama as nama_lengkap, 
                p.nama,
                p.gelar_depan, 
                p.gelar_belakang, 
                p.nip, 
                p.nuptk, 
                COALESCE(jp.jabatan_ptk, 'Kepala Sekolah') as jabatan_ptk,
                pt.tahun_ajaran_id
            FROM ptk_terdaftar pt
            JOIN ptk p ON pt.ptk_id = p.ptk_id
            LEFT JOIN jabatan_ptk jp ON pt.jabatan_ptk_id = jp.jabatan_ptk_id
            WHERE (pt.soft_delete = 0 OR pt.soft_delete IS NULL OR pt.soft_delete = '0')
              AND (p.soft_delete = 0 OR p.soft_delete IS NULL OR p.soft_delete = '0')
              AND (
                  pt.jabatan_ptk_id = '2' 
                  OR LOWER(jp.jabatan_ptk) LIKE '%kepala sekolah%'
                  OR LOWER(pt.jabatan_ptk_id) LIKE '%kepala sekolah%'
              )
            ORDER BY pt.tahun_ajaran_id DESC, pt.tmt_tugas DESC
            LIMIT 1
        `).catch(() => [[]]);

        if (ptRows && ptRows.length > 0) {
            const raw = ptRows[0];
            const fullData = await fetchStaffCompleteNameServer(p, raw.nip || raw.ptk_id || raw.nama);
            return {
                ...raw,
                fullName: fullData?.fullName || formatNamaGelarServer(raw.gelar_depan, raw.nama || raw.nama_lengkap, raw.gelar_belakang),
                nama_lengkap: fullData?.fullName || formatNamaGelarServer(raw.gelar_depan, raw.nama || raw.nama_lengkap, raw.gelar_belakang)
            };
        }

        // 2. Cek dari tugas_tambahan (jabatan_ptk_id = 2 / Kepala Sekolah, penugasan masih aktif)
        const [ttRows]: any = await p.query(`
            SELECT 
                p.ptk_id,
                p.nama as nama_lengkap, 
                p.nama,
                p.gelar_depan, 
                p.gelar_belakang, 
                p.nip, 
                p.nuptk, 
                COALESCE(jp.jabatan_ptk, 'Kepala Sekolah') as jabatan_ptk
            FROM tugas_tambahan tt
            JOIN ptk p ON tt.ptk_id = p.ptk_id
            LEFT JOIN jabatan_ptk jp ON tt.jabatan_ptk_id = jp.jabatan_ptk_id
            WHERE (tt.soft_delete = 0 OR tt.soft_delete IS NULL OR tt.soft_delete = '0')
              AND (p.soft_delete = 0 OR p.soft_delete IS NULL OR p.soft_delete = '0')
              AND (
                  tt.jabatan_ptk_id = '2' 
                  OR LOWER(jp.jabatan_ptk) LIKE '%kepala sekolah%'
                  OR LOWER(tt.jabatan_ptk_id) LIKE '%kepala sekolah%'
              )
              AND (tt.tst_tambahan IS NULL OR tt.tst_tambahan = '' OR tt.tst_tambahan >= CURRENT_DATE())
            ORDER BY tt.tmt_tambahan DESC
            LIMIT 1
        `).catch(() => [[]]);

        if (ttRows && ttRows.length > 0) {
            const raw = ttRows[0];
            const fullData = await fetchStaffCompleteNameServer(p, raw.nip || raw.ptk_id || raw.nama);
            return {
                ...raw,
                fullName: fullData?.fullName || formatNamaGelarServer(raw.gelar_depan, raw.nama || raw.nama_lengkap, raw.gelar_belakang),
                nama_lengkap: fullData?.fullName || formatNamaGelarServer(raw.gelar_depan, raw.nama || raw.nama_lengkap, raw.gelar_belakang)
            };
        }

        // 3. Cek dari tabel ptk langsung jika terisi di kolom jabatan_ptk / jenis_ptk
        const [ptkRows]: any = await p.query(`
            SELECT 
                ptk_id,
                nama as nama_lengkap, 
                nama,
                gelar_depan, 
                gelar_belakang, 
                nip, 
                nuptk, 
                jabatan_ptk
            FROM ptk
            WHERE (soft_delete = 0 OR soft_delete IS NULL OR soft_delete = '0')
              AND (
                  LOWER(COALESCE(jabatan_ptk, '')) LIKE '%kepala sekolah%'
                  OR LOWER(COALESCE(jenis_ptk, '')) LIKE '%kepala sekolah%'
                  OR LOWER(COALESCE(tugas_tambahan, '')) LIKE '%kepala sekolah%'
              )
            LIMIT 1
        `).catch(() => [[]]);

        if (ptkRows && ptkRows.length > 0) {
            const raw = ptkRows[0];
            const fullData = await fetchStaffCompleteNameServer(p, raw.nip || raw.ptk_id || raw.nama);
            return {
                ...raw,
                fullName: fullData?.fullName || formatNamaGelarServer(raw.gelar_depan, raw.nama || raw.nama_lengkap, raw.gelar_belakang),
                nama_lengkap: fullData?.fullName || formatNamaGelarServer(raw.gelar_depan, raw.nama || raw.nama_lengkap, raw.gelar_belakang)
            };
        }

        // 4. Fallback ke pengaturan_sekolah jika ada (hanya jika bukan data anomali lama)
        let sData = sekolahData;
        if (!sData) {
            const [sek]: any = await p.query("SELECT * FROM pengaturan_sekolah LIMIT 1").catch(() => [[]]);
            if (sek && sek.length > 0) sData = sek[0];
        }

        const rawFallbackName = String(sData?.nama_kepsek || sData?.headmaster_name || '').trim();
        const isAnomaly = rawFallbackName.toLowerCase().includes('neni') || rawFallbackName.toLowerCase().includes('herawati');

        if (sData && rawFallbackName && !isAnomaly) {
            const rawFallbackNip = (sData.nip_kepsek && sData.nip_kepsek !== '197003181992032007') ? sData.nip_kepsek : (sData.headmaster_nip !== '197003181992032007' ? sData.headmaster_nip : '-');
            const gD = sData.headmaster_gelar_depan || sData.gelar_depan || '';
            const gB = sData.headmaster_gelar_belakang || sData.gelar_belakang || '';
            const fullName = formatNamaGelarServer(gD, rawFallbackName, gB);
            return {
                ptk_id: null,
                nama_lengkap: fullName,
                fullName: fullName,
                nama: rawFallbackName,
                nip: rawFallbackNip || '-',
                nuptk: '-',
                gelar_depan: gD,
                gelar_belakang: gB,
                jabatan_ptk: 'Kepala Sekolah'
            };
        }

        return null;
    } catch (e) {
        return null;
    }
}

app.get("/api/berkas-insentif/:id/cetak-pernyataan", authenticate, asyncHandler(async (req: any, res: any) => {
    const { id } = req.params;
    const p = getPool();
    
    // 1. Ambil data berkas insentif
    const [berkas]: any = await p.query("SELECT * FROM berkas_insentif WHERE id = ?", [id]);
    if (berkas.length === 0) return res.status(404).json({ error: "Data tidak ditemukan" });
    
    const berkasInsentif = berkas[0];
    const penerimaIds = typeof berkasInsentif.penerima === 'string' ? JSON.parse(berkasInsentif.penerima) : (berkasInsentif.penerima || []);
    
    // 2. Ambil data sekolah
    let sekolahData = null;
    try {
        const [sekolah]: any = await p.query("SELECT * FROM pengaturan_sekolah LIMIT 1");
        if (sekolah.length > 0) sekolahData = sekolah[0];
    } catch (e) {}

    // 3. Ambil data Kepala Sekolah aktif
    const kepsekData = await getActiveKepalaSekolah(p, sekolahData);

    // 4. Ambil data Pengawas Sekolah
    let pengawasData = null;
    try {
        const [pengawas]: any = await p.query(`
            SELECT 
                nama as nama_lengkap, 
                nama,
                gelar_depan, 
                gelar_belakang, 
                nip, 
                nuptk, 
                jabatan_ptk 
            FROM ptk 
            WHERE LOWER(jabatan_ptk) LIKE '%pengawas%' 
               OR LOWER(jenis_ptk) LIKE '%pengawas%' 
            LIMIT 1
        `);
        if (pengawas.length > 0) {
            pengawasData = pengawas[0];
        } else if (sekolahData && (sekolahData.nama_pengawas || sekolahData.supervisor_name)) {
            pengawasData = {
                nama_lengkap: sekolahData.nama_pengawas || sekolahData.supervisor_name,
                nama: sekolahData.nama_pengawas || sekolahData.supervisor_name,
                nip: sekolahData.nip_pengawas || sekolahData.supervisor_nip || '-',
                nuptk: '-',
                gelar_depan: sekolahData.supervisor_gelar_depan || '',
                gelar_belakang: sekolahData.supervisor_gelar_belakang || ''
            };
        }
    } catch (e) {}
    
    // 5. Ambil data pegawai penerima
    let pegawaiList: any[] = [];
    if (penerimaIds && Array.isArray(penerimaIds) && penerimaIds.length > 0) {
        const placeholders = penerimaIds.map(() => '?').join(',');
        try {
            const [rows]: any = await p.query(`
                SELECT 
                    p.ptk_id as pegawai_id,
                    p.ptk_id,
                    p.nama as nama_lengkap,
                    p.nama,
                    p.gelar_depan,
                    p.gelar_belakang,
                    p.nip,
                    p.nuptk,
                    COALESCE(p.jabatan_ptk, p.jenis_ptk, 'Guru') as jabatan_ptk,
                    COALESCE(p.mengajar, p.tugas_tambahan, '') as bidang_mengajar
                FROM ptk p
                WHERE p.ptk_id IN (${placeholders})
            `, penerimaIds);
            pegawaiList = rows;
        } catch (errDb: any) {
            console.error("Fetch pegawai insentif error:", errDb.message);
        }
    }
    
    res.json({
        berkas: berkasInsentif,
        sekolah: sekolahData,
        kepsek: kepsekData,
        pengawas: pengawasData,
        pegawai: pegawaiList
    });
}));

