app.get("/api/cetak/keterangan-rombel", authenticate, asyncHandler(async (req: any, res: any) => {
    const p = getPool();
    
    // 1. Fetch pengaturan_sekolah
    let sekolahData: any = null;
    try {
        const [sekolah]: any = await p.query("SELECT * FROM pengaturan_sekolah LIMIT 1");
        if (sekolah.length > 0) sekolahData = sekolah[0];
    } catch (e) {}
    
    // 2. Fetch Kepsek and Pengawas
    const kepsekData = await getActiveKepalaSekolah(p, sekolahData);

    let pengawasData: any = null;
    try {
        const [pengawas]: any = await p.query(`
            SELECT 
                nama as nama_lengkap, 
                nama,
                gelar_depan, 
                gelar_belakang, 
                nip, 
                nuptk, 
                jabatan_ptk 
            FROM ptk 
            WHERE LOWER(jabatan_ptk) LIKE '%pengawas%' 
               OR LOWER(jenis_ptk) LIKE '%pengawas%' 
            LIMIT 1
        `);
        if (pengawas.length > 0) {
            pengawasData = pengawas[0];
        } else if (sekolahData && (sekolahData.nama_pengawas || sekolahData.supervisor_name)) {
            pengawasData = {
                nama_lengkap: sekolahData.nama_pengawas || sekolahData.supervisor_name,
                nama: sekolahData.nama_pengawas || sekolahData.supervisor_name,
                nip: sekolahData.nip_pengawas || sekolahData.supervisor_nip || '-',
                nuptk: '-',
                gelar_depan: sekolahData.supervisor_gelar_depan || '',
                gelar_belakang: sekolahData.supervisor_gelar_belakang || ''
            };
        }
    } catch (e) {}

    // 3. Deteksi semester_id dan tahun pelajaran aktif yang sedang berjalan
    let activeSemesterId = null;
    try {
        const [semRows]: any = await p.query(`
            SELECT semester_id 
            FROM rombongan_belajar 
            WHERE semester_id IS NOT NULL AND semester_id != '' 
              AND (soft_delete = 0 OR soft_delete IS NULL OR soft_delete = '0' OR soft_delete = '')
            ORDER BY semester_id DESC 
            LIMIT 1
        `);
        if (semRows.length > 0) {
            activeSemesterId = semRows[0].semester_id;
        }
    } catch (e) {}

    let tahunPelajaran = null;
    let semesterName = null;
    if (activeSemesterId && String(activeSemesterId).length >= 5) {
        const yStr = String(activeSemesterId).substring(0, 4);
        const yNum = parseInt(yStr);
        tahunPelajaran = !isNaN(yNum) ? `${yNum}/${yNum + 1}` : null;
        semesterName = String(activeSemesterId).endsWith('1') ? 'Ganjil' : 'Genap';
    } else {
        const now = new Date();
        const currentYear = now.getFullYear();
        const currentMonth = now.getMonth() + 1; // 1-12
        if (currentMonth >= 7) {
            tahunPelajaran = `${currentYear}/${currentYear + 1}`;
            semesterName = 'Ganjil';
        } else {
            tahunPelajaran = `${currentYear - 1}/${currentYear}`;
            semesterName = 'Genap';
        }
    }
    
    // 4. Fetch rombel data HANYA untuk tahun pelajaran/semester yang sedang berjalan
    let rombelRows: any[] = [];
    try {
        const query = activeSemesterId ? `
            SELECT r.*, 
                   r.nama as name, 
                   COALESCE(r.tingkat_pendidikan_id, r.tingkat) as tingkat, 
                   COALESCE(ptk.nama, p.nama_lengkap) as wali_kelas_name, 
                   COALESCE(ptk.gelar_depan, p.gelar_depan) as gelar_depan, 
                   COALESCE(ptk.gelar_belakang, p.gelar_belakang) as gelar_belakang,
                   (SELECT COUNT(DISTINCT pd.peserta_didik_id) FROM anggota_rombel ar JOIN peserta_didik pd ON ar.peserta_didik_id = pd.peserta_didik_id WHERE ar.rombongan_belajar_id = r.rombongan_belajar_id AND (ar.soft_delete = 0 OR ar.soft_delete IS NULL OR ar.soft_delete = '0') AND (pd.soft_delete = 0 OR pd.soft_delete IS NULL OR pd.soft_delete = '0') AND pd.jenis_kelamin = 'L') as count_l,
                   (SELECT COUNT(DISTINCT pd.peserta_didik_id) FROM anggota_rombel ar JOIN peserta_didik pd ON ar.peserta_didik_id = pd.peserta_didik_id WHERE ar.rombongan_belajar_id = r.rombongan_belajar_id AND (ar.soft_delete = 0 OR ar.soft_delete IS NULL OR ar.soft_delete = '0') AND (pd.soft_delete = 0 OR pd.soft_delete IS NULL OR pd.soft_delete = '0') AND pd.jenis_kelamin = 'P') as count_p,
                   (SELECT COUNT(DISTINCT pd.peserta_didik_id) FROM anggota_rombel ar JOIN peserta_didik pd ON ar.peserta_didik_id = pd.peserta_didik_id WHERE ar.rombongan_belajar_id = r.rombongan_belajar_id AND (ar.soft_delete = 0 OR ar.soft_delete IS NULL OR ar.soft_delete = '0') AND (pd.soft_delete = 0 OR pd.soft_delete IS NULL OR pd.soft_delete = '0')) as student_count
            FROM (
                SELECT *, ROW_NUMBER() OVER (
                    PARTITION BY nama 
                    ORDER BY COALESCE(semester_id, '0') DESC, COALESCE(last_sync, '') DESC, COALESCE(create_date, '') DESC
                ) as rn
                FROM rombongan_belajar
                WHERE (soft_delete = 0 OR soft_delete IS NULL OR soft_delete = '0' OR soft_delete = '')
                  AND (semester_id = ? OR semester_id IS NULL)
            ) r
            LEFT JOIN ptk ON (r.ptk_id = ptk.ptk_id OR r.wali_kelas_id = ptk.ptk_id)
            LEFT JOIN pegawai p ON (r.wali_kelas_id = p.pegawai_id OR r.ptk_id = p.pegawai_id)
            WHERE r.rn = 1
            ORDER BY CAST(COALESCE(r.tingkat_pendidikan_id, r.tingkat) AS UNSIGNED) ASC, r.nama ASC
        ` : `
            SELECT r.*, 
                   r.nama as name, 
                   COALESCE(r.tingkat_pendidikan_id, r.tingkat) as tingkat, 
                   COALESCE(ptk.nama, p.nama_lengkap) as wali_kelas_name, 
                   COALESCE(ptk.gelar_depan, p.gelar_depan) as gelar_depan, 
                   COALESCE(ptk.gelar_belakang, p.gelar_belakang) as gelar_belakang,
                   (SELECT COUNT(DISTINCT pd.peserta_didik_id) FROM anggota_rombel ar JOIN peserta_didik pd ON ar.peserta_didik_id = pd.peserta_didik_id WHERE ar.rombongan_belajar_id = r.rombongan_belajar_id AND (ar.soft_delete = 0 OR ar.soft_delete IS NULL OR ar.soft_delete = '0') AND (pd.soft_delete = 0 OR pd.soft_delete IS NULL OR pd.soft_delete = '0') AND pd.jenis_kelamin = 'L') as count_l,
                   (SELECT COUNT(DISTINCT pd.peserta_didik_id) FROM anggota_rombel ar JOIN peserta_didik pd ON ar.peserta_didik_id = pd.peserta_didik_id WHERE ar.rombongan_belajar_id = r.rombongan_belajar_id AND (ar.soft_delete = 0 OR ar.soft_delete IS NULL OR ar.soft_delete = '0') AND (pd.soft_delete = 0 OR pd.soft_delete IS NULL OR pd.soft_delete = '0') AND pd.jenis_kelamin = 'P') as count_p,
                   (SELECT COUNT(DISTINCT pd.peserta_didik_id) FROM anggota_rombel ar JOIN peserta_didik pd ON ar.peserta_didik_id = pd.peserta_didik_id WHERE ar.rombongan_belajar_id = r.rombongan_belajar_id AND (ar.soft_delete = 0 OR ar.soft_delete IS NULL OR ar.soft_delete = '0') AND (pd.soft_delete = 0 OR pd.soft_delete IS NULL OR pd.soft_delete = '0')) as student_count
            FROM (
                SELECT *, ROW_NUMBER() OVER (
                    PARTITION BY nama 
                    ORDER BY COALESCE(semester_id, '0') DESC, COALESCE(last_sync, '') DESC, COALESCE(create_date, '') DESC
                ) as rn
                FROM rombongan_belajar
                WHERE (soft_delete = 0 OR soft_delete IS NULL OR soft_delete = '0' OR soft_delete = '')
            ) r
            LEFT JOIN ptk ON (r.ptk_id = ptk.ptk_id OR r.wali_kelas_id = ptk.ptk_id)
            LEFT JOIN pegawai p ON (r.wali_kelas_id = p.pegawai_id OR r.ptk_id = p.pegawai_id)
            WHERE r.rn = 1
            ORDER BY CAST(COALESCE(r.tingkat_pendidikan_id, r.tingkat) AS UNSIGNED) ASC, r.nama ASC
        `;
        const params = activeSemesterId ? [activeSemesterId] : [];
        const staffMap = await getStaffGelarMap(p);
        const [rows]: any = await p.query(query, params);
        rombelRows = (rows || []).map((r: any) => {
            const teacher = staffMap.get(String(r.ptk_id || r.wali_kelas_id || '').toLowerCase());
            return {
                ...r,
                wali_kelas_name: teacher ? teacher.name : (r.wali_kelas_name || null),
                wali_kelas_nip: teacher ? teacher.nip : (r.wali_kelas_nip || ''),
                gelar_depan: teacher ? teacher.gelar_depan : (r.gelar_depan || ''),
                gelar_belakang: teacher ? teacher.gelar_belakang : (r.gelar_belakang || '')
            };
        });
    } catch (errQuery: any) {
        console.error("Fetch rombel cetak error:", errQuery.message);
    }

    // 5. Aggregate by tingkat
    const countByTingkat: Record<string, number> = {};
    for (const r of rombelRows) {
        const t = r.tingkat || 'Belum Diatur';
        if (!countByTingkat[t]) countByTingkat[t] = 0;
        countByTingkat[t]++;
    }
    const tingkatAggr = Object.keys(countByTingkat).map(k => ({ tingkat: k, count: countByTingkat[k] }));
    
    res.json({
        sekolah: sekolahData,
        kepsek: kepsekData,
        pengawas: pengawasData,
        rombels: rombelRows,
        tingkatAggr,
        tahun_pelajaran: tahunPelajaran,
        semester: semesterName,
        semester_id: activeSemesterId
    });
}));

