const resolvePelanggaranUserScope = async (user: any) => {
    if (!user) return { isRestricted: true, isStudent: false, isTeacher: false, isFullAccess: false, studentId: null, allowedRombels: [], staffName: null };
    
    // 1. Siswa (Student Portal) -> Hanya data dirinya sendiri
    if (user.type === 'student') {
        return { isRestricted: false, isStudent: true, isTeacher: false, isFullAccess: false, studentId: user.id || user.peserta_didik_id, allowedRombels: [], staffName: null };
    }

    // 2. Admin / Superadmin / Kepala Sekolah / Guru BK -> Akses Penuh Semua Rombel
    const roleLower = String(user.role || user.role_name || '').toLowerCase();
    const perms = Array.isArray(user.permissions) ? user.permissions : [];
    const isFullAccess = perms.includes('all') || 
                         perms.includes('surat_panggilan:manage_all') ||
                         roleLower.includes('admin') || 
                         roleLower.includes('superadmin') ||
                         roleLower.includes('kepala sekolah') || 
                         roleLower.includes('kepsek') || 
                         roleLower.includes('konseling') || 
                         roleLower.includes('bk');

    if (isFullAccess) {
        return { isRestricted: false, isStudent: false, isTeacher: false, isFullAccess: true, studentId: null, allowedRombels: [], staffName: null };
    }

    // 3. Guru / Wali Kelas -> Hanya siswa di rombel yang diampunya atau yang dilaporkan/dibina olehnya
    const staffId = user.staff_id || user.id;
    let allowedRombels: string[] = [];
    let staffName = user.username || '';

    if (staffId) {
        try {
            const [rRows]: any = await getPool().query(
                "SELECT nama FROM rombongan_belajar WHERE (wali_kelas_id = ? OR ptk_id = ?) AND (soft_delete = 0 OR soft_delete IS NULL)",
                [staffId, staffId]
            );
            allowedRombels = (rRows || []).map((r: any) => r.nama).filter(Boolean);
            
            const [pRows]: any = await getPool().query(
                "SELECT nama FROM ptk WHERE ptk_id = ? LIMIT 1",
                [staffId]
            );
            if (pRows.length > 0 && pRows[0].nama) {
                staffName = pRows[0].nama;
            }
        } catch (e) {
            console.error("Error resolving wali kelas scope:", e);
        }
    }

    return { isRestricted: false, isStudent: false, isTeacher: true, isFullAccess: false, studentId: null, allowedRombels, staffName, staffId };
};

// Endpoint khusus portal siswa untuk melihat buku pelanggaran & status panggilannya
app.get("/api/student/pelanggaran", authenticate, asyncHandler(async (req: any, res: any) => {
    const studentId = req.user?.id || req.user?.peserta_didik_id;
    if (!studentId) {
        return res.status(400).json({ error: "Sesi siswa tidak valid." });
    }

    const pool = getPool();
    const [pelanggaranRows]: any = await pool.query(`
        SELECT ps.*,
               sp.nomor_surat as nomor_surat_panggilan,
               CASE 
                   WHEN ps.status_panggilan = 'sudah_dipanggil' OR sp.id IS NOT NULL OR ps.surat_panggilan_id IS NOT NULL THEN 'sudah_dipanggil'
                   ELSE 'belum_dipanggil'
               END as status_panggilan
        FROM pelanggaran_siswa ps
        LEFT JOIN surat_panggilan sp ON (
            ps.surat_panggilan_id = sp.id 
            OR (sp.pelanggaran_ids IS NOT NULL AND (
                sp.pelanggaran_ids LIKE CONCAT('%"', ps.id, '"%') 
                OR sp.pelanggaran_ids LIKE CONCAT('%[', ps.id, ',%') 
                OR sp.pelanggaran_ids LIKE CONCAT('%,', ps.id, ',%') 
                OR sp.pelanggaran_ids LIKE CONCAT('%,', ps.id, ']') 
                OR sp.pelanggaran_ids LIKE CONCAT('[', ps.id, ']')
            ))
        )
        WHERE ps.peserta_didik_id = ?
        GROUP BY ps.id
        ORDER BY ps.tanggal_kejadian DESC, ps.id DESC
    `, [studentId]);

    const [suratPanggilanRows]: any = await pool.query(
        "SELECT * FROM surat_panggilan WHERE peserta_didik_id = ? ORDER BY tanggal_surat DESC, id DESC",
        [studentId]
    );

    const [suratPernyataanRows]: any = await pool.query(
        "SELECT * FROM surat_pernyataan_siswa WHERE peserta_didik_id = ? ORDER BY tanggal_surat DESC, id DESC",
        [studentId]
    );

    const totalPoin = (pelanggaranRows || []).reduce((acc: number, cur: any) => acc + (Number(cur.poin) || 0), 0);

    res.json({
        totalPoin,
        totalKasus: (pelanggaranRows || []).length,
        totalSuratPanggilan: (suratPanggilanRows || []).length,
        totalSuratPernyataan: (suratPernyataanRows || []).length,
        pelanggaran: pelanggaranRows || [],
        suratPanggilan: suratPanggilanRows || [],
        suratPernyataan: suratPernyataanRows || []
    });
}));

app.get("/api/pelanggaran-siswa", authenticate, asyncHandler(async (req: any, res: any) => {
    const scope = await resolvePelanggaranUserScope(req.user);
    const { q, kategori, status_panggilan, rombel, tanggal_mulai, tanggal_akhir } = req.query;
    
    let query = `
        SELECT ps.*,
               s.nama as nama_siswa_current,
               s.nisn as nisn_current,
               s.nomor_telepon_seluler as hp_orang_tua,
               s.nama_ayah,
               s.nama_ibu_kandung as nama_ibu,
               s.nama_wali,
               sp.nomor_surat as nomor_surat_panggilan,
               CASE 
                   WHEN ps.status_panggilan = 'sudah_dipanggil' OR sp.id IS NOT NULL OR ps.surat_panggilan_id IS NOT NULL THEN 'sudah_dipanggil'
                   ELSE 'belum_dipanggil'
               END as status_panggilan
        FROM pelanggaran_siswa ps
        LEFT JOIN peserta_didik s ON (ps.peserta_didik_id = s.peserta_didik_id)
        LEFT JOIN surat_panggilan sp ON (
            ps.surat_panggilan_id = sp.id 
            OR (sp.pelanggaran_ids IS NOT NULL AND (
                sp.pelanggaran_ids LIKE CONCAT('%"', ps.id, '"%') 
                OR sp.pelanggaran_ids LIKE CONCAT('%[', ps.id, ',%') 
                OR sp.pelanggaran_ids LIKE CONCAT('%,', ps.id, ',%') 
                OR sp.pelanggaran_ids LIKE CONCAT('%,', ps.id, ']') 
                OR sp.pelanggaran_ids LIKE CONCAT('[', ps.id, ']')
            ))
        )
        WHERE 1=1
    `;
    const params: any[] = [];

    // Filter Hak Akses Role
    if (scope.isStudent) {
        query += ` AND ps.peserta_didik_id = ?`;
        params.push(scope.studentId);
    } else if (scope.isTeacher) {
        if (scope.allowedRombels.length > 0) {
            const placeholders = scope.allowedRombels.map(() => '?').join(',');
            query += ` AND (ps.kelas_rombel IN (${placeholders}) OR ps.guru_pelapor LIKE ? OR ps.guru_pembina LIKE ?)`;
            params.push(...scope.allowedRombels, `%${scope.staffName}%`, `%${scope.staffName}%`);
        } else if (scope.staffName) {
            query += ` AND (ps.guru_pelapor LIKE ? OR ps.guru_pembina LIKE ?)`;
            params.push(`%${scope.staffName}%`, `%${scope.staffName}%`);
        }
    }

    if (q) {
        query += ` AND (ps.nama_siswa LIKE ? OR ps.nisn LIKE ? OR ps.nipd LIKE ? OR ps.jenis_pelanggaran LIKE ? OR ps.uraian_kejadian LIKE ? OR ps.guru_pelapor LIKE ? OR ps.guru_pembina LIKE ?)`;
        const p = `%${q}%`;
        params.push(p, p, p, p, p, p, p);
    }
    if (kategori && kategori !== 'semua' && kategori !== 'All') {
        query += ` AND ps.kategori = ?`;
        params.push(kategori);
    }
    if (status_panggilan && status_panggilan !== 'semua' && status_panggilan !== 'All') {
        if (status_panggilan === 'sudah_dipanggil') {
            query += ` AND (ps.status_panggilan = 'sudah_dipanggil' OR sp.id IS NOT NULL OR ps.surat_panggilan_id IS NOT NULL)`;
        } else if (status_panggilan === 'belum_dipanggil') {
            query += ` AND (ps.status_panggilan = 'belum_dipanggil' OR ps.status_panggilan IS NULL) AND sp.id IS NULL AND ps.surat_panggilan_id IS NULL`;
        } else {
            query += ` AND ps.status_panggilan = ?`;
            params.push(status_panggilan);
        }
    }
    if (rombel && rombel !== 'semua' && rombel !== 'All') {
        query += ` AND ps.kelas_rombel LIKE ?`;
        params.push(`%${rombel}%`);
    }
    if (tanggal_mulai) {
        query += ` AND ps.tanggal_kejadian >= ?`;
        params.push(tanggal_mulai);
    }
    if (tanggal_akhir) {
        query += ` AND ps.tanggal_kejadian <= ?`;
        params.push(tanggal_akhir);
    }
    query += ` GROUP BY ps.id ORDER BY ps.tanggal_kejadian DESC, ps.id DESC`;
    const [rows]: any = await getPool().query(query, params);
    res.json(rows || []);
}));

