app.get("/api/surat-panggilan", authenticate, asyncHandler(async (req: any, res: any) => {
    const scope = await resolvePelanggaranUserScope(req.user);
    const { q, kategori, status, rombel } = req.query;
    let query = `
        SELECT sp.*, 
               s.nama as nama_siswa_current,
               s.nisn as nisn_current,
               s.nomor_telepon_seluler as hp_orang_tua,
               s.nama_ayah,
               s.nama_ibu_kandung as nama_ibu,
               s.nama_wali
        FROM surat_panggilan sp
        LEFT JOIN peserta_didik s ON (sp.peserta_didik_id = s.peserta_didik_id)
        WHERE 1=1
    `;
    const params: any[] = [];

    // Filter Hak Akses Role
    if (scope.isStudent) {
        query += ` AND sp.peserta_didik_id = ?`;
        params.push(scope.studentId);
    } else if (scope.isTeacher) {
        if (scope.allowedRombels.length > 0) {
            const placeholders = scope.allowedRombels.map(() => '?').join(',');
            query += ` AND (sp.kelas_rombel IN (${placeholders}) OR sp.nama_penandatangan LIKE ?)`;
            params.push(...scope.allowedRombels, `%${scope.staffName}%`);
        } else if (scope.staffName) {
            query += ` AND sp.nama_penandatangan LIKE ?`;
            params.push(`%${scope.staffName}%`);
        }
    }

    if (q) {
        query += ` AND (sp.nomor_surat LIKE ? OR sp.nama_siswa LIKE ? OR sp.nisn LIKE ? OR sp.nipd LIKE ? OR sp.alasan_panggilan LIKE ? OR sp.nama_orang_tua LIKE ?)`;
        const p = `%${q}%`;
        params.push(p, p, p, p, p, p);
    }
    if (kategori && kategori !== 'semua' && kategori !== 'All') {
        query += ` AND sp.kategori_panggilan = ?`;
        params.push(kategori);
    }
    if (status && status !== 'semua' && status !== 'All') {
        query += ` AND sp.status = ?`;
        params.push(status);
    }
    if (rombel && rombel !== 'semua' && rombel !== 'All') {
        query += ` AND sp.kelas_rombel LIKE ?`;
        params.push(`%${rombel}%`);
    }
    query += ` ORDER BY sp.tanggal_surat DESC, sp.id DESC`;
    const [rows]: any = await getPool().query(query, params);
    res.json(rows || []);
}));

app.get("/api/surat-panggilan/options/siswa", authenticate, asyncHandler(async (req: any, res: any) => {
    const rawQ = (req.query.q || '').toString().trim();
    const pool = getPool();
    
    try {
        let sql = `
            SELECT 
                s.peserta_didik_id as id,
                s.peserta_didik_id,
                COALESCE(s.nama, '') as nama_lengkap,
                COALESCE(s.nisn, '') as nisn,
                COALESCE(rpd.nipd, s.nipd, '') as nipd,
                COALESCE(rombel_data.rombel, '') as rombel,
                COALESCE(s.nama_ayah, '') as nama_ayah,
                COALESCE(s.nama_ibu_kandung, '') as nama_ibu,
                COALESCE(s.nama_wali, '') as nama_wali,
                COALESCE(s.nomor_telepon_seluler, s.nomor_telepon_rumah, '') as nomor_hp_ortu
            FROM peserta_didik s
            LEFT JOIN (
                SELECT 
                    peserta_didik_id, 
                    MAX(nipd) as nipd
                FROM registrasi_peserta_didik
                GROUP BY peserta_didik_id
            ) rpd ON rpd.peserta_didik_id = s.peserta_didik_id
            LEFT JOIN (
                SELECT 
                    ar.peserta_didik_id,
                    MAX(rb.nama) as rombel
                FROM anggota_rombel ar
                JOIN rombongan_belajar rb ON rb.rombongan_belajar_id = ar.rombongan_belajar_id
                GROUP BY ar.peserta_didik_id
            ) rombel_data ON rombel_data.peserta_didik_id = s.peserta_didik_id
            WHERE 1=1
        `;
        const params: any[] = [];
        if (rawQ) {
            sql += ` AND (s.nama LIKE ? OR s.nisn LIKE ? OR s.nik LIKE ? OR s.nipd LIKE ? OR rpd.nipd LIKE ? OR rombel_data.rombel LIKE ?)`;
            const searchParam = `%${rawQ}%`;
            params.push(searchParam, searchParam, searchParam, searchParam, searchParam, searchParam);
        }
        sql += ` ORDER BY s.nama ASC LIMIT 100`;
        const [rows]: any = await pool.query(sql, params);
        return res.json(rows || []);
    } catch (err1) {
        console.warn("[/api/surat-panggilan/options/siswa] Primary query failed, using direct query:", err1);
        try {
            let simpleSql = `
                SELECT 
                    s.peserta_didik_id as id,
                    s.peserta_didik_id,
                    COALESCE(s.nama, '') as nama_lengkap,
                    COALESCE(s.nisn, '') as nisn,
                    COALESCE(s.nipd, '') as nipd,
                    '' as rombel,
                    COALESCE(s.nama_ayah, '') as nama_ayah,
                    COALESCE(s.nama_ibu_kandung, '') as nama_ibu,
                    COALESCE(s.nama_wali, '') as nama_wali,
                    COALESCE(s.nomor_telepon_seluler, s.nomor_telepon_rumah, '') as nomor_hp_ortu
                FROM peserta_didik s
                WHERE 1=1
            `;
            const params2: any[] = [];
            if (rawQ) {
                simpleSql += ` AND (s.nama LIKE ? OR s.nisn LIKE ? OR s.nik LIKE ? OR s.nipd LIKE ?)`;
                const searchParam = `%${rawQ}%`;
                params2.push(searchParam, searchParam, searchParam, searchParam);
            }
            const [rows2]: any = await pool.query(simpleSql, params2);
            return res.json(rows2 || []);
        } catch (err2) {
            console.error("[/api/surat-panggilan/options/siswa] Error fetching students:", err2);
            return res.json([]);
        }
    }
}));

app.get("/api/surat-panggilan/options/staff", authenticate, asyncHandler(async (req: any, res: any) => {
    let list: any[] = [];
    try {
        const pool = getPool();
        const [ptkRows]: any = await pool.query(`
            SELECT 
                p.ptk_id, 
                p.nama as nama_lengkap, 
                p.nama,
                p.nip, 
                p.gelar_depan, 
                p.gelar_belakang, 
                p.tugas_tambahan,
                p.jabatan_ptk,
                p.jenis_ptk
            FROM ptk p
            WHERE (p.soft_delete = 0 OR p.soft_delete IS NULL OR p.soft_delete = '0')
            ORDER BY p.nama ASC
        `);

        // Load gelar dari pegawai (Manajemen Pegawai)
        const pegawaiGelarMap: Record<string, { gDepan: string, gBelakang: string, nip?: string }> = {};
        try {
            const [pegRows]: any = await pool.query(`
                SELECT pegawai_id, nama_lengkap, nip, gelar_depan, gelar_belakang, jabatan FROM pegawai
            `);
            for (const peg of pegRows || []) {
                const nip = (peg.nip || '').trim();
                const pureN = (peg.nama_lengkap || '').split(',')[0].trim().toLowerCase();
                const data = {
                    gDepan: (peg.gelar_depan || '').trim() !== '-' ? (peg.gelar_depan || '').trim() : '',
                    gBelakang: (peg.gelar_belakang || '').trim() !== '-' ? (peg.gelar_belakang || '').trim() : '',
                    nip: peg.nip
                };
                if (nip && nip !== '-') pegawaiGelarMap[nip] = data;
                if (pureN) pegawaiGelarMap[pureN] = data;
            }
        } catch (ePeg) {}

        // Load gelar dari rwy_pend_formal
        const gelarMap: Record<string, { gDepan: string, gBelakang: string }> = {};
        try {
            const [rpfRows]: any = await pool.query(`
                SELECT rpf.ptk_id, rpf.gelar_akademik_id, ga.kode as gelar_kode, ga.nama as gelar_nama, ga.posisi_gelar
                FROM rwy_pend_formal rpf
                LEFT JOIN gelar_akademik ga ON rpf.gelar_akademik_id = ga.gelar_akademik_id
                WHERE (rpf.soft_delete = 0 OR rpf.soft_delete IS NULL OR rpf.soft_delete = '0')
                ORDER BY CAST(rpf.jenjang_pendidikan_id AS UNSIGNED) DESC, rpf.tahun_lulus DESC
            `);

            const mapGelarBelakang: Record<string, string> = {
                '1': 'S.Pd', '2': 'S.Pd.I', '3': 'S.Ag', '4': 'S.Kom', '5': 'S.Si', '6': 'S.Sos', '7': 'S.E', '8': 'S.T',
                '9': 'S.Stat', '10': 'S.Psi', '11': 'S.H', '12': 'S.S', '13': 'S.Sn', '14': 'M.Pd', '15': 'M.Pd.I',
                '16': 'M.Ag', '17': 'M.Kom', '18': 'M.Si', '19': 'M.M', '20': 'M.T', '21': 'M.E', '22': 'M.H',
                '23': 'A.Ma', '24': 'A.Md', '25': 'A.Md.Pd', '26': 'A.Md.Kom', '27': 'Gr.'
            };

            for (const r of rpfRows || []) {
                const pId = String(r.ptk_id);
                const gKode = r.gelar_kode || r.gelar_nama || mapGelarBelakang[String(r.gelar_akademik_id)] || '';
                const gPosisi = r.posisi_gelar;
                if (gKode) {
                    if (!gelarMap[pId]) gelarMap[pId] = { gDepan: '', gBelakang: '' };
                    if ((String(gPosisi) === '1' || gKode.startsWith('Dr') || gKode.startsWith('Prof') || gKode.startsWith('Drs') || gKode.startsWith('Dra')) && !gelarMap[pId].gDepan) {
                        gelarMap[pId].gDepan = gKode;
                    } else if (!gelarMap[pId].gBelakang && String(gPosisi) !== '1') {
                        gelarMap[pId].gBelakang = gKode;
                    }
                }
            }
        } catch (eGelar) {}

        list = (ptkRows || []).map((p: any) => {
            const pId = String(p.ptk_id);
            const nipClean = (p.nip || '').trim();
            const pureNameClean = (p.nama_lengkap || p.nama || '').split(',')[0].trim().toLowerCase();
            const pegMatch = (nipClean && pegawaiGelarMap[nipClean]) || (pureNameClean && pegawaiGelarMap[pureNameClean]);

            let pureName = (p.nama_lengkap || p.nama || '').trim();
            let gDepan = (p.gelar_depan || gelarMap[pId]?.gDepan || pegMatch?.gDepan || '').trim();
            if (gDepan === '-') gDepan = '';
            let gBelakang = (p.gelar_belakang || gelarMap[pId]?.gBelakang || pegMatch?.gBelakang || '').trim();
            if (gBelakang === '-') gBelakang = '';

            let fullName = formatNamaGelarServer(gDepan, pureName, gBelakang);
            let jbt = (p.tugas_tambahan || p.jabatan_ptk || p.jenis_ptk || 'Guru').trim();
            if (jbt === '-' || jbt === '0') jbt = 'Guru';
            return {
                ptk_id: p.ptk_id,
                nama_lengkap: fullName,
                nip: p.nip || pegMatch?.nip || '-',
                jabatan: jbt
            };
        });
    } catch (e) {}

    if (list.length === 0) {
        try {
            const [pegRows]: any = await getPool().query("SELECT pegawai_id as ptk_id, nama_lengkap, nip, gelar_depan, gelar_belakang, jabatan FROM pegawai ORDER BY nama_lengkap ASC");
            list = (pegRows || []).map((p: any) => ({
                ptk_id: p.ptk_id,
                nama_lengkap: formatNamaGelarServer(p.gelar_depan, p.nama_lengkap, p.gelar_belakang),
                nip: p.nip || '-',
                jabatan: p.jabatan || 'Guru'
            }));
        } catch (e2) {}
    }

    res.json(list);
}));

