app.post("/api/surat-panggilan/:id/upload-arsip", authenticate, uploadArsipSurat.single('file'), asyncHandler(async (req: any, res: any) => {
    if (req.user?.type === 'student') {
        return res.status(403).json({ error: "Siswa hanya berhak melihat arsip dokumen, tidak dapat mengunggah berkas." });
    }

    const { id } = req.params;
    if (!req.file) {
        return res.status(400).json({ error: "Silakan pilih berkas PDF/Scan untuk diunggah." });
    }

    const [rows]: any = await getPool().query("SELECT * FROM surat_panggilan WHERE id = ?", [id]);
    if (!rows.length) return res.status(404).json({ error: "Surat panggilan tidak ditemukan." });
    const sp = rows[0];

    const safeNamaSiswa = (sp.nama_siswa || 'Siswa').replace(/[^a-zA-Z0-9_-]/g, '_');
    const safeNoSurat = (sp.nomor_surat || `SP_${id}`).replace(/[^a-zA-Z0-9_-]/g, '_');
    const ext = path.extname(req.file.originalname) || '.pdf';
    const cleanFilename = `TTD_Surat_Panggilan_${safeNoSurat}_${safeNamaSiswa}${ext}`;

    const fileUrl = await uploadArsipFileHelper(req.file, 'Arsip Bimbingan & Konseling', 'Surat Panggilan Bertanda Tangan', cleanFilename);
    const uploaderName = req.user?.nama || req.user?.nama_lengkap || req.user?.username || 'Pihak Sekolah';

    await getPool().execute(
        "UPDATE surat_panggilan SET dokumen_arsip_url = ?, arsip_uploaded_at = NOW(), arsip_uploaded_by = ? WHERE id = ?",
        [fileUrl, uploaderName, id]
    );

    res.json({ 
        success: true, 
        dokumen_arsip_url: fileUrl, 
        arsip_uploaded_at: new Date().toISOString(),
        arsip_uploaded_by: uploaderName,
        message: "Berkas arsip surat panggilan bertanda tangan berhasil disimpan." 
    });
}));

