app.get("/api/surat-pernyataan", authenticate, asyncHandler(async (req: any, res: any) => {
    const scope = await resolvePelanggaranUserScope(req.user);
    const { q, jenis, status, rombel } = req.query;
    let query = `
        SELECT sp.*, 
               s.nama as nama_siswa_current,
               s.nisn as nisn_current,
               s.nomor_telepon_seluler as hp_orang_tua,
               s.nama_ayah,
               s.nama_ibu_kandung as nama_ibu,
               s.nama_wali
        FROM surat_pernyataan_siswa sp
        LEFT JOIN peserta_didik s ON (sp.peserta_didik_id = s.peserta_didik_id)
        WHERE 1=1
    `;
    const params: any[] = [];

    // Filter Hak Akses Role
    if (scope.isStudent) {
        query += ` AND sp.peserta_didik_id = ?`;
        params.push(scope.studentId);
    } else if (scope.isTeacher) {
        if (scope.allowedRombels.length > 0) {
            const placeholders = scope.allowedRombels.map(() => '?').join(',');
            query += ` AND (sp.kelas_rombel IN (${placeholders}) OR sp.nama_saksi_1 LIKE ? OR sp.nama_saksi_2 LIKE ?)`;
            params.push(...scope.allowedRombels, `%${scope.staffName}%`, `%${scope.staffName}%`);
        } else if (scope.staffName) {
            query += ` AND (sp.nama_saksi_1 LIKE ? OR sp.nama_saksi_2 LIKE ?)`;
            params.push(`%${scope.staffName}%`, `%${scope.staffName}%`);
        }
    }

    if (q) {
        query += ` AND (sp.nomor_surat LIKE ? OR sp.nama_siswa LIKE ? OR sp.nisn LIKE ? OR sp.nipd LIKE ? OR sp.judul_pernyataan LIKE ? OR sp.nama_orang_tua LIKE ?)`;
        const p = `%${q}%`;
        params.push(p, p, p, p, p, p);
    }
    if (jenis && jenis !== 'semua' && jenis !== 'All') {
        query += ` AND sp.jenis_pernyataan = ?`;
        params.push(jenis);
    }
    if (status && status !== 'semua' && status !== 'All') {
        query += ` AND sp.status = ?`;
        params.push(status);
    }
    if (rombel && rombel !== 'semua' && rombel !== 'All') {
        query += ` AND sp.kelas_rombel LIKE ?`;
        params.push(`%${rombel}%`);
    }
    query += ` ORDER BY sp.tanggal_surat DESC, sp.id DESC`;
    const [rows]: any = await getPool().query(query, params);
    res.json(rows || []);
}));

app.get("/api/surat-pernyataan/:id", authenticate, asyncHandler(async (req: any, res: any) => {
    const { id } = req.params;
    const [rows]: any = await getPool().query("SELECT * FROM surat_pernyataan_siswa WHERE id = ?", [id]);
    if (!rows.length) return res.status(404).json({ error: "Surat pernyataan tidak ditemukan" });
    res.json(rows[0]);
}));

app.post("/api/surat-pernyataan", authenticate, asyncHandler(async (req: any, res: any) => {
    const {
        nomor_surat, jenis_pernyataan, judul_pernyataan,
        peserta_didik_id, nama_siswa, nisn, nipd, kelas_rombel,
        nama_orang_tua, pekerjaan_orang_tua, alamat_orang_tua, nomor_hp_orang_tua,
        surat_panggilan_id, pelanggaran_ids, rincian_kasus_json,
        isi_pernyataan, alasan_pengunduran,
        tanggal_surat, tempat_surat,
        nama_saksi_1, jabatan_saksi_1, nip_saksi_1,
        nama_saksi_2, jabatan_saksi_2, nip_saksi_2,
        nama_kesiswaan, jabatan_kesiswaan, nip_kesiswaan,
        nama_kepala_sekolah, nip_kepala_sekolah,
        perlu_ttd_siswa, perlu_ttd_ortu,
        status, catatan
    } = req.body;

    if (!nama_siswa || !jenis_pernyataan || !judul_pernyataan || !tanggal_surat) {
        return res.status(400).json({ error: "Data wajib (Nama Siswa, Jenis, Judul Pernyataan, Tanggal) belum lengkap." });
    }

    // Auto generate nomor surat pernyataan jika kosong
    let noSurat = nomor_surat;
    if (!noSurat || noSurat.trim() === '') {
        const [cntRows]: any = await getPool().query("SELECT COUNT(*) as count FROM surat_pernyataan_siswa");
        const count = (cntRows[0]?.count || 0) + 1;
        const now = new Date(tanggal_surat || Date.now());
        const romanMonths = ['I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII'];
        const romanMonth = romanMonths[now.getMonth()] || 'IX';
        const year = now.getFullYear();
        const padded = String(count).padStart(3, '0');
        const code = jenis_pernyataan === 'sk_pemberhentian_sepihak' ? 'SK-DIS/SDN' : 'SPN-BK/SDN';
        noSurat = `${padded}/${code}/${romanMonth}/${year}`;
    }

    const pelIdsStr = Array.isArray(pelanggaran_ids) ? JSON.stringify(pelanggaran_ids) : (pelanggaran_ids || null);
    const rincianStr = typeof rincian_kasus_json === 'object' ? JSON.stringify(rincian_kasus_json) : (rincian_kasus_json || null);
    const isPerluTtdS = (perlu_ttd_siswa !== false && perlu_ttd_siswa !== 0 && perlu_ttd_siswa !== '0') ? 1 : 0;
    const isPerluTtdO = (perlu_ttd_ortu !== false && perlu_ttd_ortu !== 0 && perlu_ttd_ortu !== '0') ? 1 : 0;

    const [result]: any = await getPool().execute(`
        INSERT INTO surat_pernyataan_siswa (
            nomor_surat, jenis_pernyataan, judul_pernyataan,
            peserta_didik_id, nama_siswa, nisn, nipd, kelas_rombel,
            nama_orang_tua, pekerjaan_orang_tua, alamat_orang_tua, nomor_hp_orang_tua,
            surat_panggilan_id, pelanggaran_ids, rincian_kasus_json,
            isi_pernyataan, alasan_pengunduran,
            tanggal_surat, tempat_surat,
            nama_saksi_1, jabatan_saksi_1, nip_saksi_1,
            nama_saksi_2, jabatan_saksi_2, nip_saksi_2,
            nama_kesiswaan, jabatan_kesiswaan, nip_kesiswaan,
            nama_kepala_sekolah, nip_kepala_sekolah,
            perlu_ttd_siswa, perlu_ttd_ortu,
            status, catatan, created_by
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `, [
        noSurat, jenis_pernyataan, judul_pernyataan,
        peserta_didik_id || '', nama_siswa, nisn || '', nipd || '', kelas_rombel || '',
        nama_orang_tua || '', pekerjaan_orang_tua || '', alamat_orang_tua || '', nomor_hp_orang_tua || '',
        surat_panggilan_id || null, pelIdsStr, rincianStr,
        isi_pernyataan || '', alasan_pengunduran || '',
        tanggal_surat, tempat_surat || 'Tangerang',
        nama_saksi_1 || '', jabatan_saksi_1 || 'Guru Bimbingan Konseling (BK)', nip_saksi_1 || '',
        nama_saksi_2 || '', jabatan_saksi_2 || 'Wali Kelas', nip_saksi_2 || '',
        nama_kesiswaan || '', jabatan_kesiswaan || 'Bidang Kesiswaan', nip_kesiswaan || '',
        nama_kepala_sekolah || '', nip_kepala_sekolah || '',
        isPerluTtdS, isPerluTtdO,
        status || 'aktif', catatan || '', req.user?.id || null
    ]);

    res.json({ success: true, id: result.insertId, message: "Surat pernyataan berhasil dibuat." });
}));

