app.put("/api/bidang_ekskul/:id", authenticate, asyncHandler(async (req: any, res: any) => {
    const { pegawai_id, kategori, mata_pelajaran, kelas, nama_bidang } = req.body;
    const kelasArr = Array.isArray(kelas) ? kelas : (kelas ? [String(kelas)] : []);
    const kelasStr = JSON.stringify(kelasArr);
    const namaBidangVal = nama_bidang || mata_pelajaran || '';
    try {
        await getPool().execute(
            "UPDATE bidang_ekskul SET pegawai_id = ?, kategori = ?, mata_pelajaran = ?, nama_bidang = ?, kelas = ? WHERE id = ?",
            [pegawai_id, kategori || 'Guru Bidang', mata_pelajaran || null, namaBidangVal, kelasStr, req.params.id]
        );
    } catch (err: any) {
        await ensureColumn(getPool(), 'bidang_ekskul', 'pegawai_id', 'VARCHAR(100) DEFAULT NULL');
        await ensureColumn(getPool(), 'bidang_ekskul', 'kategori', "VARCHAR(100) DEFAULT 'Guru Bidang'");
        await ensureColumn(getPool(), 'bidang_ekskul', 'mata_pelajaran', 'VARCHAR(255) DEFAULT NULL');
        await ensureColumn(getPool(), 'bidang_ekskul', 'nama_bidang', 'VARCHAR(255) DEFAULT NULL');
        await ensureColumn(getPool(), 'bidang_ekskul', 'kelas', 'TEXT DEFAULT NULL');
        try {
            await getPool().query("ALTER TABLE `bidang_ekskul` MODIFY COLUMN `nama_bidang` VARCHAR(255) NULL DEFAULT NULL");
        } catch (e) {}

        await getPool().execute(
            "UPDATE bidang_ekskul SET pegawai_id = ?, kategori = ?, mata_pelajaran = ?, nama_bidang = ?, kelas = ? WHERE id = ?",
            [pegawai_id, kategori || 'Guru Bidang', mata_pelajaran || null, namaBidangVal, kelasStr, req.params.id]
        );
    }

    // Sinkronkan siswa_ids di akademik_ekskul & jadwal_ekskul (status terjadwal) sesuai kelas baru pelatih
    try {
        if (kelasArr.length > 0) {
            const normAllowed = new Set(kelasArr.map((k: string) => String(k || '').trim().toLowerCase().replace(/^kelas\s+/i, '')));
            const [stuRows]: any = await getPool().query(`
                SELECT DISTINCT pd.peserta_didik_id, rb.nama as rombel
                FROM peserta_didik pd
                INNER JOIN anggota_rombel ar ON ar.peserta_didik_id = pd.peserta_didik_id AND (ar.soft_delete = 0 OR ar.soft_delete IS NULL OR ar.soft_delete = '0')
                INNER JOIN rombongan_belajar rb ON rb.rombongan_belajar_id = ar.rombongan_belajar_id AND (rb.soft_delete = 0 OR rb.soft_delete IS NULL OR rb.soft_delete = '0')
                WHERE (pd.soft_delete = 0 OR pd.soft_delete IS NULL OR pd.soft_delete = '0')
                  AND rb.jenis_rombel IN (1, 9)
            `);
            const matchedStudentIds = (stuRows || [])
                .filter((s: any) => normAllowed.has(String(s.rombel || '').trim().toLowerCase().replace(/^kelas\s+/i, '')))
                .map((s: any) => String(s.peserta_didik_id));
            const uniqueMatchedIds = Array.from(new Set(matchedStudentIds));
            const newSiswaIdsJson = JSON.stringify(uniqueMatchedIds);

            await getPool().execute(
                "UPDATE akademik_ekskul SET pelatih_id = ?, siswa_ids = ? WHERE ekskul_id = ?",
                [pegawai_id, newSiswaIdsJson, req.params.id]
            );
            await getPool().execute(
                "UPDATE jadwal_ekskul j INNER JOIN akademik_ekskul ae ON j.pembinaan_id = ae.id SET j.siswa_ids = ? WHERE ae.ekskul_id = ? AND j.status = 'terjadwal'",
                [newSiswaIdsJson, req.params.id]
            );
        }
    } catch (syncErr) {
        console.warn("Sync ekskul siswa_ids warning:", syncErr);
    }

    res.json({ success: true });
}));

