app.post("/api/literasi/jurnal/:id/cancel", authenticate, asyncHandler(async (req: any, res: any) => {
    const jurnal_id = req.params.id;
    
    const [jurnalData]: any = await getPool().execute("SELECT siswa_id, earned_xp, status FROM literasi_jurnal WHERE id = ?", [jurnal_id]);
    if (jurnalData.length === 0) return res.status(404).json({ error: "Jurnal tidak ditemukan" });
    
    if (jurnalData[0].status !== 'disetujui' && jurnalData[0].status !== 'ditolak') return res.status(400).json({ error: "Jurnal belum dinilai" });
    
    const siswa_id = jurnalData[0].siswa_id;
    const xp_to_deduct = jurnalData[0].earned_xp || 0;
    
    await getPool().execute(
        "UPDATE literasi_jurnal SET status = 'menunggu_validasi', earned_xp = 0, dinilai_oleh = NULL WHERE id = ?",
        [jurnal_id]
    );
    
    if (xp_to_deduct > 0) {
        const [gamifikasi]: any = await getPool().execute("SELECT total_xp FROM peserta_didik_gamifikasi WHERE siswa_id = ?", [siswa_id]);
        if (gamifikasi.length > 0) {
            let total_xp = gamifikasi[0].total_xp - xp_to_deduct;
            if (total_xp < 0) total_xp = 0;
            
            // Recalculate level
            let newLevel = 1;
            if (total_xp >= 1000) newLevel = 6;
            else if (total_xp >= 700) newLevel = 5;
            else if (total_xp >= 450) newLevel = 4;
            else if (total_xp >= 250) newLevel = 3;
            else if (total_xp >= 100) newLevel = 2;
            
            await getPool().execute("UPDATE siswa_gamifikasi SET total_xp = ?, level = ? WHERE siswa_id = ?", [total_xp, newLevel, siswa_id]);
        }
    }
    
    res.json({ success: true });
}));

app.get("/api/literasi/leaderboard/:tingkat_kelas", authenticate, asyncHandler(async (req: any, res: any) => {
    const tingkat = req.params.tingkat_kelas;
    
    // Generate roman numeral mapping for rombel matching (e.g. 6 -> VI)
    const romanMap: Record<string, string> = {
        '1': 'I', '2': 'II', '3': 'III', '4': 'IV', '5': 'V', '6': 'VI',
        '7': 'VII', '8': 'VIII', '9': 'IX', '10': 'X', '11': 'XI', '12': 'XII'
    };
    const roman = romanMap[tingkat] || tingkat;

    const [leaderboard]: any = await getPool().execute(`
        SELECT 
            sg.siswa_id, 
            sg.total_xp, 
            sg.level, 
            s.nama as nama_lengkap, 
            COALESCE(rb.nama, s.rombel) as rombel,
            COALESCE(ROUND(SUM(j.waktu_baca_aktual) / 60), 0) as total_waktu_baca
        FROM peserta_didik_gamifikasi sg
        JOIN peserta_didik s ON (sg.siswa_id = s.peserta_didik_id OR sg.siswa_id = s.id)
        LEFT JOIN anggota_rombel ar ON ar.peserta_didik_id = s.peserta_didik_id
        LEFT JOIN rombongan_belajar rb ON rb.rombongan_belajar_id = ar.rombongan_belajar_id
        LEFT JOIN literasi_jurnal j ON j.siswa_id = sg.siswa_id AND j.status IN ('disetujui', 'menunggu_validasi')
        WHERE rb.tingkat_pendidikan_id = ? OR rb.nama LIKE ? OR rb.nama LIKE ? OR s.rombel LIKE ? OR s.rombel LIKE ?
        GROUP BY sg.siswa_id, sg.total_xp, sg.level, s.nama, rb.nama, s.rombel
        ORDER BY sg.total_xp DESC, total_waktu_baca ASC
        LIMIT 10
    `, [tingkat, `%${tingkat}%`, `%${roman}%`, `%${tingkat}%`, `%${roman}%`]);
    res.json({ leaderboard });
}));

app.get("/api/literasi/siswa/:id", authenticate, asyncHandler(async (req: any, res: any) => {
    const targetId = (req.params.id === 'null' || req.params.id === 'undefined' || !req.params.id) ? req.user.id : req.params.id;
    
    // Ambil data gamifikasi
    const [profile]: any = await getPool().execute("SELECT total_xp, level FROM peserta_didik_gamifikasi WHERE siswa_id = ?", [targetId]);
    const baseProfile = profile.length > 0 ? profile[0] : { total_xp: 0, level: 1 };
    
    // Ambil statistik baca & buku jurnal yang disetujui
    const [stats]: any = await getPool().execute(`
        SELECT 
            COALESCE(ROUND(SUM(waktu_baca_aktual) / 60), 0) as total_waktu_baca,
            COUNT(DISTINCT materi_id) as total_buku
        FROM literasi_jurnal 
        WHERE siswa_id = ? AND status = 'disetujui'
    `, [targetId]);
    const readStats = stats.length > 0 ? stats[0] : { total_waktu_baca: 0, total_buku: 0 };

    // Ambil data siswa & rombel/tingkat_kelas dari tabel peserta_didik & rombel
    const [siswaRows]: any = await getPool().execute(`
        SELECT 
            s.peserta_didik_id as id,
            s.nama as nama_lengkap,
            rb.nama as rombel,
            rb.tingkat_pendidikan_id as tingkat_kelas
        FROM peserta_didik s
        LEFT JOIN anggota_rombel ar ON ar.peserta_didik_id = s.peserta_didik_id
        LEFT JOIN rombongan_belajar rb ON rb.rombongan_belajar_id = ar.rombongan_belajar_id
        WHERE s.peserta_didik_id = ? OR s.id = ?
        ORDER BY COALESCE(rb.semester_id, '0') DESC
        LIMIT 1
    `, [targetId, targetId]);

    let rombel = '';
    let tingkat_kelas = '1';

    if (siswaRows.length > 0) {
        rombel = siswaRows[0].rombel || '';
        if (siswaRows[0].tingkat_kelas) {
            tingkat_kelas = String(siswaRows[0].tingkat_kelas);
        } else if (rombel) {
            const numMatch = rombel.match(/\b(1[0-2]|[1-9])\b/) || rombel.match(/\d+/);
            if (numMatch) {
                tingkat_kelas = numMatch[0];
            } else {
                const upper = rombel.toUpperCase();
                if (/\bXII\b/.test(upper)) tingkat_kelas = '12';
                else if (/\bXI\b/.test(upper)) tingkat_kelas = '11';
                else if (/\bX\b/.test(upper)) tingkat_kelas = '10';
                else if (/\bIX\b/.test(upper)) tingkat_kelas = '9';
                else if (/\bVIII\b/.test(upper)) tingkat_kelas = '8';
                else if (/\bVII\b/.test(upper)) tingkat_kelas = '7';
                else if (/\bVI\b/.test(upper)) tingkat_kelas = '6';
                else if (/\bV\b/.test(upper)) tingkat_kelas = '5';
                else if (/\bIV\b/.test(upper)) tingkat_kelas = '4';
                else if (/\bIII\b/.test(upper)) tingkat_kelas = '3';
                else if (/\bII\b/.test(upper)) tingkat_kelas = '2';
                else if (/\bI\b/.test(upper)) tingkat_kelas = '1';
            }
        }
    }

    res.json({
        ...baseProfile,
        ...readStats,
        nama_lengkap: siswaRows.length > 0 ? siswaRows[0].nama_lengkap : '',
        rombel,
        tingkat_kelas
    });
}));

