app.post("/api/arsip-surat/:id/disposisi-respon", authenticate, asyncHandler(async (req: any, res: any) => {
    const id = req.params.id;
    const [existingRows]: any = await getPool().query("SELECT * FROM arsip_surat WHERE id = ?", [id]);
    if (!existingRows || existingRows.length === 0) {
        return res.status(404).json({ success: false, message: "Arsip surat tidak ditemukan" });
    }

    const current = existingRows[0];
    const { respon_teks, status_tindak_lanjut } = req.body;
    const user = req.user || {};

    let listTujuan: any[] = [];
    try {
        listTujuan = typeof current.disposisi_tujuan === 'string' ? JSON.parse(current.disposisi_tujuan) : (current.disposisi_tujuan || []);
    } catch (_) {}

    const nowStr = new Date().toISOString();
    let found = false;

    listTujuan = listTujuan.map((t: any) => {
        const isMatch = (t.id && (String(t.id) === String(user.id) || String(t.id) === String(user.staff_id))) ||
                        (t.nama && [user.nama, user.nama_lengkap, user.username].filter(Boolean).some((n: any) => String(n).toLowerCase() === String(t.nama).toLowerCase()));
        
        if (isMatch) {
            found = true;
            return {
                ...t,
                status: status_tindak_lanjut || 'selesai',
                respon: respon_teks,
                tanggal_respon: nowStr
            };
        }
        return t;
    });

    if (!found) {
        listTujuan.push({
            id: user.id || user.staff_id,
            nama: user.nama || user.username || 'Staf',
            nip: user.nip || '',
            jabatan: user.jabatan || user.role_name || 'Staf',
            status: status_tindak_lanjut || 'selesai',
            respon: respon_teks,
            tanggal_respon: nowStr
        });
    }

    const allFinished = listTujuan.length > 0 && listTujuan.every((t: any) => t.status === 'selesai');
    const newStatusDisposisi = allFinished ? 'selesai' : 'proses';

    await getPool().query(`
        UPDATE arsip_surat SET
            disposisi_tujuan = ?,
            disposisi_respon_terakhir = ?,
            status_disposisi = ?
        WHERE id = ?
    `, [
        JSON.stringify(listTujuan),
        respon_teks || '',
        newStatusDisposisi,
        id
    ]);

    res.json({
        success: true,
        message: "Laporan respon tindak lanjut disposisi berhasil disimpan!"
    });
}));

app.delete("/api/arsip-surat/:id", authenticate, asyncHandler(async (req: any, res: any) => {
    const id = req.params.id;
    const [rows]: any = await getPool().query("SELECT * FROM arsip_surat WHERE id = ?", [id]);
    if (!rows || rows.length === 0) {
        return res.status(404).json({ success: false, message: "Arsip surat tidak ditemukan" });
    }

    const item = rows[0];
    const user = req.user || {};
    const isSuperAdmin = 
        user.role?.toLowerCase() === 'superadmin' || 
        user.role_name?.toLowerCase() === 'superadmin' || 
        user.type === 'superadmin' ||
        user.username?.toLowerCase() === 'admin';

    const isOwner = 
        (item.user_id && (Number(item.user_id) === Number(user.id) || Number(item.user_id) === Number(user.staff_id))) ||
        (item.created_by && [user.nama, user.nama_lengkap, user.username, user.email, String(user.id)].filter(Boolean).some((val: any) => String(val).toLowerCase() === String(item.created_by).toLowerCase()));

    if (!isSuperAdmin && !isOwner) {
        return res.status(403).json({ 
            success: false, 
            message: "Akses ditolak: Arsip surat hanya dapat dihapus oleh pembuatnya atau pengguna dengan peran Superadmin." 
        });
    }

    try {
        if (item.berkas_url && item.berkas_url.startsWith('/uploads/arsip_surat/')) {
            const filePath = path.join(process.cwd(), item.berkas_url);
            if (fs.existsSync(filePath)) fs.unlinkSync(filePath);
        }
        let lampiran: any[] = [];
        try { lampiran = typeof item.lampiran_lain === 'string' ? JSON.parse(item.lampiran_lain) : (item.lampiran_lain || []); } catch (_) {}
        for (const f of lampiran) {
            if (f.url && f.url.startsWith('/uploads/arsip_surat/')) {
                const filePath = path.join(process.cwd(), f.url);
                if (fs.existsSync(filePath)) fs.unlinkSync(filePath);
            }
        }
    } catch (cleanErr) {
        console.warn("[Arsip Delete] File clean warning:", cleanErr);
    }

    await getPool().query("DELETE FROM arsip_surat WHERE id = ?", [id]);
    res.json({ success: true, message: "Arsip surat berhasil dihapus" });
}));

