async function ensurePerpustakaanTables() {
    try {
        const pool = getPool();
        await pool.query(`
            CREATE TABLE IF NOT EXISTS perpustakaan_buku (
                id INT AUTO_INCREMENT PRIMARY KEY,
                kode_buku VARCHAR(100) NOT NULL UNIQUE,
                isbn VARCHAR(50) DEFAULT '',
                judul VARCHAR(255) NOT NULL,
                pengarang VARCHAR(255) DEFAULT '',
                penerbit VARCHAR(255) DEFAULT '',
                tahun_terbit VARCHAR(10) DEFAULT '',
                tahun_pengadaan VARCHAR(10) DEFAULT '',
                sumber_pengadaan VARCHAR(100) DEFAULT 'Dana BOS Reguler',
                kategori VARCHAR(100) DEFAULT 'Buku Pelajaran',
                klasifikasi_ddc VARCHAR(50) DEFAULT '',
                rak_lokasi VARCHAR(100) DEFAULT 'Rak A1',
                stok_total INT DEFAULT 1,
                stok_tersedia INT DEFAULT 1,
                cover_url VARCHAR(255) DEFAULT '',
                ebook_url VARCHAR(255) DEFAULT '',
                deskripsi TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                INDEX idx_kategori (kategori),
                INDEX idx_judul (judul)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
        `);

        // Migration check for existing tables
        const [bukuCols]: any = await pool.query("SHOW COLUMNS FROM perpustakaan_buku LIKE 'tahun_pengadaan'");
        if (!bukuCols || bukuCols.length === 0) {
            await pool.query("ALTER TABLE perpustakaan_buku ADD COLUMN tahun_pengadaan VARCHAR(10) DEFAULT '' AFTER tahun_terbit");
        }
        const [sumberCols]: any = await pool.query("SHOW COLUMNS FROM perpustakaan_buku LIKE 'sumber_pengadaan'");
        if (!sumberCols || sumberCols.length === 0) {
            await pool.query("ALTER TABLE perpustakaan_buku ADD COLUMN sumber_pengadaan VARCHAR(100) DEFAULT 'Dana BOS Reguler' AFTER tahun_pengadaan");
        }

        await pool.query(`
            CREATE TABLE IF NOT EXISTS perpustakaan_sirkulasi (
                id INT AUTO_INCREMENT PRIMARY KEY,
                kode_transaksi VARCHAR(100) NOT NULL UNIQUE,
                buku_id INT NOT NULL,
                tipe_peminjam ENUM('siswa', 'guru', 'umum') DEFAULT 'siswa',
                peminjam_id VARCHAR(64) DEFAULT NULL,
                peminjam_nama VARCHAR(255) NOT NULL,
                peminjam_identitas VARCHAR(100) DEFAULT '',
                peminjam_kelas VARCHAR(100) DEFAULT '',
                tanggal_pinjam DATE NOT NULL,
                tanggal_kembali_rencana DATE NOT NULL,
                tanggal_kembali_realisasi DATE NULL,
                status ENUM('dipinjam', 'kembali', 'terlambat', 'hilang') DEFAULT 'dipinjam',
                denda INT DEFAULT 0,
                kondisi_buku_kembali VARCHAR(50) DEFAULT 'Baik',
                catatan TEXT,
                petugas_nama VARCHAR(100) DEFAULT '',
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                INDEX idx_status (status),
                INDEX idx_peminjam (peminjam_nama)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
        `);

        await pool.query(`
            CREATE TABLE IF NOT EXISTS perpustakaan_kunjungan (
                id INT AUTO_INCREMENT PRIMARY KEY,
                tipe_pengunjung ENUM('siswa', 'guru', 'tamu') DEFAULT 'siswa',
                pengunjung_id VARCHAR(64) DEFAULT NULL,
                pengunjung_nama VARCHAR(255) NOT NULL,
                pengunjung_identitas VARCHAR(100) DEFAULT '',
                pengunjung_kelas VARCHAR(100) DEFAULT '',
                keperluan VARCHAR(255) DEFAULT 'Membaca & Meminjam Buku',
                tanggal_kunjungan DATETIME DEFAULT CURRENT_TIMESTAMP,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                INDEX idx_tanggal_kunjungan (tanggal_kunjungan)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
        `);

        await pool.query(`
            CREATE TABLE IF NOT EXISTS perpustakaan_pengaturan (
                id INT PRIMARY KEY DEFAULT 1,
                lama_pinjam_hari INT DEFAULT 7,
                maksimal_buku INT DEFAULT 2,
                denda_per_hari INT DEFAULT 0,
                syarat_ketentuan TEXT,
                kategori_list TEXT DEFAULT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
        `);

        // Migration check for kategori_list
        const [kategoriCols]: any = await pool.query("SHOW COLUMNS FROM perpustakaan_pengaturan LIKE 'kategori_list'");
        if (!kategoriCols || kategoriCols.length === 0) {
            await pool.query("ALTER TABLE perpustakaan_pengaturan ADD COLUMN kategori_list TEXT DEFAULT NULL");
        }

        const [settingRows]: any = await pool.query("SELECT id FROM perpustakaan_pengaturan WHERE id = 1");
        if (!settingRows || settingRows.length === 0) {
            await pool.query(`
                INSERT INTO perpustakaan_pengaturan (id, lama_pinjam_hari, maksimal_buku, denda_per_hari, syarat_ketentuan, kategori_list)
                VALUES (1, 7, 2, 0, 'Harap menjaga kebersihan dan keutuhan buku perpustakaan. Pengembalian tepat waktu.', ?)
            `, [JSON.stringify([
                'Buku Pelajaran',
                'Buku Guru',
                'Agama dan Budi Pekerti',
                'Cerita & Fiksi',
                'Ensiklopedia',
                'Sains & Teknologi',
                'Sejarah & Budaya',
                'Kamus & Bahasa',
                'Karya Ilmiah / Referensi',
                'Majalah & Komik Edukasi',
                'Umum'
            ])]);
        }
    } catch (e: any) {
        console.warn("[DB] ensurePerpustakaanTables warning:", e.message);
    }
}

