app.get("/api/perpustakaan/buku", authenticate, asyncHandler(async (req: any, res: any) => {
    await ensurePerpustakaanTables();
    try {
        const { kategori, rak, ketersediaan, has_ebook, q } = req.query;
        let query = "SELECT * FROM perpustakaan_buku WHERE 1=1";
        const params: any[] = [];

        if (kategori && kategori !== 'Semua' && kategori !== 'all') {
            query += " AND kategori = ?";
            params.push(kategori);
        }
        if (rak && rak !== 'Semua' && rak !== 'all') {
            query += " AND rak_lokasi = ?";
            params.push(rak);
        }
        if (ketersediaan === 'tersedia') {
            query += " AND stok_tersedia > 0";
        } else if (ketersediaan === 'habis') {
            query += " AND stok_tersedia <= 0";
        }
        if (has_ebook === '1' || has_ebook === 'true') {
            query += " AND ebook_url != '' AND ebook_url IS NOT NULL";
        }
        if (q) {
            query += " AND (judul LIKE ? OR pengarang LIKE ? OR penerbit LIKE ? OR kode_buku LIKE ? OR isbn LIKE ? OR klasifikasi_ddc LIKE ?)";
            const pattern = `%${q}%`;
            params.push(pattern, pattern, pattern, pattern, pattern, pattern);
        }

        query += " ORDER BY judul ASC, id DESC";
        const [rows]: any = await getPool().query(query, params);
        res.json({ success: true, count: rows.length, data: rows || [] });
    } catch (err: any) {
        console.error("[Perpus Buku] Fetch error:", err);
        res.json({ success: true, count: 0, data: [] });
    }
}));

