app.put("/api/perpustakaan/buku/:id", authenticate, uploadPerpustakaan.fields([
    { name: 'cover', maxCount: 1 },
    { name: 'ebook', maxCount: 1 }
]), asyncHandler(async (req: any, res: any) => {
    await ensurePerpustakaanTables();
    const id = req.params.id;
    const pool = getPool();
    const [existingRows]: any = await pool.query("SELECT * FROM perpustakaan_buku WHERE id = ?", [id]);
    if (!existingRows || existingRows.length === 0) {
        return res.status(404).json({ success: false, message: "Buku tidak ditemukan" });
    }
    const current = existingRows[0];

    const files = req.files as { [fieldname: string]: Express.Multer.File[] } || {};
    const {
        kode_buku,
        isbn,
        judul,
        pengarang,
        penerbit,
        tahun_terbit,
        tahun_pengadaan,
        sumber_pengadaan,
        kategori,
        klasifikasi_ddc,
        rak_lokasi,
        stok_total,
        deskripsi,
        existing_cover_url,
        existing_ebook_url
    } = req.body;

    let coverUrl = existing_cover_url !== undefined ? existing_cover_url : current.cover_url;
    if (files.cover && files.cover.length > 0) {
        coverUrl = `/uploads/perpustakaan/${files.cover[0].filename}`;
    }

    let ebookUrl = existing_ebook_url !== undefined ? existing_ebook_url : current.ebook_url;
    if (files.ebook && files.ebook.length > 0) {
        ebookUrl = `/uploads/perpustakaan/${files.ebook[0].filename}`;
    }

    const newTotal = stok_total !== undefined ? Math.max(1, parseInt(stok_total) || 1) : current.stok_total;
    const delta = newTotal - current.stok_total;
    const newTersedia = Math.max(0, current.stok_tersedia + delta);

    await pool.query(`
        UPDATE perpustakaan_buku SET
            kode_buku = ?,
            isbn = ?,
            judul = ?,
            pengarang = ?,
            penerbit = ?,
            tahun_terbit = ?,
            tahun_pengadaan = ?,
            sumber_pengadaan = ?,
            kategori = ?,
            klasifikasi_ddc = ?,
            rak_lokasi = ?,
            stok_total = ?,
            stok_tersedia = ?,
            cover_url = ?,
            ebook_url = ?,
            deskripsi = ?
        WHERE id = ?
    `, [
        kode_buku || current.kode_buku,
        isbn !== undefined ? isbn : current.isbn,
        judul || current.judul,
        pengarang !== undefined ? pengarang : current.pengarang,
        penerbit !== undefined ? penerbit : current.penerbit,
        tahun_terbit !== undefined ? tahun_terbit : current.tahun_terbit,
        tahun_pengadaan !== undefined ? tahun_pengadaan : current.tahun_pengadaan,
        sumber_pengadaan !== undefined ? sumber_pengadaan : current.sumber_pengadaan,
        kategori || current.kategori,
        klasifikasi_ddc !== undefined ? klasifikasi_ddc : current.klasifikasi_ddc,
        rak_lokasi !== undefined ? rak_lokasi : current.rak_lokasi,
        newTotal,
        newTersedia,
        coverUrl,
        ebookUrl,
        deskripsi !== undefined ? deskripsi : current.deskripsi,
        id
    ]);

    res.json({ success: true, message: "Katalog buku berhasil diperbarui!" });
}));

