// Live Search Peminjam (Siswa Dapodik & Guru PTK)
app.get("/api/perpustakaan/cari-peminjam", authenticate, asyncHandler(async (req: any, res: any) => {
    const q = (req.query.q || '').toString().trim();
    if (!q || q.length < 2) {
        return res.json({ success: true, data: [] });
    }

    const pool = getPool();
    const pattern = `%${q}%`;
    const results: any[] = [];

    try {
        // Cari dari peserta_didik (Dapodik Murni)
        const [siswaRows]: any = await pool.query(`
            SELECT 
                pd.peserta_didik_id as id,
                pd.nama as nama,
                COALESCE(rpd.nipd, pd.nipd, '') as nipd,
                COALESCE(pd.nisn, '') as nisn,
                COALESCE(rb.nama, '') as kelas,
                'siswa' as tipe
            FROM peserta_didik pd
            LEFT JOIN registrasi_peserta_didik rpd ON pd.peserta_didik_id = rpd.peserta_didik_id
            LEFT JOIN anggota_rombel ar ON pd.peserta_didik_id = ar.peserta_didik_id
            LEFT JOIN rombongan_belajar rb ON ar.rombongan_belajar_id = rb.rombongan_belajar_id
            WHERE (pd.nama LIKE ? OR pd.nisn LIKE ? OR rpd.nipd LIKE ?)
            LIMIT 20
        `, [pattern, pattern, pattern]);

        for (const s of (siswaRows || [])) {
            results.push({
                id: s.id,
                nama: s.nama,
                identitas: s.nisn ? `NISN: ${s.nisn}` : (s.nipd ? `NIPD: ${s.nipd}` : '-'),
                kelas: s.kelas || 'Siswa',
                tipe: 'siswa'
            });
        }
    } catch (_) {}

    try {
        // Cari dari PTK / Guru
        const [guruRows]: any = await pool.query(`
            SELECT ptk_id as id, nama, nip, 'guru' as tipe
            FROM ptk
            WHERE (nama LIKE ? OR nip LIKE ?)
            LIMIT 10
        `, [pattern, pattern]);

        for (const g of (guruRows || [])) {
            results.push({
                id: g.id,
                nama: g.nama,
                identitas: g.nip ? `NIP: ${g.nip}` : 'Guru / Tenaga Kependidikan',
                kelas: 'Guru / Tenaga Kependidikan',
                tipe: 'guru'
            });
        }
    } catch (_) {}

    res.json({ success: true, count: results.length, data: results });
}));

