// Helper matcher untuk tingkat / fase kurikulum
function isAstsLevelMatching(ruleLevels: string, targetLevel: string): boolean {
    if (!ruleLevels || ruleLevels === 'Semua' || !targetLevel || targetLevel === 'Semua') return true;

    const ruleArr = ruleLevels.split(',').map(s => s.trim().toUpperCase());
    const target = targetLevel.trim().toUpperCase();

    if (ruleArr.includes(target)) return true;

    const faseMap: Record<string, string[]> = {
        'FASE A': ['1', '2'],
        'FASE B': ['3', '4'],
        'FASE C': ['5', '6'],
        'FASE B-C': ['3', '4', '5', '6'],
        'FASE B, C': ['3', '4', '5', '6'],
        'FASE B, FASE C': ['3', '4', '5', '6'],
        'FASE D': ['7', '8', '9'],
        'FASE E': ['10'],
        'FASE F': ['11', '12']
    };

    // Expand rule levels into set of numeric grades
    let ruleGrades = new Set<string>();
    for (const r of ruleArr) {
        if (faseMap[r]) {
            faseMap[r].forEach(num => ruleGrades.add(num));
        } else {
            const num = r.replace(/[^0-9]/g, '');
            if (num) ruleGrades.add(num);
            else ruleGrades.add(r);
        }
    }

    // Expand target level into set of numeric grades
    let targetGrades = new Set<string>();
    if (faseMap[target]) {
        faseMap[target].forEach(num => targetGrades.add(num));
    } else {
        const num = target.replace(/[^0-9]/g, '');
        if (num) targetGrades.add(num);
        else targetGrades.add(target);
    }

    // Check intersection
    for (const g of targetGrades) {
        if (ruleGrades.has(g)) return true;
    }

    return false;
}

// 1. Ambil daftar mata pelajaran (filter berdasarkan rombel, tingkat/fase, bentuk pendidikan, kurikulum)
app.get(["/api/asts/mapel", "/api/ref_mata_pelajaran", "/api/mapel-global"], authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    await ensureAstsTables(pool);
    const { rombel_id, tingkat, kurikulum, bentuk_pendidikan } = req.query;

    let targetTingkat = tingkat ? String(tingkat).trim() : '';
    let targetBentuk = bentuk_pendidikan ? String(bentuk_pendidikan).trim() : '';
    let targetKurikulum = kurikulum ? String(kurikulum).trim() : '';

    if (rombel_id) {
        const [rRows]: any = await pool.query(
            "SELECT tingkat, tingkat_pendidikan_id, nama, name FROM rombongan_belajar WHERE (rombongan_belajar_id = ? OR CAST(id AS CHAR) = ?) AND (soft_delete = 0 OR soft_delete IS NULL OR soft_delete = '0' OR soft_delete = '') LIMIT 1",
            [rombel_id, rombel_id]
        );
        if (rRows.length > 0) {
            const rawT = String(rRows[0].tingkat || rRows[0].tingkat_pendidikan_id || '').trim();
            const rName = String(rRows[0].nama || rRows[0].name || '');
            const numMatch = rawT || (rName.match(/\b([1-9]|1[0-2])\b/)?.[1] || '');
            if (!targetTingkat) {
                if (numMatch === '1' || numMatch === '2') targetTingkat = 'FASE A';
                else if (numMatch === '3' || numMatch === '4') targetTingkat = 'FASE B';
                else if (numMatch === '5' || numMatch === '6') targetTingkat = 'FASE C';
                else if (numMatch === '7' || numMatch === '8' || numMatch === '9') targetTingkat = 'FASE D';
                else if (numMatch === '10') targetTingkat = 'FASE E';
                else if (numMatch === '11' || numMatch === '12') targetTingkat = 'FASE F';
                else targetTingkat = rawT || numMatch;
            }
        }
    }

    // Always fetch site settings from pengaturan_sekolah safely
    let siteSettings: any = {};
    try {
        const [sRows]: any = await pool.query("SELECT * FROM pengaturan_sekolah WHERE id = 1 LIMIT 1");
        siteSettings = sRows[0] || {};
    } catch (e) {
        try {
            const [sRows]: any = await pool.query("SELECT * FROM pengaturan_sekolah LIMIT 1");
            siteSettings = sRows[0] || {};
        } catch (e2) {}
    }

    if (!targetBentuk) {
        targetBentuk = String(siteSettings.bentuk_pendidikan_str || siteSettings.bentuk_pendidikan || siteSettings.bentuk_pendidikan_id || '').trim();
    }
    if (!targetKurikulum) {
        targetKurikulum = String(siteSettings.kurikulum || 'Kurikulum Merdeka').trim();
    }

    let normBentuk = targetBentuk;
    const tbLower = targetBentuk.toLowerCase();
    if (tbLower === '4' || tbLower === '7' || tbLower.includes('sd') || tbLower.includes('mi') || tbLower.includes('paket a')) normBentuk = 'SD';
    else if (tbLower === '5' || tbLower === '8' || tbLower.includes('smp') || tbLower.includes('mts') || tbLower.includes('paket b')) normBentuk = 'SMP';
    else if (tbLower === '6' || tbLower === '9' || tbLower === '13' || tbLower.includes('sma') || tbLower.includes('ma') || tbLower.includes('paket c')) normBentuk = 'SMA';
    else if (tbLower === '15' || tbLower.includes('smk')) normBentuk = 'SMK';

    let normKurikulum = targetKurikulum.toLowerCase().includes('2013') || targetKurikulum.toLowerCase().includes('k13') ? 'Kurikulum 2013' : 'Kurikulum Merdeka';

    // Auto-seed default mapel jika tabel belum ada atau kosong
    let rows: any[] = [];
    try {
        const [r]: any = await pool.query("SELECT * FROM ref_mata_pelajaran ORDER BY urutan ASC, nama_mapel ASC");
        rows = r || [];
    } catch (tblErr: any) {
        await seedMataPelajaranDefault(pool, true);
        const [r]: any = await pool.query("SELECT * FROM ref_mata_pelajaran ORDER BY urutan ASC, nama_mapel ASC");
        rows = r || [];
    }

    if (rows.length === 0) {
        await seedMataPelajaranDefault(pool, true);
        const [r]: any = await pool.query("SELECT * FROM ref_mata_pelajaran ORDER BY urutan ASC, nama_mapel ASC");
        rows = r || [];
    }

    // Filter all_data strictly by Bentuk Pendidikan & Kurikulum
    const configList = (rows || []).filter((m: any) => {
        if (m.bentuk_pendidikan && m.bentuk_pendidikan !== 'Semua' && normBentuk) {
            if (m.bentuk_pendidikan.toUpperCase() !== normBentuk.toUpperCase() && !normBentuk.toUpperCase().includes(m.bentuk_pendidikan.toUpperCase())) {
                return false;
            }
        }
        if (m.kurikulum && m.kurikulum !== 'Semua' && normKurikulum) {
            if (m.kurikulum.toUpperCase() !== normKurikulum.toUpperCase()) {
                return false;
            }
        }
        return true;
    });

    // Filter data for active rombel/tingkat/fase
    const filtered = configList.filter((m: any) => {
        if (rombel_id && m.rombel_id && String(m.rombel_id) === String(rombel_id)) {
            return m.status_aktif !== 0;
        }
        if (m.rombel_id && (!rombel_id || String(m.rombel_id) !== String(rombel_id))) {
            return false;
        }

        if (targetTingkat && !isAstsLevelMatching(m.tingkat, targetTingkat)) {
            return false;
        }

        return m.status_aktif !== 0;
    });

    // Helper deduplication by nama_mapel + kelompok
    const deduplicateMapels = (items: any[]) => {
        const seen = new Set<string>();
        return items.filter((m: any) => {
            const key = `${(m.nama_mapel || '').trim().toLowerCase()}:::${(m.kelompok || 'Wajib').trim().toLowerCase()}:::${(m.tingkat || 'Semua').trim().toLowerCase()}:::${(m.rombel_id || '')}`;
            if (seen.has(key)) return false;
            seen.add(key);
            return true;
        });
    };

    const uniqueFiltered = deduplicateMapels(filtered);
    const uniqueConfigList = deduplicateMapels(configList);

    res.json({
        success: true,
        data: targetTingkat ? uniqueFiltered : (uniqueFiltered.length > 0 ? uniqueFiltered : uniqueConfigList),
        all_data: uniqueConfigList,
        meta: {
            tingkat: targetTingkat,
            bentuk_pendidikan: normBentuk,
            kurikulum: normKurikulum,
            rombel_id
        }
    });
}));

// 2. Tambah Mapel Kustom
app.post(["/api/asts/mapel", "/api/ref_mata_pelajaran", "/api/mapel-global"], authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    await ensureAstsTables(pool);
    const { kode_mapel, nama_mapel, kelompok, bentuk_pendidikan, kurikulum, tingkat, rombel_id, kkm, urutan, status_aktif } = req.body;
    if (!nama_mapel || !nama_mapel.trim()) {
        return res.status(400).json({ error: "Nama mata pelajaran wajib diisi." });
    }

    const [result]: any = await pool.query(
        "INSERT INTO ref_mata_pelajaran (kode_mapel, nama_mapel, kelompok, bentuk_pendidikan, kurikulum, tingkat, rombel_id, kkm, urutan, status_aktif) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
        [
            kode_mapel || null,
            nama_mapel.trim(),
            kelompok || 'Wajib',
            bentuk_pendidikan || 'Semua',
            kurikulum || 'Kurikulum Merdeka',
            tingkat || 'Semua',
            rombel_id || null,
            kkm ? parseFloat(kkm) : 75.00,
            urutan ? parseInt(urutan) : 0,
            status_aktif !== undefined ? (status_aktif ? 1 : 0) : 1
        ]
    );

    res.json({ success: true, message: "Mata pelajaran berhasil ditambahkan!", id: result.insertId });
}));

// 3. Update Mapel
app.put(["/api/asts/mapel/:id", "/api/ref_mata_pelajaran/:id", "/api/mapel-global/:id"], authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    await ensureAstsTables(pool);
    const { id } = req.params;
    const { kode_mapel, nama_mapel, kelompok, bentuk_pendidikan, kurikulum, tingkat, rombel_id, kkm, urutan, status_aktif } = req.body;

    if (!nama_mapel || !nama_mapel.trim()) {
        return res.status(400).json({ error: "Nama mata pelajaran wajib diisi." });
    }

    // Ambil info mapel sebelum di-update untuk sinkronisasi nama lama ke nama baru di nilai_asts
    const [oldRow]: any = await pool.query("SELECT nama_mapel FROM ref_mata_pelajaran WHERE id = ? LIMIT 1", [id]).catch(() => [[]]);
    const oldNamaMapel = oldRow?.[0]?.nama_mapel;

    await pool.query(
        "UPDATE ref_mata_pelajaran SET kode_mapel = ?, nama_mapel = ?, kelompok = ?, bentuk_pendidikan = ?, kurikulum = ?, tingkat = ?, rombel_id = ?, kkm = ?, urutan = ?, status_aktif = ? WHERE id = ?",
        [
            kode_mapel || null,
            nama_mapel.trim(),
            kelompok || 'Wajib',
            bentuk_pendidikan || 'Semua',
            kurikulum || 'Kurikulum Merdeka',
            tingkat || 'Semua',
            rombel_id || null,
            kkm ? parseFloat(kkm) : 75.00,
            urutan ? parseInt(urutan) : 0,
            status_aktif !== undefined ? (status_aktif ? 1 : 0) : 1,
            id
        ]
    );

    // Sinkronkan nama_mapel & kkm di tabel nilai_asts yang memiliki mapel_id ini atau nama_mapel lama
    if (id) {
        const kkmFloat = kkm !== undefined && kkm !== null && !isNaN(parseFloat(kkm)) ? parseFloat(kkm) : 75.00;
        await pool.query("UPDATE nilai_asts SET nama_mapel = ?, mapel_id = ?, kkm = ? WHERE mapel_id = ?", [nama_mapel.trim(), id, kkmFloat, id]).catch(() => {});
        if (oldNamaMapel && oldNamaMapel.trim().toLowerCase() !== nama_mapel.trim().toLowerCase()) {
            await pool.query("UPDATE nilai_asts SET nama_mapel = ?, mapel_id = ?, kkm = ? WHERE (mapel_id IS NULL OR mapel_id = ?) AND TRIM(LOWER(nama_mapel)) = TRIM(LOWER(?))", [nama_mapel.trim(), id, kkmFloat, id, oldNamaMapel.trim()]).catch(() => {});
        }
    }

    res.json({ success: true, message: "Mata pelajaran berhasil diperbarui!" });
}));

