app.post(["/api/asts/mapel/reorder", "/api/ref_mata_pelajaran/reorder", "/api/mapel-global/reorder"], authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    await ensureAstsTables(pool);
    const { orders } = req.body; // array of { id, urutan } or array of ids

    if (Array.isArray(orders)) {
        for (let i = 0; i < orders.length; i++) {
            const item = orders[i];
            const id = typeof item === 'object' ? item.id : item;
            const urutan = typeof item === 'object' && item.urutan !== undefined ? parseInt(item.urutan) : (i + 1);
            if (id) {
                await pool.query("UPDATE ref_mata_pelajaran SET urutan = ? WHERE id = ?", [urutan, id]);
            }
        }
    }

    res.json({ success: true, message: "Urutan mata pelajaran berhasil diperbarui!" });
}));

