                    [String(g.peserta_didik_id).trim(), String(canonicalRombelId).trim(), itemMapelId, targetMapel, semId, thnAjar, val, predikatVal, currentKkm, statusTuntas, catatan, guruId, guruNama, pengisiNama, pengisiId]
