// 7.1 Ambil Nilai ASTS Lengkap untuk 1 Siswa (Semua Mapel)
app.get("/api/asts/nilai-by-student", authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    await ensureAstsTables(pool);
    const { peserta_didik_id, rombongan_belajar_id, semester_id, tahun_ajaran } = req.query;

    if (!peserta_didik_id || !rombongan_belajar_id) {
        return res.status(400).json({ error: "Siswa dan Rombel wajib dipilih." });
    }

    const semId = semester_id ? String(semester_id).trim() : '1';
    const thnAjar = tahun_ajaran ? String(tahun_ajaran).trim() : '2024/2025';

    // 1. Info Siswa
    const [students]: any = await pool.query(`
        SELECT 
            pd.peserta_didik_id,
            pd.nama,
            COALESCE(pd.nisn, '') as nisn,
            COALESCE(NULLIF(rpd.nipd, ''), NULLIF(pd.nipd, ''), '') as nipd,
            COALESCE(pd.jenis_kelamin, 'L') as jenis_kelamin,
            COALESCE(pd.foto_profil, '') as foto_profil
        FROM peserta_didik pd
        LEFT JOIN (
            SELECT 
                peserta_didik_id, 
                MAX(nipd) as nipd
            FROM registrasi_peserta_didik
            WHERE (soft_delete = 0 OR soft_delete IS NULL OR soft_delete = '0')
              AND (jenis_keluar_id IS NULL OR jenis_keluar_id = '' OR jenis_keluar_id = '0' OR jenis_keluar_id = 0)
            GROUP BY peserta_didik_id
        ) rpd ON rpd.peserta_didik_id = pd.peserta_didik_id
        WHERE pd.peserta_didik_id = ?
        LIMIT 1
    `, [peserta_didik_id]);

    if (students.length === 0) {
        return res.status(404).json({ error: "Data siswa tidak ditemukan." });
    }

    // 2. Info Tingkat Rombel & Site Settings
    const [rombelRows]: any = await pool.query(`
        SELECT tingkat, tingkat_pendidikan_id, nama 
        FROM rombongan_belajar 
        WHERE rombongan_belajar_id = ? OR id = ?
        LIMIT 1
    `, [rombongan_belajar_id, rombongan_belajar_id]);
    const rombelTingkat = rombelRows[0]?.tingkat || rombelRows[0]?.tingkat_pendidikan_id || 'Semua';

    let siteSettings: any = {};
    try {
        const [sRows]: any = await pool.query("SELECT * FROM pengaturan_sekolah WHERE id = 1 LIMIT 1");
        siteSettings = sRows[0] || {};
    } catch (e) {
        try {
            const [sRows]: any = await pool.query("SELECT * FROM pengaturan_sekolah LIMIT 1");
            siteSettings = sRows[0] || {};
        } catch (e2) {}
    }

    let targetBentuk = String(siteSettings.bentuk_pendidikan_str || siteSettings.bentuk_pendidikan || siteSettings.bentuk_pendidikan_id || '').trim();
    let targetKurikulum = String(siteSettings.kurikulum || 'Kurikulum Merdeka').trim();

    let normBentuk = targetBentuk;
    const tbLower = targetBentuk.toLowerCase();
    if (tbLower === '4' || tbLower === '7' || tbLower.includes('sd') || tbLower.includes('mi') || tbLower.includes('paket a')) normBentuk = 'SD';
    else if (tbLower === '5' || tbLower === '8' || tbLower.includes('smp') || tbLower.includes('mts') || tbLower.includes('paket b')) normBentuk = 'SMP';
    else if (tbLower === '6' || tbLower === '9' || tbLower === '13' || tbLower.includes('sma') || tbLower.includes('ma') || tbLower.includes('paket c')) normBentuk = 'SMA';
    else if (tbLower === '15' || tbLower.includes('smk')) normBentuk = 'SMK';

    let normKurikulum = targetKurikulum.toLowerCase().includes('2013') || targetKurikulum.toLowerCase().includes('k13') ? 'Kurikulum 2013' : 'Kurikulum Merdeka';

    // 3. Daftar Mata Pelajaran yang Relevan (Filtered by Bentuk & Kurikulum & Tingkat)
    let rawMapels: any[] = [];
    try {
        const [r]: any = await pool.query(`
            SELECT * FROM ref_mata_pelajaran 
            WHERE status_aktif = 1 
            ORDER BY urutan ASC, nama_mapel ASC
        `);
        rawMapels = r || [];
    } catch (tblErr: any) {
        await seedMataPelajaranDefault(pool, true);
        const [r]: any = await pool.query(`
            SELECT * FROM ref_mata_pelajaran 
            WHERE status_aktif = 1 
            ORDER BY urutan ASC, nama_mapel ASC
        `);
        rawMapels = r || [];
    }

    if (rawMapels.length === 0) {
        await seedMataPelajaranDefault(pool, true);
        const [r]: any = await pool.query(`
            SELECT * FROM ref_mata_pelajaran 
            WHERE status_aktif = 1 
            ORDER BY urutan ASC, nama_mapel ASC
        `);
        rawMapels = r || [];
    }

    const mapels = (rawMapels || []).filter((m: any) => {
        if (m.rombel_id && String(m.rombel_id) === String(rombongan_belajar_id)) return true;
        if (m.rombel_id && String(m.rombel_id) !== String(rombongan_belajar_id)) return false;

        if (m.bentuk_pendidikan && m.bentuk_pendidikan !== 'Semua' && normBentuk) {
            if (m.bentuk_pendidikan.toUpperCase() !== normBentuk.toUpperCase() && !normBentuk.toUpperCase().includes(m.bentuk_pendidikan.toUpperCase())) {
                return false;
            }
        }
        if (m.kurikulum && m.kurikulum !== 'Semua' && normKurikulum) {
            if (m.kurikulum.toUpperCase() !== normKurikulum.toUpperCase()) {
                return false;
            }
        }
        if (rombelTingkat && !isAstsLevelMatching(m.tingkat, String(rombelTingkat))) {
            return false;
        }
        return true;
    });

    // 4. Nilai ASTS Siswa Ini
    const [existingGrades]: any = await pool.query(`
        SELECT * FROM nilai_asts
        WHERE (peserta_didik_id = ? OR peserta_didik_id = ?) 
          AND (rombongan_belajar_id = ? OR rombongan_belajar_id = ?) 
          AND (
              semester_id = ? 
              OR semester_id = ? 
              OR semester_id LIKE CONCAT('%', ?) 
              OR ? LIKE CONCAT('%', semester_id)
          )
          AND (
              tahun_ajaran = ? 
              OR tahun_ajaran LIKE CONCAT('%', ?) 
              OR ? LIKE CONCAT('%', tahun_ajaran)
          )
    `, [
        peserta_didik_id, 
        students[0].peserta_didik_id, 
        rombongan_belajar_id, 
        rombelRows[0]?.rombongan_belajar_id || rombongan_belajar_id, 
        semId, 
        semId.slice(-1), 
        semId.slice(-1),
        semId,
        thnAjar,
        thnAjar.slice(0, 4),
        thnAjar
    ]);

    const gradeMap = new Map<string, any>();
    existingGrades.forEach((g: any) => {
        if (g.nama_mapel) {
            gradeMap.set(g.nama_mapel.trim().toLowerCase(), g);
            if (g.mapel_id) gradeMap.set(`id_${g.mapel_id}`, g);
        }
    });

    const combinedMapels = mapels.map((m: any) => {
        const cleanName = (m.nama_mapel || '').trim().toLowerCase();
        const grade = (m.id ? gradeMap.get(`id_${m.id}`) : null) || gradeMap.get(cleanName);
        return {
            mapel_id: m.id,
            kode_mapel: m.kode_mapel,
            nama_mapel: m.nama_mapel,
            kelompok: m.kelompok || 'Wajib',
            kkm: grade ? parseFloat(grade.kkm) : (m.kkm || 75.00),
            nilai: grade && grade.nilai !== null && grade.nilai !== undefined ? parseFloat(grade.nilai) : null,
            status_tuntas: grade ? grade.status_tuntas : null,
            catatan: grade ? (grade.catatan || '') : '',
            last_update: grade ? grade.updated_at : null
        };
    });

    res.json({
        success: true,
        student: students[0],
        rombel: rombelRows[0] || {},
        mapels: combinedMapels
    });
}));

// 7.2 Simpan Batch Nilai ASTS untuk 1 Siswa (Semua Mapel Siswa Tersebut)
app.post("/api/asts/nilai-by-student/batch", authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    await ensureAstsTables(pool);
    const { peserta_didik_id, rombongan_belajar_id, semester_id, tahun_ajaran, grades } = req.body;

    if (!peserta_didik_id || !rombongan_belajar_id || !grades || !Array.isArray(grades)) {
        return res.status(400).json({ error: "Data input nilai per siswa tidak lengkap." });
    }

    const semId = semester_id ? String(semester_id).trim() : '1';
    const thnAjar = tahun_ajaran ? String(tahun_ajaran).trim() : '2024/2025';

    // Resolve Wali Kelas / Guru of the Rombel
    const [rbWali]: any = await pool.query(
        `SELECT rb.ptk_id, rb.wali_kelas_id, ptk.nama as nama_wali_kelas, ptk.nip as nip_wali_kelas 
         FROM rombongan_belajar rb 
         LEFT JOIN ptk ON (rb.wali_kelas_id = ptk.ptk_id OR rb.ptk_id = ptk.ptk_id)
         WHERE rb.rombongan_belajar_id = ? OR rb.id = ? 
         LIMIT 1`,
        [rombongan_belajar_id, rombongan_belajar_id]
    ).catch(() => [[]]);

    const waliNama = rbWali?.[0]?.nama_wali_kelas || null;
    const waliId = rbWali?.[0]?.wali_kelas_id || rbWali?.[0]?.ptk_id || null;

    // Identify user who inputs the score
    const pengisiNama = req.user?.nama_lengkap || req.user?.nama || req.user?.username || 'Super Administrator';
    const pengisiId = req.user?.id || null;

    const guruNama = waliNama || req.user?.nama_lengkap || req.user?.nama || 'Guru Kelas';
    const guruId = waliId || req.user?.staff_id || req.user?.ptk_id || null;

    // Build mapel_id cache
    const [allRefMapels]: any = await pool.query("SELECT id, nama_mapel FROM ref_mata_pelajaran").catch(() => [[]]);
    const mapelIdMap = new Map<string, number>();
    (allRefMapels || []).forEach((m: any) => {
        if (m.nama_mapel) mapelIdMap.set(m.nama_mapel.trim().toLowerCase(), m.id);
    });

    let savedCount = 0;

    for (const g of grades) {
        if (!g.nama_mapel) continue;
        const targetMapel = String(g.nama_mapel).trim();
        const val = g.nilai !== null && g.nilai !== undefined && g.nilai !== '' ? Math.min(100, Math.max(0, parseFloat(g.nilai))) : null;
        if (val === null || isNaN(val)) {
            await pool.query(
                `DELETE FROM nilai_asts 
                 WHERE (peserta_didik_id = ? OR peserta_didik_id = ?) 
                   AND (rombongan_belajar_id = ? OR rombongan_belajar_id = ?) 
                   AND (nama_mapel = ? OR TRIM(LOWER(nama_mapel)) = TRIM(LOWER(?))) 
                   AND (semester_id = ? OR semester_id = ? OR semester_id LIKE CONCAT('%', ?)) 
                   AND (tahun_ajaran = ? OR REPLACE(REPLACE(tahun_ajaran, ' ', ''), '-', '/') = REPLACE(REPLACE(?, ' ', ''), '-', '/'))`,
                [
                    String(peserta_didik_id).trim(), String(peserta_didik_id).trim(),
                    String(rombongan_belajar_id).trim(), String(rombongan_belajar_id).trim(),
                    targetMapel, targetMapel, 
                    semId, semId.slice(-1), semId.slice(-1), 
                    thnAjar, thnAjar
                ]
            ).catch(() => {});
            savedCount++;
            continue;
        }

        const currentKkm = g.kkm ? parseFloat(g.kkm) : 75.00;
        const predikatVal = convertAstsScoreToPredikat(val, currentKkm);
        const statusTuntas = (predikatVal && ['A', 'B', 'C'].includes(predikatVal)) || (val !== null && val >= currentKkm) ? 'Tuntas' : 'Belum Tuntas';
        const catatan = g.catatan ? String(g.catatan).trim() : null;
        const itemMapelId = g.mapel_id || mapelIdMap.get(targetMapel.toLowerCase()) || null;

        try {
            await pool.query(`
                INSERT INTO nilai_asts (
                    peserta_didik_id, rombongan_belajar_id, mapel_id, nama_mapel, semester_id, tahun_ajaran, nilai, predikat, kkm, status_tuntas, catatan, guru_id, guru_nama, pengisi_nilai, created_by
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                ON DUPLICATE KEY UPDATE 
                    mapel_id = VALUES(mapel_id),
                    nilai = VALUES(nilai),
                    predikat = VALUES(predikat),
                    kkm = VALUES(kkm),
                    status_tuntas = VALUES(status_tuntas),
                    catatan = VALUES(catatan),
                    guru_id = VALUES(guru_id),
                    guru_nama = VALUES(guru_nama),
                    pengisi_nilai = VALUES(pengisi_nilai),
                    created_by = VALUES(created_by),
                    updated_at = NOW()
            `, [
                String(peserta_didik_id).trim(), String(rombongan_belajar_id).trim(), itemMapelId, targetMapel, semId, thnAjar, val, predikatVal, currentKkm, statusTuntas, catatan, guruId, guruNama, pengisiNama, pengisiId
            ]);
            savedCount++;
        } catch (insertErr: any) {
            console.warn("[ASTS] Upsert fallback for single student:", peserta_didik_id, insertErr.message);
            const [exist]: any = await pool.query(
                "SELECT id FROM nilai_asts WHERE peserta_didik_id = ? AND rombongan_belajar_id = ? AND nama_mapel = ? AND (semester_id = ? OR semester_id LIKE CONCAT('%', ?)) LIMIT 1",
                [String(peserta_didik_id).trim(), String(rombongan_belajar_id).trim(), targetMapel, semId, semId.slice(-1)]
            );
            if (exist && exist.length > 0) {
                await pool.query(
                    "UPDATE nilai_asts SET mapel_id = ?, nilai = ?, predikat = ?, kkm = ?, status_tuntas = ?, catatan = ?, guru_id = ?, guru_nama = ?, pengisi_nilai = ?, updated_at = NOW() WHERE id = ?",
                    [itemMapelId, val, predikatVal, currentKkm, statusTuntas, catatan, guruId, guruNama, pengisiNama, exist[0].id]
                );
            } else {
                await pool.query(
                    "INSERT INTO nilai_asts (peserta_didik_id, rombongan_belajar_id, mapel_id, nama_mapel, semester_id, tahun_ajaran, nilai, predikat, kkm, status_tuntas, catatan, guru_id, guru_nama, pengisi_nilai, created_by) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    [String(peserta_didik_id).trim(), String(rombongan_belajar_id).trim(), itemMapelId, targetMapel, semId, thnAjar, val, predikatVal, currentKkm, statusTuntas, catatan, guruId, guruNama, pengisiNama, pengisiId]
                );
            }
            savedCount++;
        }
    }

    await pool.query("UPDATE peserta_didik SET last_update = NOW() WHERE peserta_didik_id = ?", [peserta_didik_id]).catch(() => {});

    res.json({ success: true, message: `Nilai ASTS siswa (${savedCount} mapel) berhasil disimpan!`, saved_count: savedCount });
}));

// 7.3 Simpan Batch Matriks Semua Nilai (Banyak Siswa x Banyak Mapel Sekaligus)
app.post("/api/asts/matrix/batch", authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    await ensureAstsTables(pool);
    const { rombongan_belajar_id, semester_id, tahun_ajaran, matrix } = req.body;

    if (!rombongan_belajar_id || !matrix || !Array.isArray(matrix)) {
        return res.status(400).json({ error: "Data matriks nilai tidak lengkap." });
    }

    const semId = semester_id ? String(semester_id).trim() : '1';
    const thnAjar = tahun_ajaran ? String(tahun_ajaran).trim() : '2024/2025';

    // Canonicalize rombongan_belajar_id (support UUID, ID, or Rombel Name)
    let canonicalRombelId = String(rombongan_belajar_id).trim();
    const [rbCheck]: any = await pool.query(
        "SELECT rombongan_belajar_id FROM rombongan_belajar WHERE rombongan_belajar_id = ? OR id = ? OR nama = ? LIMIT 1",
        [canonicalRombelId, canonicalRombelId, canonicalRombelId]
    ).catch(() => [[]]);
    if (rbCheck && rbCheck.length > 0 && rbCheck[0].rombongan_belajar_id) {
        canonicalRombelId = rbCheck[0].rombongan_belajar_id;
    }

    // Resolve Wali Kelas / Guru of the Rombel
    const [rbWali]: any = await pool.query(
        `SELECT rb.ptk_id, rb.wali_kelas_id, ptk.nama as nama_wali_kelas, ptk.nip as nip_wali_kelas 
         FROM rombongan_belajar rb 
         LEFT JOIN ptk ON (rb.wali_kelas_id = ptk.ptk_id OR rb.ptk_id = ptk.ptk_id)
         WHERE rb.rombongan_belajar_id = ? OR rb.id = ? 
         LIMIT 1`,
        [canonicalRombelId, canonicalRombelId]
    ).catch(() => [[]]);

    const waliNama = rbWali?.[0]?.nama_wali_kelas || null;
    const waliId = rbWali?.[0]?.wali_kelas_id || rbWali?.[0]?.ptk_id || null;

    // Identify user who inputs the score
    const pengisiNama = req.user?.nama_lengkap || req.user?.nama || req.user?.username || 'Super Administrator';
    const pengisiId = req.user?.id || null;

    const guruNama = waliNama || req.user?.nama_lengkap || req.user?.nama || 'Guru Kelas';
    const guruId = waliId || req.user?.staff_id || req.user?.ptk_id || null;

    // Build mapel_id cache and kelompok cache
    const [allRefMapels]: any = await pool.query("SELECT id, nama_mapel, kelompok FROM ref_mata_pelajaran").catch(() => [[]]);
    const mapelIdMap = new Map<string, number>();
    const mapelKelompokMap = new Map<string, string>();
    (allRefMapels || []).forEach((m: any) => {
        if (m.nama_mapel) {
            const clean = m.nama_mapel.trim().toLowerCase();
            mapelIdMap.set(clean, m.id);
            mapelKelompokMap.set(clean, m.kelompok || 'Wajib');
        }
    });

    const affectedStudentIds = new Set<string>();
    let savedCount = 0;

    for (const item of matrix) {
        if (!item.peserta_didik_id || !item.nama_mapel) continue;
        const targetMapel = String(item.nama_mapel).trim();
        const mapelKelompok = mapelKelompokMap.get(targetMapel.toLowerCase()) || 'Wajib';
        const isEkskul = isAstsEkskulMapel(targetMapel, mapelKelompok);

        const rawVal = item.nilai !== null && item.nilai !== undefined ? String(item.nilai).trim().toUpperCase() : '';
        const rawPredikat = item.predikat !== null && item.predikat !== undefined ? String(item.predikat).trim().toUpperCase() : '';
        
        const currentKkm = item.kkm ? parseFloat(item.kkm) : 75.00;
        let predikatVal: string | null = null;
        let val: number | null = null;

        if (isEkskul) {
            if (['A', 'B', 'C', 'D', 'E'].includes(rawVal)) {
                predikatVal = rawVal;
            } else if (['A', 'B', 'C', 'D', 'E'].includes(rawPredikat)) {
                predikatVal = rawPredikat;
            } else if (rawVal !== '' && !isNaN(parseFloat(rawVal))) {
                predikatVal = convertAstsScoreToPredikat(rawVal, currentKkm);
            }
        } else {
            if (rawVal !== '' && !isNaN(parseFloat(rawVal))) {
                val = Math.min(100, Math.max(0, Math.round(parseFloat(rawVal))));
                predikatVal = convertAstsScoreToPredikat(val, currentKkm);
            } else if (['A', 'B', 'C', 'D', 'E'].includes(rawPredikat)) {
                predikatVal = rawPredikat;
            } else if (['A', 'B', 'C', 'D', 'E'].includes(rawVal)) {
                predikatVal = rawVal;
            }
        }

        if (val === null && !predikatVal) {
            // Nilai dikosongkan/direset -> Hapus record nilai yang lama dari database agar benar-benar kosong!
            await pool.query(
                `DELETE FROM nilai_asts 
                 WHERE (peserta_didik_id = ? OR peserta_didik_id = ?) 
                   AND (rombongan_belajar_id = ? OR rombongan_belajar_id = ?) 
                   AND (nama_mapel = ? OR TRIM(LOWER(nama_mapel)) = TRIM(LOWER(?))) 
                   AND (semester_id = ? OR semester_id = ? OR semester_id LIKE CONCAT('%', ?)) 
                   AND (tahun_ajaran = ? OR REPLACE(REPLACE(tahun_ajaran, ' ', ''), '-', '/') = REPLACE(REPLACE(?, ' ', ''), '-', '/'))`,
                [
                    String(item.peserta_didik_id).trim(), String(item.peserta_didik_id).trim(),
                    String(canonicalRombelId).trim(), String(canonicalRombelId).trim(),
                    targetMapel, targetMapel, 
                    semId, semId.slice(-1), semId.slice(-1), 
                    thnAjar, thnAjar
                ]
            ).catch(() => {});
            savedCount++;
            affectedStudentIds.add(String(item.peserta_didik_id));
            continue;
        }

        const statusTuntas = (predikatVal && ['A', 'B', 'C'].includes(predikatVal)) || (val !== null && val >= currentKkm) ? 'Tuntas' : 'Belum Tuntas';
        const catatan = isEkskul ? null : (item.catatan ? String(item.catatan).trim() : null);
        const itemMapelId = item.mapel_id || mapelIdMap.get(targetMapel.toLowerCase()) || null;

        try {
            await pool.query(`
                INSERT INTO nilai_asts (
                    peserta_didik_id, rombongan_belajar_id, mapel_id, nama_mapel, semester_id, tahun_ajaran, nilai, predikat, kkm, status_tuntas, catatan, guru_id, guru_nama, pengisi_nilai, created_by
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                ON DUPLICATE KEY UPDATE 
                    mapel_id = VALUES(mapel_id),
                    nilai = VALUES(nilai),
                    predikat = VALUES(predikat),
                    kkm = VALUES(kkm),
                    status_tuntas = VALUES(status_tuntas),
                    catatan = VALUES(catatan),
                    guru_id = VALUES(guru_id),
                    guru_nama = VALUES(guru_nama),
                    pengisi_nilai = VALUES(pengisi_nilai),
                    created_by = VALUES(created_by),
                    updated_at = NOW()
            `, [
                String(item.peserta_didik_id).trim(), String(canonicalRombelId).trim(), itemMapelId, targetMapel, semId, thnAjar, val, predikatVal, currentKkm, statusTuntas, catatan, guruId, guruNama, pengisiNama, pengisiId
            ]);
            savedCount++;
        } catch (insertErr: any) {
            console.warn("[ASTS] Upsert fallback for matrix item:", item.peserta_didik_id, insertErr.message);
            const [exist]: any = await pool.query(
                "SELECT id FROM nilai_asts WHERE peserta_didik_id = ? AND rombongan_belajar_id = ? AND nama_mapel = ? AND (semester_id = ? OR semester_id LIKE CONCAT('%', ?)) LIMIT 1",
                [String(item.peserta_didik_id).trim(), String(canonicalRombelId).trim(), targetMapel, semId, semId.slice(-1)]
            );
            if (exist && exist.length > 0) {
                await pool.query(
                    "UPDATE nilai_asts SET mapel_id = ?, nilai = ?, predikat = ?, kkm = ?, status_tuntas = ?, catatan = ?, guru_id = ?, guru_nama = ?, pengisi_nilai = ?, updated_at = NOW() WHERE id = ?",
                    [itemMapelId, val, predikatVal, currentKkm, statusTuntas, catatan, guruId, guruNama, pengisiNama, exist[0].id]
                );
            } else {
                await pool.query(
                    "INSERT INTO nilai_asts (peserta_didik_id, rombongan_belajar_id, mapel_id, nama_mapel, semester_id, tahun_ajaran, nilai, predikat, kkm, status_tuntas, catatan, guru_id, guru_nama, pengisi_nilai, created_by) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    [String(item.peserta_didik_id).trim(), String(canonicalRombelId).trim(), itemMapelId, targetMapel, semId, thnAjar, val, predikatVal, currentKkm, statusTuntas, catatan, guruId, guruNama, pengisiNama, pengisiId]
                );
            }
            savedCount++;
        }

        affectedStudentIds.add(item.peserta_didik_id);
    }

    for (const sId of affectedStudentIds) {
        await pool.query("UPDATE peserta_didik SET last_update = NOW() WHERE peserta_didik_id = ?", [sId]).catch(() => {});
    }

    res.json({ success: true, message: `Matriks nilai ASTS (${savedCount} entri) berhasil disimpan!`, saved_count: savedCount });
}));

// 7.4 Ambil Penilaian Sikap Spiritual & Sosial Rombel
app.get("/api/asts/sikap", authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    await ensureAstsTables(pool);
    const { rombongan_belajar_id, nama_rombel, semester_id, tahun_ajaran } = req.query;

    if (!rombongan_belajar_id && !nama_rombel) {
        return res.status(400).json({ error: "Rombongan belajar wajib dipilih." });
    }

    const semId = semester_id ? String(semester_id).trim() : '1';
    const semShort = semId.length > 1 ? semId.slice(-1) : semId;
    const thnAjar = tahun_ajaran ? String(tahun_ajaran).trim() : '2024/2025';

    const targetRombelStr = String(rombongan_belajar_id || nama_rombel || '').trim();
    const extraRombelName = nama_rombel ? String(nama_rombel).trim() : '';
    const { idList, nameList } = await resolveRombelCandidates(pool, targetRombelStr, extraRombelName, semId, thnAjar);
    const idPlaceholders = idList.map(() => '?').join(',') || "''";

    const [students]: any = await pool.query(`
        SELECT DISTINCT
            COALESCE(pd.peserta_didik_id, pd.id) as peserta_didik_id,
            COALESCE(pd.nama, pd.nama_lengkap) as nama,
            COALESCE(pd.nisn, '') as nisn,
            COALESCE(NULLIF(rpd.nipd, ''), NULLIF(pd.nipd, ''), '') as nipd,
            COALESCE(pd.jenis_kelamin, 'L') as jenis_kelamin,
            COALESCE(pd.foto_profil, '') as foto_profil,
            nas.id as sikap_id,
            nas.predikat_spiritual,
            nas.aspek_spiritual,
            nas.deskripsi_spiritual,
            nas.predikat_sosial,
            nas.aspek_sosial,
            nas.deskripsi_sosial,
            nas.guru_id,
            nas.guru_nama,
            nas.updated_at as last_update
        FROM anggota_rombel ar
        JOIN peserta_didik pd ON (ar.peserta_didik_id = pd.peserta_didik_id OR ar.peserta_didik_id = pd.id)
        LEFT JOIN (
            SELECT 
                peserta_didik_id, 
                MAX(nipd) as nipd
            FROM registrasi_peserta_didik
            WHERE (jenis_keluar_id IS NULL OR jenis_keluar_id = '' OR jenis_keluar_id = '0' OR jenis_keluar_id = 0)
            GROUP BY peserta_didik_id
        ) rpd ON (rpd.peserta_didik_id = pd.peserta_didik_id OR rpd.peserta_didik_id = pd.id)
        LEFT JOIN nilai_asts_sikap nas ON (
            (nas.peserta_didik_id = pd.peserta_didik_id OR nas.peserta_didik_id = pd.id)
            AND (nas.rombongan_belajar_id IN (${idPlaceholders}))
            AND (
                nas.semester_id = ? 
                OR nas.semester_id = ? 
                OR nas.semester_id LIKE CONCAT('%', ?)
                OR ? LIKE CONCAT('%', nas.semester_id)
            )
            AND (
                nas.tahun_ajaran = ?
                OR REPLACE(REPLACE(nas.tahun_ajaran, ' ', ''), '-', '/') = REPLACE(REPLACE(?, ' ', ''), '-', '/')
                OR nas.tahun_ajaran LIKE CONCAT('%', ?, '%')
                OR ? LIKE CONCAT('%', nas.tahun_ajaran, '%')
            )
        )
        WHERE ar.rombongan_belajar_id IN (${idPlaceholders})
          AND (ar.soft_delete = 0 OR ar.soft_delete IS NULL OR ar.soft_delete = '0' OR ar.soft_delete = '')
          AND (pd.soft_delete = 0 OR pd.soft_delete IS NULL OR pd.soft_delete = '0' OR pd.soft_delete = '')
        ORDER BY COALESCE(pd.nama, pd.nama_lengkap) ASC
    `, [
        ...idList,
        semId, semShort, semShort, semId,
        thnAjar, thnAjar, thnAjar, thnAjar,
        ...idList
    ]);

    // Deduplicate students by peserta_didik_id
    const studentMap = new Map<string, any>();
    for (const s of (students || [])) {
        const id = String(s.peserta_didik_id || '').trim();
        if (!id) continue;
        if (!studentMap.has(id)) {
            studentMap.set(id, s);
        } else {
            const existing = studentMap.get(id);
            const sHasSikap = s.predikat_spiritual || s.predikat_sosial;
            const existHasSikap = existing.predikat_spiritual || existing.predikat_sosial;
            if (sHasSikap && !existHasSikap) {
                studentMap.set(id, s);
            } else if (s.last_update && existing.last_update && new Date(s.last_update) > new Date(existing.last_update)) {
                studentMap.set(id, s);
            }
        }
    }
    const uniqueStudents = Array.from(studentMap.values()).sort((a: any, b: any) =>
        String(a.nama || a.nama_lengkap || '').trim().localeCompare(String(b.nama || b.nama_lengkap || '').trim(), 'id', { sensitivity: 'base' })
    );

    res.json({
        success: true,
        data: uniqueStudents,
        count: uniqueStudents.length,
        meta: {
            rombongan_belajar_id,
            semester_id: semId,
            tahun_ajaran: thnAjar
        }
    });
}));

