app.get("/api/asts/student/me", authenticate, asyncHandler(async (req: any, res: any) => {
    if (req.user.type !== 'student') return res.status(403).json({ error: "Access denied" });
    const pool = getPool();
    await ensureAstsTables(pool);
    const studentId = req.user.id || req.user.peserta_didik_id;
    const nisn = req.user.nisn || req.user.username;

    let pdId = studentId;
    if (!pdId || pdId === 'not-found') {
        const [pdRows]: any = await pool.query(
            "SELECT peserta_didik_id FROM peserta_didik WHERE nisn = ? OR nik = ? LIMIT 1",
            [nisn, nisn]
        );
        if (pdRows.length > 0) pdId = pdRows[0].peserta_didik_id;
    }

    if (!pdId) {
        return res.status(404).json({ error: "Data siswa tidak ditemukan." });
    }

    const [grades]: any = await pool.query(`
        SELECT 
            na.*,
            rb.nama as nama_rombel,
            rmp.kelompok
        FROM nilai_asts na
        LEFT JOIN rombongan_belajar rb ON (na.rombongan_belajar_id = rb.rombongan_belajar_id OR na.rombongan_belajar_id = rb.id)
        LEFT JOIN ref_mata_pelajaran rmp ON (
            na.mapel_id = rmp.id 
            OR LOWER(TRIM(na.nama_mapel)) = LOWER(TRIM(rmp.nama_mapel))
        )
        WHERE na.peserta_didik_id = ?
        ORDER BY na.tahun_ajaran DESC, na.semester_id DESC, na.nama_mapel ASC
    `, [pdId]);

    const [sikapRows]: any = await pool.query(`
        SELECT * FROM nilai_asts_sikap WHERE peserta_didik_id = ?
    `, [pdId]).catch(() => [[]]);

    const grouped: Record<string, any[]> = {};
    grades.forEach((g: any) => {
        const key = `${g.tahun_ajaran} - Semester ${g.semester_id === '1' ? 'Ganjil' : (g.semester_id === '2' ? 'Genap' : g.semester_id)}`;
        if (!grouped[key]) grouped[key] = [];
        grouped[key].push(g);
    });

    res.json({
        success: true,
        grades,
        sikap: sikapRows || [],
        grouped
    });
}));

