async function ensureTryoutTables(pool: any) {
    try {
        await pool.query(`
            CREATE TABLE IF NOT EXISTS tryout_kegiatan (
                id INT AUTO_INCREMENT PRIMARY KEY,
                nama_kegiatan VARCHAR(200) NOT NULL,
                tahun_ajaran VARCHAR(20) NOT NULL,
                semester_id VARCHAR(5) DEFAULT '2',
                tanggal_mulai DATE NULL,
                tanggal_selesai DATE NULL,
                keterangan TEXT NULL,
                is_active TINYINT(1) DEFAULT 1,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
        `);

        await pool.query(`
            CREATE TABLE IF NOT EXISTS tryout_sesi (
                id INT AUTO_INCREMENT PRIMARY KEY,
                kegiatan_id INT NULL,
                nama_sesi VARCHAR(150) NOT NULL,
                hari_ke INT DEFAULT 1,
                sesi_ke INT DEFAULT 1,
                tahun_ajaran VARCHAR(20) NOT NULL,
                semester_id VARCHAR(5) DEFAULT '2',
                tanggal_pelaksanaan DATE NULL,
                tanggal_rapor DATE NULL,
                keterangan TEXT NULL,
                is_active TINYINT(1) DEFAULT 1,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
        `);

        try {
            await pool.query("ALTER TABLE tryout_sesi ADD COLUMN kegiatan_id INT NULL;");
        } catch {}
        try {
            await pool.query("ALTER TABLE tryout_sesi ADD COLUMN hari_ke INT DEFAULT 1;");
        } catch {}
        try {
            await pool.query("ALTER TABLE tryout_sesi ADD COLUMN sesi_ke INT DEFAULT 1;");
        } catch {}
        try {
            await pool.query("ALTER TABLE tryout_sesi ADD COLUMN is_active TINYINT(1) DEFAULT 1;");
        } catch {}
        try {
            await pool.query("ALTER TABLE tryout_sesi ADD COLUMN tanggal_pelaksanaan DATE NULL;");
        } catch {}
        try {
            await pool.query("ALTER TABLE tryout_sesi ADD COLUMN tanggal_rapor DATE NULL;");
        } catch {}

        await pool.query(`
            CREATE TABLE IF NOT EXISTS tryout_mapel (
                id INT AUTO_INCREMENT PRIMARY KEY,
                sesi_id INT NULL,
                nama_mapel VARCHAR(150) NOT NULL,
                kode_mapel VARCHAR(50) DEFAULT NULL,
                kkm DECIMAL(5,2) DEFAULT 75.00,
                urutan INT DEFAULT 0,
                status_aktif TINYINT(1) DEFAULT 1,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
        `);

        try {
            await pool.query("ALTER TABLE tryout_mapel ADD COLUMN sesi_id INT NULL;");
        } catch {}
        try {
            await pool.query("CREATE INDEX idx_tryout_mapel_sesi ON tryout_mapel(sesi_id);");
        } catch {}

        await pool.query(`
            CREATE TABLE IF NOT EXISTS tryout_nilai (
                id INT AUTO_INCREMENT PRIMARY KEY,
                sesi_id INT NOT NULL,
                peserta_didik_id VARCHAR(64) NOT NULL,
                rombongan_belajar_id VARCHAR(64) NOT NULL,
                nama_rombel VARCHAR(100) NULL,
                mapel_id INT NOT NULL,
                nama_mapel VARCHAR(150) NOT NULL,
                kkm DECIMAL(5,2) DEFAULT 75.00,
                nilai DECIMAL(5,2) NULL,
                catatan_wali TEXT NULL,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                UNIQUE KEY uniq_tryout_entry (sesi_id, peserta_didik_id(36), mapel_id)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
        `);

        // Check if tryout_kegiatan is empty, seed initial kegiatan
        const [kegiatanRows]: any = await pool.query("SELECT COUNT(*) as total FROM tryout_kegiatan").catch(() => [[]]);
        const nowYear = new Date().getFullYear();
        const nowMonth = new Date().getMonth() + 1;
        const currentTa = nowMonth >= 7 ? `${nowYear}/${nowYear + 1}` : `${nowYear - 1}/${nowYear}`;

        if (!kegiatanRows || kegiatanRows.length === 0 || kegiatanRows[0].total === 0) {
            const [insKeg]: any = await pool.query(`
                INSERT INTO tryout_kegiatan (nama_kegiatan, tahun_ajaran, semester_id, keterangan, is_active)
                VALUES ('TRYOUT TKA (Tes Kemampuan Akademik)', ?, '2', 'Pelaksanaan Tryout TKA Multi-Hari & Multi-Sesi', 1)
            `, [currentTa]).catch(() => [{ insertId: 1 }]);
            const defaultKegId = insKeg?.insertId || 1;

            // Link existing sesi to default kegiatan
            await pool.query("UPDATE tryout_sesi SET kegiatan_id = ? WHERE kegiatan_id IS NULL", [defaultKegId]).catch(() => {});
        }

        // Check if tryout_sesi is empty, seed defaults
        const [sesiRows]: any = await pool.query("SELECT COUNT(*) as total FROM tryout_sesi").catch(() => [[]]);
        if (!sesiRows || sesiRows.length === 0 || sesiRows[0].total === 0) {
            const [kegs]: any = await pool.query("SELECT id FROM tryout_kegiatan LIMIT 1").catch(() => [[]]);
            const kegId = kegs?.[0]?.id || 1;

            const [s1]: any = await pool.query(`
                INSERT INTO tryout_sesi (kegiatan_id, nama_sesi, hari_ke, sesi_ke, tahun_ajaran, semester_id, keterangan, is_active)
                VALUES (?, 'Hari 1 - Sesi 1 (Matematika)', 1, 1, ?, '2', 'Pelaksanaan Hari Pertama Sesi 1', 1)
            `, [kegId, currentTa]);

            const [s2]: any = await pool.query(`
                INSERT INTO tryout_sesi (kegiatan_id, nama_sesi, hari_ke, sesi_ke, tahun_ajaran, semester_id, keterangan, is_active)
                VALUES (?, 'Hari 1 - Sesi 2 (Bahasa Indonesia)', 1, 2, ?, '2', 'Pelaksanaan Hari Pertama Sesi 2', 1)
            `, [kegId, currentTa]);

            const [s3]: any = await pool.query(`
                INSERT INTO tryout_sesi (kegiatan_id, nama_sesi, hari_ke, sesi_ke, tahun_ajaran, semester_id, keterangan, is_active)
                VALUES (?, 'Hari 2 - Sesi 1 (Matematika)', 2, 1, ?, '2', 'Pelaksanaan Hari Kedua Sesi 1', 1)
            `, [kegId, currentTa]);

            const [s4]: any = await pool.query(`
                INSERT INTO tryout_sesi (kegiatan_id, nama_sesi, hari_ke, sesi_ke, tahun_ajaran, semester_id, keterangan, is_active)
                VALUES (?, 'Hari 2 - Sesi 2 (Bahasa Indonesia)', 2, 2, ?, '2', 'Pelaksanaan Hari Kedua Sesi 2', 1)
            `, [kegId, currentTa]);

            // Seed specific mapels
            if (s1?.insertId) {
                await pool.query("INSERT INTO tryout_mapel (sesi_id, nama_mapel, kode_mapel, kkm, urutan) VALUES (?, 'Matematika', 'MAT', 70.00, 1)", [s1.insertId]).catch(() => {});
            }
            if (s2?.insertId) {
                await pool.query("INSERT INTO tryout_mapel (sesi_id, nama_mapel, kode_mapel, kkm, urutan) VALUES (?, 'Bahasa Indonesia', 'BIN', 75.00, 1)", [s2.insertId]).catch(() => {});
            }
            if (s3?.insertId) {
                await pool.query("INSERT INTO tryout_mapel (sesi_id, nama_mapel, kode_mapel, kkm, urutan) VALUES (?, 'Matematika', 'MAT', 70.00, 1)", [s3.insertId]).catch(() => {});
            }
            if (s4?.insertId) {
                await pool.query("INSERT INTO tryout_mapel (sesi_id, nama_mapel, kode_mapel, kkm, urutan) VALUES (?, 'Bahasa Indonesia', 'BIN', 75.00, 1)", [s4.insertId]).catch(() => {});
            }
        }
    } catch (e: any) {
        console.warn("[TRYOUT] ensureTryoutTables warning:", e.message);
    }
}

