// WIZARD PEMBUATAN KEGIATAN MULTI-SESI / MULTI-HARI BESERTA MAPEL OTOMATIS
app.post("/api/tryout/kegiatan/wizard", authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    await ensureTryoutTables(pool);
    const { nama_kegiatan, tahun_ajaran, semester_id, semester, tanggal_mulai, tanggal_selesai, keterangan, sesi_items, sessions } = req.body;

    const sessionList = (Array.isArray(sesi_items) && sesi_items.length > 0) ? sesi_items : ((Array.isArray(sessions) && sessions.length > 0) ? sessions : []);

    if (!nama_kegiatan || !nama_kegiatan.trim()) {
        return res.status(400).json({ error: "Nama judul kegiatan tryout wajib diisi." });
    }
    if (sessionList.length === 0) {
        return res.status(400).json({ error: "Minimal harus mengatur 1 sesi / hari tryout." });
    }

    const resolvedSemester = semester_id || (semester === 'Ganjil' ? '1' : '2');
    const cleanTglMulai = (tanggal_mulai && String(tanggal_mulai).trim()) ? String(tanggal_mulai).trim().split('T')[0] : null;
    const cleanTglSelesai = (tanggal_selesai && String(tanggal_selesai).trim()) ? String(tanggal_selesai).trim().split('T')[0] : null;

    // 1. Buat Kegiatan
    const [kegRes]: any = await pool.query(`
        INSERT INTO tryout_kegiatan (nama_kegiatan, tahun_ajaran, semester_id, tanggal_mulai, tanggal_selesai, keterangan, is_active)
        VALUES (?, ?, ?, ?, ?, ?, 1)
    `, [
        nama_kegiatan.trim(),
        tahun_ajaran || '2025/2026',
        resolvedSemester,
        cleanTglMulai,
        cleanTglSelesai,
        keterangan || null
    ]);
    const kegiatanId = kegRes.insertId;

    // 2. Buat Tiap Sesi & Mapelnya
    for (let i = 0; i < sessionList.length; i++) {
        const item = sessionList[i];
        const sName = item.nama_sesi || `Sesi ${i + 1}`;
        const sHari = item.hari_ke || Math.floor(i / 2) + 1;
        const sSesi = item.sesi_ke || (i % 2) + 1;
        const sTgl = (item.tanggal_pelaksanaan && String(item.tanggal_pelaksanaan).trim()) 
            ? String(item.tanggal_pelaksanaan).trim().split('T')[0] 
            : cleanTglMulai;

        const [sesiRes]: any = await pool.query(`
            INSERT INTO tryout_sesi (kegiatan_id, nama_sesi, hari_ke, sesi_ke, tahun_ajaran, semester_id, tanggal_pelaksanaan, is_active)
            VALUES (?, ?, ?, ?, ?, ?, ?, 1)
        `, [
            kegiatanId,
            sName.trim(),
            sHari,
            sSesi,
            tahun_ajaran || '2025/2026',
            resolvedSemester,
            sTgl
        ]);
        const sesiId = sesiRes.insertId;

        // Tambahkan mapel yang dipilih pada sesi ini
        const mapels = Array.isArray(item.mapels) ? item.mapels : [];
        for (let mIdx = 0; mIdx < mapels.length; mIdx++) {
            const m = mapels[mIdx];
            if (m.nama_mapel && m.nama_mapel.trim()) {
                await pool.query(`
                    INSERT INTO tryout_mapel (sesi_id, nama_mapel, kode_mapel, kkm, urutan, status_aktif)
                    VALUES (?, ?, ?, ?, ?, 1)
                `, [
                    sesiId,
                    m.nama_mapel.trim(),
                    m.kode_mapel ? m.kode_mapel.trim().toUpperCase() : null,
                    m.kkm ? parseFloat(m.kkm) : 75.00,
                    mIdx + 1
                ]);
            }
        }
    }

    res.json({ success: true, kegiatan_id: kegiatanId, message: `Kegiatan "${nama_kegiatan}" beserta ${sessionList.length} sesi berhasil dibuat!` });
}));

