app.post("/api/tryout/matrix/batch", authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    await ensureTryoutTables(pool);
    const { sesi_id, rombongan_belajar_id, nama_rombel, items } = req.body;

    if (!sesi_id || !items || !Array.isArray(items) || items.length === 0) {
        return res.status(400).json({ error: "Data nilai tryout tidak lengkap." });
    }

    // Check if session is active
    const [sesiRows]: any = await pool.query("SELECT is_active, nama_sesi FROM tryout_sesi WHERE id = ?", [sesi_id]);
    if (sesiRows && sesiRows.length > 0) {
        const sesi = sesiRows[0];
        if (sesi.is_active === 0 || sesi.is_active === false || sesi.is_active === '0') {
            return res.status(403).json({ error: `Sesi "${sesi.nama_sesi}" sedang dinonaktifkan / terkunci. Nilai tidak dapat disimpan atau diubah.` });
        }
    }

    const cleanItems = items.map((it: any) => {
        let valNum: number | null = null;
        if (it.nilai !== undefined && it.nilai !== null && it.nilai !== '') {
            const parsed = parseFloat(String(it.nilai).replace(',', '.'));
            if (!isNaN(parsed)) {
                valNum = Math.min(100, Math.max(0, parsed));
            }
        }
        return {
            sesi_id: parseInt(sesi_id),
            peserta_didik_id: String(it.peserta_didik_id).trim(),
            rombongan_belajar_id: String(rombongan_belajar_id || it.rombongan_belajar_id || '').trim(),
            nama_rombel: nama_rombel || it.nama_rombel || null,
            mapel_id: parseInt(it.mapel_id),
            nama_mapel: String(it.nama_mapel || '').trim(),
            kkm: it.kkm ? parseFloat(it.kkm) : 75.00,
            nilai: valNum,
            catatan_wali: it.catatan_wali || null
        };
    });

    for (const item of cleanItems) {
        await pool.query(`
            INSERT INTO tryout_nilai (
                sesi_id, peserta_didik_id, rombongan_belajar_id, nama_rombel, mapel_id, nama_mapel, kkm, nilai, catatan_wali
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON DUPLICATE KEY UPDATE
                nilai = VALUES(nilai),
                kkm = VALUES(kkm),
                nama_mapel = VALUES(nama_mapel),
                nama_rombel = VALUES(nama_rombel),
                catatan_wali = COALESCE(VALUES(catatan_wali), catatan_wali),
                updated_at = NOW()
        `, [
            item.sesi_id,
            item.peserta_didik_id,
            item.rombongan_belajar_id,
            item.nama_rombel,
            item.mapel_id,
            item.nama_mapel,
            item.kkm,
            item.nilai,
            item.catatan_wali
        ]);
    }

    res.json({ success: true, count: cleanItems.length });
}));

