app.get("/api/tryout/leger", authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    await ensureTryoutTables(pool);
    const { sesi_id, rombongan_belajar_id } = req.query;

    if (!sesi_id || !rombongan_belajar_id) {
        return res.status(400).json({ error: "Sesi tryout dan rombel wajib dipilih." });
    }

    // 1. Info Sesi Tryout
    const [sesiRows]: any = await pool.query("SELECT * FROM tryout_sesi WHERE id = ? LIMIT 1", [sesi_id]);
    const sesiInfo = sesiRows[0] || { nama_sesi: 'Tryout Ujian Sekolah', tahun_ajaran: '2026/2027' };
    if (!sesiInfo.tahun_ajaran) sesiInfo.tahun_ajaran = '2026/2027';

    // 2. Info Rombel & Wali Kelas
    // 2. Info Rombel & Wali Kelas
    const targetRombelStr = String(rombongan_belajar_id || req.query.nama_rombel || '').trim();
    const extraRombelName = req.query.nama_rombel ? String(req.query.nama_rombel).trim() : '';
    const { idList, nameList } = await resolveRombelCandidates(pool, targetRombelStr, extraRombelName);
    const idPlaceholders = idList.map(() => '?').join(',') || "''";

    const [rombelRows]: any = await pool.query(`
        SELECT 
            rb.rombongan_belajar_id,
            rb.nama as nama_rombel,
            rb.tingkat,
            rb.tingkat_pendidikan_id,
            rb.wali_kelas_id,
            ptk.nama as nama_wali_kelas,
            ptk.nip as nip_wali_kelas,
            ptk.gelar_depan,
            ptk.gelar_belakang
        FROM rombongan_belajar rb
        LEFT JOIN ptk ON (rb.wali_kelas_id = ptk.ptk_id OR rb.ptk_id = ptk.ptk_id)
        WHERE rb.rombongan_belajar_id IN (${idPlaceholders})
        LIMIT 1
    `, [...idList]);

    const rombelInfo = rombelRows[0] || { nama_rombel: extraRombelName || 'Kelas 6', tingkat: '6', rombongan_belajar_id: idList[0] || rombongan_belajar_id };

    // 3. Info Profil Sekolah & Kepsek
    const [schRows]: any = await pool.query("SELECT * FROM pengaturan_sekolah WHERE id = 1 LIMIT 1").catch(() => [[]]);
    const sekolahInfo = (schRows && schRows[0]) || {};
    try {
        const activeKepsek = await getActiveKepalaSekolah(pool, sekolahInfo);
        if (activeKepsek) {
            const kName = activeKepsek.nama || activeKepsek.nama_lengkap || '';
            const kNip = activeKepsek.nip || '';
            sekolahInfo.nama_kepsek = kName;
            sekolahInfo.headmaster_name = kName;
            sekolahInfo.nip_kepsek = kNip || '-';
            sekolahInfo.headmaster_nip = kNip || '-';
            sekolahInfo.kepsek_gelar_depan = activeKepsek.gelar_depan || '';
            sekolahInfo.kepsek_gelar_belakang = activeKepsek.gelar_belakang || '';
        }
    } catch {}

    // 4. Mapel Tryout Aktif untuk Sesi Ini
    const [mapelList]: any = await pool.query(`
        SELECT * FROM tryout_mapel 
        WHERE (sesi_id = ? OR (sesi_id IS NULL AND NOT EXISTS (SELECT 1 FROM tryout_mapel tm2 WHERE tm2.sesi_id = ?)))
          AND (status_aktif = 1 OR status_aktif IS NULL) 
        ORDER BY urutan ASC, id ASC
    `, [sesi_id, sesi_id]);

    // 5. Siswa di Rombel Aktif
    const [students]: any = await pool.query(`
        SELECT DISTINCT
            COALESCE(pd.peserta_didik_id, pd.id) as peserta_didik_id,
            COALESCE(pd.nama, pd.nama_lengkap) as nama,
            COALESCE(pd.nisn, '') as nisn,
            COALESCE(NULLIF(rpd.nipd, ''), NULLIF(pd.nipd, ''), '') as nipd,
            COALESCE(pd.jenis_kelamin, 'L') as jenis_kelamin,
            ar.rombongan_belajar_id,
            rb.nama as nama_rombel
        FROM anggota_rombel ar
        JOIN peserta_didik pd ON (ar.peserta_didik_id = pd.peserta_didik_id OR ar.peserta_didik_id = pd.id)
        JOIN rombongan_belajar rb ON ar.rombongan_belajar_id = rb.rombongan_belajar_id
        LEFT JOIN (
            SELECT peserta_didik_id, MAX(nipd) as nipd
            FROM registrasi_peserta_didik
            WHERE (jenis_keluar_id IS NULL OR jenis_keluar_id = '' OR jenis_keluar_id = '0' OR jenis_keluar_id = 0)
              AND (soft_delete = 0 OR soft_delete IS NULL OR soft_delete = '0' OR soft_delete = '')
            GROUP BY peserta_didik_id
        ) rpd ON (pd.peserta_didik_id = rpd.peserta_didik_id OR pd.id = rpd.peserta_didik_id)
        WHERE ar.rombongan_belajar_id IN (${idPlaceholders})
          AND (ar.soft_delete = 0 OR ar.soft_delete IS NULL OR ar.soft_delete = '0' OR ar.soft_delete = '')
          AND (pd.soft_delete = 0 OR pd.soft_delete IS NULL OR pd.soft_delete = '0' OR pd.soft_delete = '')
          AND (pd.status_aktif IS NULL OR pd.status_aktif = 1 OR pd.status_aktif = '1' OR pd.status_aktif = 'Aktif')
        ORDER BY pd.nama ASC
    `, [...idList]);

    // 6. Nilai Tryout untuk Rombel Ini
    const [nilaiRows]: any = await pool.query(`
        SELECT tn.*
        FROM tryout_nilai tn
        WHERE tn.sesi_id = ? AND (tn.rombongan_belajar_id IN (${idPlaceholders}) OR tn.nama_rombel = ?)
    `, [sesi_id, ...idList, req.query.nama_rombel || rombelInfo.nama_rombel]);

    // 7. Nilai Tryout untuk Semua Rombel Kelas 6 (untuk Ranking Paralel)
    const [allGrade6Nilai]: any = await pool.query(`
        SELECT tn.peserta_didik_id, AVG(tn.nilai) as avg_nilai, SUM(tn.nilai) as total_nilai
        FROM tryout_nilai tn
        WHERE tn.sesi_id = ? AND tn.nilai IS NOT NULL
        GROUP BY tn.peserta_didik_id
        ORDER BY avg_nilai DESC
    `, [sesi_id]);

    const paralelRankingMap: Record<string, number> = {};
    allGrade6Nilai.forEach((item: any, idx: number) => {
        paralelRankingMap[String(item.peserta_didik_id)] = idx + 1;
    });

    // Map nilai per student
    const studentGradesMap: Record<string, Record<number, any>> = {};
    const studentCatatanMap: Record<string, string> = {};

    (nilaiRows || []).forEach((n: any) => {
        const sId = String(n.peserta_didik_id);
        if (!studentGradesMap[sId]) studentGradesMap[sId] = {};
        studentGradesMap[sId][n.mapel_id] = n;
        if (n.catatan_wali) studentCatatanMap[sId] = n.catatan_wali;
    });

    // Calculate per-student stats
    const studentStats = (students || []).map((s: any) => {
        const sId = String(s.peserta_didik_id);
        const grades = studentGradesMap[sId] || {};
        let total = 0;
        let count = 0;
        const mapels: any[] = [];

        mapelList.forEach((m: any) => {
            const g = grades[m.id];
            const val = g && g.nilai !== null && g.nilai !== undefined ? parseFloat(g.nilai) : null;
            if (val !== null && !isNaN(val)) {
                total += val;
                count++;
            }
            mapels.push({
                mapel_id: m.id,
                nama_mapel: m.nama_mapel,
                kode_mapel: m.kode_mapel,
                kkm: m.kkm,
                nilai: val,
                tuntas: val !== null ? val >= (m.kkm || 75) : false
            });
        });

        const rataRata = count > 0 ? parseFloat((total / count).toFixed(2)) : 0;
        const rankingParalel = paralelRankingMap[sId] || null;

        return {
            ...s,
            mapels,
            total: parseFloat(total.toFixed(2)),
            rata_rata: rataRata,
            jumlah_mapel_diisi: count,
            catatan_wali: studentCatatanMap[sId] || '',
            ranking_paralel: rankingParalel,
            total_siswa_paralel: allGrade6Nilai.length
        };
    });

    // Calculate class ranking
    studentStats.sort((a: any, b: any) => b.rata_rata - a.rata_rata);
    studentStats.forEach((s: any, idx: number) => {
        s.ranking_kelas = idx + 1;
        s.total_siswa_kelas = studentStats.length;
    });

    // Sort back alphabetically by name for display consistency
    const sortedByName = [...studentStats].sort((a: any, b: any) => a.nama.localeCompare(b.nama));

    res.json({
        sesi: sesiInfo,
        rombel: rombelInfo,
        sekolah: sekolahInfo,
        mapels: mapelList,
        students: sortedByName,
        total_siswa: sortedByName.length,
        total_siswa_paralel: allGrade6Nilai.length
    });
}));

// 5. GET Rekap Multi-Sesi / Akumulasi Total TryOut TKA (Lintas Sesi, Hari, & Mapel)
app.get("/api/tryout/rekap-multi-sesi", authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    await ensureTryoutTables(pool);
    const { rombongan_belajar_id, sesi_ids, kegiatan_id } = req.query;

    if (!rombongan_belajar_id) {
        return res.status(400).json({ error: "Rombongan belajar wajib dipilih." });
    }

    // 1. Dapatkan daftar sesi yang diminta, atau sesi berdasarkan kegiatan_id, atau seluruh sesi
    let parsedSesiIds: number[] = [];
    if (sesi_ids && typeof sesi_ids === 'string') {
        parsedSesiIds = sesi_ids.split(',').map(s => parseInt(s.trim())).filter(n => !isNaN(n));
    }

    let sesiQuery = "SELECT * FROM tryout_sesi";
    let sesiParams: any[] = [];
    if (kegiatan_id) {
        sesiQuery += " WHERE kegiatan_id = ?";
        sesiParams.push(parseInt(String(kegiatan_id)));
    } else if (parsedSesiIds.length > 0) {
        sesiQuery += ` WHERE id IN (${parsedSesiIds.map(() => '?').join(',')})`;
        sesiParams = parsedSesiIds;
    }
    sesiQuery += " ORDER BY hari_ke ASC, sesi_ke ASC, tanggal_pelaksanaan ASC, id ASC";

    const [sesiRows]: any = await pool.query(sesiQuery, sesiParams);
    const sesiList = sesiRows || [];
    if (sesiList.length === 0) {
        return res.json({ sesi_list: [], mapels: [], students: [], distinct_mapels: [] });
    }

    const activeSesiIds = sesiList.map((s: any) => s.id);

    // Dapatkan info kegiatan terkait
    let kegiatanData: any = null;
    const effKId = kegiatan_id ? parseInt(String(kegiatan_id)) : (sesiList[0]?.kegiatan_id || null);
    if (effKId) {
        const [kRows]: any = await pool.query("SELECT * FROM tryout_kegiatan WHERE id = ? LIMIT 1", [effKId]).catch(() => [[]]);
        if (kRows && kRows.length > 0) kegiatanData = kRows[0];
    }

    // 2. Info Rombel & Sekolah
    const targetRombelStr = String(rombongan_belajar_id || req.query.nama_rombel || '').trim();
    const extraRombelName = req.query.nama_rombel ? String(req.query.nama_rombel).trim() : '';
    const { idList, nameList } = await resolveRombelCandidates(pool, targetRombelStr, extraRombelName);
    const idPlaceholders = idList.map(() => '?').join(',') || "''";

    const [rombelRows]: any = await pool.query(`
        SELECT 
            rb.rombongan_belajar_id,
            rb.nama as nama_rombel,
            rb.tingkat,
            rb.tingkat_pendidikan_id,
            rb.wali_kelas_id,
            ptk.nama as nama_wali_kelas,
            ptk.nip as nip_wali_kelas,
            ptk.gelar_depan,
            ptk.gelar_belakang
        FROM rombongan_belajar rb
        LEFT JOIN ptk ON (rb.wali_kelas_id = ptk.ptk_id OR rb.ptk_id = ptk.ptk_id)
        WHERE rb.rombongan_belajar_id IN (${idPlaceholders})
        LIMIT 1
    `, [...idList]);
    const rombelInfo = rombelRows[0] || { nama_rombel: extraRombelName || 'Kelas 6', tingkat: '6', rombongan_belajar_id: idList[0] || rombongan_belajar_id };

    const [schRows]: any = await pool.query("SELECT * FROM pengaturan_sekolah WHERE id = 1 LIMIT 1").catch(() => [[]]);
    const sekolahInfo = (schRows && schRows[0]) || {};
    try {
        const activeKepsek = await getActiveKepalaSekolah(pool, sekolahInfo);
        if (activeKepsek) {
            const kName = activeKepsek.nama || activeKepsek.nama_lengkap || '';
            const kNip = activeKepsek.nip || '';
            sekolahInfo.nama_kepsek = kName;
            sekolahInfo.headmaster_name = kName;
            sekolahInfo.nip_kepsek = kNip || '-';
            sekolahInfo.headmaster_nip = kNip || '-';
            sekolahInfo.kepsek_gelar_depan = activeKepsek.gelar_depan || '';
            sekolahInfo.kepsek_gelar_belakang = activeKepsek.gelar_belakang || '';
        }
    } catch {}

    // 3. Mapel per sesi
    const [mapelRows]: any = await pool.query(`
        SELECT tm.*, ts.nama_sesi, ts.tanggal_pelaksanaan
        FROM tryout_mapel tm
        JOIN tryout_sesi ts ON tm.sesi_id = ts.id
        WHERE tm.sesi_id IN (${activeSesiIds.map(() => '?').join(',')})
          AND (tm.status_aktif = 1 OR tm.status_aktif IS NULL)
        ORDER BY ts.tanggal_pelaksanaan ASC, ts.id ASC, tm.urutan ASC, tm.id ASC
    `, activeSesiIds);

    // 4. Siswa di Rombel
    const [students]: any = await pool.query(`
        SELECT DISTINCT
            COALESCE(pd.peserta_didik_id, pd.id) as peserta_didik_id,
            COALESCE(pd.nama, pd.nama_lengkap) as nama,
            COALESCE(pd.nisn, '') as nisn,
            COALESCE(NULLIF(rpd.nipd, ''), NULLIF(pd.nipd, ''), '') as nipd,
            COALESCE(pd.jenis_kelamin, 'L') as jenis_kelamin,
            ar.rombongan_belajar_id,
            rb.nama as nama_rombel
        FROM anggota_rombel ar
        JOIN peserta_didik pd ON (ar.peserta_didik_id = pd.peserta_didik_id OR ar.peserta_didik_id = pd.id)
        JOIN rombongan_belajar rb ON ar.rombongan_belajar_id = rb.rombongan_belajar_id
        LEFT JOIN (
            SELECT peserta_didik_id, MAX(nipd) as nipd
            FROM registrasi_peserta_didik
            WHERE (jenis_keluar_id IS NULL OR jenis_keluar_id = '' OR jenis_keluar_id = '0' OR jenis_keluar_id = 0)
              AND (soft_delete = 0 OR soft_delete IS NULL OR soft_delete = '0' OR soft_delete = '')
            GROUP BY peserta_didik_id
        ) rpd ON (pd.peserta_didik_id = rpd.peserta_didik_id OR pd.id = rpd.peserta_didik_id)
        WHERE ar.rombongan_belajar_id IN (${idPlaceholders})
          AND (ar.soft_delete = 0 OR ar.soft_delete IS NULL OR ar.soft_delete = '0' OR ar.soft_delete = '')
          AND (pd.soft_delete = 0 OR pd.soft_delete IS NULL OR pd.soft_delete = '0' OR pd.soft_delete = '')
          AND (pd.status_aktif IS NULL OR pd.status_aktif = 1 OR pd.status_aktif = '1' OR pd.status_aktif = 'Aktif')
        ORDER BY pd.nama ASC
    `, [...idList]);

    // 5. Seluruh nilai pada sesi-sesi tersebut
    const [nilaiRows]: any = await pool.query(`
        SELECT tn.*
        FROM tryout_nilai tn
        WHERE tn.sesi_id IN (${activeSesiIds.map(() => '?').join(',')})
          AND (tn.rombongan_belajar_id IN (${idPlaceholders}) OR tn.nama_rombel = ?)
    `, [...activeSesiIds, ...idList, req.query.nama_rombel || rombelInfo.nama_rombel]);

    // 6. Ranking Paralel Akumulasi
    const [allGrade6Nilai]: any = await pool.query(`
        SELECT tn.peserta_didik_id, AVG(tn.nilai) as avg_nilai, SUM(tn.nilai) as total_nilai
        FROM tryout_nilai tn
        WHERE tn.sesi_id IN (${activeSesiIds.map(() => '?').join(',')}) AND tn.nilai IS NOT NULL
        GROUP BY tn.peserta_didik_id
        ORDER BY avg_nilai DESC
    `, activeSesiIds);

    const paralelRankingMap: Record<string, number> = {};
    allGrade6Nilai.forEach((item: any, idx: number) => {
        paralelRankingMap[String(item.peserta_didik_id)] = idx + 1;
    });

    // Susun peta nilai per siswa: studentScores[pid][sesi_id][mapel_id] = nilai
    const studentScores: Record<string, Record<number, Record<number, number>>> = {};
    const studentCatatan: Record<string, string> = {};

    (nilaiRows || []).forEach((n: any) => {
        const pid = String(n.peserta_didik_id);
        const sId = Number(n.sesi_id);
        const mId = Number(n.mapel_id);
        if (!studentScores[pid]) studentScores[pid] = {};
        if (!studentScores[pid][sId]) studentScores[pid][sId] = {};
        if (n.nilai !== null && n.nilai !== undefined) {
            studentScores[pid][sId][mId] = parseFloat(n.nilai);
        }
        if (n.catatan_wali && !studentCatatan[pid]) {
            studentCatatan[pid] = n.catatan_wali;
        }
    });

    // Identifikasi distinct nama mapel (misal: "Matematika", "Bahasa Indonesia", dsb.)
    const distinctMapelNames: string[] = [];
    (mapelRows || []).forEach((m: any) => {
        const cleanName = m.nama_mapel.trim();
        if (!distinctMapelNames.includes(cleanName)) {
            distinctMapelNames.push(cleanName);
        }
    });

    // Format data per student
    const studentRows = (students || []).map((st: any) => {
        const pid = String(st.peserta_didik_id);
        const pScores = studentScores[pid] || {};

        let grandTotal = 0;
        let grandCount = 0;

        // Breakdown per Sesi
        const sesiBreakdown: Record<number, { total: number; avg: number; count: number; scores: Record<number, number> }> = {};
        sesiList.forEach((s: any) => {
            const sId = s.id;
            const sessionMapels = (mapelRows || []).filter((m: any) => m.sesi_id === sId);
            let sTotal = 0;
            let sCount = 0;
            const sMapelScores: Record<number, number> = {};

            sessionMapels.forEach((m: any) => {
                const val = pScores[sId]?.[m.id];
                if (val !== undefined && val !== null && !isNaN(val)) {
                    sMapelScores[m.id] = val;
                    sTotal += val;
                    sCount++;
                    grandTotal += val;
                    grandCount++;
                }
            });

            sesiBreakdown[sId] = {
                total: parseFloat(sTotal.toFixed(2)),
                avg: sCount > 0 ? parseFloat((sTotal / sCount).toFixed(2)) : 0,
                count: sCount,
                scores: sMapelScores
            };
        });

        // Breakdown per Mapel Name (lintas sesi)
        const mapelBreakdown: Record<string, { total: number; avg: number; count: number; sesiScores: Record<number, number> }> = {};
        distinctMapelNames.forEach(mName => {
            let mTotal = 0;
            let mCount = 0;
            const mSesiScores: Record<number, number> = {};

            (mapelRows || []).filter((m: any) => m.nama_mapel.trim().toLowerCase() === mName.toLowerCase()).forEach((m: any) => {
                const val = pScores[m.sesi_id]?.[m.id];
                if (val !== undefined && val !== null && !isNaN(val)) {
                    mSesiScores[m.sesi_id] = val;
                    mTotal += val;
                    mCount++;
                }
            });

            mapelBreakdown[mName] = {
                total: parseFloat(mTotal.toFixed(2)),
                avg: mCount > 0 ? parseFloat((mTotal / mCount).toFixed(2)) : 0,
                count: mCount,
                sesiScores: mSesiScores
            };
        });

        const grandAvg = grandCount > 0 ? parseFloat((grandTotal / grandCount).toFixed(2)) : 0;

        return {
            ...st,
            sesi_breakdown: sesiBreakdown,
            mapel_breakdown: mapelBreakdown,
            total_akumulasi: parseFloat(grandTotal.toFixed(2)),
            rata_rata_akumulasi: grandAvg,
            total_mapel_diisi: grandCount,
            catatan_wali: studentCatatan[pid] || '',
            ranking_paralel_akumulasi: paralelRankingMap[pid] || null
        };
    });

    // Hitung ranking kelas akumulasi
    const sortedByScore = [...studentRows].sort((a: any, b: any) => b.rata_rata_akumulasi - a.rata_rata_akumulasi);
    sortedByScore.forEach((s: any, idx: number) => {
        s.ranking_kelas_akumulasi = idx + 1;
        s.total_siswa_kelas = sortedByScore.length;
    });

    // Urutkan kembali berdasarkan nama untuk display
    const finalStudents = [...sortedByScore].sort((a: any, b: any) => a.nama.localeCompare(b.nama));

    res.json({
        sesi_list: sesiList,
        rombel: rombelInfo,
        sekolah: sekolahInfo,
        mapels: mapelRows,
        distinct_mapels: distinctMapelNames,
        students: finalStudents,
        total_siswa: finalStudents.length,
        total_siswa_paralel: allGrade6Nilai.length
    });
}));

// =========================================================================
// PENILAIAN HARIAN (FORMATIF / TP / TUGAS / ULANGAN HARIAN) - STANDAR DAPODIK
// =========================================================================

async function ensurePenilaianHarianTables(poolParam?: any) {
    const pool = poolParam || getPool();
    try {
        await pool.query(`
            CREATE TABLE IF NOT EXISTS penilaian_harian (
                id INT AUTO_INCREMENT PRIMARY KEY,
                rombongan_belajar_id VARCHAR(64) NOT NULL,
                nama_rombel VARCHAR(150) NULL,
                mapel_id INT DEFAULT NULL,
                nama_mapel VARCHAR(150) NOT NULL,
                kode_mapel VARCHAR(50) DEFAULT NULL,
                tanggal_penilaian DATE NOT NULL,
                jenis_penilaian VARCHAR(50) DEFAULT 'PH',
                judul_penilaian VARCHAR(255) NOT NULL,
                materi_pokok TEXT NULL,
                kkm DECIMAL(5,2) DEFAULT 75.00,
                semester_id VARCHAR(10) NOT NULL DEFAULT '1',
                tahun_ajaran VARCHAR(20) NOT NULL DEFAULT '2024/2025',
                guru_id VARCHAR(64) DEFAULT NULL,
                guru_nama VARCHAR(150) DEFAULT NULL,
                created_by INT DEFAULT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                INDEX idx_ph_rombel (rombongan_belajar_id(36)),
                INDEX idx_ph_mapel (nama_mapel(50)),
                INDEX idx_ph_tgl (tanggal_penilaian)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
        `);

        await pool.query(`
            CREATE TABLE IF NOT EXISTS nilai_penilaian_harian (
                id INT AUTO_INCREMENT PRIMARY KEY,
                penilaian_harian_id INT NOT NULL,
                peserta_didik_id VARCHAR(64) NOT NULL,
                rombongan_belajar_id VARCHAR(64) NOT NULL,
                nilai DECIMAL(5,2) NULL,
                kkm DECIMAL(5,2) DEFAULT 75.00,
                status_tuntas VARCHAR(30) DEFAULT 'Tuntas',
                nilai_remedial DECIMAL(5,2) NULL,
                nilai_akhir DECIMAL(5,2) NULL,
                catatan TEXT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                UNIQUE KEY uniq_ph_siswa (penilaian_harian_id, peserta_didik_id(36)),
                INDEX idx_nph_pd (peserta_didik_id(36)),
                INDEX idx_nph_ph_id (penilaian_harian_id)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
        `);

        // Safe column checks / migrations
        const [phCols]: any = await pool.query("SHOW COLUMNS FROM penilaian_harian").catch(() => [[]]);
        const existingPhColNames = (phCols || []).map((c: any) => c.Field ? c.Field.toLowerCase() : '');
        if (!existingPhColNames.includes('jenis_penilaian')) {
            await pool.query("ALTER TABLE penilaian_harian ADD COLUMN jenis_penilaian VARCHAR(50) DEFAULT 'PH'").catch(() => {});
        }
        if (!existingPhColNames.includes('materi_pokok')) {
            await pool.query("ALTER TABLE penilaian_harian ADD COLUMN materi_pokok TEXT NULL").catch(() => {});
        }
        if (!existingPhColNames.includes('guru_nama')) {
            await pool.query("ALTER TABLE penilaian_harian ADD COLUMN guru_nama VARCHAR(150) NULL").catch(() => {});
        }

        const [nphCols]: any = await pool.query("SHOW COLUMNS FROM nilai_penilaian_harian").catch(() => [[]]);
        const existingNphColNames = (nphCols || []).map((c: any) => c.Field ? c.Field.toLowerCase() : '');
        if (!existingNphColNames.includes('nilai_remedial')) {
            await pool.query("ALTER TABLE nilai_penilaian_harian ADD COLUMN nilai_remedial DECIMAL(5,2) NULL").catch(() => {});
        }
        if (!existingNphColNames.includes('nilai_akhir')) {
            await pool.query("ALTER TABLE nilai_penilaian_harian ADD COLUMN nilai_akhir DECIMAL(5,2) NULL").catch(() => {});
        }
    } catch (err: any) {
        console.warn("[Penilaian Harian] ensurePenilaianHarianTables warning:", err.message);
    }
}

// 1. Ambil Daftar Sesi Penilaian Harian (dengan ringkasan statistik)
app.get("/api/penilaian-harian", authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    await ensurePenilaianHarianTables(pool);
    const { rombongan_belajar_id, nama_rombel, nama_mapel, mapel_id, semester_id, tahun_ajaran, tanggal, start_date, end_date, search } = req.query;

    let targetRombelStr = String(rombongan_belajar_id || nama_rombel || '').trim();
    let semId = semester_id ? String(semester_id).trim() : '';
    let thnAjar = tahun_ajaran ? String(tahun_ajaran).trim() : '';
    let targetMapel = nama_mapel ? String(nama_mapel).trim() : '';

    let idList: string[] = [];
    if (targetRombelStr) {
        const resolved = await resolveRombelCandidates(pool, targetRombelStr, String(nama_rombel || ''), semId);
        idList = resolved.idList;
    }

    let query = `
        SELECT 
            ph.*,
            COALESCE(rb.nama, ph.nama_rombel) as nama_rombel_display,
            COUNT(nph.id) as total_siswa_terdaftar,
            COUNT(CASE WHEN nph.nilai IS NOT NULL THEN 1 END) as total_siswa_dinilai,
            COUNT(CASE WHEN COALESCE(nph.nilai_akhir, nph.nilai) >= ph.kkm THEN 1 END) as total_tuntas,
            COUNT(CASE WHEN COALESCE(nph.nilai_akhir, nph.nilai) < ph.kkm THEN 1 END) as total_belum_tuntas,
            AVG(COALESCE(nph.nilai_akhir, nph.nilai)) as rata_rata_nilai,
            MAX(COALESCE(nph.nilai_akhir, nph.nilai)) as nilai_tertinggi,
            MIN(COALESCE(nph.nilai_akhir, nph.nilai)) as nilai_terendah
        FROM penilaian_harian ph
        LEFT JOIN rombongan_belajar rb ON (ph.rombongan_belajar_id = rb.rombongan_belajar_id OR ph.rombongan_belajar_id = rb.id)
        LEFT JOIN nilai_penilaian_harian nph ON ph.id = nph.penilaian_harian_id
        WHERE 1=1
    `;
    const params: any[] = [];

    if (idList.length > 0) {
        query += ` AND (ph.rombongan_belajar_id IN (${idList.map(() => '?').join(',')}) OR ph.rombongan_belajar_id = ? OR ph.nama_rombel LIKE CONCAT('%', ?, '%'))`;
        params.push(...idList, targetRombelStr, targetRombelStr);
    } else if (targetRombelStr) {
        query += ` AND (ph.rombongan_belajar_id = ? OR ph.nama_rombel LIKE CONCAT('%', ?, '%'))`;
        params.push(targetRombelStr, targetRombelStr);
    }

    if (targetMapel && targetMapel !== 'Semua') {
        query += ` AND (TRIM(LOWER(ph.nama_mapel)) = TRIM(LOWER(?)) OR ph.nama_mapel = ?)`;
        params.push(targetMapel, targetMapel);
    }

    if (semId) {
        const semShort = semId.length > 1 ? semId.slice(-1) : semId;
        query += ` AND (ph.semester_id = ? OR ph.semester_id = ?)`;
        params.push(semId, semShort);
    }

    if (thnAjar) {
        query += ` AND (ph.tahun_ajaran = ? OR REPLACE(REPLACE(ph.tahun_ajaran, ' ', ''), '-', '/') = REPLACE(REPLACE(?, ' ', ''), '-', '/'))`;
        params.push(thnAjar, thnAjar);
    }

    if (tanggal) {
        query += ` AND DATE(ph.tanggal_penilaian) = DATE(?)`;
        params.push(tanggal);
    }
    if (start_date) {
        query += ` AND DATE(ph.tanggal_penilaian) >= DATE(?)`;
        params.push(start_date);
    }
    if (end_date) {
        query += ` AND DATE(ph.tanggal_penilaian) <= DATE(?)`;
        params.push(end_date);
    }

    if (search) {
        query += ` AND (ph.judul_penilaian LIKE CONCAT('%', ?, '%') OR ph.materi_pokok LIKE CONCAT('%', ?, '%') OR ph.nama_mapel LIKE CONCAT('%', ?, '%'))`;
        params.push(search, search, search);
    }

    query += ` GROUP BY ph.id ORDER BY ph.tanggal_penilaian DESC, ph.id DESC`;

    const [rows]: any = await pool.query(query, params);

    res.json({
        success: true,
        data: rows.map((r: any) => ({
            ...r,
            rata_rata_nilai: r.rata_rata_nilai !== null ? parseFloat(Number(r.rata_rata_nilai).toFixed(1)) : null,
            nilai_tertinggi: r.nilai_tertinggi !== null ? parseFloat(Number(r.nilai_tertinggi).toFixed(1)) : null,
            nilai_terendah: r.nilai_terendah !== null ? parseFloat(Number(r.nilai_terendah).toFixed(1)) : null
        }))
    });
}));

// 2. Ambil Detail Sesi Penilaian Harian + Daftar Siswa Lengkap
app.get("/api/penilaian-harian/:id", authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    await ensurePenilaianHarianTables(pool);
    const { id } = req.params;

    const [phRows]: any = await pool.query("SELECT * FROM penilaian_harian WHERE id = ? LIMIT 1", [id]);
    if (!phRows || phRows.length === 0) {
        return res.status(404).json({ error: "Sesi Penilaian Harian tidak ditemukan." });
    }
    const session = phRows[0];

    // Resolve candidates rombel
    const { idList } = await resolveRombelCandidates(pool, session.rombongan_belajar_id, session.nama_rombel || '', session.semester_id);
    const idPlaceholders = idList.length > 0 ? idList.map(() => '?').join(',') : '?';
    const rombelParams = idList.length > 0 ? idList : [session.rombongan_belajar_id];

    const [students]: any = await pool.query(`
        SELECT DISTINCT
            COALESCE(pd.peserta_didik_id, pd.id) as peserta_didik_id,
            COALESCE(pd.nama, pd.nama_lengkap) as nama,
            COALESCE(pd.nisn, '') as nisn,
            COALESCE(NULLIF(rpd.nipd, ''), NULLIF(pd.nipd, ''), '') as nipd,
            COALESCE(pd.jenis_kelamin, 'L') as jenis_kelamin,
            COALESCE(pd.foto_profil, '') as foto_profil,
            nph.id as nilai_id,
            nph.nilai,
            nph.kkm,
            nph.status_tuntas,
            nph.nilai_remedial,
            nph.nilai_akhir,
            nph.catatan,
            nph.updated_at as last_update
        FROM anggota_rombel ar
        JOIN peserta_didik pd ON (ar.peserta_didik_id = pd.peserta_didik_id OR ar.peserta_didik_id = pd.id)
        LEFT JOIN (
            SELECT peserta_didik_id, MAX(nipd) as nipd
            FROM registrasi_peserta_didik
            WHERE (jenis_keluar_id IS NULL OR jenis_keluar_id = '' OR jenis_keluar_id = '0' OR jenis_keluar_id = 0)
            GROUP BY peserta_didik_id
        ) rpd ON (rpd.peserta_didik_id = pd.peserta_didik_id OR rpd.peserta_didik_id = pd.id)
        LEFT JOIN nilai_penilaian_harian nph ON (
            nph.penilaian_harian_id = ? 
            AND (nph.peserta_didik_id = pd.peserta_didik_id OR nph.peserta_didik_id = pd.id)
        )
        WHERE ar.rombongan_belajar_id IN (${idPlaceholders})
          AND (ar.soft_delete = 0 OR ar.soft_delete IS NULL OR ar.soft_delete = '0' OR ar.soft_delete = '')
          AND (pd.soft_delete = 0 OR pd.soft_delete IS NULL OR pd.soft_delete = '0' OR pd.soft_delete = '')
        ORDER BY COALESCE(pd.nama, pd.nama_lengkap) ASC
    `, [session.id, ...rombelParams]);

    // Deduplicate students
    const studentMap = new Map<string, any>();
    for (const s of (students || [])) {
        const sid = String(s.peserta_didik_id || '').trim();
        if (!sid) continue;
        if (!studentMap.has(sid)) {
            studentMap.set(sid, s);
        } else {
            const existing = studentMap.get(sid);
            if (s.nilai !== null && existing.nilai === null) {
                studentMap.set(sid, s);
            }
        }
    }

    const uniqueStudents = Array.from(studentMap.values()).sort((a, b) => (a.nama || '').localeCompare(b.nama || ''));

    // Compute stats
    let totalScore = 0;
    let scoredCount = 0;
    let tuntasCount = 0;
    let maxScore = -1;
    let minScore = 999;

    uniqueStudents.forEach(st => {
        const finalVal = st.nilai_akhir !== null && st.nilai_akhir !== undefined ? parseFloat(st.nilai_akhir) : (st.nilai !== null && st.nilai !== undefined ? parseFloat(st.nilai) : null);
        if (finalVal !== null && !isNaN(finalVal)) {
            totalScore += finalVal;
            scoredCount++;
            if (finalVal >= (session.kkm || 75)) tuntasCount++;
            if (finalVal > maxScore) maxScore = finalVal;
            if (finalVal < minScore) minScore = finalVal;
        }
    });

    res.json({
        success: true,
        session,
        students: uniqueStudents,
        summary: {
            total_siswa: uniqueStudents.length,
            siswa_dinilai: scoredCount,
            total_tuntas: tuntasCount,
            total_belum_tuntas: scoredCount - tuntasCount,
            rata_rata: scoredCount > 0 ? parseFloat((totalScore / scoredCount).toFixed(1)) : null,
            nilai_tertinggi: scoredCount > 0 ? maxScore : null,
            nilai_terendah: scoredCount > 0 ? minScore : null
        }
    });
}));

