app.post("/api/laporan-kinerja/upload-foto", authenticate, uploadKinerja.single("foto"), asyncHandler(async (req: any, res: any) => {
    if (!req.file) {
        return res.status(400).json({ error: "File foto kegiatan wajib diunggah." });
    }
    const photoUrl = `/uploads/kinerja/${req.file.filename}`;
    res.json({ success: true, photo_url: photoUrl, filename: req.file.filename });
}));

// 2. Master Template Pekerjaan Rutin
app.get("/api/laporan-kinerja-template", authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    await ensureLaporanKinerjaTables(pool);
    const { kategori } = req.query;

    let conditions: string[] = [];
    let params: any[] = [];

    if (kategori && String(kategori).trim() !== '' && String(kategori).trim() !== 'Semua') {
        conditions.push("(kategori = ? OR kategori = 'Umum / Semua Tugas' OR kategori = 'Umum')");
        params.push(String(kategori).trim());
    }

    const whereClause = conditions.length > 0 ? `WHERE ${conditions.join(" AND ")}` : "";

    const [rows]: any = await pool.query(`
        SELECT * FROM laporan_kinerja_template 
        ${whereClause}
        ORDER BY kategori ASC, nama_kegiatan ASC
    `, params);
    res.json(rows || []);
}));

app.post("/api/laporan-kinerja-template", authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    await ensureLaporanKinerjaTables(pool);
    const { kategori, nama_kegiatan, deskripsi_default, output_default, is_global } = req.body;
    if (!nama_kegiatan || !String(nama_kegiatan).trim()) {
        return res.status(400).json({ error: "Nama kegiatan template wajib diisi." });
    }

    const [result]: any = await pool.query(`
        INSERT INTO laporan_kinerja_template (kategori, nama_kegiatan, deskripsi_default, output_default, created_by, is_global)
        VALUES (?, ?, ?, ?, ?, ?)
    `, [
        kategori || 'Petugas Kebersihan',
        String(nama_kegiatan).trim(),
        deskripsi_default || '',
        output_default || '',
        req.user?.staff_id || req.user?.id || null,
        is_global !== undefined ? (is_global ? 1 : 0) : 1
    ]);

    res.json({ success: true, id: result.insertId, message: "Template pekerjaan rutin berhasil ditambahkan!" });
}));

