app.get("/api/laporan-kinerja-pegawai-wajib", authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    await ensureLaporanKinerjaTables(pool);
    const { search, active_only, tugas_pokok } = req.query;

    let conditions: string[] = [];
    let params: any[] = [];

    if (active_only === '1' || active_only === 'true') {
        conditions.push("pw.is_active = 1");
    }

    if (tugas_pokok && String(tugas_pokok).trim() !== '') {
        conditions.push("pw.tugas_pokok = ?");
        params.push(String(tugas_pokok).trim());
    }

    if (search && String(search).trim() !== '') {
        const s = `%${String(search).trim()}%`;
        conditions.push("(pw.nama_pegawai LIKE ? OR pw.nip_nik LIKE ? OR pw.tugas_pokok LIKE ? OR pw.jabatan_tugas LIKE ? OR pw.unit_kerja LIKE ?)");
        params.push(s, s, s, s, s);
    }

    const whereClause = conditions.length > 0 ? `WHERE ${conditions.join(" AND ")}` : "";

    const query = `
        SELECT 
            pw.*,
            (
                SELECT COUNT(*) 
                FROM laporan_kinerja lk 
                WHERE (lk.pegawai_id = pw.pegawai_id AND pw.pegawai_id IS NOT NULL AND pw.pegawai_id != '')
                   OR (lk.user_id = pw.user_id AND pw.user_id IS NOT NULL)
                   OR (LOWER(TRIM(lk.nama_pegawai)) = LOWER(TRIM(pw.nama_pegawai)))
            ) AS total_laporan,
            (
                SELECT lk.periode_akhir 
                FROM laporan_kinerja lk 
                WHERE (lk.pegawai_id = pw.pegawai_id AND pw.pegawai_id IS NOT NULL AND pw.pegawai_id != '')
                   OR (lk.user_id = pw.user_id AND pw.user_id IS NOT NULL)
                   OR (LOWER(TRIM(lk.nama_pegawai)) = LOWER(TRIM(pw.nama_pegawai)))
                ORDER BY lk.periode_akhir DESC, lk.id DESC
                LIMIT 1
            ) AS laporan_terakhir,
            (
                SELECT lk.status 
                FROM laporan_kinerja lk 
                WHERE (lk.pegawai_id = pw.pegawai_id AND pw.pegawai_id IS NOT NULL AND pw.pegawai_id != '')
                   OR (lk.user_id = pw.user_id AND pw.user_id IS NOT NULL)
                   OR (LOWER(TRIM(lk.nama_pegawai)) = LOWER(TRIM(pw.nama_pegawai)))
                ORDER BY lk.periode_akhir DESC, lk.id DESC
                LIMIT 1
            ) AS status_terakhir
        FROM laporan_kinerja_pegawai_wajib pw
        ${whereClause}
        ORDER BY pw.is_active DESC, pw.nama_pegawai ASC
    `;

    const [rows]: any = await pool.query(query, params);
    res.json(rows || []);
}));

app.post("/api/laporan-kinerja-pegawai-wajib", authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    await ensureLaporanKinerjaTables(pool);
    const { 
        pegawai_id, user_id, nama_pegawai, nip_nik, 
        tugas_pokok, jabatan_tugas, unit_kerja, status_kepegawaian, 
        target_periode, is_active, keterangan, password 
    } = req.body;

    if (!nama_pegawai || !String(nama_pegawai).trim()) {
        return res.status(400).json({ error: "Nama pegawai wajib diisi." });
    }

    const resolvedTugasPokok = tugas_pokok || jabatan_tugas || 'Petugas Kebersihan';
    const cleanNipNik = String(nip_nik || '').trim();
    const loginUsername = cleanNipNik || (pegawai_id ? String(pegawai_id).trim() : String(nama_pegawai).toLowerCase().replace(/\s+/g, '_'));
    const rawPassword = (password && String(password).trim()) ? String(password).trim() : (cleanNipNik || '123456');

    let linkedUserId: number | null = user_id ? Number(user_id) : null;

    try {
        // 1. Cek apakah user di pengguna_web sudah ada
        const [existingUsers]: any = await pool.query(
            "SELECT id, username, password FROM pengguna_web WHERE username = ? OR (staff_id = ? AND staff_id IS NOT NULL)",
            [loginUsername, pegawai_id || null]
        );

        if (existingUsers && existingUsers.length > 0) {
            linkedUserId = existingUsers[0].id;
            // Jika admin memasukkan custom password baru saat mendaftarkan ulang
            if (password && String(password).trim()) {
                const hashedPassword = await bcrypt.hash(rawPassword, 10);
                await pool.query("UPDATE pengguna_web SET password = ? WHERE id = ?", [hashedPassword, linkedUserId]);
            }
        } else {
            // 2. Jika belum ada akun, pastikan role 'Pegawai' atau 'Tendik' tersedia di tabel peran
            let roleId = 1;
            try {
                const [roles]: any = await pool.query("SELECT id FROM peran WHERE name IN ('Pegawai', 'Tendik', 'Tenaga Kependidikan', 'Staff') LIMIT 1");
                if (roles && roles.length > 0) {
                    roleId = roles[0].id;
                } else {
                    const defaultPerms = JSON.stringify([
                        "laporan_kinerja:view",
                        "laporan_kinerja:create",
                        "laporan_kinerja:update",
                        "laporan_kinerja:delete"
                    ]);
                    const [newRole]: any = await pool.query("INSERT INTO peran (name, permissions) VALUES ('Pegawai', ?)", [defaultPerms]);
                    roleId = newRole.insertId;
                }
            } catch (rErr) {
                console.warn("[LaporanKinerja] Role check notice:", rErr);
            }

            // 3. Buat akun baru di tabel pengguna_web
            const hashedPassword = await bcrypt.hash(rawPassword, 10);
            const [newUser]: any = await pool.query(
                "INSERT INTO pengguna_web (staff_id, role_id, username, password, status_aktif) VALUES (?, ?, ?, ?, ?)",
                [pegawai_id || null, roleId, loginUsername, hashedPassword, is_active !== undefined ? (is_active ? 1 : 0) : 1]
            );
            linkedUserId = newUser.insertId;
        }
    } catch (authErr: any) {
        console.warn("[LaporanKinerja] Notice syncing pengguna_web account:", authErr.message);
    }

    const [result]: any = await pool.query(`
        INSERT INTO laporan_kinerja_pegawai_wajib 
        (pegawai_id, user_id, nama_pegawai, nip_nik, tugas_pokok, jabatan_tugas, unit_kerja, status_kepegawaian, target_periode, is_active, keterangan)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `, [
        pegawai_id || null,
        linkedUserId || null,
        String(nama_pegawai).trim(),
        cleanNipNik,
        resolvedTugasPokok,
        jabatan_tugas || resolvedTugasPokok,
        unit_kerja || '',
        status_kepegawaian || 'Honorer',
        target_periode || 'Bulanan',
        is_active !== undefined ? (is_active ? 1 : 0) : 1,
        keterangan || null
    ]);

    res.json({ 
        success: true, 
        id: result.insertId, 
        user_id: linkedUserId,
        username: loginUsername,
        message: `Pegawai wajib lapor kinerja berhasil didaftarkan! Akun login aktif (Username: ${loginUsername}).` 
    });
}));

