app.post("/api/laporan-kinerja/my-password", authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    const { password_baru, password_lama } = req.body;

    if (!password_baru || String(password_baru).trim().length < 4) {
        return res.status(400).json({ error: "Password baru minimal harus 4 karakter." });
    }

    const userId = req.user?.id;
    const username = req.user?.username;

    if (!userId && !username) {
        return res.status(401).json({ error: "Sesi pengguna tidak valid." });
    }

    // Ambil data user saat ini
    const [userRows]: any = await pool.query(
        "SELECT id, username, password FROM pengguna_web WHERE id = ? OR username = ? LIMIT 1",
        [userId || null, username || null]
    );

    if (!userRows || userRows.length === 0) {
        return res.status(404).json({ error: "Akun pengguna tidak ditemukan di sistem." });
    }

    const currentUser = userRows[0];

    // Jika pegawai menyertakan password lama, validasi
    if (password_lama && String(password_lama).trim()) {
        const isMatch = await bcrypt.compare(String(password_lama).trim(), currentUser.password);
        if (!isMatch && String(password_lama).trim() !== currentUser.password) {
            return res.status(400).json({ error: "Password saat ini yang Anda masukkan salah." });
        }
    }

    const hashedPassword = await bcrypt.hash(String(password_baru).trim(), 10);
    await pool.query("UPDATE pengguna_web SET password = ? WHERE id = ?", [hashedPassword, currentUser.id]);

    res.json({ 
        success: true, 
        message: "Password akun Anda berhasil diperbarui! Silakan gunakan password baru pada login berikutnya." 
    });
}));

