app.get("/api/laporan-kinerja", authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    await ensureLaporanKinerjaTables(pool);
    const { search, pegawai_id, status, start_date, end_date } = req.query;

    const isAdmin = req.user?.role_name === 'Superadmin' || 
                    req.user?.role_name === 'Admin' || 
                    req.user?.role_name === 'Admin (Superadmin)' ||
                    (req.user?.permissions && (req.user.permissions.includes('all') || req.user.permissions.includes('laporan_kinerja:approve')));

    let conditions: string[] = [];
    let params: any[] = [];

    // If not admin, restrict to user's own reports
    if (!isAdmin) {
        conditions.push("(lk.user_id = ? OR lk.pegawai_id = ? OR LOWER(lk.nama_pegawai) = ?)");
        params.push(
            req.user?.id || 0,
            req.user?.staff_id || '',
            String(req.user?.nama_lengkap || req.user?.nama || '').trim().toLowerCase()
        );
    } else if (pegawai_id) {
        conditions.push("(lk.pegawai_id = ? OR lk.user_id = ?)");
        params.push(pegawai_id, pegawai_id);
    }

    if (status && String(status).trim() !== '') {
        conditions.push("lk.status = ?");
        params.push(String(status).trim());
    }

    if (start_date) {
        conditions.push("lk.periode_akhir >= ?");
        params.push(start_date);
    }

    if (end_date) {
        conditions.push("lk.periode_awal <= ?");
        params.push(end_date);
    }

    if (search && String(search).trim() !== '') {
        const q = `%${String(search).trim()}%`;
        conditions.push("(lk.judul_laporan LIKE ? OR lk.nama_pegawai LIKE ? OR lk.jabatan_tugas LIKE ? OR lk.nip_nik LIKE ?)");
        params.push(q, q, q, q);
    }

    const whereSql = conditions.length > 0 ? `WHERE ${conditions.join(" AND ")}` : "";

    const [rows]: any = await pool.query(`
        SELECT lk.*, 
               (SELECT COUNT(*) FROM laporan_kinerja_item lki WHERE lki.laporan_id = lk.id) as total_kegiatan,
               (SELECT COUNT(*) FROM laporan_kinerja_item lki WHERE lki.laporan_id = lk.id AND lki.foto_kegiatan IS NOT NULL AND lki.foto_kegiatan != '') as total_foto
        FROM laporan_kinerja lk
        ${whereSql}
        ORDER BY lk.periode_awal DESC, lk.id DESC
    `, params);

    res.json(rows || []);
}));

