// Helper untuk kalkulasi format nomor peserta dinamis
function generateDynamicNomorPeserta(
    segments: Array<{ id: string; type: string; value?: string; enabled?: boolean; digits?: number; start?: number; startVal?: number; endVal?: number }>,
    separator: string = '-',
    index: number = 0,
    roomCode: string = '01'
): string {
    if (!Array.isArray(segments) || segments.length === 0) {
        // Default format: Jenjang(01) - Prov(28) - Kota(01) - Sekolah(0123) - Urut(0001) - Validasi(9-2)
        segments = [
            { id: 'jenjang', type: 'jenjang', value: '01', enabled: true },
            { id: 'provinsi', type: 'provinsi', value: '28', enabled: true },
            { id: 'kota', type: 'kota', value: '01', enabled: true },
            { id: 'sekolah', type: 'sekolah', value: '0123', enabled: true },
            { id: 'nomor_urut', type: 'nomor_urut', digits: 4, start: 1, enabled: true },
            { id: 'validasi', type: 'validasi', startVal: 9, endVal: 2, enabled: true }
        ];
    }

    const activeSegments = segments.filter(s => s && s.enabled !== false);
    const parts: string[] = [];

    for (const seg of activeSegments) {
        switch (seg.type) {
            case 'jenjang':
            case 'provinsi':
            case 'kota':
            case 'sekolah':
            case 'tahun':
            case 'custom':
                parts.push(String(seg.value || '').trim());
                break;
            case 'ruang':
                parts.push(String(roomCode || seg.value || '01').trim());
                break;
            case 'nomor_urut': {
                const startSeq = Number(seg.start || 1);
                const digits = Number(seg.digits || 4);
                const currentSeq = startSeq + index;
                parts.push(String(currentSeq).padStart(digits, '0'));
                break;
            }
            case 'validasi': {
                const sVal = Number(seg.startVal !== undefined ? seg.startVal : 9);
                const eVal = Number(seg.endVal !== undefined ? seg.endVal : 2);
                const high = Math.max(sVal, eVal);
                const low = Math.min(sVal, eVal);
                const span = (high - low + 1) || 1;
                const offset = index % span;
                const calcVal = high - offset;
                parts.push(String(calcVal));
                break;
            }
            default:
                if (seg.value) parts.push(String(seg.value).trim());
                break;
        }
    }

    return parts.filter(Boolean).join(separator !== undefined ? separator : '-');
}

