app.post("/api/ujian/sesi/:id/generate-ruang", authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    const { id } = req.params;
    const { 
        jumlah = 1, 
        prefix = 'Ruang', 
        kapasitas = 20, 
        posisi_pintu = 'kiri', 
        pola_meja = 'ular_tangga_kolom', 
        jumlah_kolom = 4, 
        jumlah_baris = 5,
        reset = false 
    } = req.body;

    const conn = await pool.getConnection();
    try {
        await conn.beginTransaction();

        if (reset) {
            await conn.query("DELETE FROM ujian_peserta WHERE ujian_id = ?", [id]);
            await conn.query("DELETE FROM ujian_ruang WHERE ujian_id = ?", [id]);
        }

        // Get max current sequence
        const [currMax]: any = await conn.query("SELECT COALESCE(MAX(urutan), 0) as max_urutan FROM ujian_ruang WHERE ujian_id = ?", [id]);
        let startUrutan = Number(currMax[0]?.max_urutan || 0);

        const count = Math.min(Math.max(1, Number(jumlah)), 50);
        const ruangValues = [];

        for (let i = 1; i <= count; i++) {
            const seq = startUrutan + i;
            const noRuang = `${prefix} ${String(seq).padStart(2, '0')}`;
            ruangValues.push([
                id,
                noRuang,
                noRuang,
                Math.min(Math.max(1, Number(kapasitas) || 20), 50),
                null,
                null,
                posisi_pintu === 'kanan' ? 'kanan' : 'kiri',
                pola_meja || 'ular_tangga_kolom',
                Math.min(Math.max(1, Number(jumlah_kolom) || 4), 15),
                Math.min(Math.max(1, Number(jumlah_baris) || 5), 15),
                seq,
                null
            ]);
        }

        if (ruangValues.length > 0) {
            await conn.query(`
                INSERT INTO ujian_ruang 
                (ujian_id, nomor_ruang, nama_ruang, kapasitas_maksimal, pengawas_1, pengawas_2, posisi_pintu, pola_meja, jumlah_kolom, jumlah_baris, urutan, keterangan)
                VALUES ?
            `, [ruangValues]);
        }

        await conn.commit();
        res.json({ success: true, message: `Berhasil menambahkan ${count} ruangan baru!` });
    } catch (err: any) {
        await conn.rollback();
        throw err;
    } finally {
        conn.release();
    }
}));

