// 10. Get All Participants in Exam Session (Joined with 100% Dapodik `peserta_didik` & `registrasi_peserta_didik`)
app.get("/api/ujian/sesi/:id/peserta", authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    const { id } = req.params;

    const [participants]: any = await pool.query(`
        SELECT 
            p.id as peserta_id,
            p.ujian_id,
            p.ruang_id,
            p.peserta_didik_id,
            p.nomor_peserta,
            p.nomor_meja,
            p.urutan_peserta,
            p.rombel_asal,
            pd.nama as nama_lengkap,
            pd.nisn,
            COALESCE(NULLIF(TRIM(rpd.nipd), ''), NULLIF(TRIM(pd.nipd), ''), '') as nipd,
            pd.nik,
            pd.jenis_kelamin,
            pd.tempat_lahir,
            pd.tanggal_lahir,
            COALESCE(fs_foto.drive, fs_foto.server, pd.foto_profil) as foto_profil,
            r.nomor_ruang,
            r.nama_ruang,
            r.pengawas_1,
            r.pengawas_2
        FROM ujian_peserta p
        JOIN peserta_didik pd ON pd.peserta_didik_id = p.peserta_didik_id
        LEFT JOIN (
            SELECT peserta_didik_id, MAX(nipd) as nipd 
            FROM registrasi_peserta_didik 
            WHERE (soft_delete = 0 OR soft_delete IS NULL) AND nipd IS NOT NULL AND TRIM(nipd) != '' 
            GROUP BY peserta_didik_id
        ) rpd ON rpd.peserta_didik_id = pd.peserta_didik_id
        LEFT JOIN file_storage fs_foto ON (fs_foto.data_id = pd.peserta_didik_id OR fs_foto.data_id = pd.id) AND fs_foto.tipe_data = 'siswa' AND fs_foto.kategori = 'foto_profil'
        JOIN ujian_ruang r ON r.id = p.ruang_id
        WHERE p.ujian_id = ?
        ORDER BY r.urutan ASC, p.nomor_meja ASC, p.nomor_peserta ASC
    `, [id]);

    res.json(participants);
}));

// 11. Assign Students to a Specific Room (Enforcing Max 20 & No Duplicate Across Rooms in Same Exam)
app.post("/api/ujian/ruang/:ruang_id/peserta", authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    const { ruang_id } = req.params;
    const { peserta_didik_ids = [] } = req.body;

    if (!Array.isArray(peserta_didik_ids) || peserta_didik_ids.length === 0) {
        return res.status(400).json({ error: "Pilih minimal 1 siswa untuk ditambahkan!" });
    }

    // 1. Ambil data ruang & sesi
    const [ruangRows]: any = await pool.query("SELECT * FROM ujian_ruang WHERE id = ? LIMIT 1", [ruang_id]);
    if (!ruangRows || ruangRows.length === 0) {
        return res.status(404).json({ error: "Ruangan tidak ditemukan." });
    }
    const ruang = ruangRows[0];
    const ujianId = ruang.ujian_id;

    // 2. Ambil sesi ujian untuk konfigurasi format nomor
    const [sesiRows]: any = await pool.query("SELECT * FROM ujian_sesi WHERE id = ? LIMIT 1", [ujianId]);
    if (!sesiRows || sesiRows.length === 0) {
        return res.status(404).json({ error: "Sesi ujian tidak ditemukan." });
    }
    const sesi = sesiRows[0];
    let formatSegments: any[] = [];
    try {
        formatSegments = JSON.parse(sesi.format_nomor_peserta || '[]');
    } catch {
        formatSegments = [];
    }

    // 3. Cek kapasitas ruang saat ini
    const [countInRuang]: any = await pool.query("SELECT COUNT(*) as cnt FROM ujian_peserta WHERE ruang_id = ?", [ruang_id]);
    const currentRuangCount = Number(countInRuang[0]?.cnt || 0);
    const maxKapasitas = Number(ruang.kapasitas_maksimal || sesi.max_peserta_per_ruang || 20);

    if (currentRuangCount + peserta_didik_ids.length > maxKapasitas) {
        return res.status(400).json({ 
            error: `Kapasitas ruangan ${ruang.nomor_ruang} melebihi batas! Maksimal ${maxKapasitas} peserta (Saat ini: ${currentRuangCount}, mencoba menambah: ${peserta_didik_ids.length}).` 
        });
    }

    // 4. VALIDASI KETAT: Cek apakah ada siswa yang SUDAH terdaftar di ruangan lain pada sesi ujian ini
    const placeholders = peserta_didik_ids.map(() => '?').join(',');
    const [alreadyAssigned]: any = await pool.query(`
        SELECT p.peserta_didik_id, pd.nama, r.nomor_ruang 
        FROM ujian_peserta p
        JOIN peserta_didik pd ON pd.peserta_didik_id = p.peserta_didik_id
        JOIN ujian_ruang r ON r.id = p.ruang_id
        WHERE p.ujian_id = ? AND p.peserta_didik_id IN (${placeholders})
    `, [ujianId, ...peserta_didik_ids]);

    if (alreadyAssigned && alreadyAssigned.length > 0) {
        const names = alreadyAssigned.map((a: any) => `${a.nama} (sudah di ${a.nomor_ruang})`).join(', ');
        return res.status(400).json({
            error: `Siswa berikut sudah terdaftar di ruangan lain: ${names}. Setiap siswa hanya bisa berada di 1 ruangan!`
        });
    }

    // 5. Ambil data siswa & rombel asal
    const [pdList]: any = await pool.query(`
        SELECT pd.peserta_didik_id, pd.nama, rb.nama as nama_rombel
        FROM peserta_didik pd
        LEFT JOIN anggota_rombel ar ON ar.peserta_didik_id = pd.peserta_didik_id
        LEFT JOIN rombongan_belajar rb ON rb.rombongan_belajar_id = ar.rombongan_belajar_id
        WHERE pd.peserta_didik_id IN (${placeholders})
        ORDER BY rb.nama ASC, pd.nama ASC
    `, peserta_didik_ids);

    // 6. Hitung total urutan global di seluruh sesi untuk nomor peserta yang unik
    const [totalSesiPeserta]: any = await pool.query("SELECT COUNT(*) as total FROM ujian_peserta WHERE ujian_id = ?", [ujianId]);
    let globalIndex = Number(totalSesiPeserta[0]?.total || 0);

    const conn = await pool.getConnection();
    try {
        await conn.beginTransaction();

        const insertValues = [];
        let roomMeja = currentRuangCount;

        for (const pd of pdList) {
            roomMeja++;
            const nomorPeserta = generateDynamicNomorPeserta(
                formatSegments,
                sesi.separator_nomor || '-',
                globalIndex,
                String(ruang.urutan || 1).padStart(2, '0')
            );
            globalIndex++;

            insertValues.push([
                ujianId,
                ruang_id,
                pd.peserta_didik_id,
                nomorPeserta,
                roomMeja,
                globalIndex,
                pd.nama_rombel || 'Umum'
            ]);
        }

        if (insertValues.length > 0) {
            await conn.query(`
                INSERT INTO ujian_peserta 
                (ujian_id, ruang_id, peserta_didik_id, nomor_peserta, nomor_meja, urutan_peserta, rombel_asal)
                VALUES ?
            `, [insertValues]);
        }

        await conn.commit();
        res.json({ 
            success: true, 
            count: insertValues.length,
            message: `Berhasil menambahkan ${insertValues.length} siswa ke ${ruang.nomor_ruang}!` 
        });
    } catch (err: any) {
        await conn.rollback();
        throw err;
    } finally {
        conn.release();
    }
}));

// 12. Auto-Distribute Students Across All Rooms in Exam Session (Max 20 per room, No Duplicates)
app.post("/api/ujian/sesi/:id/auto-distribusi", authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    const { id } = req.params;
    const { 
        rombel_ids = [], 
        reset_existing = true, 
        sort_by = 'rombel_nama', // 'rombel_nama' | 'nama_asc' | 'nisn_asc'
        auto_create_rooms = true,
        custom_room_count = 0
    } = req.body;

    const conn = await pool.getConnection();
    try {
        await conn.beginTransaction();

        // 1. Ambil Sesi & Format Nomor
        const [sesiRows]: any = await conn.query("SELECT * FROM ujian_sesi WHERE id = ? LIMIT 1", [id]);
        if (!sesiRows || sesiRows.length === 0) {
            return res.status(404).json({ error: "Sesi ujian tidak ditemukan." });
        }
        const sesi = sesiRows[0];
        let formatSegments: any[] = [];
        try {
            formatSegments = JSON.parse(sesi.format_nomor_peserta || '[]');
        } catch {
            formatSegments = [];
        }

        // 2. Ambil daftar siswa yang aktif
        let studentQuery = `
            SELECT DISTINCT
                pd.peserta_didik_id, 
                pd.nama, 
                pd.nisn, 
                COALESCE(NULLIF(TRIM(rpd.nipd), ''), NULLIF(TRIM(pd.nipd), ''), '') as nipd,
                pd.jenis_kelamin,
                rb.rombongan_belajar_id,
                rb.nama as nama_rombel,
                rb.tingkat as tingkat_rombel
            FROM peserta_didik pd
            LEFT JOIN (
                SELECT peserta_didik_id, MAX(nipd) as nipd 
                FROM registrasi_peserta_didik 
                WHERE (soft_delete = 0 OR soft_delete IS NULL) AND nipd IS NOT NULL AND TRIM(nipd) != '' 
                GROUP BY peserta_didik_id
            ) rpd ON rpd.peserta_didik_id = pd.peserta_didik_id
            JOIN anggota_rombel ar ON ar.peserta_didik_id = pd.peserta_didik_id
            JOIN rombongan_belajar rb ON rb.rombongan_belajar_id = ar.rombongan_belajar_id
            WHERE (pd.status_aktif = 1 OR pd.status_aktif IS NULL)
        `;

        const queryParams: any[] = [];
        if (Array.isArray(rombel_ids) && rombel_ids.length > 0) {
            studentQuery += ` AND rb.rombongan_belajar_id IN (${rombel_ids.map(() => '?').join(',')})`;
            queryParams.push(...rombel_ids);
        } else if (sesi.tingkat && sesi.tingkat !== 'Semua Tingkat' && sesi.tingkat !== 'Semua') {
            // Ekstrak digit angka atau string tingkat untuk fleksibilitas (misal "Kelas 6" -> match tingkat 6, VI, atau nama yang mengandung "6")
            const rawTingkat = String(sesi.tingkat).trim();
            const digitMatch = rawTingkat.match(/\d+/);
            const numStr = digitMatch ? digitMatch[0] : '';
            
            if (numStr) {
                studentQuery += ` AND (rb.tingkat = ? OR rb.tingkat = ? OR rb.nama LIKE ? OR rb.nama LIKE ?)`;
                queryParams.push(rawTingkat, numStr, `%${rawTingkat}%`, `%${numStr}%`);
            } else {
                studentQuery += ` AND (rb.tingkat = ? OR rb.nama LIKE ?)`;
                queryParams.push(rawTingkat, `%${rawTingkat}%`);
            }
        }

        // Jika tidak reset_existing, exclude siswa yang sudah terdaftar
        if (!reset_existing) {
            studentQuery += ` AND pd.peserta_didik_id NOT IN (SELECT peserta_didik_id FROM ujian_peserta WHERE ujian_id = ?)`;
            queryParams.push(id);
        }

        if (sort_by === 'nisn_asc') {
            studentQuery += ` ORDER BY pd.nisn ASC, pd.nama ASC`;
        } else if (sort_by === 'nama_asc') {
            studentQuery += ` ORDER BY pd.nama ASC`;
        } else {
            studentQuery += ` ORDER BY rb.nama ASC, pd.nama ASC`;
        }

        const [availableStudents]: any = await conn.query(studentQuery, queryParams);
        if (!availableStudents || availableStudents.length === 0) {
            return res.status(400).json({ 
                error: "Tidak ada data siswa yang ditemukan untuk kriteria sesi ujian ini. Pastikan data siswa & rombel telah tersedia!" 
            });
        }

        // 3. Ambil atau Buat Ruangan
        let [ruangList]: any = await conn.query("SELECT * FROM ujian_ruang WHERE ujian_id = ? ORDER BY urutan ASC, id ASC", [id]);
        const maxPerRuang = Math.min(Math.max(1, Number(sesi.max_peserta_per_ruang || 20)), 20); // Standar maks 20

        if ((!ruangList || ruangList.length === 0) && auto_create_rooms) {
            // Otomatis buat ruangan sesuai jumlah siswa yang ada
            const neededRooms = custom_room_count > 0 ? custom_room_count : Math.ceil(availableStudents.length / maxPerRuang);
            const roomInserts: any[] = [];
            for (let i = 1; i <= neededRooms; i++) {
                const roomNum = `Ruang ${String(i).padStart(2, '0')}`;
                roomInserts.push([id, roomNum, `Ruang Ujian ${String(i).padStart(2, '0')}`, maxPerRuang, i]);
            }
            if (roomInserts.length > 0) {
                await conn.query(`
                    INSERT INTO ujian_ruang (ujian_id, nomor_ruang, nama_ruang, kapasitas_maksimal, urutan)
                    VALUES ?
                `, [roomInserts]);
            }
            // Refresh ruangList
            [ruangList] = await conn.query("SELECT * FROM ujian_ruang WHERE ujian_id = ? ORDER BY urutan ASC, id ASC", [id]);
        }

        if (!ruangList || ruangList.length === 0) {
            return res.status(400).json({ 
                error: "Belum ada ruangan yang dibuat pada sesi ini. Silakan buat ruangan terlebih dahulu atau centang opsi 'Buat Ruangan Otomatis'." 
            });
        }

        if (reset_existing) {
            await conn.query("DELETE FROM ujian_peserta WHERE ujian_id = ?", [id]);
        }

        // 4. Hitung kapasitas tiap ruang
        let totalCapacity = ruangList.reduce((sum: number, r: any) => sum + Number(r.kapasitas_maksimal || maxPerRuang), 0);
        
        // Jika kapasitas masih kurang dan auto_create_rooms aktif, tambahkan ruangan baru secara otomatis
        if (availableStudents.length > totalCapacity && auto_create_rooms) {
            const deficit = availableStudents.length - totalCapacity;
            const extraRoomsNeeded = Math.ceil(deficit / maxPerRuang);
            const startOrder = ruangList.length + 1;
            const extraRoomInserts: any[] = [];
            for (let i = 0; i < extraRoomsNeeded; i++) {
                const rNum = `Ruang ${String(startOrder + i).padStart(2, '0')}`;
                extraRoomInserts.push([id, rNum, `Ruang Ujian ${String(startOrder + i).padStart(2, '0')}`, maxPerRuang, startOrder + i]);
            }
            if (extraRoomInserts.length > 0) {
                await conn.query(`
                    INSERT INTO ujian_ruang (ujian_id, nomor_ruang, nama_ruang, kapasitas_maksimal, urutan)
                    VALUES ?
                `, [extraRoomInserts]);
            }
            // Refresh ruangList
            [ruangList] = await conn.query("SELECT * FROM ujian_ruang WHERE ujian_id = ? ORDER BY urutan ASC, id ASC", [id]);
        }

        // 5. Alokasikan siswa ke ruangan (Max 20 per ruang, no duplicate)
        let studentIdx = 0;
        let globalIndex = 0;
        const insertValues: any[] = [];

        for (const ruang of ruangList) {
            const maxCap = Math.min(Math.max(1, Number(ruang.kapasitas_maksimal || maxPerRuang)), 20);
            
            // Cek jumlah siswa yang sudah ada jika tidak reset
            let existingInRoom = 0;
            if (!reset_existing) {
                const [curRoomCnt]: any = await conn.query("SELECT COUNT(*) as cnt FROM ujian_peserta WHERE ruang_id = ?", [ruang.id]);
                existingInRoom = Number(curRoomCnt[0]?.cnt || 0);
            }

            const roomSpace = Math.max(0, maxCap - existingInRoom);
            for (let seat = 1; seat <= roomSpace && studentIdx < availableStudents.length; seat++) {
                const s = availableStudents[studentIdx];
                const nomorMeja = existingInRoom + seat;
                
                const nomorPeserta = generateDynamicNomorPeserta(
                    formatSegments,
                    sesi.separator_nomor || '-',
                    globalIndex,
                    String(ruang.urutan || 1).padStart(2, '0')
                );

                insertValues.push([
                    id,
                    ruang.id,
                    s.peserta_didik_id,
                    nomorPeserta,
                    nomorMeja,
                    globalIndex + 1,
                    s.nama_rombel || 'Umum'
                ]);

                studentIdx++;
                globalIndex++;
            }
        }

        if (insertValues.length > 0) {
            await conn.query(`
                INSERT INTO ujian_peserta 
                (ujian_id, ruang_id, peserta_didik_id, nomor_peserta, nomor_meja, urutan_peserta, rombel_asal)
                VALUES ?
            `, [insertValues]);
        }

        await conn.commit();
        res.json({
            success: true,
            total_allocated: insertValues.length,
            total_students: availableStudents.length,
            total_rooms: ruangList.length,
            unallocated: Math.max(0, availableStudents.length - insertValues.length),
            message: `Berhasil mengalokasikan ${insertValues.length} siswa ke dalam ${ruangList.length} ruangan ujian!`
        });
    } catch (err: any) {
        await conn.rollback();
        throw err;
    } finally {
        conn.release();
    }
}));

// 13. Regenerate All Exam Participant Numbers in Session
app.post("/api/ujian/sesi/:id/regenerate-nomor", authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    const { id } = req.params;

    const conn = await pool.getConnection();
    try {
        await conn.beginTransaction();

        const [sesiRows]: any = await conn.query("SELECT * FROM ujian_sesi WHERE id = ? LIMIT 1", [id]);
        if (!sesiRows || sesiRows.length === 0) {
            return res.status(404).json({ error: "Sesi ujian tidak ditemukan." });
        }
        const sesi = sesiRows[0];
        let formatSegments: any[] = [];
        try {
            formatSegments = JSON.parse(sesi.format_nomor_peserta || '[]');
        } catch {
            formatSegments = [];
        }

        // Ambil semua peserta urut berdasarkan urutan ruang dan meja
        const [participants]: any = await conn.query(`
            SELECT p.id, p.ruang_id, r.urutan as ruang_urutan
            FROM ujian_peserta p
            JOIN ujian_ruang r ON r.id = p.ruang_id
            WHERE p.ujian_id = ?
            ORDER BY r.urutan ASC, p.nomor_meja ASC, p.id ASC
        `, [id]);

        for (let idx = 0; idx < participants.length; idx++) {
            const p = participants[idx];
            const nomorPeserta = generateDynamicNomorPeserta(
                formatSegments,
                sesi.separator_nomor || '-',
                idx,
                String(p.ruang_urutan || 1).padStart(2, '0')
            );

            await conn.query(`
                UPDATE ujian_peserta 
                SET nomor_peserta = ?, urutan_peserta = ?
                WHERE id = ?
            `, [nomorPeserta, idx + 1, p.id]);
        }

        await conn.commit();
        res.json({
            success: true,
            count: participants.length,
            message: `Berhasil mengenerate ulang nomor peserta untuk ${participants.length} siswa!`
        });
    } catch (err: any) {
        await conn.rollback();
        throw err;
    } finally {
        conn.release();
    }
}));

