// 16. Move Participant to Another Room
app.put("/api/ujian/peserta/:id/move", authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    const { id } = req.params;
    const { target_ruang_id } = req.body;

    if (!target_ruang_id) {
        return res.status(400).json({ error: "Target ruangan wajib dipilih!" });
    }

    // Cek kapasitas target ruang
    const [targetRuang]: any = await pool.query("SELECT * FROM ujian_ruang WHERE id = ? LIMIT 1", [target_ruang_id]);
    if (!targetRuang || targetRuang.length === 0) {
        return res.status(404).json({ error: "Target ruangan tidak ditemukan." });
    }

    const [cnt]: any = await pool.query("SELECT COUNT(*) as count FROM ujian_peserta WHERE ruang_id = ?", [target_ruang_id]);
    const currentCount = Number(cnt[0]?.count || 0);
    const maxCap = Number(targetRuang[0]?.kapasitas_maksimal || 20);

    if (currentCount >= maxCap) {
        return res.status(400).json({ error: `Ruangan ${targetRuang[0].nomor_ruang} sudah penuh (maksimal ${maxCap} siswa)!` });
    }

    const nextMeja = currentCount + 1;
    await pool.query("UPDATE ujian_peserta SET ruang_id = ?, nomor_meja = ? WHERE id = ?", [target_ruang_id, nextMeja, id]);

    res.json({ success: true, message: `Siswa berhasil dipindahkan ke ${targetRuang[0].nomor_ruang}!` });
}));

