// 17. Get Formatted PTK List (Dapodik 100% compliant with titles and NIP)
app.get("/api/ujian/ptk-list", authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    try {
        const [rows]: any = await pool.query(`
            SELECT 
                ptk_id,
                nama,
                gelar_depan,
                gelar_belakang,
                nip,
                nuptk,
                nik,
                jenis_kelamin,
                jenis_ptk_id_str,
                status_kepegawaian_id_str
            FROM ptk
            WHERE soft_delete = 0 OR soft_delete IS NULL OR soft_delete = '0' OR soft_delete = ''
            ORDER BY nama ASC
        `);

        const cleanStr = (s?: string | null) => (s || '').replace(/^[\s\-_–—]+/, '').trim();
        const isValidGelar = (g?: string | null) => {
            const c = cleanStr(g);
            return c !== '' && c !== '-' && c !== '--' && c !== '-.' && c !== 'null' && c !== 'undefined';
        };

        const ptkList = (rows || []).map((p: any) => {
            const rawName = cleanStr(p.nama);
            const gd = (p.gelar_depan || '').trim();
            const gb = (p.gelar_belakang || '').trim();

            let fullName = rawName;
            if (isValidGelar(gd) && !fullName.toLowerCase().startsWith(gd.toLowerCase())) {
                fullName = `${gd} ${fullName}`;
            }
            if (isValidGelar(gb)) {
                const cleanGb = gb.replace(/^,\s*/, '').trim();
                if (cleanGb && !fullName.toLowerCase().includes(cleanGb.toLowerCase())) {
                    fullName = `${fullName}, ${cleanGb}`;
                }
            }
            fullName = cleanStr(fullName);

            return {
                ptk_id: p.ptk_id,
                nama: rawName,
                fullName,
                gelar_depan: p.gelar_depan || '',
                gelar_belakang: p.gelar_belakang || '',
                nip: p.nip || '',
                nuptk: p.nuptk || '',
                nik: p.nik || '',
                jenis_kelamin: p.jenis_kelamin || 'L',
                jabatan: p.jenis_ptk_id_str || 'Guru',
                status_kepegawaian: p.status_kepegawaian_id_str || 'PNS'
            };
        });

        res.json({ success: true, data: ptkList });
    } catch (e: any) {
        console.error("Error fetching PTK list for exam proctor:", e);
        res.status(500).json({ success: false, error: e.message, data: [] });
    }
}));

