app.get("/api/ujian/sesi/:id/pengawas-jadwal", authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    const { id } = req.params;
    const { tanggal, ruang_id, ptk_id } = req.query;

    let query = `
        SELECT 
            j.*,
            r.nomor_ruang,
            r.nama_ruang,
            r.urutan as ruang_urutan,
            r.kapasitas_maksimal
        FROM ujian_pengawas_jadwal j
        JOIN ujian_ruang r ON r.id = j.ruang_id
        WHERE j.ujian_id = ?
    `;
    const params: any[] = [id];

    if (tanggal) {
        query += " AND j.tanggal = ?";
        params.push(tanggal);
    }
    if (ruang_id) {
        query += " AND j.ruang_id = ?";
        params.push(ruang_id);
    }
    if (ptk_id) {
        query += " AND (j.ptk_id_1 = ? OR j.ptk_id_2 = ?)";
        params.push(ptk_id, ptk_id);
    }

    query += " ORDER BY j.tanggal ASC, j.jam_mulai ASC, j.sesi_ke ASC, r.urutan ASC, r.id ASC";

    const [rows]: any = await pool.query(query, params);
    const cleanStr = (s?: string | null) => (s || '').replace(/^[\s\-_–—]+/, '').trim();

    const mappedRows = (rows || []).map((j: any) => ({
        ...j,
        pengawas_1: cleanStr(j.pengawas_1),
        pengawas_2: cleanStr(j.pengawas_2)
    }));

    // Hitung juga statistik rekap per pengawas
    const [rekapRows]: any = await pool.query(`
        SELECT 
            COALESCE(ptk_id_1, pengawas_1) as proctor_key,
            pengawas_1 as nama_pengawas,
            nip_pengawas_1 as nip,
            COUNT(*) as total_sesi
        FROM ujian_pengawas_jadwal
        WHERE ujian_id = ? AND pengawas_1 IS NOT NULL AND pengawas_1 != ''
        GROUP BY COALESCE(ptk_id_1, pengawas_1), pengawas_1, nip_pengawas_1
        ORDER BY total_sesi DESC, pengawas_1 ASC
    `, [id]);

    const mappedRekap = (rekapRows || []).map((r: any) => ({
        ...r,
        nama_pengawas: cleanStr(r.nama_pengawas)
    }));

    res.json({
        success: true,
        data: mappedRows,
        rekap: mappedRekap
    });
}));

