// 23. SMART RANDOMIZER & ROLLING PROCTOR AUTO-DISTRIBUTION
app.post("/api/ujian/sesi/:id/pengawas-jadwal/auto-distribusi", authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    const { id } = req.params;
    const {
        hari_list = [], // Array of { tanggal: 'YYYY-MM-DD', sesi_ke: 'Sesi 1', jam_mulai: '07:30', jam_selesai: '09:30', mata_pelajaran: 'Matematika' }
        ptk_list = [], // Array of { ptk_id, nama, fullName, nip }
        pengawas_per_ruang = 1, // 1 or 2
        reset_existing = true,
        acak_ruangan_tiap_hari = true
    } = req.body;

    if (!Array.isArray(hari_list) || hari_list.length === 0) {
        return res.status(400).json({ error: "Tentukan minimal 1 hari / jadwal tanggal pelaksanaan ujian!" });
    }

    if (!Array.isArray(ptk_list) || ptk_list.length === 0) {
        return res.status(400).json({ error: "Pilih minimal 1 guru/pegawai yang ditugaskan sebagai pengawas!" });
    }

    // 1. Ambil seluruh ruangan pada sesi ujian ini
    const [ruangList]: any = await pool.query(
        "SELECT id, nomor_ruang, nama_ruang, urutan FROM ujian_ruang WHERE ujian_id = ? ORDER BY urutan ASC, id ASC",
        [id]
    );

    if (!ruangList || ruangList.length === 0) {
        return res.status(400).json({ error: "Belum ada ruangan yang dibuat pada sesi ujian ini. Buat ruangan terlebih dahulu!" });
    }

    const conn = await pool.getConnection();
    try {
        await conn.beginTransaction();

        if (reset_existing) {
            await conn.query("DELETE FROM ujian_pengawas_jadwal WHERE ujian_id = ?", [id]);
        }

        // Shuffle helper (Fisher-Yates)
        const shuffleArray = (arr: any[]) => {
            const copy = [...arr];
            for (let i = copy.length - 1; i > 0; i--) {
                const j = Math.floor(Math.random() * (i + 1));
                [copy[i], copy[j]] = [copy[j], copy[i]];
            }
            return copy;
        };

        const totalRuang = ruangList.length;
        const totalSlotsNeededPerDay = totalRuang * Math.max(1, Number(pengawas_per_ruang) || 1);
        
        // Track beban tugas per guru untuk menjamin keadilan (fair distribution)
        const teacherWorkload: Record<string, number> = {};
        ptk_list.forEach((p: any) => {
            teacherWorkload[p.ptk_id || p.nama] = 0;
        });

        const insertValues: any[] = [];
        let rollingOffset = Math.floor(Math.random() * ptk_list.length);

        // Loop setiap slot hari / tanggal & jam sesi ujian
        for (let hIdx = 0; hIdx < hari_list.length; hIdx++) {
            const slot = hari_list[hIdx];
            const tanggal = slot.tanggal;
            const sesiKe = slot.sesi_ke || `Sesi ${hIdx + 1}`;
            const jamMulai = slot.jam_mulai || '07:30';
            const jamSelesai = slot.jam_selesai || '09:30';
            const mapel = slot.mata_pelajaran || '';

            // Hapus jadwal hari ini jika tidak full reset tapi mereplace tanggal ini
            if (!reset_existing) {
                await conn.query("DELETE FROM ujian_pengawas_jadwal WHERE ujian_id = ? AND tanggal = ? AND sesi_ke = ?", [id, tanggal, sesiKe]);
            }

            // Pilih pengawas untuk slot waktu ini:
            // Urutkan kandidat pengawas berdasarkan beban terendah, lalu beri sentuhan acak (rolling shuffle)
            let candidateProctors = [...ptk_list].sort((a, b) => {
                const wA = teacherWorkload[a.ptk_id || a.nama] || 0;
                const wB = teacherWorkload[b.ptk_id || b.nama] || 0;
                return wA - wB;
            });

            // Terapkan rolling shift agar rotasi bergerak antar ruang
            if (acak_ruangan_tiap_hari) {
                const chunkTop = candidateProctors.slice(0, Math.min(candidateProctors.length, totalSlotsNeededPerDay * 2));
                candidateProctors = shuffleArray(chunkTop).concat(candidateProctors.slice(chunkTop.length));
            }

            let proctorPointer = 0;
            const assignedInThisSlot = new Set<string>();

            // Iterasi untuk setiap ruangan
            for (let rIdx = 0; rIdx < ruangList.length; rIdx++) {
                const ruang = ruangList[rIdx];

                // Pengawas 1
                let p1 = null;
                for (let k = 0; k < candidateProctors.length; k++) {
                    const idx = (proctorPointer + k) % candidateProctors.length;
                    const cand = candidateProctors[idx];
                    const key = cand.ptk_id || cand.nama;
                    if (!assignedInThisSlot.has(key)) {
                        p1 = cand;
                        assignedInThisSlot.add(key);
                        teacherWorkload[key] = (teacherWorkload[key] || 0) + 1;
                        proctorPointer = (idx + 1) % candidateProctors.length;
                        break;
                    }
                }
                if (!p1) {
                    // Fallback jika jumlah guru lebih sedikit dari jumlah ruangan
                    p1 = candidateProctors[proctorPointer % candidateProctors.length];
                    proctorPointer++;
                }

                // Pengawas 2 (opsional jika pengawas_per_ruang >= 2)
                let p2 = null;
                if (pengawas_per_ruang >= 2) {
                    for (let k = 0; k < candidateProctors.length; k++) {
                        const idx = (proctorPointer + k) % candidateProctors.length;
                        const cand = candidateProctors[idx];
                        const key = cand.ptk_id || cand.nama;
                        if (!assignedInThisSlot.has(key)) {
                            p2 = cand;
                            assignedInThisSlot.add(key);
                            teacherWorkload[key] = (teacherWorkload[key] || 0) + 1;
                            proctorPointer = (idx + 1) % candidateProctors.length;
                            break;
                        }
                    }
                    if (!p2 && candidateProctors.length > 1) {
                        p2 = candidateProctors[proctorPointer % candidateProctors.length];
                        proctorPointer++;
                    }
                }

                const cleanStr = (s?: string | null) => (s || '').replace(/^[\s\-_–—]+/, '').trim();
                const p1Clean = cleanStr(p1?.fullName || p1?.nama || 'Pengawas Ruang');
                const p2Clean = p2 ? cleanStr(p2.fullName || p2.nama) : null;

                insertValues.push([
                    id,
                    ruang.id,
                    tanggal,
                    sesiKe,
                    jamMulai,
                    jamSelesai,
                    mapel || null,
                    p1?.ptk_id || null,
                    p1Clean,
                    p1?.nip || null,
                    p2?.ptk_id || null,
                    p2Clean,
                    p2?.nip || null,
                    'hadir',
                    p2 ? 'hadir' : null,
                    null
                ]);

                // Update juga pengawas default di tabel ruang jika ini hari pertama
                if (hIdx === 0) {
                    await conn.query(`
                        UPDATE ujian_ruang 
                        SET pengawas_1 = ?, pengawas_2 = ?
                        WHERE id = ?
                    `, [
                        p1Clean || null,
                        p2Clean || null,
                        ruang.id
                    ]);
                }
            }
        }

        if (insertValues.length > 0) {
            await conn.query(`
                INSERT INTO ujian_pengawas_jadwal
                (ujian_id, ruang_id, tanggal, sesi_ke, jam_mulai, jam_selesai, mata_pelajaran, ptk_id_1, pengawas_1, nip_pengawas_1, ptk_id_2, pengawas_2, nip_pengawas_2, status_hadir_1, status_hadir_2, catatan)
                VALUES ?
            `, [insertValues]);
        }

        await conn.commit();
        res.json({
            success: true,
            total_slots: insertValues.length,
            total_days: hari_list.length,
            total_rooms: ruangList.length,
            total_teachers: ptk_list.length,
            message: `Berhasil mengacak & mendistribusikan ${insertValues.length} jadwal pengawas untuk ${ruangList.length} ruangan selama ${hari_list.length} hari ujian!`
        });
    } catch (err: any) {
        await conn.rollback();
        console.error("Error auto distributing exam proctors:", err);
        throw err;
    } finally {
        conn.release();
    }
}));

