app.post("/api/ujian/sesi/:id/panitia", authenticate, asyncHandler(async (req: any, res: any) => {
    const { id } = req.params;
    const { jabatan_panitia, nama, nip, jabatan_dinas, uraian_tugas, urutan } = req.body;

    if (!nama || !nama.trim()) {
        return res.status(400).json({ success: false, message: "Nama personil panitia wajib diisi!" });
    }
    if (!jabatan_panitia || !jabatan_panitia.trim()) {
        return res.status(400).json({ success: false, message: "Jabatan dalam kepanitiaan wajib dipilih/diisi!" });
    }

    let nextUrutan = urutan;
    if (nextUrutan === undefined || nextUrutan === null || isNaN(nextUrutan)) {
        const [maxRows]: any = await pool.query(
            "SELECT COALESCE(MAX(urutan), 0) + 1 AS next_u FROM ujian_panitia WHERE ujian_id = ?",
            [id]
        );
        nextUrutan = maxRows?.[0]?.next_u || 1;
    }

    const [result]: any = await pool.query(`
        INSERT INTO ujian_panitia (ujian_id, jabatan_panitia, nama, nip, jabatan_dinas, uraian_tugas, urutan)
        VALUES (?, ?, ?, ?, ?, ?, ?)
    `, [
        id,
        jabatan_panitia.trim(),
        nama.trim(),
        nip ? nip.trim() : null,
        jabatan_dinas ? jabatan_dinas.trim() : null,
        uraian_tugas ? uraian_tugas.trim() : null,
        nextUrutan
    ]);

    res.json({
        success: true,
        id: result.insertId,
        message: "Anggota panitia berhasil ditambahkan!"
    });
}));

