const uploadUjianPelaporan = multer({
    storage: multer.diskStorage({
        destination: (req, file, cb) => {
            const dir = path.join(uploadDir, 'ujian');
            if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
            cb(null, dir);
        },
        filename: (req, file, cb) => {
            const ext = path.extname(file.originalname);
            cb(null, `laporan-${Date.now()}-${Math.round(Math.random() * 1E6)}${ext}`);
        }
    }),
    limits: { fileSize: 2 * 1024 * 1024 } // Maksimal 2MB per foto dokumentasi kegiatan
});

// Upload Single / Multiple Foto Kegiatan Ujian
app.post("/api/ujian/sesi/:id/pelaporan-upload", authenticate, (req: any, res: any) => {
    uploadUjianPelaporan.single('foto')(req, res, async (err: any) => {
        if (err) {
            console.error("Upload error:", err);
            if (err.code === 'LIMIT_FILE_SIZE') {
                return res.status(400).json({ error: "Ukuran foto melebihi batas maksimal 2 MB per foto!" });
            }
            return res.status(400).json({ error: err.message || "Gagal mengunggah foto kegiatan" });
        }
        if (!req.file) return res.status(400).json({ error: "Tidak ada berkas foto yang dipilih!" });

        let fileUrl = `/uploads/ujian/${req.file.filename}`;
        const gdLink = await uploadToGoogleDriveFallback(req.file.path, req.file.filename, req.file.mimetype, 'umum', 'Dokumentasi Pelaksanaan Ujian');
        if (gdLink) {
            fileUrl = gdLink;
        }

        res.json({ success: true, url: fileUrl, filename: req.file.filename });
    });
});

// GET Pelaporan Lengkap untuk Sesi Ujian (Config, Daftar Laporan Harian, & Rekapitulasi)
app.get("/api/ujian/sesi/:id/pelaporan", authenticate, asyncHandler(async (req: any, res: any) => {
    const { id } = req.params;
    const pool = getPool();

    // 1. Ambil config pelaporan dari sesi
    const [sesiRows]: any = await pool.query(
        "SELECT id, nama_ujian, tahun_ajaran, semester_id, tingkat, tanggal_mulai, tanggal_selesai, sk_panitia_config, pelaporan_config FROM ujian_sesi WHERE id = ?",
        [id]
    );
    if (!sesiRows || sesiRows.length === 0) {
        return res.status(404).json({ error: "Sesi ujian tidak ditemukan" });
    }
    const sesi = sesiRows[0];
    let pelaporanConfig = {};
    if (sesi.pelaporan_config) {
        try {
            pelaporanConfig = typeof sesi.pelaporan_config === 'string' ? JSON.parse(sesi.pelaporan_config) : sesi.pelaporan_config;
        } catch (e) {
            pelaporanConfig = {};
        }
    }

    // 2. Ambil seluruh pelaporan harian
    const [harianList]: any = await pool.query(
        "SELECT * FROM ujian_pelaporan_harian WHERE ujian_id = ? ORDER BY hari_ke ASC, tanggal ASC, id ASC",
        [id]
    );

    const parsedHarian = (harianList || []).map((row: any) => {
        let fotoList = [];
        if (row.foto_kegiatan) {
            try {
                fotoList = typeof row.foto_kegiatan === 'string' ? JSON.parse(row.foto_kegiatan) : row.foto_kegiatan;
            } catch (e) {
                fotoList = [];
            }
        }
        return {
            ...row,
            foto_kegiatan: Array.isArray(fotoList) ? fotoList : []
        };
    });

    // 3. Stats
    const [pRes]: any = await pool.query("SELECT COUNT(*) AS total FROM ujian_peserta WHERE ujian_id = ?", [id]);
    const totalPeserta = pRes[0]?.total || 0;
    const [rRes]: any = await pool.query("SELECT COUNT(*) AS total FROM ujian_ruang WHERE ujian_id = ?", [id]);
    const totalRuang = rRes[0]?.total || 0;
    const [panRes]: any = await pool.query("SELECT COUNT(*) AS total FROM ujian_panitia WHERE ujian_id = ?", [id]);
    const totalPanitia = panRes[0]?.total || 0;

    res.json({
        success: true,
        sesi,
        pelaporan_config: pelaporanConfig,
        harian_list: parsedHarian,
        stats: {
            total_hari: parsedHarian.length,
            total_peserta: totalPeserta,
            total_ruang: totalRuang,
            total_panitia: totalPanitia
        }
    });
}));

