app.post("/api/admin/siswa/bulk-photo-upload", authenticate, uploadBulkStudentPhotos.fields([
    { name: 'photos', maxCount: 500 },
    { name: 'zip_file', maxCount: 1 }
]), asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    const files = req.files || {};
    const photoFiles = files['photos'] || [];
    const zipFiles = files['zip_file'] || [];

    if (photoFiles.length === 0 && zipFiles.length === 0) {
        return res.status(400).json({ error: "Silakan pilih beberapa file foto (.jpg/.png) atau file arsip .ZIP berisi foto berpenamaan NISN!" });
    }

    await pool.query(`
        CREATE TABLE IF NOT EXISTS file_storage (
            id INT AUTO_INCREMENT PRIMARY KEY,
            data_id VARCHAR(255) NOT NULL,
            tipe_data VARCHAR(50) NOT NULL,
            kategori VARCHAR(50) NOT NULL,
            nama_file VARCHAR(255) NULL,
            server VARCHAR(500) NULL,
            drive VARCHAR(500) NULL,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            INDEX idx_data_lookup (data_id, tipe_data, kategori)
        )
    `);

    // Fetch all students map: nisn -> { peserta_didik_id, nama, nisn }
    const [allStudents]: any = await pool.query("SELECT peserta_didik_id, nisn, nipd, nama FROM peserta_didik");
    const nisnMap: Record<string, any> = {};
    const nipdMap: Record<string, any> = {};

    for (const s of allStudents || []) {
        if (s.nisn) {
            const cleanN = String(s.nisn).trim();
            nisnMap[cleanN] = s;
            nisnMap[cleanN.replace(/^0+/, '')] = s;
        }
        if (s.nipd) {
            const cleanP = String(s.nipd).trim();
            nipdMap[cleanP] = s;
        }
    }

    const matchedList: Array<{ nisn: string; nama: string; foto_url: string; peserta_didik_id: string }> = [];
    const unmatchedList: string[] = [];

    const processPhotoBuffer = async (originalName: string, bufferOrFilePath: Buffer | string) => {
        const ext = path.extname(originalName).toLowerCase();
        if (!['.jpg', '.jpeg', '.png', '.webp'].includes(ext)) {
            return;
        }

        const rawBase = path.basename(originalName, path.extname(originalName)).trim();
        const cleanKey = rawBase.replace(/[^a-zA-Z0-9_-]/g, '').trim();
        const student = nisnMap[cleanKey] || nisnMap[cleanKey.replace(/^0+/, '')] || nipdMap[cleanKey];

        if (!student) {
            unmatchedList.push(originalName);
            return;
        }

        const destFilename = `student-${student.nisn || student.peserta_didik_id}-${Date.now()}-${Math.round(Math.random() * 1E4)}${ext}`;
        const destPath = path.join(uploadDir, 'profiles', destFilename);
        const photoUrl = `/uploads/profiles/${destFilename}`;

        if (Buffer.isBuffer(bufferOrFilePath)) {
            fs.writeFileSync(destPath, bufferOrFilePath);
        } else {
            fs.copyFileSync(bufferOrFilePath, destPath);
        }

        // Save to file_storage & update peserta_didik
        await pool.query("DELETE FROM file_storage WHERE data_id = ? AND tipe_data = 'siswa' AND kategori = 'foto_profil'", [student.peserta_didik_id]);
        await pool.query(
            "INSERT INTO file_storage (data_id, tipe_data, kategori, nama_file, server) VALUES (?, 'siswa', 'foto_profil', ?, ?)",
            [student.peserta_didik_id, originalName, photoUrl]
        );

        try {
            await pool.query("UPDATE peserta_didik SET foto_profil = ? WHERE peserta_didik_id = ?", [photoUrl, student.peserta_didik_id]);
        } catch {}

        matchedList.push({
            nisn: student.nisn || cleanKey,
            nama: student.nama,
            foto_url: photoUrl,
            peserta_didik_id: student.peserta_didik_id
        });
    };

    // 1. Process direct photos
    for (const f of photoFiles) {
        await processPhotoBuffer(f.originalname, f.path);
        try { fs.unlinkSync(f.path); } catch {}
    }

    // 2. Process ZIP file if uploaded
    for (const zf of zipFiles) {
        try {
            const zip = new AdmZip(zf.path);
            const zipEntries = zip.getEntries();
            for (const entry of zipEntries) {
                if (!entry.isDirectory && !entry.entryName.startsWith('__MACOSX') && !entry.entryName.startsWith('.')) {
                    const originalName = path.basename(entry.entryName);
                    const buf = entry.getData();
                    await processPhotoBuffer(originalName, buf);
                }
            }
        } catch (zipErr) {
            console.error("Error reading ZIP file:", zipErr);
        } finally {
            try { fs.unlinkSync(zf.path); } catch {}
        }
    }

    res.json({
        success: true,
        message: `Berhasil memproses foto! ${matchedList.length} foto siswa berhasil dicocokkan dengan NISN & diperbarui.${unmatchedList.length > 0 ? ` (${unmatchedList.length} file tidak ditemukan NISN-nya di data Dapodik)` : ''}`,
        total_matched: matchedList.length,
        total_unmatched: unmatchedList.length,
        matched: matchedList,
        unmatched: unmatchedList
    });
}));

