async function ensureKokurikulerTables(poolParam?: any) {
    const pool = poolParam || getPool();
    try {
        await pool.query(`
            CREATE TABLE IF NOT EXISTS kokurikuler_kegiatan (
                id INT AUTO_INCREMENT PRIMARY KEY,
                nama_kegiatan VARCHAR(255) NOT NULL,
                kategori VARCHAR(100) NOT NULL DEFAULT 'Proyek Karakter P5',
                fase VARCHAR(50) NOT NULL DEFAULT 'Fase A',
                tingkat_pendidikan_id VARCHAR(20) DEFAULT NULL,
                rombongan_belajar_id VARCHAR(36) DEFAULT NULL,
                dimensi_fokus TEXT DEFAULT NULL,
                deskripsi_tujuan TEXT DEFAULT NULL,
                semester_id VARCHAR(10) DEFAULT '1',
                tahun_ajaran VARCHAR(20) DEFAULT '2026/2027',
                is_active TINYINT DEFAULT 1,
                created_by VARCHAR(100) DEFAULT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                INDEX idx_kokurikuler_rombel (rombongan_belajar_id),
                INDEX idx_kokurikuler_fase (fase)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
        `);
        await pool.query(`
            CREATE TABLE IF NOT EXISTS kokurikuler_nilai (
                id INT AUTO_INCREMENT PRIMARY KEY,
                kegiatan_id INT NOT NULL,
                peserta_didik_id VARCHAR(36) NOT NULL,
                nilai_karakter VARCHAR(20) DEFAULT 'BSH',
                catatan_karakter TEXT DEFAULT NULL,
                nilai_proses VARCHAR(20) DEFAULT 'BSH',
                catatan_proses TEXT DEFAULT NULL,
                nilai_hasil_karya VARCHAR(20) DEFAULT 'BSH',
                catatan_hasil_karya TEXT DEFAULT NULL,
                narasi_rapor TEXT DEFAULT NULL,
                guru_penilai_id VARCHAR(100) DEFAULT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                UNIQUE KEY uq_kegiatan_siswa (kegiatan_id, peserta_didik_id),
                INDEX idx_kn_kegiatan (kegiatan_id),
                INDEX idx_kn_siswa (peserta_didik_id)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
        `);
    } catch (e: any) {
        console.warn("[KOKURIKULER] ensureKokurikulerTables warning:", e.message);
    }
}

// 1. GET /api/kokurikuler/kegiatan - Ambil daftar kegiatan kokurikuler
app.get("/api/kokurikuler/kegiatan", authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    await ensureKokurikulerTables(pool);
    const { fase, kategori, rombongan_belajar_id, search, semester_id } = req.query;

    let conditions: string[] = ["1=1"];
    let params: any[] = [];

    if (fase && fase !== 'Semua') {
        conditions.push("kk.fase = ?");
        params.push(fase);
    }
    if (kategori && kategori !== 'Semua') {
        conditions.push("kk.kategori = ?");
        params.push(kategori);
    }
    if (rombongan_belajar_id && rombongan_belajar_id !== 'semua' && rombongan_belajar_id !== 'Semua') {
        let targetFase: string | null = null;
        try {
            const [rRows]: any = await pool.query(
                "SELECT tingkat, tingkat_pendidikan_id, nama FROM rombongan_belajar WHERE rombongan_belajar_id = ? OR id = ? LIMIT 1",
                [rombongan_belajar_id, rombongan_belajar_id]
            );
            if (rRows && rRows.length > 0) {
                const r = rRows[0];
                const rawT = r.tingkat || r.tingkat_pendidikan_id || (r.nama?.match(/\d+/)?.[0]);
                const tNum = rawT ? parseInt(String(rawT)) : null;
                if (tNum === 1 || tNum === 2) targetFase = 'Fase A';
                else if (tNum === 3 || tNum === 4) targetFase = 'Fase B';
                else if (tNum === 5 || tNum === 6) targetFase = 'Fase C';
                else if (tNum === 7 || tNum === 8 || tNum === 9) targetFase = 'Fase D';
                else if (tNum === 10) targetFase = 'Fase E';
                else if (tNum === 11 || tNum === 12) targetFase = 'Fase F';
                else if (tNum === 0) targetFase = 'Fase Fondasi';
            }
        } catch {}

        if (targetFase) {
            conditions.push("(kk.fase = ? AND (kk.rombongan_belajar_id = ? OR kk.rombongan_belajar_id IS NULL OR kk.rombongan_belajar_id = ''))");
            params.push(targetFase, rombongan_belajar_id);
        } else {
            conditions.push("(kk.rombongan_belajar_id = ?)");
            params.push(rombongan_belajar_id);
        }
    }
    if (semester_id) {
        conditions.push("kk.semester_id = ?");
        params.push(semester_id);
    }
    if (search && search.trim()) {
        conditions.push("(kk.nama_kegiatan LIKE ? OR kk.deskripsi_tujuan LIKE ?)");
        params.push(`%${search.trim()}%`, `%${search.trim()}%`);
    }

    const sql = `
        SELECT 
            kk.*,
            COALESCE(rb.nama, 'Semua Kelas / Rombel') as nama_rombel,
            (SELECT COUNT(DISTINCT kn.peserta_didik_id) FROM kokurikuler_nilai kn WHERE kn.kegiatan_id = kk.id) as total_dinilai
        FROM kokurikuler_kegiatan kk
        LEFT JOIN rombongan_belajar rb ON (kk.rombongan_belajar_id = rb.rombongan_belajar_id OR kk.rombongan_belajar_id = rb.id)
        WHERE ${conditions.join(" AND ")}
        ORDER BY kk.id DESC
    `;

    const [rows]: any = await pool.query(sql, params);
    res.json({ success: true, data: rows });
}));

