// 4. GET /api/kokurikuler/penilaian - Ambil daftar siswa per rombel beserta nilai 3 pilar kegiatan
app.get("/api/kokurikuler/penilaian", authenticate, asyncHandler(async (req: any, res: any) => {
    const pool = getPool();
    const { kegiatan_id, rombongan_belajar_id } = req.query;

    if (!kegiatan_id || !rombongan_belajar_id) {
        return res.status(400).json({ success: false, message: "Parameter kegiatan_id dan rombongan_belajar_id wajib diisi" });
    }

    // Ambil info kegiatan
    const [kegiatanRows]: any = await pool.query("SELECT * FROM kokurikuler_kegiatan WHERE id = ?", [kegiatan_id]);
    if (!kegiatanRows || kegiatanRows.length === 0) {
        return res.status(404).json({ success: false, message: "Kegiatan tidak ditemukan" });
    }

    // Ambil daftar siswa dari peserta_didik murni via anggota_rombel
    const sqlStudents = `
        SELECT 
            pd.peserta_didik_id,
            pd.nama,
            pd.nisn,
            pd.nik,
            pd.jenis_kelamin,
            pd.foto_profil,
            rpd.nipd,
            kn.id as nilai_id,
            kn.kegiatan_id,
            COALESCE(kn.nilai_karakter, '') as nilai_karakter,
            COALESCE(kn.catatan_karakter, '') as catatan_karakter,
            COALESCE(kn.nilai_proses, '') as nilai_proses,
            COALESCE(kn.catatan_proses, '') as catatan_proses,
            COALESCE(kn.nilai_hasil_karya, '') as nilai_hasil_karya,
            COALESCE(kn.catatan_hasil_karya, '') as catatan_hasil_karya,
            COALESCE(kn.narasi_rapor, '') as narasi_rapor,
            kn.updated_at as nilai_updated_at
        FROM anggota_rombel ar
        JOIN peserta_didik pd ON (ar.peserta_didik_id = pd.peserta_didik_id OR ar.peserta_didik_id = pd.id)
        LEFT JOIN registrasi_peserta_didik rpd ON (pd.peserta_didik_id = rpd.peserta_didik_id)
        LEFT JOIN kokurikuler_nilai kn ON (kn.peserta_didik_id = pd.peserta_didik_id AND kn.kegiatan_id = ?)
        WHERE ar.rombongan_belajar_id = ?
          AND (ar.soft_delete = 0 OR ar.soft_delete IS NULL OR ar.soft_delete = '0')
          AND (pd.soft_delete = 0 OR pd.soft_delete IS NULL OR pd.soft_delete = '0')
        ORDER BY pd.nama ASC
    `;

    const [studentRows]: any = await pool.query(sqlStudents, [kegiatan_id, rombongan_belajar_id]);

    res.json({
        success: true,
        kegiatan: kegiatanRows[0],
        students: studentRows
    });
}));

