// 4. Get RKA Items
app.get('/api/bosda/rka', authenticate, asyncHandler(async (req: any, res: any) => {
    const tahun = req.query.tahun ? String(req.query.tahun).trim() : new Date().getFullYear().toString();
    const kategori_id = req.query.kategori_id;
    const anggaran_id = req.query.anggaran_id ? Number(req.query.anggaran_id) : null;
    const pool = getPool();

    let sql = `
        SELECT 
            r.*, 
            k.nama_kategori,
            k.tipe_kategori,
            k.kode_rekening,
            k.anggaran_id as kategori_anggaran_id,
            parent.uraian_barang as parent_uraian,
            COALESCE(sub.total_terbelanja, 0) as qty_terbelanja,
            (r.volume - COALESCE(sub.total_terbelanja, 0)) as sisa_qty,
            (COALESCE(sub.total_terbelanja, 0) * r.harga_satuan) as realisasi_nominal,
            (r.total_pagu - (COALESCE(sub.total_terbelanja, 0) * r.harga_satuan)) as sisa_pagu
        FROM bosda_rka_item r
        JOIN bosda_kategori k ON k.id = r.kategori_id
        LEFT JOIN bosda_rka_item parent ON parent.id = r.parent_id
        LEFT JOIN (
            SELECT pi.rka_item_id, SUM(pi.volume) as total_terbelanja
            FROM bosda_pesanan_item pi
            JOIN bosda_pesanan p ON p.id = pi.pesanan_id
            WHERE p.status != 'dibatalkan'
            GROUP BY pi.rka_item_id
        ) sub ON sub.rka_item_id = r.id
        WHERE r.tahun_anggaran = ?
    `;
    const params: any[] = [tahun];
    if (anggaran_id) {
        sql += ` AND (r.anggaran_id = ? OR k.anggaran_id = ?)`;
        params.push(anggaran_id, anggaran_id);
    }
    if (kategori_id) {
        sql += ` AND r.kategori_id = ?`;
        params.push(kategori_id);
    }
    sql += ` ORDER BY k.urutan ASC, COALESCE(r.parent_id, r.id) ASC, r.is_header DESC, r.urutan ASC, r.id ASC`;

    const [rows]: any = await pool.execute(sql, params);
    res.json(rows);
}));

// 5. Upsert RKA Item (Direct Item or Judul Header)
app.post('/api/bosda/rka', authenticate, asyncHandler(async (req: any, res: any) => {
    const { id, kategori_id, anggaran_id, tahun_anggaran, uraian_barang, spesifikasi, volume, satuan, harga_satuan, urutan, parent_id, is_header } = req.body;
    if (!kategori_id || !uraian_barang || !uraian_barang.trim()) {
        return res.status(400).json({ error: 'Kategori dan Uraian / Nama Kegiatan wajib diisi' });
    }
    const tahun = tahun_anggaran ? String(tahun_anggaran).trim() : new Date().getFullYear().toString();
    const isHeaderVal = (is_header === 1 || is_header === true || is_header === '1') ? 1 : 0;
    const parentIdVal = isHeaderVal ? null : (parent_id ? Number(parent_id) : null);
    const vol = isHeaderVal ? 0 : (Number(volume) || 1);
    const sat = isHeaderVal ? '' : (satuan ? String(satuan).trim() : 'Pcs');
    const hrg = isHeaderVal ? 0 : (Number(harga_satuan) || 0);
    const totalPagu = isHeaderVal ? 0 : (vol * hrg);
    const spek = spesifikasi ? String(spesifikasi).trim() : '';
    const urt = Number(urutan) || 0;

    const pool = getPool();
    let angId = anggaran_id ? Number(anggaran_id) : null;
    if (!angId) {
        const [k]: any = await pool.execute('SELECT anggaran_id FROM bosda_kategori WHERE id = ?', [kategori_id]);
        if (k && k.length > 0) angId = k[0].anggaran_id;
    }

    // Validasi Pagu Anggaran: Total RKA tidak boleh melebihi Pagu Plafon Anggaran yang ditentukan
    if (!isHeaderVal && angId) {
        const [angRow]: any = await pool.execute('SELECT nama_anggaran, pagu_anggaran FROM bosda_sumber_anggaran WHERE id = ?', [angId]);
        if (angRow && angRow.length > 0) {
            const paguPlafon = Number(angRow[0].pagu_anggaran || 0);
            if (paguPlafon > 0) {
                let rkaCheckSql = `
                    SELECT COALESCE(SUM(total_pagu), 0) as current_total 
                    FROM bosda_rka_item 
                    WHERE (anggaran_id = ? OR kategori_id IN (SELECT id FROM bosda_kategori WHERE anggaran_id = ?)) 
                      AND tahun_anggaran = ? 
                      AND (is_header = 0 OR is_header IS NULL)
                `;
                const rkaCheckParams: any[] = [angId, angId, tahun];
                if (id) {
                    rkaCheckSql += ' AND id != ?';
                    rkaCheckParams.push(id);
                }
                const [curRka]: any = await pool.execute(rkaCheckSql, rkaCheckParams);
                const currentTotal = Number(curRka[0]?.current_total || 0);
                const prospectiveTotal = currentTotal + totalPagu;

                if (prospectiveTotal > paguPlafon) {
                    const kelebihan = prospectiveTotal - paguPlafon;
                    const sisaTersedia = Math.max(0, paguPlafon - currentTotal);
                    return res.status(400).json({
                        error: `Total RKA (Rp ${prospectiveTotal.toLocaleString('id-ID')}) melebihi batas Pagu Anggaran "${angRow[0].nama_anggaran}" (Rp ${paguPlafon.toLocaleString('id-ID')}). Maksimal tambahan nilai RKA yang diperbolehkan adalah Rp ${sisaTersedia.toLocaleString('id-ID')} (Kelebihan Rp ${kelebihan.toLocaleString('id-ID')}).`
                    });
                }
            }
        }
    }

    if (id) {
        await pool.execute(
            'UPDATE bosda_rka_item SET kategori_id = ?, anggaran_id = COALESCE(?, anggaran_id), uraian_barang = ?, spesifikasi = ?, volume = ?, satuan = ?, harga_satuan = ?, total_pagu = ?, urutan = ?, parent_id = ?, is_header = ?, updated_at = NOW() WHERE id = ?',
            [kategori_id, angId, uraian_barang.trim(), spek, vol, sat, hrg, totalPagu, urt, parentIdVal, isHeaderVal, id]
        );
        res.json({ success: true, message: isHeaderVal ? 'Judul Kelompok Belanja berhasil diperbarui' : 'Item RKA BOSDA berhasil diperbarui', id });
    } else {
        const [result]: any = await pool.execute(
            'INSERT INTO bosda_rka_item (kategori_id, anggaran_id, tahun_anggaran, uraian_barang, spesifikasi, volume, satuan, harga_satuan, total_pagu, urutan, parent_id, is_header) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
            [kategori_id, angId, tahun, uraian_barang.trim(), spek, vol, sat, hrg, totalPagu, urt, parentIdVal, isHeaderVal]
        );
        res.json({ success: true, message: isHeaderVal ? 'Judul Kelompok Belanja berhasil ditambahkan' : 'Item RKA BOSDA berhasil ditambahkan', id: result.insertId });
    }
}));

// 5b. Import Batch RKA Items (Header and Detail items from Excel)
app.post('/api/bosda/rka/import', authenticate, asyncHandler(async (req: any, res: any) => {
    const { anggaran_id, tahun_anggaran, default_kategori_id, items } = req.body;
    if (!Array.isArray(items) || items.length === 0) {
        return res.status(400).json({ error: 'Data impor kosong atau format tidak sesuai.' });
    }

    const tahun = tahun_anggaran ? String(tahun_anggaran).trim() : new Date().getFullYear().toString();
    const pool = getPool();
    let angId = anggaran_id ? Number(anggaran_id) : null;
    let defKatId = default_kategori_id ? Number(default_kategori_id) : null;

    if (!angId && defKatId) {
        const [k]: any = await pool.execute('SELECT anggaran_id FROM bosda_kategori WHERE id = ?', [defKatId]);
        if (k && k.length > 0 && k[0].anggaran_id) angId = Number(k[0].anggaran_id);
    }

    // 1. Calculate incoming pagu (hanya baris non-header)
    let incomingTotalPagu = 0;
    for (const row of items) {
        const isHdr = row.is_header === 1 || row.is_header === true || 
            String(row.jenis || '').toUpperCase().includes('JUDUL') || 
            String(row.jenis || '').toUpperCase().includes('HEADER') ||
            String(row.jenis || '').toUpperCase().includes('KELOMPOK');
        if (!isHdr) {
            const v = Math.max(0, Number(row.volume) || 0);
            const h = Math.max(0, Number(row.harga_satuan) || 0);
            incomingTotalPagu += (v * h);
        }
    }

    // 2. Validasi Pagu Plafon jika sumber anggaran dibatasi
    if (angId && incomingTotalPagu > 0) {
        const [angRow]: any = await pool.execute('SELECT nama_anggaran, pagu_anggaran FROM bosda_sumber_anggaran WHERE id = ?', [angId]);
        if (angRow && angRow.length > 0) {
            const paguPlafon = Number(angRow[0].pagu_anggaran || 0);
            if (paguPlafon > 0) {
                const [curRka]: any = await pool.execute(
                    `SELECT COALESCE(SUM(total_pagu), 0) as current_total 
                     FROM bosda_rka_item 
                     WHERE (anggaran_id = ? OR kategori_id IN (SELECT id FROM bosda_kategori WHERE anggaran_id = ?)) 
                       AND tahun_anggaran = ? 
                       AND (is_header = 0 OR is_header IS NULL)`,
                    [angId, angId, tahun]
                );
                const currentTotal = Number(curRka[0]?.current_total || 0);
                const prospectiveTotal = currentTotal + incomingTotalPagu;

                if (prospectiveTotal > paguPlafon) {
                    const kelebihan = prospectiveTotal - paguPlafon;
                    const sisaTersedia = Math.max(0, paguPlafon - currentTotal);
                    return res.status(400).json({
                        error: `Total RKA setelah import (Rp ${prospectiveTotal.toLocaleString('id-ID')}) melebihi batas Pagu Anggaran "${angRow[0].nama_anggaran}" (Rp ${paguPlafon.toLocaleString('id-ID')}). Maksimal tambahan nilai RKA yang diperbolehkan adalah Rp ${sisaTersedia.toLocaleString('id-ID')} (Kelebihan Rp ${kelebihan.toLocaleString('id-ID')}).`
                    });
                }
            }
        }
    }

    // 3. Ambil daftar kategori yang sudah ada
    let katQuery = 'SELECT id, nama_kategori, kode_rekening, tipe_kategori, urutan FROM bosda_kategori WHERE tahun_anggaran = ?';
    const katParams: any[] = [tahun];
    if (angId) {
        katQuery += ' AND anggaran_id = ?';
        katParams.push(angId);
    }
    const [existingKats]: any = await pool.execute(katQuery, katParams);
    const katMap = new Map<string, any>();
    existingKats.forEach((k: any) => {
        katMap.set(k.nama_kategori.toLowerCase().trim(), k);
        if (k.kode_rekening) katMap.set(k.kode_rekening.toLowerCase().trim(), k);
    });

    let nextKatUrutan = existingKats.reduce((max: number, k: any) => Math.max(max, Number(k.urutan || 0)), 0) + 1;

    // 4. Mulai Transaksi Database
    const conn = await pool.getConnection();
    try {
        await conn.beginTransaction();

        // Ambil header yang sudah ada di DB untuk anggaran & tahun ini
        const [existingHeaders]: any = await conn.execute(
            `SELECT id, kategori_id, uraian_barang FROM bosda_rka_item 
             WHERE tahun_anggaran = ? AND (is_header = 1 OR is_header = TRUE)`,
            [tahun]
        );
        const headerMap = new Map<string, number>();
        existingHeaders.forEach((h: any) => {
            const key = `${h.kategori_id}::${h.uraian_barang.toLowerCase().trim()}`;
            headerMap.set(key, h.id);
        });

        let totalHeaders = 0;
        let totalItems = 0;
        let lastCreatedHeaderId: number | null = null;
        let lastHeaderKategoriId: number | null = null;

        for (let idx = 0; idx < items.length; idx++) {
            const row = items[idx];
            const uraian = String(row.uraian_barang || '').trim();
            if (!uraian) continue;

            // Tentukan kategori_id
            let targetKatId = defKatId;
            const katStr = String(row.kategori || '').trim();
            if (katStr) {
                const normalizedKat = katStr.toLowerCase();
                if (katMap.has(normalizedKat)) {
                    targetKatId = katMap.get(normalizedKat).id;
                } else {
                    // Buat kategori baru secara otomatis
                    let detectedTipe = 'barang_jasa';
                    if (katStr.startsWith('5.2') || normalizedKat.includes('modal') || normalizedKat.includes('aset')) {
                        detectedTipe = 'modal';
                    } else if (katStr.startsWith('5.1.02.04') || normalizedKat.includes('dinas') || normalizedKat.includes('perjalanan')) {
                        detectedTipe = 'perjalanan_dinas';
                    }

                    const [newKatRes]: any = await conn.execute(
                        'INSERT INTO bosda_kategori (anggaran_id, tahun_anggaran, nama_kategori, tipe_kategori, kode_rekening, urutan) VALUES (?, ?, ?, ?, ?, ?)',
                        [angId, tahun, katStr, detectedTipe, String(row.kode_rekening || '').trim(), nextKatUrutan++]
                    );
                    targetKatId = newKatRes.insertId;
                    const newKatObj = { id: targetKatId, nama_kategori: katStr, kode_rekening: '', tipe_kategori: detectedTipe };
                    katMap.set(normalizedKat, newKatObj);
                }
            }

            if (!targetKatId) {
                // Fallback jika belum ada kategori sama sekali
                if (existingKats.length > 0) {
                    targetKatId = existingKats[0].id;
                } else {
                    const [defKatRes]: any = await conn.execute(
                        'INSERT INTO bosda_kategori (anggaran_id, tahun_anggaran, nama_kategori, tipe_kategori, urutan) VALUES (?, ?, ?, ?, ?)',
                        [angId, tahun, 'Belanja Barang dan Jasa Umum', 'barang_jasa', 1]
                    );
                    targetKatId = defKatRes.insertId;
                    existingKats.push({ id: targetKatId, nama_kategori: 'Belanja Barang dan Jasa Umum' });
                }
            }

            const isHeader = row.is_header === 1 || row.is_header === true ||
                String(row.jenis || '').toUpperCase().includes('JUDUL') ||
                String(row.jenis || '').toUpperCase().includes('HEADER') ||
                String(row.jenis || '').toUpperCase().includes('KELOMPOK');

            const spek = String(row.spesifikasi || '').trim();
            const urt = Number(row.urutan) || (idx + 1);

            if (isHeader) {
                // Simpan sebagai Header / Judul Kelompok
                const [insHeader]: any = await conn.execute(
                    'INSERT INTO bosda_rka_item (kategori_id, anggaran_id, tahun_anggaran, uraian_barang, spesifikasi, volume, satuan, harga_satuan, total_pagu, urutan, parent_id, is_header) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
                    [targetKatId, angId, tahun, uraian, spek, 0, '', 0, 0, urt, null, 1]
                );
                const headerId = insHeader.insertId;
                const key = `${targetKatId}::${uraian.toLowerCase()}`;
                headerMap.set(key, headerId);
                lastCreatedHeaderId = headerId;
                lastHeaderKategoriId = targetKatId;
                totalHeaders++;
            } else {
                // Rincian Item Belanja
                let parentId: number | null = null;
                const parentStr = String(row.kelompok || row.parent || '').trim();

                if (parentStr) {
                    const key = `${targetKatId}::${parentStr.toLowerCase()}`;
                    if (headerMap.has(key)) {
                        parentId = headerMap.get(key)!;
                    } else {
                        // Jika judul induk ditulis tapi belum pernah dibuat, otomatis buatkan judulnya!
                        const [insParent]: any = await conn.execute(
                            'INSERT INTO bosda_rka_item (kategori_id, anggaran_id, tahun_anggaran, uraian_barang, spesifikasi, volume, satuan, harga_satuan, total_pagu, urutan, parent_id, is_header) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
                            [targetKatId, angId, tahun, parentStr, '', 0, '', 0, 0, urt, null, 1]
                        );
                        parentId = insParent.insertId;
                        headerMap.set(key, parentId);
                        totalHeaders++;
                    }
                } else if (row.link_to_last_header && lastCreatedHeaderId && lastHeaderKategoriId === targetKatId) {
                    parentId = lastCreatedHeaderId;
                }

                const vol = Math.max(0, Number(row.volume) || 1);
                const sat = String(row.satuan || 'Pcs').trim() || 'Pcs';
                const hrg = Math.max(0, Number(row.harga_satuan) || 0);
                const totalPagu = vol * hrg;

                await conn.execute(
                    'INSERT INTO bosda_rka_item (kategori_id, anggaran_id, tahun_anggaran, uraian_barang, spesifikasi, volume, satuan, harga_satuan, total_pagu, urutan, parent_id, is_header) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
                    [targetKatId, angId, tahun, uraian, spek, vol, sat, hrg, totalPagu, urt, parentId, 0]
                );
                totalItems++;
            }
        }

        await conn.commit();
        res.json({
            success: true,
            message: `Berhasil mengimpor ${totalItems + totalHeaders} data RKA (${totalHeaders} Judul Kelompok & ${totalItems} Rincian Belanja).`,
            totalHeaders,
            totalItems,
            totalImported: totalHeaders + totalItems
        });
    } catch (err: any) {
        await conn.rollback();
        console.error('Error importing BOSDA RKA:', err);
        res.status(500).json({ error: 'Gagal mengimpor data RKA: ' + (err.message || 'Kesalahan database') });
    } finally {
        conn.release();
    }
}));

