// 8. Summary BOSDA (Pagu vs Belanja vs Sisa Saldo & Penerimaan)
app.get('/api/bosda/summary', authenticate, asyncHandler(async (req: any, res: any) => {
    const tahun = req.query.tahun ? String(req.query.tahun).trim() : new Date().getFullYear().toString();
    const anggaran_id = req.query.anggaran_id ? Number(req.query.anggaran_id) : null;
    const pool = getPool();

    await ensureDefaultBosdaCategories(tahun, anggaran_id || undefined);

    let katSql = `
        SELECT 
            k.id as kategori_id,
            k.anggaran_id,
            k.nama_kategori,
            k.tipe_kategori,
            k.kode_rekening,
            COALESCE(rka.total_pagu, 0) as pagu_kategori,
            COALESCE(terima.total_penerimaan, 0) as penerimaan_kategori,
            COALESCE(belanja.total_belanja, 0) as belanja_kategori,
            (COALESCE(rka.total_pagu, 0) - COALESCE(belanja.total_belanja, 0)) as sisa_kategori,
            (COALESCE(terima.total_penerimaan, 0) - COALESCE(belanja.total_belanja, 0)) as sisa_kas_kategori,
            COALESCE(rka.total_items, 0) as total_items,
            COALESCE(belanja.total_transaksi, 0) as total_transaksi,
            COALESCE(terima.total_transaksi, 0) as total_transaksi_penerimaan
        FROM bosda_kategori k
        LEFT JOIN (
            SELECT kategori_id, SUM(total_pagu) as total_pagu, COUNT(id) as total_items
            FROM bosda_rka_item
            WHERE tahun_anggaran = ? AND (is_header = 0 OR is_header IS NULL)
            GROUP BY kategori_id
        ) rka ON rka.kategori_id = k.id
        LEFT JOIN (
            SELECT kategori_id, SUM(nominal) as total_penerimaan, COUNT(DISTINCT penerimaan_id) as total_transaksi
            FROM (
                SELECT pk.kategori_id, pk.nominal, pk.penerimaan_id 
                FROM bosda_penerimaan_kategori pk
                JOIN bosda_penerimaan p ON p.id = pk.penerimaan_id
                WHERE p.tahun_anggaran = ? ${anggaran_id ? 'AND p.anggaran_id = ?' : ''}
                UNION ALL
                SELECT p.kategori_id, p.jumlah_dana as nominal, p.id as penerimaan_id
                FROM bosda_penerimaan p
                WHERE p.tahun_anggaran = ? AND p.tipe_penerimaan = 'kategori' AND p.kategori_id IS NOT NULL
                  ${anggaran_id ? 'AND p.anggaran_id = ?' : ''}
                  AND NOT EXISTS (SELECT 1 FROM bosda_penerimaan_kategori WHERE penerimaan_id = p.id)
            ) sub
            GROUP BY kategori_id
        ) terima ON terima.kategori_id = k.id
        LEFT JOIN (
            SELECT kategori_id, SUM(total_nominal) as total_belanja, COUNT(id) as total_transaksi
            FROM bosda_pesanan
            WHERE tahun_anggaran = ? AND status != 'dibatalkan'
            GROUP BY kategori_id
        ) belanja ON belanja.kategori_id = k.id
        WHERE k.tahun_anggaran = ?
    `;
    const katParams: any[] = [tahun];
    // terima params (union 1)
    katParams.push(tahun);
    if (anggaran_id) katParams.push(anggaran_id);
    // terima params (union 2)
    katParams.push(tahun);
    if (anggaran_id) katParams.push(anggaran_id);
    // belanja params
    katParams.push(tahun);
    // where k.tahun_anggaran
    katParams.push(tahun);

    if (anggaran_id) {
        katSql += ` AND k.anggaran_id = ?`;
        katParams.push(anggaran_id);
    }
    katSql += ` ORDER BY k.urutan ASC, k.id ASC`;

    const [katRows]: any = await pool.execute(katSql, katParams);

    let terimaSql = `
        SELECT 
            COALESCE(SUM(jumlah_dana), 0) as total_penerimaan,
            COUNT(id) as total_transaksi_penerimaan
        FROM bosda_penerimaan
        WHERE tahun_anggaran = ?
    `;
    const terimaParams: any[] = [tahun];
    if (anggaran_id) {
        terimaSql += ` AND anggaran_id = ?`;
        terimaParams.push(anggaran_id);
    }
    const [overallTerima]: any = await pool.execute(terimaSql, terimaParams);

    let katTerimaSql = `
        SELECT COALESCE(SUM(nominal), 0) as total_kategori
        FROM (
            SELECT pk.nominal 
            FROM bosda_penerimaan_kategori pk
            JOIN bosda_penerimaan p ON p.id = pk.penerimaan_id
            WHERE p.tahun_anggaran = ? ${anggaran_id ? 'AND p.anggaran_id = ?' : ''}
            UNION ALL
            SELECT p.jumlah_dana as nominal
            FROM bosda_penerimaan p
            WHERE p.tahun_anggaran = ? AND p.tipe_penerimaan = 'kategori' AND p.kategori_id IS NOT NULL
              ${anggaran_id ? 'AND p.anggaran_id = ?' : ''}
              AND NOT EXISTS (SELECT 1 FROM bosda_penerimaan_kategori WHERE penerimaan_id = p.id)
        ) sub
    `;
    const katTerimaParams: any[] = [tahun];
    if (anggaran_id) katTerimaParams.push(anggaran_id);
    katTerimaParams.push(tahun);
    if (anggaran_id) katTerimaParams.push(anggaran_id);
    const [katTerimaResult]: any = await pool.execute(katTerimaSql, katTerimaParams);

    const totalPagu = katRows.reduce((acc: number, k: any) => acc + Number(k.pagu_kategori || 0), 0);
    const totalBelanja = katRows.reduce((acc: number, k: any) => acc + Number(k.belanja_kategori || 0), 0);
    const totalPenerimaan = Number(overallTerima[0]?.total_penerimaan || 0);
    const totalPenerimaanKategori = Number(katTerimaResult[0]?.total_kategori || 0);
    const totalPenerimaanGlobal = Math.max(0, totalPenerimaan - totalPenerimaanKategori);
    const totalPenerimaanCount = Number(overallTerima[0]?.total_transaksi_penerimaan || 0);
    const sisaSaldo = totalPagu - totalBelanja;
    const sisaKas = totalPenerimaan - totalBelanja;
    const totalItems = katRows.reduce((acc: number, k: any) => acc + Number(k.total_items || 0), 0);
    const totalPesanan = katRows.reduce((acc: number, k: any) => acc + Number(k.total_transaksi || 0), 0);

    let paguPlafonAnggaran = 0;
    if (anggaran_id) {
        const [aRow]: any = await pool.execute('SELECT pagu_anggaran FROM bosda_sumber_anggaran WHERE id = ?', [anggaran_id]);
        if (aRow && aRow.length > 0) paguPlafonAnggaran = Number(aRow[0].pagu_anggaran || 0);
    } else {
        const [aDef]: any = await pool.execute('SELECT pagu_anggaran FROM bosda_sumber_anggaran WHERE tahun_anggaran = ? ORDER BY is_default DESC, id ASC LIMIT 1', [tahun]);
        if (aDef && aDef.length > 0) paguPlafonAnggaran = Number(aDef[0].pagu_anggaran || 0);
    }

    const sisaPlafonPagu = paguPlafonAnggaran > 0 ? (paguPlafonAnggaran - totalPagu) : 0;
    const persentaseAlokasiRka = paguPlafonAnggaran > 0 ? Number(((totalPagu / paguPlafonAnggaran) * 100).toFixed(1)) : 0;

    // Penerimaan Bank vs Tunai
    let bankSql = `SELECT COALESCE(SUM(jumlah_dana), 0) as bank_masuk FROM bosda_penerimaan WHERE tahun_anggaran = ? AND (metode_penerimaan = 'transfer' OR metode_penerimaan IS NULL OR metode_penerimaan = '')`;
    let tunaiSql = `SELECT COALESCE(SUM(jumlah_dana), 0) as tunai_masuk FROM bosda_penerimaan WHERE tahun_anggaran = ? AND metode_penerimaan = 'tunai'`;
    const bParams: any[] = [tahun];
    const tParams: any[] = [tahun];
    if (anggaran_id) {
        bankSql += ` AND anggaran_id = ?`;
        tunaiSql += ` AND anggaran_id = ?`;
        bParams.push(anggaran_id);
        tParams.push(anggaran_id);
    }
    const [bankRow]: any = await pool.execute(bankSql, bParams);
    const [tunaiRow]: any = await pool.execute(tunaiSql, tParams);
    const kasBankMasuk = Number(bankRow[0]?.bank_masuk || 0);
    const kasTunaiMasuk = Number(tunaiRow[0]?.tunai_masuk || 0);

    // Mutasi Kas (Tarik Tunai Bank & Setor Bank)
    let mutasiSql = `SELECT tipe_mutasi, COALESCE(SUM(jumlah), 0) as total FROM bosda_mutasi_kas WHERE tahun_anggaran = ?`;
    const mParams: any[] = [tahun];
    if (anggaran_id) {
        mutasiSql += ` AND anggaran_id = ?`;
        mParams.push(anggaran_id);
    }
    mutasiSql += ` GROUP BY tipe_mutasi`;
    let mutasiTarikTunai = 0;
    let mutasiSetorBank = 0;
    try {
        const [mutasiRows]: any = await pool.execute(mutasiSql, mParams);
        for (const m of (mutasiRows || [])) {
            if (m.tipe_mutasi === 'tarik_tunai') mutasiTarikTunai = Number(m.total || 0);
            if (m.tipe_mutasi === 'setor_bank' || m.tipe_mutasi === 'setor_tunai') mutasiSetorBank += Number(m.total || 0);
        }
    } catch (_) {}

    // Belanja yang sudah dibayar (Transfer vs Tunai)
    let pesPaidSql = `SELECT metode_pembayaran, COALESCE(SUM(total_nominal), 0) as total FROM bosda_pesanan WHERE tahun_anggaran = ? AND status_pembayaran = 'dibayar'`;
    const pPaidParams: any[] = [tahun];
    if (anggaran_id) {
        pesPaidSql += ` AND anggaran_id = ?`;
        pPaidParams.push(anggaran_id);
    }
    pesPaidSql += ` GROUP BY metode_pembayaran`;
    let belanjaBankPaid = 0;
    let belanjaTunaiPaid = 0;
    try {
        const [paidRows]: any = await pool.execute(pesPaidSql, pPaidParams);
        for (const pr of (paidRows || [])) {
            if (pr.metode_pembayaran === 'tunai') belanjaTunaiPaid = Number(pr.total || 0);
            else belanjaBankPaid += Number(pr.total || 0);
        }
    } catch (_) {}

    // Belanja belum dibayar
    let pesUnpaidSql = `SELECT COALESCE(SUM(total_nominal), 0) as total FROM bosda_pesanan WHERE tahun_anggaran = ? AND (status_pembayaran = 'belum_bayar' OR status_pembayaran IS NULL OR status_pembayaran = '' OR status_pembayaran = 'direturn') AND status != 'dibatalkan'`;
    const pUnpaidParams: any[] = [tahun];
    if (anggaran_id) {
        pesUnpaidSql += ` AND anggaran_id = ?`;
        pUnpaidParams.push(anggaran_id);
    }
    let totalBelanjaBelumBayar = 0;
    try {
        const [unpaidRow]: any = await pool.execute(pesUnpaidSql, pUnpaidParams);
        totalBelanjaBelumBayar = Number(unpaidRow[0]?.total || 0);
    } catch (_) {}
    const totalBelanjaDibayar = belanjaBankPaid + belanjaTunaiPaid;

    const saldoKasBank = kasBankMasuk - mutasiTarikTunai + mutasiSetorBank - belanjaBankPaid;
    const saldoKasTunai = kasTunaiMasuk + mutasiTarikTunai - mutasiSetorBank - belanjaTunaiPaid;
    const saldoKasTotal = saldoKasBank + saldoKasTunai;

    res.json({
        tahun_anggaran: tahun,
        anggaran_id: anggaran_id,
        pagu_anggaran: paguPlafonAnggaran,
        sisa_plafon_pagu: sisaPlafonPagu,
        persentase_alokasi_rka: persentaseAlokasiRka,
        total_pagu: totalPagu,
        total_penerimaan: totalPenerimaan,
        total_penerimaan_global: totalPenerimaanGlobal,
        total_penerimaan_kategori: totalPenerimaanKategori,
        total_penerimaan_count: totalPenerimaanCount,
        total_belanja: totalBelanja,
        total_belanja_dibayar: totalBelanjaDibayar,
        total_belanja_belum_bayar: totalBelanjaBelumBayar,
        belanja_bank_paid: belanjaBankPaid,
        belanja_tunai_paid: belanjaTunaiPaid,
        kas_bank_masuk: kasBankMasuk,
        kas_tunai_masuk: kasTunaiMasuk,
        mutasi_tarik_tunai: mutasiTarikTunai,
        mutasi_setor_bank: mutasiSetorBank,
        saldo_kas_bank: saldoKasBank,
        saldo_kas_tunai: saldoKasTunai,
        saldo_kas_total: saldoKasTotal,
        sisa_saldo: sisaSaldo,
        sisa_saldo_kas: sisaKas,
        sisa_pagu: sisaSaldo,
        persentase_penyerapan: totalPagu > 0 ? Number(((totalBelanja / totalPagu) * 100).toFixed(1)) : 0,
        persentase_penerimaan: totalPagu > 0 ? Number(((totalPenerimaan / totalPagu) * 100).toFixed(1)) : 0,
        total_items: totalItems,
        total_pesanan: totalPesanan,
        kategori: katRows
    });
}));

// 8. List Pesanan BOSDA
app.get('/api/bosda/pesanan', authenticate, asyncHandler(async (req: any, res: any) => {
    const tahun = req.query.tahun ? String(req.query.tahun).trim() : new Date().getFullYear().toString();
    const anggaran_id = req.query.anggaran_id ? Number(req.query.anggaran_id) : null;
    const kategori_id = req.query.kategori_id;
    const status = req.query.status;
    const pool = getPool();

    let sql = `
        SELECT 
            p.*,
            k.nama_kategori,
            k.tipe_kategori,
            k.kode_rekening,
            k.anggaran_id as kategori_anggaran_id,
            (SELECT COUNT(*) FROM bosda_bukti_fisik bf WHERE bf.pesanan_id = p.id) as total_bukti_fisik,
            (SELECT COUNT(*) FROM bosda_pesanan_item pi WHERE pi.pesanan_id = p.id) as total_items,
            (SELECT COUNT(*) FROM bosda_pesanan_pegawai pp WHERE pp.pesanan_id = p.id) as total_pegawai
        FROM bosda_pesanan p
        JOIN bosda_kategori k ON k.id = p.kategori_id
        WHERE p.tahun_anggaran = ?
    `;
    const params: any[] = [tahun];
    if (anggaran_id) {
        sql += ` AND (p.anggaran_id = ? OR k.anggaran_id = ?)`;
        params.push(anggaran_id, anggaran_id);
    }
    if (kategori_id) {
        sql += ` AND p.kategori_id = ?`;
        params.push(kategori_id);
    }
    if (status) {
        sql += ` AND p.status = ?`;
        params.push(status);
    }
    sql += ` ORDER BY p.tanggal_pesanan DESC, p.id DESC`;

    const [rows]: any = await pool.execute(sql, params);
    if (rows && rows.length > 0) {
        const pesananIds = rows.map((r: any) => r.id);
        const [items]: any = await pool.query(
            `SELECT * FROM bosda_pesanan_item WHERE pesanan_id IN (?) ORDER BY id ASC`,
            [pesananIds]
        );
        const [pegawai]: any = await pool.query(
            `SELECT * FROM bosda_pesanan_pegawai WHERE pesanan_id IN (?) ORDER BY id ASC`,
            [pesananIds]
        );
        const [bukti]: any = await pool.query(
            `SELECT * FROM bosda_bukti_fisik WHERE pesanan_id IN (?) ORDER BY id ASC`,
            [pesananIds]
        );

        const itemsMap: Record<number, any[]> = {};
        const pegawaiMap: Record<number, any[]> = {};
        const buktiMap: Record<number, any[]> = {};

        for (const it of (items || [])) {
            if (!itemsMap[it.pesanan_id]) itemsMap[it.pesanan_id] = [];
            itemsMap[it.pesanan_id].push(it);
        }
        for (const pg of (pegawai || [])) {
            if (!pegawaiMap[pg.pesanan_id]) pegawaiMap[pg.pesanan_id] = [];
            pegawaiMap[pg.pesanan_id].push(pg);
        }
        for (const bf of (bukti || [])) {
            if (!buktiMap[bf.pesanan_id]) buktiMap[bf.pesanan_id] = [];
            buktiMap[bf.pesanan_id].push(bf);
        }

        for (const r of rows) {
            r.items = itemsMap[r.id] || [];
            r.pegawai = pegawaiMap[r.id] || [];
            r.bukti_fisik = buktiMap[r.id] || [];
        }
    }
    res.json(rows);
}));

