app.get('/api/bosda/pesanan/:id', authenticate, asyncHandler(async (req: any, res: any) => {
    const { id } = req.params;
    const pool = getPool();

    const [pesanan]: any = await pool.execute(`
        SELECT p.*, k.nama_kategori, k.tipe_kategori, k.kode_rekening, k.anggaran_id as kategori_anggaran_id
        FROM bosda_pesanan p
        JOIN bosda_kategori k ON k.id = p.kategori_id
        WHERE p.id = ?
    `, [id]);

    if (!pesanan || pesanan.length === 0) {
        return res.status(404).json({ error: 'Data pesanan tidak ditemukan' });
    }

    const [items]: any = await pool.execute('SELECT * FROM bosda_pesanan_item WHERE pesanan_id = ? ORDER BY id ASC', [id]);
    const [pegawai]: any = await pool.execute('SELECT * FROM bosda_pesanan_pegawai WHERE pesanan_id = ? ORDER BY id ASC', [id]);
    const [bukti]: any = await pool.execute('SELECT * FROM bosda_bukti_fisik WHERE pesanan_id = ? ORDER BY id ASC', [id]);

    res.json({
        ...pesanan[0],
        items: items || [],
        pegawai: pegawai || [],
        bukti_fisik: bukti || []
    });
}));

// 10. Create / Update Pesanan BOSDA
app.post('/api/bosda/pesanan', authenticate, asyncHandler(async (req: any, res: any) => {
    const {
        id, anggaran_id, tahun_anggaran, kategori_id, nomor_pesanan, tanggal_pesanan, nama_kegiatan, tipe,
        nama_toko, nama_pemilik, alamat_toko, telepon_toko, npwp_toko, nomor_rekening, bank_toko,
        maksud_tujuan, tempat_berangkat, tempat_tujuan, tanggal_berangkat, tanggal_kembali, lama_hari, dasar_surat_tugas,
        nomor_bast, tanggal_bast, nama_penerima, nip_penerima, status, catatan,
        items, pegawai
    } = req.body;

    if (!kategori_id || !nama_kegiatan || !nama_kegiatan.trim()) {
        return res.status(400).json({ error: 'Kategori dan Nama Kegiatan / Keperluan wajib diisi' });
    }

    const tahun = tahun_anggaran ? String(tahun_anggaran).trim() : new Date().getFullYear().toString();
    const noPesanan = nomor_pesanan && nomor_pesanan.trim() ? nomor_pesanan.trim() : `027/${Date.now().toString().slice(-4)}/SP-BOSDA/${tahun}`;
    const tglPesanan = tanggal_pesanan || new Date().toISOString().split('T')[0];
    const stat = status || 'dipesan';

    let totalNominal = 0;
    if (Array.isArray(items) && items.length > 0) {
        totalNominal = items.reduce((acc: number, it: any) => acc + (Number(it.volume || 0) * Number(it.harga_satuan || 0)), 0);
    } else if (Array.isArray(pegawai) && pegawai.length > 0) {
        totalNominal = pegawai.reduce((acc: number, pg: any) => acc + Number(pg.total_diterima || ((Number(pg.biaya_transport || 0) + Number(pg.uang_harian || 0)))), 0);
    }

    const pool = getPool();
    let angId = anggaran_id ? Number(anggaran_id) : null;
    if (!angId) {
        const [k]: any = await pool.execute('SELECT anggaran_id FROM bosda_kategori WHERE id = ?', [kategori_id]);
        if (k && k.length > 0) angId = k[0].anggaran_id;
    }

    let pesananId = id;

    if (id) {
        const [existingPes]: any = await pool.execute('SELECT status FROM bosda_pesanan WHERE id = ?', [id]);
        if (existingPes && existingPes.length > 0 && existingPes[0].status === 'selesai') {
            return res.status(400).json({ error: 'Pesanan ini sudah selesai dan Berita Acara (BAST) telah disetujui. Data pesanan terkunci dan tidak dapat diedit kembali.' });
        }

        await pool.execute(`
            UPDATE bosda_pesanan SET
                anggaran_id = COALESCE(?, anggaran_id), kategori_id = ?, nomor_pesanan = ?, tanggal_pesanan = ?, nama_kegiatan = ?, tipe = ?,
                nama_toko = ?, nama_pemilik = ?, alamat_toko = ?, telepon_toko = ?, npwp_toko = ?, nomor_rekening = ?, bank_toko = ?,
                maksud_tujuan = ?, tempat_berangkat = ?, tempat_tujuan = ?, tanggal_berangkat = ?, tanggal_kembali = ?, lama_hari = ?, dasar_surat_tugas = ?,
                nomor_bast = ?, tanggal_bast = ?, nama_penerima = ?, nip_penerima = ?, status = ?, total_nominal = ?, catatan = ?,
                updated_at = NOW()
            WHERE id = ?
        `, [
            angId, kategori_id, noPesanan, tglPesanan, nama_kegiatan.trim(), tipe || 'barang_jasa',
            nama_toko || '', nama_pemilik || '', alamat_toko || '', telepon_toko || '', npwp_toko || '', nomor_rekening || '', bank_toko || '',
            maksud_tujuan || '', tempat_berangkat || '', tempat_tujuan || '', tanggal_berangkat || null, tanggal_kembali || null, Number(lama_hari) || 1, dasar_surat_tugas || '',
            nomor_bast || '', tanggal_bast || null, nama_penerima || '', nip_penerima || '', stat, totalNominal, catatan || '',
            id
        ]);

        await pool.execute('DELETE FROM bosda_pesanan_item WHERE pesanan_id = ?', [id]);
        await pool.execute('DELETE FROM bosda_pesanan_pegawai WHERE pesanan_id = ?', [id]);
    } else {
        const [result]: any = await pool.execute(`
            INSERT INTO bosda_pesanan (
                anggaran_id, tahun_anggaran, kategori_id, nomor_pesanan, tanggal_pesanan, nama_kegiatan, tipe,
                nama_toko, nama_pemilik, alamat_toko, telepon_toko, npwp_toko, nomor_rekening, bank_toko,
                maksud_tujuan, tempat_berangkat, tempat_tujuan, tanggal_berangkat, tanggal_kembali, lama_hari, dasar_surat_tugas,
                nomor_bast, tanggal_bast, nama_penerima, nip_penerima, status, total_nominal, catatan
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `, [
            angId, tahun, kategori_id, noPesanan, tglPesanan, nama_kegiatan.trim(), tipe || 'barang_jasa',
            nama_toko || '', nama_pemilik || '', alamat_toko || '', telepon_toko || '', npwp_toko || '', nomor_rekening || '', bank_toko || '',
            maksud_tujuan || '', tempat_berangkat || '', tempat_tujuan || '', tanggal_berangkat || null, tanggal_kembali || null, Number(lama_hari) || 1, dasar_surat_tugas || '',
            nomor_bast || '', tanggal_bast || null, nama_penerima || '', nip_penerima || '', stat, totalNominal, catatan || ''
        ]);
        pesananId = result.insertId;
    }

    // Auto-register / sync toko in bosda_rekanan if provided
    if (nama_toko && String(nama_toko).trim()) {
        try {
            const tokoTrim = String(nama_toko).trim();
            const [existRek]: any = await pool.execute('SELECT id FROM bosda_rekanan WHERE nama_toko = ?', [tokoTrim]);
            if (existRek.length === 0) {
                await pool.execute(
                    'INSERT INTO bosda_rekanan (nama_toko, nama_pemilik, alamat_toko, telepon_toko, npwp_toko, nomor_rekening, bank_toko) VALUES (?, ?, ?, ?, ?, ?, ?)',
                    [tokoTrim, nama_pemilik || '', alamat_toko || '', telepon_toko || '', npwp_toko || '', nomor_rekening || '', bank_toko || '']
                );
            }
        } catch (_) {}
    }

    if (Array.isArray(items) && items.length > 0) {
        for (const it of items) {
            const v = Number(it.volume) || 1;
            const h = Number(it.harga_satuan) || 0;
            await pool.execute(
                'INSERT INTO bosda_pesanan_item (pesanan_id, rka_item_id, uraian_barang, spesifikasi, volume, satuan, harga_satuan, total_harga) VALUES (?, ?, ?, ?, ?, ?, ?, ?)',
                [pesananId, it.rka_item_id || null, it.uraian_barang || 'Barang', it.spesifikasi || '', v, it.satuan || 'Pcs', h, v * h]
            );
        }
    }

    if (Array.isArray(pegawai) && pegawai.length > 0) {
        for (const pg of pegawai) {
            const bTransport = Number(pg.biaya_transport) || 0;
            const uHarian = Number(pg.uang_harian) || 0;
            const tot = pg.total_diterima ? Number(pg.total_diterima) : (bTransport + uHarian);
            await pool.execute(
                'INSERT INTO bosda_pesanan_pegawai (pesanan_id, ptk_id, nama_pegawai, nip, pangkat_golongan, jabatan, biaya_transport, uang_harian, total_diterima) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)',
                [pesananId, pg.ptk_id || null, pg.nama_pegawai || '', pg.nip || '', pg.pangkat_golongan || '', pg.jabatan || '', bTransport, uHarian, tot]
            );
        }
    }

    res.json({ success: true, message: 'Pesanan / Transaksi BOSDA berhasil disimpan', id: pesananId });
}));

