app.delete('/api/bosda/pesanan/:id', authenticate, asyncHandler(async (req: any, res: any) => {
    const { id } = req.params;
    const pool = getPool();

    const [existingPes]: any = await pool.execute('SELECT status FROM bosda_pesanan WHERE id = ?', [id]);
    if (existingPes && existingPes.length > 0 && existingPes[0].status === 'selesai') {
        return res.status(400).json({ error: 'Pesanan ini sudah selesai dan Berita Acara (BAST) telah disetujui. Pesanan yang sudah selesai tidak dapat dihapus.' });
    }

    const [files]: any = await pool.execute('SELECT file_url FROM bosda_bukti_fisik WHERE pesanan_id = ?', [id]);
    for (const f of files || []) {
        try {
            if (f.file_url) {
                const localPath = path.join(process.cwd(), f.file_url.replace(/^\//, ''));
                if (fs.existsSync(localPath)) fs.unlinkSync(localPath);
            }
        } catch (_) {}
    }

    await pool.execute('DELETE FROM bosda_bukti_fisik WHERE pesanan_id = ?', [id]);
    await pool.execute('DELETE FROM bosda_pesanan_item WHERE pesanan_id = ?', [id]);
    await pool.execute('DELETE FROM bosda_pesanan_pegawai WHERE pesanan_id = ?', [id]);
    await pool.execute('DELETE FROM bosda_pesanan WHERE id = ?', [id]);

    res.json({ success: true, message: 'Transaksi pesanan berhasil dihapus' });
}));

