// 12a. Pembayaran Pesanan Belanja (Transfer / Tunai)
app.post('/api/bosda/pesanan/:id/bayar', authenticate, asyncHandler(async (req: any, res: any) => {
    const { id } = req.params;
    const { metode_pembayaran, tanggal_bayar, nomor_bukti_bayar, rekening_asal, catatan_bayar } = req.body;
    const pool = getPool();

    const [pesRows]: any = await pool.execute('SELECT * FROM bosda_pesanan WHERE id = ?', [id]);
    if (!pesRows || pesRows.length === 0) {
        return res.status(404).json({ error: 'Pesanan belanja tidak ditemukan' });
    }

    const tgl = tanggal_bayar ? String(tanggal_bayar).slice(0, 10) : new Date().toISOString().slice(0, 10);
    const metode = (metode_pembayaran === 'tunai') ? 'tunai' : 'transfer';

    // Validasi kecukupan saldo kas jika pembayaran baru dilakukan
    if (pesRows[0].status_pembayaran !== 'dibayar') {
        const tahun = pesRows[0].tahun_anggaran || tgl.slice(0, 4);
        const anggaran_id = pesRows[0].anggaran_id || null;
        const tagihanNominal = Number(pesRows[0].total_nominal || 0);

        // Hitung Penerimaan Kas (Bank vs Tunai)
        let pSql = `SELECT metode_penerimaan, COALESCE(SUM(jumlah_dana), 0) as total FROM bosda_penerimaan WHERE tahun_anggaran = ?`;
        const pParams: any[] = [tahun];
        if (anggaran_id) {
            pSql += ` AND anggaran_id = ?`;
            pParams.push(anggaran_id);
        }
        pSql += ` GROUP BY metode_penerimaan`;
        let kasBankMasuk = 0;
        let kasTunaiMasuk = 0;
        try {
            const [pRows]: any = await pool.execute(pSql, pParams);
            for (const r of (pRows || [])) {
                if (r.metode_penerimaan === 'tunai') kasTunaiMasuk += Number(r.total || 0);
                else kasBankMasuk += Number(r.total || 0);
            }
        } catch (_) {}

        // Hitung Mutasi Kas
        let mSql = `SELECT tipe_mutasi, COALESCE(SUM(jumlah), 0) as total FROM bosda_mutasi_kas WHERE tahun_anggaran = ?`;
        const mParams: any[] = [tahun];
        if (anggaran_id) {
            mSql += ` AND anggaran_id = ?`;
            mParams.push(anggaran_id);
        }
        mSql += ` GROUP BY tipe_mutasi`;
        let mutasiTarikTunai = 0;
        let mutasiSetorBank = 0;
        try {
            const [mRows]: any = await pool.execute(mSql, mParams);
            for (const m of (mRows || [])) {
                if (m.tipe_mutasi === 'tarik_tunai') mutasiTarikTunai = Number(m.total || 0);
                if (m.tipe_mutasi === 'setor_bank' || m.tipe_mutasi === 'setor_tunai') mutasiSetorBank += Number(m.total || 0);
            }
        } catch (_) {}

        // Belanja yang sudah dibayar
        let paidSql = `SELECT metode_pembayaran, COALESCE(SUM(total_nominal), 0) as total FROM bosda_pesanan WHERE tahun_anggaran = ? AND status_pembayaran = 'dibayar'`;
        const paidParams: any[] = [tahun];
        if (anggaran_id) {
            paidSql += ` AND anggaran_id = ?`;
            paidParams.push(anggaran_id);
        }
        paidSql += ` GROUP BY metode_pembayaran`;
        let belanjaBankPaid = 0;
        let belanjaTunaiPaid = 0;
        try {
            const [paidRows]: any = await pool.execute(paidSql, paidParams);
            for (const pr of (paidRows || [])) {
                if (pr.metode_pembayaran === 'tunai') belanjaTunaiPaid += Number(pr.total || 0);
                else belanjaBankPaid += Number(pr.total || 0);
            }
        } catch (_) {}

        const saldoKasBank = kasBankMasuk - mutasiTarikTunai + mutasiSetorBank - belanjaBankPaid;
        const saldoKasTunai = kasTunaiMasuk + mutasiTarikTunai - mutasiSetorBank - belanjaTunaiPaid;

        if (metode === 'transfer' && saldoKasBank < tagihanNominal) {
            return res.status(400).json({ 
                error: `Saldo Kas Bank (Rp ${saldoKasBank.toLocaleString('id-ID')}) tidak mencukupi untuk melakukan pembayaran tagihan belanja sebesar Rp ${tagihanNominal.toLocaleString('id-ID')}` 
            });
        }
        if (metode === 'tunai' && saldoKasTunai < tagihanNominal) {
            return res.status(400).json({ 
                error: `Saldo Kas Tunai (Rp ${saldoKasTunai.toLocaleString('id-ID')}) tidak mencukupi untuk melakukan pembayaran tagihan belanja sebesar Rp ${tagihanNominal.toLocaleString('id-ID')}` 
            });
        }
    }

    const noBukti = nomor_bukti_bayar && String(nomor_bukti_bayar).trim() 
        ? String(nomor_bukti_bayar).trim() 
        : `BKK-${String(id).padStart(3, '0')}/BOSDA/${tgl.slice(0, 4)}`;

    const noBast = pesRows[0].nomor_bast || `BAST/${String(id).padStart(3, '0')}/BOSDA/${tgl.slice(0, 4)}`;
    const tglBast = pesRows[0].tanggal_bast || tgl;

    await pool.execute(`
        UPDATE bosda_pesanan 
        SET status_pembayaran = 'dibayar',
            status = 'selesai',
            nomor_bast = ?,
            tanggal_bast = ?,
            metode_pembayaran = ?,
            tanggal_bayar = ?,
            nomor_bukti_bayar = ?,
            rekening_asal = ?,
            catatan_bayar = ?,
            tanggal_return = NULL,
            alasan_return = NULL,
            updated_at = NOW()
        WHERE id = ?
    `, [noBast, tglBast, metode, tgl, noBukti, rekening_asal || '', catatan_bayar || '', id]);

    res.json({ 
        success: true, 
        message: `Pembayaran belanja berhasil dicatat via ${metode === 'transfer' ? 'Transfer Bank' : 'Kas Tunai'}. Status pesanan selesai & BAST diterbitkan.`,
        status_pembayaran: 'dibayar',
        status: 'selesai',
        metode_pembayaran: metode
    });
}));

