export interface CpanelConfig {
    host: string;            // e.g. https://sdntanahtinggi1.sch.id:2083 or https://cpanel.domain.com:2083
    username: string;        // cPanel username e.g. sdntanahtinggi1
    apiToken: string;        // cPanel API Token
    domain: string;          // Domain for email e.g. sdntanahtinggi1.sch.id
    defaultQuotaMb?: number; // default quota in MB, e.g. 500 (0 = unlimited)
    webmailUrl?: string;     // e.g. https://webmail.sdntanahtinggi1.sch.id or https://sdntanahtinggi1.sch.id:2096
    namingPattern?: 'nama.nip' | 'nama' | 'first_last' | 'nip';
}

/**
 * Normalizes host URL by ensuring HTTPS and default port :2083 if not specified
 * Handles inputs like: "sdntanahtinggi1.sch.id", "sdntanahtinggi1.sch.id/cpanel", "https://sdntanahtinggi1.sch.id"
 */
export function normalizeCpanelHost(host: string, portOverride?: number): string {
    if (!host) return '';
    let clean = host.trim().replace(/\/cpanel\/?$/i, '').replace(/\/+$/, '');
    if (!clean.startsWith('http://') && !clean.startsWith('https://')) {
        clean = 'https://' + clean;
    }
    try {
        const urlObj = new URL(clean);
        const protocol = urlObj.protocol || 'https:';
        const hostname = urlObj.hostname;
        const port = portOverride || (urlObj.port ? parseInt(urlObj.port) : 2083);
        return `${protocol}//${hostname}:${port}`;
    } catch (e) {
        // Fallback simple regex
        const hostname = clean.replace(/^https?:\/\//, '').replace(/\/.*$/, '').replace(/:\d+$/, '');
        const port = portOverride || 2083;
        return `https://${hostname}:${port}`;
    }
}

/**
 * Fetch cPanel configuration from database
 */
export async function getCpanelConfig(pool: any): Promise<CpanelConfig | null> {
    try {
        const [rows]: any = await pool.execute("SELECT cpanel_config FROM pengaturan_sekolah WHERE id = 1");
        if (rows.length > 0 && rows[0].cpanel_config) {
            const raw = rows[0].cpanel_config;
            const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
            return parsed;
        }
        return null;
    } catch (err) {
        console.error("[cPanel] Error fetching config:", err);
        return null;
    }
}

/**
 * Save cPanel configuration to database
 */
export async function saveCpanelConfig(pool: any, config: CpanelConfig): Promise<boolean> {
    try {
        const configJson = JSON.stringify(config);
        await pool.execute("UPDATE pengaturan_sekolah SET cpanel_config = ? WHERE id = 1", [configJson]);
        return true;
    } catch (err) {
        console.error("[cPanel] Error saving config:", err);
        return false;
    }
}

/**
 * Helper to execute UAPI request to cPanel
 */
async function callCpanelUapi(config: CpanelConfig, module: string, func: string, params: Record<string, any> = {}, method: 'GET' | 'POST' = 'POST') {
    const host = normalizeCpanelHost(config.host);
    const user = config.username?.trim();
    const token = config.apiToken?.trim();

    if (!host || !user || !token) {
        throw new Error("Konfigurasi cPanel tidak lengkap (Host, Username, atau Token belum diisi).");
    }

    let url = `${host}/execute/${module}/${func}`;
    const headers: Record<string, string> = {
        'Authorization': `cpanel ${user}:${token}`
    };

    let fetchOptions: RequestInit = {
        method,
        headers,
        signal: AbortSignal.timeout(15000)
    };

    if (method === 'GET') {
        const searchParams = new URLSearchParams();
        Object.entries(params).forEach(([k, v]) => {
            if (v !== undefined && v !== null) {
                searchParams.append(k, String(v));
            }
        });
        const qs = searchParams.toString();
        if (qs) url += `?${qs}`;
    } else {
        const searchParams = new URLSearchParams();
        Object.entries(params).forEach(([k, v]) => {
            if (v !== undefined && v !== null) {
                searchParams.append(k, String(v));
            }
        });
        headers['Content-Type'] = 'application/x-www-form-urlencoded';
        fetchOptions.body = searchParams.toString();
    }

    const response = await fetch(url, fetchOptions);
    const data: any = await response.json().catch(() => ({}));

    if (response.status >= 400 && response.status !== 200) {
        const errDetail = Array.isArray(data?.errors) ? data.errors.join(', ') : `HTTP ${response.status}: ${response.statusText}`;
        throw new Error(errDetail);
    }

    const dataObj = data;
    if (dataObj.status === 0 || (Array.isArray(dataObj.errors) && dataObj.errors.length > 0)) {
        const errMsg = Array.isArray(dataObj.errors) ? dataObj.errors.join(', ') : (dataObj.message || 'Terjadi kegagalan pada UAPI cPanel');
        throw new Error(errMsg);
    }

    return dataObj;
}

/**
 * Test cPanel connection & verify API Token
 */
export async function testCpanelConnection(config: CpanelConfig): Promise<{ ok: boolean; message: string; count?: number; domain?: string }> {
    try {
        const res = await callCpanelUapi(config, 'Email', 'count_pops', {}, 'GET');
        const count = res.data?.total || res.data || 0;
        return {
            ok: true,
            message: `Koneksi cPanel Berhasil! Server merespons dengan baik (${count} akun email terdeteksi).`,
            count: Number(count),
            domain: config.domain
        };
    } catch (err: any) {
        return {
            ok: false,
            message: `Gagal terhubung ke cPanel: ${err.message}`
        };
    }
}

/**
 * List all email accounts with disk usage from cPanel
 */
export async function listCpanelEmailAccounts(config: CpanelConfig): Promise<any[]> {
    try {
        const res = await callCpanelUapi(config, 'Email', 'list_pops_with_disk', {}, 'GET');
        return res.data || [];
    } catch (err: any) {
        console.error("[cPanel] Error listing pops:", err);
        throw err;
    }
}

/**
 * Create a new email account via cPanel UAPI
 */
export async function createCpanelEmailAccount(
    config: CpanelConfig, 
    emailUser: string, 
    password: string, 
    quotaMb: number = 500, 
    domainOverride?: string
): Promise<{ ok: boolean; email: string; message?: string }> {
    const domain = (domainOverride || config.domain || '').trim().toLowerCase();
    const cleanUser = emailUser.trim().toLowerCase().replace(/@.*$/, ''); // take only username part

    if (!cleanUser || !password || !domain) {
        throw new Error("Username email, password, dan domain wajib diisi.");
    }

    const quota = quotaMb === 0 ? 0 : (quotaMb || config.defaultQuotaMb || 500);

    const res = await callCpanelUapi(config, 'Email', 'add_pop', {
        email: cleanUser,
        domain: domain,
        password: password,
        quota: quota
    });

    return {
        ok: true,
        email: `${cleanUser}@${domain}`,
        message: res.messages ? res.messages.join(', ') : 'Akun email berhasil dibuat di server cPanel!'
    };
}

/**
 * Reset / change email password via cPanel UAPI
 */
export async function changeCpanelEmailPassword(
    config: CpanelConfig, 
    emailUser: string, 
    newPassword: string, 
    domainOverride?: string
): Promise<{ ok: boolean; message?: string }> {
    const domain = (domainOverride || config.domain || '').trim().toLowerCase();
    const cleanUser = emailUser.trim().toLowerCase().replace(/@.*$/, '');
    const fullEmail = `${cleanUser}@${domain}`;

    let lastError: any = null;

    // 1. Coba UAPI Email::passwd_pop dengan username terpisah
    try {
        await callCpanelUapi(config, 'Email', 'passwd_pop', {
            email: cleanUser,
            domain: domain,
            password: newPassword
        });
        return { ok: true, message: 'Password email berhasil diperbarui di server cPanel.' };
    } catch (err: any) {
        lastError = err;
        console.warn(`[cPanel passwd_pop] Attempt 1 (user: ${cleanUser}, domain: ${domain}) failed:`, err.message);
    }

    // 2. Coba UAPI Email::passwd_pop dengan full email
    try {
        await callCpanelUapi(config, 'Email', 'passwd_pop', {
            email: fullEmail,
            domain: domain,
            password: newPassword
        });
        return { ok: true, message: 'Password email berhasil diperbarui di server cPanel.' };
    } catch (err: any) {
        lastError = err;
        console.warn(`[cPanel passwd_pop] Attempt 2 (fullEmail: ${fullEmail}) failed:`, err.message);
    }

    // 3. Coba UAPI Email::passwd_pop dengan param user & domain
    try {
        await callCpanelUapi(config, 'Email', 'passwd_pop', {
            user: cleanUser,
            domain: domain,
            password: newPassword
        });
        return { ok: true, message: 'Password email berhasil diperbarui di server cPanel.' };
    } catch (err: any) {
        lastError = err;
        console.warn(`[cPanel passwd_pop] Attempt 3 (user param: ${cleanUser}) failed:`, err.message);
    }

    const rawMsg = lastError?.message || 'Gagal mengubah password di server cPanel.';
    if (rawMsg.toLowerCase().includes('strength') || rawMsg.toLowerCase().includes('weak') || rawMsg.toLowerCase().includes('sandi')) {
        throw new Error(`Password ditolak cPanel karena terlalu lemah. Gunakan minimal 8 karakter dengan kombinasi huruf besar, huruf kecil, angka, dan simbol (contoh: Guru#2026!Sekolah).`);
    }

    throw new Error(rawMsg);
}

/**
 * Update / change email quota via cPanel UAPI
 * quotaMb: 0 for unlimited, or positive integer for MB limit
 */
export async function editCpanelEmailQuota(
    config: CpanelConfig, 
    emailUser: string, 
    quotaMb: number, 
    domainOverride?: string
): Promise<{ ok: boolean; message?: string }> {
    const domain = (domainOverride || config.domain || '').trim().toLowerCase();
    const cleanUser = emailUser.trim().toLowerCase().replace(/@.*$/, '');

    const quota = quotaMb === 0 || quotaMb < 0 ? 0 : Number(quotaMb);

    const res = await callCpanelUapi(config, 'Email', 'edit_pop_quota', {
        email: cleanUser,
        domain: domain,
        quota: quota
    });

    return {
        ok: true,
        message: quota === 0 ? 'Kuota email berhasil disetel Unlimited.' : `Kuota email berhasil disetel ${quota} MB.`
    };
}

/**
 * Delete email account via cPanel UAPI
 */
export async function deleteCpanelEmailAccount(
    config: CpanelConfig, 
    emailUser: string, 
    domainOverride?: string
): Promise<{ ok: boolean; message?: string }> {
    const domain = (domainOverride || config.domain || '').trim().toLowerCase();
    const cleanUser = emailUser.trim().toLowerCase().replace(/@.*$/, '');

    const res = await callCpanelUapi(config, 'Email', 'delete_pop', {
        email: cleanUser,
        domain: domain
    });

    return {
        ok: true,
        message: 'Akun email berhasil dihapus dari server cPanel.'
    };
}

/**
 * Create a direct Single Sign-On (SSO) login session for Webmail
 * Allows 1-click login into Roundcube without asking for password
 */
export async function createCpanelWebmailSession(config: CpanelConfig, emailAddress: string, clientIp?: string): Promise<string> {
    const cleanEmail = emailAddress.trim().toLowerCase();
    const userPart = cleanEmail.split('@')[0];
    const domainPart = cleanEmail.split('@')[1] || config.domain || '';
    const defaultFallback = `https://${domainPart}/webmail`;

    let hostBase = (config.host || '').replace(/:[0-9]+$/, '').replace(/\/+$/, '');
    if (!hostBase) hostBase = `https://${domainPart}`;
    if (!hostBase.startsWith('http://') && !hostBase.startsWith('https://')) {
        hostBase = `https://${hostBase}`;
    }
    const webmailPort = hostBase.startsWith('https') ? 2096 : 2095;

    const rawIp = (clientIp || '').replace(/^::ffff:/, '').trim();
    const isPublicIp = rawIp && rawIp !== '127.0.0.1' && rawIp !== '::1' && !rawIp.startsWith('192.168.') && !rawIp.startsWith('10.');

    const formatSessionUrl = (rawUrlOrToken: string) => {
        if (!rawUrlOrToken) return defaultFallback;
        if (rawUrlOrToken.startsWith('http://') || rawUrlOrToken.startsWith('https://')) {
            try {
                const parsed = new URL(rawUrlOrToken);
                if (parsed.hostname === '127.0.0.1' || parsed.hostname === 'localhost') {
                    const hostObj = new URL(hostBase);
                    parsed.hostname = hostObj.hostname;
                    return parsed.toString();
                }
            } catch (e) {}
            return rawUrlOrToken;
        }
        const cleanPath = rawUrlOrToken.startsWith('/') ? rawUrlOrToken : `/${rawUrlOrToken}`;
        if (cleanPath.startsWith('/cpsess') && !cleanPath.includes('session=') && !cleanPath.includes('/login')) {
            return `${hostBase}:${webmailPort}${cleanPath.replace(/\/+$/, '')}/login/`;
        }
        return `${hostBase}:${webmailPort}${cleanPath}`;
    };

    // 1. Try Session::create_webmail_session_for_mail_user with userPart & domain
    let lastError: any = null;
    try {
        const uapiParams1: any = {
            login: userPart,
            domain: domainPart
        };
        if (isPublicIp) uapiParams1.ip = rawIp;

        const res1 = await callCpanelUapi(config, 'Session', 'create_webmail_session_for_mail_user', uapiParams1);
        const d1 = res1.data || {};
        if (d1.url) {
            const finalUrl = formatSessionUrl(d1.url);
            console.log(`[cPanel SSO] Generated Webmail URL for ${cleanEmail}:`, finalUrl);
            return finalUrl;
        }
        if (d1.security_token) {
            const finalUrl = formatSessionUrl(d1.security_token);
            console.log(`[cPanel SSO] Generated Token Webmail URL for ${cleanEmail}:`, finalUrl);
            return finalUrl;
        }
    } catch (e1: any) {
        lastError = e1;
        console.warn("[cPanel SSO] create_webmail_session_for_mail_user (userPart, domain) failed:", e1.message);
    }

    // 2. Try Session::create_webmail_session_for_mail_user with full email & domain
    try {
        const uapiParams2: any = {
            login: cleanEmail,
            domain: domainPart
        };
        if (isPublicIp) uapiParams2.ip = rawIp;

        const res2 = await callCpanelUapi(config, 'Session', 'create_webmail_session_for_mail_user', uapiParams2);
        const d2 = res2.data || {};
        if (d2.url) {
            const finalUrl = formatSessionUrl(d2.url);
            console.log(`[cPanel SSO] Generated Webmail URL (full email) for ${cleanEmail}:`, finalUrl);
            return finalUrl;
        }
        if (d2.security_token) {
            const finalUrl = formatSessionUrl(d2.security_token);
            console.log(`[cPanel SSO] Generated Token Webmail URL (full email) for ${cleanEmail}:`, finalUrl);
            return finalUrl;
        }
    } catch (e2: any) {
        lastError = e2;
        console.warn("[cPanel SSO] create_webmail_session_for_mail_user (email, domain) failed:", e2.message);
    }

    // 3. Try Session::create_user_session with service: 'webmaild'
    try {
        const uapiParams3: any = {
            service: 'webmaild',
            user: cleanEmail
        };
        if (isPublicIp) uapiParams3.ip = rawIp;

        const res3 = await callCpanelUapi(config, 'Session', 'create_user_session', uapiParams3);
        const d3 = res3.data || {};
        if (d3.url) {
            const finalUrl = formatSessionUrl(d3.url);
            console.log(`[cPanel SSO] Generated create_user_session URL for ${cleanEmail}:`, finalUrl);
            return finalUrl;
        }
    } catch (e3: any) {
        console.warn("[cPanel SSO] create_user_session (webmaild, cleanEmail) failed:", e3.message);
    }

    // If UAPI threw an explicit error (e.g. Permission denied on API token), throw it
    if (lastError && lastError.message) {
        throw new Error(`cPanel UAPI Error: ${lastError.message}`);
    }

    // Fallback to standard webmail URL
    return defaultFallback;
}

