import { google } from 'googleapis';
import { Readable } from 'stream';
import { getPool } from './server';

export async function getGoogleDriveConfig() {
    try {
        const [rows]: any = await getPool().execute("SELECT google_drive_config FROM pengaturan_sekolah WHERE id = 1");
        if (rows.length > 0 && rows[0].google_drive_config) {
            return JSON.parse(rows[0].google_drive_config);
        }
        return null;
    } catch (err) {
        console.error("Error fetching drive config:", err);
        return null;
    }
}

function getDriveClient(config: any) {
    if (!config || !config.clientEmail || !config.privateKey) {
        throw new Error("Kredensial Google Drive belum lengkap di pengaturan.");
    }
    const auth = new google.auth.JWT({
        email: config.clientEmail,
        key: config.privateKey.replace(/\\n/g, '\n'),
        scopes: ['https://www.googleapis.com/auth/drive.file', 'https://www.googleapis.com/auth/drive']
    });
    return google.drive({ version: 'v3', auth });
}

export async function testDriveConnection(config: any, testFolderId: string) {
    try {
        // 1. Google Apps Script Web App Method (Recommended)
        if (config?.appScriptUrl) {
            const url = config.appScriptUrl.trim();
            const res = await fetch(url, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    action: 'test',
                    folderId: testFolderId || config.rootFolderGlobal || ''
                })
            });

            if (!res.ok) {
                const text = await res.text().catch(() => '');
                return { 
                    ok: false, 
                    error: `Google Apps Script mengembalikan HTTP ${res.status}: ${text.substring(0, 100)}`,
                    hint: "Pastikan Web App di-deploy dengan opsi 'Who has access: Anyone' dan 'Execute as: Me'."
                };
            }

            const data: any = await res.json().catch(async () => {
                const text = await res.text();
                return { ok: false, error: text };
            });

            if (data.ok) {
                return { ok: true, rootFolderName: data.rootFolderName || 'Google Drive (Apps Script Connected)' };
            } else {
                return { ok: false, error: data.error || 'Gagal terhubung ke Google Apps Script', hint: data.hint };
            }
        }

        // 2. Fallback: Google Cloud Service Account Method
        if (!testFolderId) {
            return { ok: false, error: "Folder ID belum diisi!" };
        }
        const drive = getDriveClient(config);
        const res = await drive.files.get({
            fileId: testFolderId,
            fields: 'id, name, permissions',
            supportsAllDrives: true
        });
        
        return { ok: true, rootFolderName: res.data.name };
    } catch (err: any) {
        console.error("Test Drive Error:", err);
        return { ok: false, error: err.message, hint: "Pastikan URL Google Apps Script sudah benar atau folder sudah di-share ke Service Account." };
    }
}

async function findOrCreateFolder(drive: any, folderName: string, parentId: string) {
    const res = await drive.files.list({
        q: `mimeType='application/vnd.google-apps.folder' and name='${folderName.replace(/'/g, "\\'")}' and '${parentId}' in parents and trashed=false`,
        fields: 'files(id, name)',
        spaces: 'drive',
        supportsAllDrives: true,
        includeItemsFromAllDrives: true
    });
    if (res.data.files && res.data.files.length > 0) {
        return res.data.files[0].id;
    }
    const fileMetadata = {
        name: folderName,
        mimeType: 'application/vnd.google-apps.folder',
        parents: [parentId]
    };
    const folder = await drive.files.create({
        requestBody: fileMetadata,
        fields: 'id',
        supportsAllDrives: true
    });
    
    // Set permission to anyone with link can view for the folder
    await drive.permissions.create({
        fileId: folder.data.id,
        requestBody: {
            role: 'reader',
            type: 'anyone',
        },
        supportsAllDrives: true
    });

    return folder.data.id;
}

export async function uploadFileToDrive(options: any) {
    const { buffer, originalFilename, mimeType, schoolName, category, folderType, subfolderName } = options;
    const config = await getGoogleDriveConfig();
    if (!config) throw new Error("Google Drive belum dikonfigurasi di Pengaturan Web.");
    
    // 1. Google Apps Script Method (Recommended)
    if (config.appScriptUrl) {
        const url = config.appScriptUrl.trim();
        const base64 = buffer.toString('base64');
        
        const payload = {
            base64,
            filename: originalFilename,
            mimeType: mimeType || 'application/octet-stream',
            schoolName: schoolName || 'Dapoy Storage',
            category: category || 'Umum',
            subfolderName: subfolderName || '',
            folderId: config.rootFolderGlobal || ''
        };

        const res = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });

        if (!res.ok) {
            const errText = await res.text().catch(() => '');
            throw new Error(`Upload Apps Script Gagal (HTTP ${res.status}): ${errText.substring(0, 150)}`);
        }

        const data: any = await res.json();
        if (!data.ok) {
            throw new Error(data.error || "Gagal mengunggah file via Google Apps Script");
        }

        const directLink = data.directUrl || (data.fileId ? `https://lh3.googleusercontent.com/d/${data.fileId}` : data.viewLink);

        return {
            viewLink: data.viewLink || directLink,
            downloadLink: data.downloadLink || directLink,
            id: data.fileId,
            directLink
        };
    }

    // 2. Fallback: Google Cloud Service Account Method
    if (!config.rootFolderGlobal) throw new Error("Root Folder ID belum diisi di Pengaturan Drive.");
    const drive = getDriveClient(config);
    
    const mainFolderId = await findOrCreateFolder(drive, schoolName || 'Dapoy Storage', config.rootFolderGlobal);
    const categoryFolderId = await findOrCreateFolder(drive, category || 'Umum', mainFolderId);
    let finalFolderId = categoryFolderId;
    if (subfolderName) {
        finalFolderId = await findOrCreateFolder(drive, subfolderName, categoryFolderId);
    }
    
    const stream = new Readable();
    stream.push(buffer);
    stream.push(null);
    
    const fileMetadata = {
        name: originalFilename,
        parents: [finalFolderId]
    };
    const media = {
        mimeType: mimeType,
        body: stream
    };
    
    const file = await drive.files.create({
        requestBody: fileMetadata,
        media: media,
        fields: 'id, webViewLink, webContentLink',
        supportsAllDrives: true
    });
    
    await drive.permissions.create({
        fileId: file.data.id,
        requestBody: {
            role: 'reader',
            type: 'anyone',
        },
        supportsAllDrives: true
    });
    
    const directLink = `https://lh3.googleusercontent.com/d/${file.data.id}`;
    return { 
        viewLink: file.data.webViewLink || directLink, 
        downloadLink: file.data.webContentLink || directLink,
        id: file.data.id,
        directLink
    };
}
